UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'لؤلؤة المحيط - السلمون والهليون'), description_ar = COALESCE(description_ar, 'ثنائي كلاسيكي يرطّب البشرة من الداخل ويساعد على تخفيف الوذمة.

