UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'فلافل مخبوزة في الفرن'), description_ar = COALESCE(description_ar, 'مذاق شرقي غني بالألياف ومقرمش، مخبوز في الفرن لمن تفضّلن تجنب القلي.

