UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'تدفّق الكهرمان - شاي الحلبة'), description_ar = COALESCE(description_ar, 'الحلبة من أقوى النباتات المُدرّة للحليب في العالم، إذ تحفّز هرمون البرولاكتين.'), category_ar = COALESCE(category_ar, 'مشروبات_صحية'), ingredients_ar = COALESCE(ingredients_ar, '["بذور الحلبة (Fenugreek): 1 ملعقة صغيرة","الماء: 2 كوب","العسل: 1 ملعقة صغيرة (اختياري)","الليمون: بضع قطرات"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["حمّصي بذور الحلبة قليلًا في مقلاة جافة لمدة 1-2 دقيقة (مع الحرص على عدم احتراقها)","أضيفيها إلى الماء المغلي","اتركيها تُنقع لمدة 10 دقائق، ثم صفّيها","أضيفي العسل والليمون حسب الرغبة","اشربي 2-3 أكواب يوميًا، ويمكن ملاحظة زيادة إدرار الحليب خلال 24-48 ساعة"]'::jsonb) WHERE id = '52d3741b-ea80-45a2-99fd-beda7e7b6c4a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وعاء الماتشا الصباحي'), description_ar = COALESCE(description_ar, 'غني بمضادات الأكسدة ويساعد على تسريع عملية الأيض، وهو مناسب لمن ترغب في الاستيقاظ بنشاط دون كافيين.

الفائدة: يسرّع شاي الماتشا عملية الأيض ويساعد على تنقية البشرة. وعلى عكس القهوة، لا يمنحكِ دفعة مفاجئة من الطاقة يعقبها التعب، بل يحافظ على نشاطكِ المتوازن طوال اليوم.'), category_ar = COALESCE(category_ar, 'الفطور'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["موز مجمّد: 1 حبة","مسحوق الماتشا: 1 ملعقة صغيرة","سبانخ: 1 حفنة صغيرة","حليب اللوز: نصف كوب","للتزيين: رقائق جوز الهند، وحبات اللوز، وشرائح الكيوي."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي الموز والماتشا والسبانخ والحليب في الخلاط حتى تحصلي على سموذي كثيف القوام. اسكبيه في وعاء وزيّنيه بالمكسّرات وشرائح الكيوي."]'::jsonb) WHERE id = '8c4792f6-0abc-4597-99d1-ff981dc2a340';
