UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'موس الشوكولاتة بالأفوكادو'), description_ar = COALESCE(description_ar, 'الأفوكادو غني بحمض الفوليك والمغنيسيوم، ويساعد الكاكاو على تحسين المزاج'), category_ar = COALESCE(category_ar, 'مشروبات_صحية'), ingredients_ar = COALESCE(ingredients_ar, '["الأفوكادو - 1 حبة","الكاكاو - 2 ملعقة كبيرة","العسل - 3 ملعقة كبيرة","الفانيليا","حليب اللوز - 3 ملاعق"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي جميع المكونات في الخلاط","اخلطيها حتى تحصلي على قوام كريمي","ضعيها في الثلاجة لمدة 30 دقيقة","قدميها مع الفراولة"]'::jsonb) WHERE id = 'c7535dc2-4407-4715-bc23-3a8242531319';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'المعجزة الخضراء - كفتة بالشبت'), description_ar = COALESCE(description_ar, 'أشهر أسرار المطبخ الأذربيجاني لدعم إدرار الحليب: الكثير من الشبت! فهو يساعد على تدفق الحليب.'), category_ar = COALESCE(category_ar, 'وجبة_الغداء'), ingredients_ar = COALESCE(ingredients_ar, '["اللحم المفروم (بقري أو دجاج): 300 qr","الأرز: نصف كوب","الشبت: حزمتان كبيرتان","البطاطس: 2 حبة","البصل: 1 حبة","الملح والفلفل"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي اللحم المفروم والأرز المغسول ونصف كمية الشبت المفروم ناعمًا","أضيفي الملح والفلفل وشكّلي الخليط على هيئة كرات كفتة","ضعي البطاطس والبصل المقطعين في الماء المغلي","بعد 5 دقائق، أضيفي كرات الكفتة واطهيها على نار هادئة لمدة 25-30 دقيقة","قرب انتهاء الطهي، افرمي الكمية المتبقية من الشبت وأضيفيها إلى الحساء"]'::jsonb) WHERE id = 'b8788575-43f0-4748-a08b-a02e6044caa7';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بيتزا القرنبيط'), description_ar = COALESCE(description_ar, 'للاستمتاع بمذاق البيتزا من دون شعور بالذنب، ومن دون غلوتين أو عجين.

الفائدة: القرنبيط غني بالمغذيات النباتية ويدعم وظائف الكبد الطبيعية. كما أن هذه البيتزا لا تسبب عادةً الانتفاخ أو حرقة المعدة.'), category_ar = COALESCE(category_ar, 'العشاء'), ingredients_ar = COALESCE(ingredients_ar, '["القرنبيط: نصف رأس (مبشور ومعصور جيدًا للتخلص من الماء تمامًا)","البيض: 1 حبة","الجبن (مبشور): 3 ملاعق كبيرة (للعجين)","للوجه: معجون الطماطم، شرائح الطماطم، الجبن، الريحان."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اعجني القرنبيط المبشور مع البيض والجبن، ثم افرديه في صينية الفرن على شكل عجينة بيتزا. اخبزيه على درجة حرارة 200 لمدة 15 دقيقة (حتى يتحمر). ثم أخرجيه ووزعي فوقه الصلصة والمكونات، وأعيديه إلى الفرن لمدة 5 دقائق إضافية حتى يذوب الجبن."]'::jsonb) WHERE id = 'e3dad099-6f8a-4e3c-8dfa-2922158c70b6';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سلطة الفطر والسبانخ الدافئة'), description_ar = COALESCE(description_ar, 'سلطة دافئة ومشبعة بنكهة ترابية، مثالية للأمسيات التي لا ترغبين فيها بتناول اللحم.

الفائدة: يساعد المغنيسيوم الموجود في السبانخ على استرخاء العضلات، بينما يحتوي الفطر على فيتامين D وفيتامينات المجموعة B الداعمة للمناعة.'), category_ar = COALESCE(category_ar, 'العشاء'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فطر الشامبينيون أو فطر المحار: 150 غرامًا (مقطع)","السبانخ الصغيرة: 2-3 حفنات (نيئة)","الجوز: حفنة واحدة","خل بلسمي، زيت الزيتون، الثوم (قليلًا)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["شوّحي الفطر مع فص واحد من الثوم في قليل من الزيت حتى يتحمر. ضعي السبانخ في وعاء، ثم اسكبي فوقها الفطر الساخن (ستساعد الحرارة على تليين السبانخ قليلًا). رشي الجوز وأضيفي رشة من الخل البلسمي."]'::jsonb) WHERE id = 'cc18259a-201a-4dd4-83bd-d60fc14dccba';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سباغيتي الكوسا بالعدس'), description_ar = COALESCE(description_ar, 'بديل للمعكرونة غني بالبروتين النباتي، يبدد اشتياقكِ إلى السباغيتي.

