UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'موهيتو الكركديه الياقوتي'), description_ar = COALESCE(description_ar, 'مذاق أحمر شهي، يُعد إكسيرًا للشباب ويساعد على تنظيم ضغط الدم.

