UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'حليب اللافندر'), description_ar = COALESCE(description_ar, 'مشروب سحري يبدّد التوتر بعد يوم شاق ويساعدكِ على النوم كطفل رضيع.

