UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'تشيز كيك الكاجو بالفراولة'), description_ar = COALESCE(description_ar, 'تشيز كيك رائع «نباتي نيّئ» يُحضّر من دون منتجات الألبان أو الدقيق أو السكر.

