UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'لقيمات الكينوا والشوكولاتة'), description_ar = COALESCE(description_ar, 'ألذ إجابة مقرمشة وصحية للرغبة الشديدة في تناول الشوكولاتة خلال فترة ما قبل الدورة الشهرية (PMS).

