UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'تارت الكاكاو والأفوكادو'), description_ar = COALESCE(description_ar, 'نسخة صحية للغاية وغير مخبوزة من تارت الشوكولاتة، بطعم لن يجعلكِ تتوقعين مدى فائدتها.

