UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'تمر بزبدة الفول السوداني'), description_ar = COALESCE(description_ar, 'وجبة خفيفة تمنحكِ إحساس تناول شوكولاتة الكراميل الحقيقية، وتزودكِ بالطاقة فورًا.

