UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كوكو إسبريسو بارد'), description_ar = COALESCE(description_ar, 'تحفة منعشة وخالية من السكر لمحبات النكهات الاستوائية.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["جرعة واحدة (shot) من الإسبريسو، كوب واحد من ماء جوز الهند الطبيعي (coconut water)، وكمية وفيرة من الثلج."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["املئي الكوب بالثلج ثم اسكبي ماء جوز الهند. أضيفي الإسبريسو ببطء في النهاية لتتكوّن طبقتان بلونين مختلفين. حرّكي المشروب واستمتعي به."]'::jsonb) WHERE id = '269778e2-5f1d-4cd3-b820-0a1898c7e6ea';
