UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'هريس السبانخ والبازلاء
(8 أشهر+)'), description_ar = COALESCE(description_ar, 'وجبة غنية بالحديد والبروتين، تلفت الانتباه بلونها، لأبطال المستقبل الأقوياء.

الفائدة: يدعم حمض الفوليك الموجود في السبانخ والبروتين الموجود في البازلاء الخضراء النمو السريع.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), ingredients_ar = COALESCE(ingredients_ar, '["السبانخ: حفنة واحدة (منظفة)","البازلاء الخضراء الطازجة: 1 ملعقة طعام","البطاطس: نصف حبة صغيرة","الزبدة: قطعة صغيرة جدًا (غير مملحة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اسلقي البطاطس والبازلاء في الماء. أضيفي السبانخ قبل رفعها عن النار بقليل. صفّي الماء، ثم أضيفي الزبدة واهرسي المكونات حتى تصبح هريسًا."]'::jsonb) WHERE id = 'fb03ef40-89b2-4c37-a867-f84dac70544e';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بانكيك التوت الأزرق
(9 أشهر+)'), description_ar = COALESCE(description_ar, 'وجبة لذيذة يمكن لطفلكِ تناولها بيده (BLW)، وتساعد على تطوير مهاراته الحركية.

الفائدة: التوت الأزرق مضاد أكسدة قوي يحفّز نشاط الدماغ. بانكيك طري خالٍ من السكر والدقيق.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الموز: 1 حبة (ناضجة ومهروسة)","صفار البيض: 1 حبة (يُمنع بياض البيض حتى عمر سنة)","التوت الأزرق: 6-7 حبات (مقطعة إلى نصفين)","دقيق الشوفان: 1 ملعقة طعام."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اهرسي الموز، ثم اخلطيه مع صفار البيض والدقيق. أضيفي التوت الأزرق المقطع. ضعي كميات صغيرة بالملعقة على شكل دوائر في مقلاة دون زيت، واطهيها من الجانبين."]'::jsonb) WHERE id = 'e4dcec61-d668-42ad-9158-cfc7b2b1485d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'فلات وايت بالشوفان والقرفة'), description_ar = COALESCE(description_ar, 'قهوة خفيفة وعطرية لا ترفع سكر الدم (الإنسولين) بشكل مفاجئ.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general', 'milk_boost']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 فنجان (شوت) إسبريسو، نصف كوب من حليب الشوفان المخفوق، 1 ملعقة صغيرة من مسحوق القرفة."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أضيفي حليب الشوفان الساخن ذا الرغوة الكثيفة إلى الإسبريسو، ثم رشي كمية وفيرة من القرفة."]'::jsonb) WHERE id = 'a3480015-30ca-4f9a-b8de-a642fd9a639c';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وعاء الدب بالتوت العليق (لعمر سنتين فأكثر)'), description_ar = COALESCE(description_ar, 'وعاء سموذي ممتع يمنح إحساس الآيس كريم، ومناسب كوجبة خفيفة أو فطور.

الفائدة: الزبادي المصفّى غني بالبروبيوتيك (ويعزز المناعة)، أما التوت فهو مصدر غني بمضادات الأكسدة.'), category_ar = COALESCE(category_ar, 'التغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الزبادي المصفّى: 3 ملاعق كبيرة","توت العليق أو الفراولة المجمّدة: حفنة واحدة","الموز: نصف حبة (لخلطها مع الزبادي)","للتزيين: شرائح موز وتوت أزرق (لتشكيل وجه الدب)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي الزبادي ونصف حبة الموز والتوت المجمّد في الخلاط حتى يصبح المزيج ناعمًا تمامًا وكثيفًا كالكريمة.","اسكبي المزيج في وعاء.","شكّلي أذني الدب بشريحتين من الموز، وعينيه وأنفه بحبات التوت الأزرق."]'::jsonb) WHERE id = 'b83ce14e-ac83-4541-a4e8-d4b8fa3d176e';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'موكا داكنة صحية'), description_ar = COALESCE(description_ar, 'بديل خالٍ من الشراب المُحلّى لمن ترغب في الاستمتاع بمذاق القهوة والشوكولاتة في آنٍ واحد.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 فنجان إسبريسو، 1 ملعقة صغيرة من الكاكاو النقي، 1 ملعقة صغيرة من العسل، 1 كوب من حليب اللوز الساخن."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أذيبي الكاكاو والعسل في الإسبريسو الساخن. ثم أضيفي حليب اللوز الساخن والرغوي."]'::jsonb) WHERE id = 'fdd5be2e-2d65-464b-84d3-084f637ea16e';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بيتزا الوجوه المبتسمة (لعمر سنتين فأكثر)'), description_ar = COALESCE(description_ar, 'بيتزا ممتعة وصحية يمكن لطفلكِ البالغ من العمر سنتين مساعدتكِ في تحضيرها.

الفائدة: خالية من الإضافات لأنها محضّرة في المنزل. كما تساعد الطفل على تكوين ارتباط عاطفي بالطعام من خلال شكل الوجه المبتسم.'), category_ar = COALESCE(category_ar, 'التغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["خبز بيتا صغير من القمح الكامل (أو خبز لافاش صغير): 1 قطعة","معجون طماطم (منزلي الصنع وخالٍ من السكر): 1 ملعقة كبيرة","جبن موزاريلا: ملعقتان كبيرتان مبشورتان","حلقات من الزيتون الأسود (للعينين) وشريط من الفلفل الأحمر (للفم)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["وزّعي معجون الطماطم على خبز البيتا.","رشّي فوقه كمية وفيرة من الجبن.","شكّلي \"وجهًا مبتسمًا\" باستخدام الزيتون والفلفل. اخبزيها في الفرن حتى يذوب الجبن (نحو 5-7 دقائق)."]'::jsonb) WHERE id = 'b7520537-fae1-481b-9bea-7a9cf32f15f7';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مهروس الأفوكادو والبيض
(8 أشهر+)'), description_ar = COALESCE(description_ar, 'مزيج طبيعي غني بالعناصر الغذائية لا يتطلب الطهي (باستثناء البيض)، وينقذ الأمهات في الصباح.

الفائدة: يجمع بين نوعين رائعين من «الأطعمة الخارقة». تساهم أحماض أوميغا الدهنية الموجودة في الأفوكادو ومادة الكولين الموجودة في صفار البيض مباشرةً في نمو القدرات الذهنية والذاكرة.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["صفار بيضة مسلوقة جيدًا: 1 حبة","أفوكادو: ربع حبة (ناضجة وطرية جدًا)","حليب الأم أو الحليب الصناعي."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اهرسي الأفوكادو وصفار البيضة المسلوقة جيدًا بالشوكة في وعاء. إذا كان القوام كثيفًا جدًا، فأضيفي بضع قطرات من حليب الأم أو الماء الفاتر لتليين المزيج."]'::jsonb) WHERE id = 'e39c8f3d-f865-4de6-8f5d-d3f60a5624c8';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'باستا النمر الوردي (عمر سنة+)'), description_ar = COALESCE(description_ar, 'باستا مرحة بالجبن والشمندر، تسحر الأطفال بلونها.

الفائدة: يدعم الشمندر الدورة الدموية، بينما يُعد الجبن مصدرًا غنيًا بالكالسيوم الضروري لنمو العظام.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["معكرونة صغيرة للأطفال: 3-4 ملاعق طعام","هريس الشمندر (مسلوق ومهروس): 1 ملعقة طعام","جبن لور (مالح) أو جبن كريمي: 1 ملعقة طعام"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اسلقي المعكرونة في الماء حتى تصبح طرية تمامًا، ثم صفّيها. أضيفي هريس الشمندر والجبن إلى المعكرونة الساخنة وامزجي جيدًا. ستكتسب المعكرونة فورًا لونًا ورديًا زاهيًا."]'::jsonb) WHERE id = 'dc9362af-ecb7-4bac-9ddf-d84bf1aa2f2d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ناجتس صحي (عمر سنة+)'), description_ar = COALESCE(description_ar, 'بديل صحي للناجتس الجاهز، يُخبز في الفرن ويخلو من الإضافات.

الفائدة: يُعد مصدرًا متكاملًا للطاقة بفضل بروتين الدجاج النقي والألياف الموجودة في الشوفان.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["صدر دجاج: 100 غ (مفروم في الخلاط أو مقطع إلى قطع صغيرة جدًا)","دقيق الشوفان (أو رقائق شوفان مطحونة): للتغليف","بيضة: 1 حبة (مخفوقة)","مسحوق الفلفل الأحمر الحلو (بابريكا غير حارة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أضيفي كمية قليلة جدًا من البابريكا إلى الدجاج واعجنيه. قسّميه إلى قطع صغيرة، ثم اغمسيها أولًا في البيض وبعد ذلك في دقيق الشوفان. اخبزيها على ورق الخَبز في الفرن على درجة حرارة 180 لمدة 20 دقيقة."]'::jsonb) WHERE id = '732a8d20-182d-45bb-9171-f30bbd4cd142';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بسكويت الأرنب (لعمر سنتين فأكثر)'), description_ar = COALESCE(description_ar, 'بسكويت منزلي مقرمش ومفيد جدًا، خالٍ من السكر ويُعد بديلًا للبسكويت الجاهز.

الفائدة: يساعد الشوفان الغني بالألياف والجزر الغني بالفيتامينات على تحسين هضم الطفل. وهو بديل صحي جدًا لبسكويت المتاجر.'), category_ar = COALESCE(category_ar, 'الغذاء التكميلي'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["رقائق الشوفان: كوب واحد","الجزر: حبة واحدة (مبشورة)","هريس التفاح: نصف كوب (اطهي التفاح واهرسيه، ليمنح البسكويت حلاوة طبيعية)","الزبيب (مفروم فرمًا ناعمًا جدًا): ملعقة طعام واحدة","الزبدة: ملعقة طعام واحدة (مذابة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اعجني جميع المكونات جيدًا في وعاء عميق.","شكّلي بيديكِ قطع بسكويت صغيرة ومسطحة (أو استخدمي قوالب على شكل حيوانات).","اخبزيها في فرن على حرارة 170 درجة لمدة 15-20 دقيقة حتى تتحمر قليلًا."]'::jsonb) WHERE id = '7cc7ac25-0798-468f-82c0-6764afc0cd4f';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ميني برغر (لعمر 3 سنوات فأكثر)'), description_ar = COALESCE(description_ar, 'ميني برغر صحي ومحضّر منزليًا بنسبة 100%، يساعد على الحد من الرغبة في تناول الوجبات السريعة.

الفائدة: يوفر اللحم النقي المفروم في المنزل البروتين والحديد، بينما يوفر خبز القمح الكامل فيتامينات B.'), category_ar = COALESCE(category_ar, 'الغذاء التكميلي'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["خبز ميني برغر من دقيق القمح الكامل: قطعتان","لحم بقري مفروم قليل الدهن: 100 غ","جبن هولندي: 1-2 شريحة رقيقة","الطماطم وأوراق الخس","زيت الزيتون."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["شكّلي من اللحم المفروم أقراصًا رقيقة ومسطحة بحجم الخبز، ثم حمّريها في مقلاة بقليل من الزيت. ضعي قرص اللحم والجبن والطماطم والخس بين قطع الخبز لتحضير الميني برغر."]'::jsonb) WHERE id = 'e6d245f4-3ec1-4650-92fc-b0b877ba16f0';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'أصابع الخضروات المخبوزة في الفرن (لعمر 3 سنوات فأكثر)'), description_ar = COALESCE(description_ar, 'أصابع خضروات ملونة ومقرمشة تُعد بديلًا للبطاطس المقلية التقليدية.

الفائدة: البطاطا الحلوة والجزر غنيان بفيتامين A. ولأنها غير مقلية، فهي خالية من الدهون المتحولة.'), category_ar = COALESCE(category_ar, 'الغذاء التكميلي'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["البطاطا الحلوة: حبة واحدة","الجزر: حبة كبيرة واحدة","زيت الزيتون: ملعقة طعام واحدة","كمية قليلة جدًا من الملح ومسحوق الفلفل الأحمر الحلو (البابريكا)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["قطّعي الخضروات إلى أصابع طويلة ومتساوية الحجم مثل البطاطس المقلية. اخلطيها مع زيت الزيتون والتوابل، ثم رتّبيها على ورق الخَبز. اخبزيها على حرارة 200 درجة لمدة 20-25 دقيقة حتى تصبح أطرافها مقرمشة."]'::jsonb) WHERE id = '705fa4d6-de4b-4c10-bc6c-46c0cc463f11';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'خبز محمّص على شكل دب تيدي (3 سنوات+)'), description_ar = COALESCE(description_ar, 'وجبة شهية سترسم الابتسامة على وجهكِ في الإفطار، ولا يستغرق تحضيرها سوى 2 دقيقة.

الفائدة: تحتوي زبدة الفول السوداني على دهون مفيدة للدماغ وبروتين، بينما يمنح الموز الطاقة.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["خبز قمح كامل مربع: 1 شريحة (محمّصة)","زبدة الفول السوداني: 1 ملعقة طعام","موز: 3 شرائح دائرية","توت أزرق: 3 حبات."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ادهني زبدة الفول السوداني على الخبز المحمّص. ضعي شريحتين من الموز عند الحافتين العلويتين لتشكيل الأذنين، وضعي الثالثة مكان الأنف. استخدمي حبات التوت الأزرق لتشكيل العينين وطرف الأنف."]'::jsonb) WHERE id = '36867e84-3459-4059-a668-70f297e35576';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مافن الحديقة السرية (3 سنوات+)'), description_ar = COALESCE(description_ar, 'مافن مالح يحتوي على الجبن والخضراوات، ويسهل حمله إلى الحديقة أو أثناء السفر.

الفائدة: خالٍ من السكر، وعملي جدًا؛ إذ يستطيع طفلكِ إمساكه وتناوله دون فوضى، كما أنه غني بالمعادن والكالسيوم.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["بيض: 2 حبة","زبادي: 2 ملعقة طعام","جزر (مبشور) وبروكلي (مفروم ناعمًا جدًا): نصف كوب","جبن أبيض: 2 ملعقة طعام (مفتت)","دقيق القمح الكامل ومسحوق الخَبز."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخفقي المكونات السائلة. أضيفي الخضراوات والجبن. أضيفي الدقيق ومسحوق الخَبز واخلطي حتى تحصلي على عجينة مافن كثيفة. وزّعيها في قوالب المافن واخبزيها على درجة حرارة 180 مئوية لمدة 20-25 دقيقة، حتى تنتفخ وتكتسب لونًا ذهبيًا."]'::jsonb) WHERE id = 'ecfe7439-ff4e-4167-ab7a-c45d91fa903c';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بيتزا الأطباق الطائرة (4 سنوات+)'), description_ar = COALESCE(description_ar, 'قطع بيتزا صغيرة مرحة وخالية من الغلوتين، تُحضّر باستخدام قبعات الفطر بدلًا من العجين.

الفائدة: فطر البورتوبيلو أو فطر الشامبينيون الكبير غني بفيتامين D. وهي طريقة رائعة لتعريف الأطفال إلى مذاق الفطر وتعويدهم عليه.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فطر شامبينيون كبير: 4-5 حبات (منزوعة السيقان)","معجون الطماطم: 2 ملعقة طعام","جبن موزاريلا: 3 ملاعق طعام (مبشور)","ذرة أو زيتون."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ادهني داخل حبات الفطر بمعجون الطماطم. ضعي فوقها الجبن وحبات الذرة. اخبزيها في فرن على درجة حرارة 180 مئوية حتى يذوب الجبن ويصبح الفطر طريًا (نحو 15 دقيقة)."]'::jsonb) WHERE id = '0a108d2a-2483-496b-8459-a35dba184122';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'نعيم الماتشا بجوز الهند'), description_ar = COALESCE(description_ar, 'مشروب دافئ وناعم بنكهة استوائية، يرطّب البشرة من الداخل.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة صغيرة من مسحوق الماتشا، 1 كوب من حليب جوز الهند، 1 رشة من خلاصة الفانيليا."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["سخّني حليب جوز الهند في قدر حتى يبدأ بالتصاعد منه البخار (من دون غليه). أضيفي الفانيليا والماتشا، ثم اخفقي المزيج باستخدام خفّاق مخصص (أو جهاز صنع رغوة الحليب) حتى تتكوّن الرغوة."]'::jsonb) WHERE id = 'f005b3c3-1f74-4e4e-bab7-c8bc5e03c14a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'فرابيه الماتشا بالنعناع'), description_ar = COALESCE(description_ar, 'بديل طبيعي 100% وخالٍ من الكافيين ومنعش لمشروبات «الفرابتشينو» المحلّاة.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة صغيرة من الماتشا، 1 موزة مجمّدة، 3-4 أوراق نعناع طازجة، نصف كوب من حليب الشوفان."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات جيدًا في الخلاط حتى تحصلي على قوام مثلّج يشبه الفرابيه."]'::jsonb) WHERE id = 'e8f085b1-b955-46e7-bd90-9c504005461c';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كاكاو بالتوابل'), description_ar = COALESCE(description_ar, 'وصفة قديمة تُنشّط عملية الأيض وتُحفّز الدورة الدموية.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة كبيرة من الكاكاو النقي، 1 رشة قرفة، كمية ضئيلة جدًا (بطرف السكين) من مسحوق الفلفل الأحمر الحار (فلفل كايين)، 1 كوب من حليب البندق الساخن، عسل."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أضيفي الكاكاو والتوابل إلى الحليب الساخن وحرّكي حتى تذوب تمامًا. سيمنحكِ التوازن بين النكهتين الحارة والحلوة شعورًا بالدفء."]'::jsonb) WHERE id = '692f8fd9-2a1f-4e6e-90a2-3450b555119d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'لقيمات السمك المقرمشة (5 سنوات+)'), description_ar = COALESCE(description_ar, 'مكعبات سمك ذهبية ومقرمشة ستُغري حتى الأطفال في سن 5 سنوات الذين يرفضون تناول السمك.

الفائدة: السمك الأبيض مصدر للفوسفور واليود والبروتين سهل الامتصاص، وهو ممتاز لتنمية القدرات الذهنية.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فيليه سمك أبيض (مثل سمك القد أو القاروص): 150 غرامًا (مقطّع إلى مكعبات ومنزوع العظام)","بيضة: 1","رقائق الذرة غير المحلّاة (كورن فليكس) أو مسحوق البقسماط: للتغليف"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["فتّتي رقائق الذرة بيديكِ. اغمسي مكعبات السمك أولًا في البيض المخفوق، ثم غلّفيها بفتات رقائق الذرة. ضعيها على ورق الخَبز واخبزيها في الفرن على درجة حرارة 180 لمدة 15-20 دقيقة."]'::jsonb) WHERE id = 'fe1e3f3e-8c82-4bdd-8cb3-2212d66df10f';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شطائر التفاح المقرمشة (5 سنوات+)'), description_ar = COALESCE(description_ar, 'وجبة خفيفة غنية بالطاقة، تُحضَّر باستخدام شرائح التفاح بدلًا من الخبز، ومناسبة بعد المدرسة أو الروضة.

الفائدة: تساعد ألياف البكتين في التفاح والبروتين الموجود في زبدة الفول السوداني على الشعور بالشبع، كما تلبّي الرغبة في تناول السكريات بصورة طبيعية.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["تفاحة كبيرة: 1 (منزوعة اللب ومقطّعة إلى حلقات)","زبدة الفول السوداني أو اللوز (غير المحلّاة): 2 ملعقة طعام","زبيب أو رقائق شوكولاتة (للحشوة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ادهني زبدة الفول السوداني على حلقة من التفاح، ثم وزّعي فوقها الزبيب وغطّيها بحلقة أخرى مثل الشطيرة. يمكنكِ تقطيعها من المنتصف ليسهل على طفلكِ الإمساك بها."]'::jsonb) WHERE id = '2f4202ed-6015-4318-b0d0-ac257ccd10af';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'قهوة باردة منقوعة بالهيل'), description_ar = COALESCE(description_ar, 'قهوة باردة منخفضة الحموضة جدًا، لا تسبّب حرقة المعدة وتساعد على الهضم.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 كوب من قهوة Cold Brew (قهوة منقوعة على البارد)، 1-2 حبة هيل (مطحونة)، ثلج، وقليل من الحليب النباتي حسب الرغبة."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أضيفي حبات الهيل المطحونة إلى القهوة أثناء نقعها (أو تصفيتها). قدّميها مع كمية وفيرة من الثلج. يضفي الهيل على القهوة نكهة \"رائعة\" ومميزة."]'::jsonb) WHERE id = '75bdd91d-7aed-40d8-9434-8c6ca0198e19';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'قوس قزح الصباحي (4 سنوات+)'), description_ar = COALESCE(description_ar, 'وجبة فطور تجمع بين فطائر البان كيك الصغيرة والفواكه، ومثالية لتناولها باليد.

الفائدة: تنوّع الفواكه يعني تنوّع الفيتامينات. تساعد الأسياخ على تنمية المهارات الحركية لدى الأطفال وزيادة اهتمامهم بالطعام.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فطائر بان كيك صغيرة: مطهية بحجم قطعة نقدية","فراولة، وشرائح موز دائرية، وشرائح كيوي.","أسياخ خشبية غير حادة الطرف."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي في الأسياخ بالتناوب: فطيرة بان كيك صغيرة، ثم فراولة، ثم موزًا، ثم فطيرة أخرى، ثم كيوي. وقدّمي بجانبها وعاءً صغيرًا من العسل أو دبس الفاكهة للتغميس."]'::jsonb) WHERE id = 'bb88a8d3-5c23-4d20-8927-32de71e35006';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كفتة السمك (4 سنوات+)'), description_ar = COALESCE(description_ar, 'مصدر غني بأوميغا-3، سيستمتع الأطفال الذين لا يحبون السمك بتناوله بفضل شكله الجذاب.

الفائدة: يعزز سمك السلمون وظائف الدماغ والذاكرة.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), ingredients_ar = COALESCE(ingredients_ar, '["فيليه سمك السلمون: 100 غرام (مسلوق ومفتّت)","بطاطس: 1 حبة (مطهية ومهروسة)","شبت: كمية قليلة جدًا (مفروم)"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اعجني البطاطس المهروسة مع السمك والشبت. افردي الخليط على ورق الخَبز وقطّعيه بقالب على شكل نجمة. اطهي القطع في المقلاة أو الفرن حتى تتحمّر قليلًا."]'::jsonb) WHERE id = '94068d6c-ec4c-4f36-a84e-fdd44212d93d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'معكرونة المجرّة (5 سنوات+)'), description_ar = COALESCE(description_ar, 'طبق كوني بصلصة الجبن الكريمية، مليء بقطع المعكرونة التي تشبه النجوم والفراشات.

الفائدة: تزيد الخضراوات ذات الألوان المختلفة، مثل البازلاء والذرة، من تنوّع الفيتامينات، بينما تكون صلصة الزبادي غير المحلّى والجبن لطيفة على المعدة.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["معكرونة الفراشات الخالية من الغلوتين (Farfalle) أو معكرونة ملوّنة: 1 كوب","بازلاء خضراء وذرة: 1 ملعقة طعام من كل منهما","طماطم كرزية: 3-4 حبات (مقطّعة إلى نصفين)","جبن كريمي (أو زبادي مصفّى): 1 ملعقة طعام."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اسلقي المعكرونة حتى تصبح طرية تمامًا ثم صفّيها، مع الاحتفاظ بقليل من ماء السلق. أضيفي الجبن الكريمي والبازلاء والذرة والطماطم إلى المعكرونة الساخنة وحرّكي المكونات. سيذوب الجبن ويكوّن صلصة كريمية."]'::jsonb) WHERE id = 'f234c77f-4a04-4526-9394-c82a1bc713cf';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مافن الحديقة السحري (4 سنوات+)'), description_ar = COALESCE(description_ar, 'مافن مالح غني بالجبن والخضروات المخبأة داخله، مناسب لأخذه إلى الحديقة أو الروضة أو في الطريق.

الفائدة: خالٍ من السكر، ويجمع بين الكالسيوم (الجبن) والفيتامينات (الخضروات)، كما يسهل حمله باليد.'), category_ar = COALESCE(category_ar, 'أغذية تكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["البيض: 2 حبة","الزبادي: 2 ملعقة كبيرة","الجزر (مبشور) والكوسا (مصفّاة من مائها): نصف كوب","الجبن الأبيض: 2 ملعقة كبيرة","الدقيق والبيكنج باودر."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخفقي المكونات السائلة مع الجبن. أضيفي الخضروات، ثم أضيفي الدقيق والبيكنج باودر في النهاية، ووزّعي الخليط في قوالب المافن واخبزيه على درجة حرارة 180 لمدة 20-25 دقيقة."]'::jsonb) WHERE id = '4232cb2b-2881-4a46-bce4-1d4070cda869';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'الإكسير السحري (5 سنوات+)'), description_ar = COALESCE(description_ar, 'حلوى شهية وجذابة تُحضّر على شكل طبقات في كوب شفاف، ومناسبة للإفطار أو كتحلية.

الفائدة: يساعد الزبادي الغني بالبروبيوتيك على تنظيم الهضم، بينما يعزز التوت الجهاز المناعي.'), category_ar = COALESCE(category_ar, 'أغذية تكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الزبادي (منزلي أو مصفّى): 1 كوب","هريس توت العليق أو الفراولة: 2 ملعقة كبيرة","غرانولا خالية من السكر أو مزيج الشوفان والمكسرات: 2 ملعقة كبيرة"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي في كوب شفاف يحبه الأطفال طبقة من الزبادي أولًا، ثم هريس الفاكهة، وبعده الغرانولا. غطّي الطبقة الأخيرة بالزبادي مجددًا، وزيّني الوجه بفاكهة طازجة."]'::jsonb) WHERE id = 'aa773f2c-e3f1-47eb-9a0d-5723d6301a77';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ليمونادة زِن'), description_ar = COALESCE(description_ar, 'ماتشا فوّارة تساعد على تسريع عملية الأيض وتخفيف الانتفاخ في أيام الصيف.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة صغيرة من مسحوق الماتشا، عصير نصف ليمونة، 1 ملعقة صغيرة من شراب الأغاف أو العسل، 1 كوب من المياه المعدنية (الغازية)، أوراق النعناع، ثلج."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخفقي الماتشا في قليل من الماء مع العسل والليمون حتى تذوب. ضعي الثلج والنعناع في كوب، ثم اسكبي فوقهما مزيج الماتشا والمياه المعدنية."]'::jsonb) WHERE id = '2e2ead49-bcaf-4338-94ee-467ad791737c';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مشروب الماكا والكاكاو للطاقة'), description_ar = COALESCE(description_ar, 'مشروب مناسب للنساء، يساعد على توازن الهرمونات وزيادة القدرة على التحمل البدني.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة كبيرة من الكاكاو، 1 ملعقة صغيرة من مسحوق الماكا (maca)، 1 كوب من حليب الشوفان، 1 حبة تمر (مهروسة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات جيدًا في الخلاط مع الحليب الساخن أو البارد."]'::jsonb) WHERE id = 'da26b0d3-2e6e-4084-9b19-693dd01e5caa';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مشروب نوتيلا صحي'), description_ar = COALESCE(description_ar, 'مشروب ساخن ولذيذ يحدّ من نوبات اشتهاء الحلويات، ولا يحتوي على السكر إطلاقًا.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة كبيرة من الكاكاو، 1 ملعقة كبيرة من زبدة البندق الطبيعية (من دون سكر)، 1 كوب من الحليب الساخن."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["امزجي زبدة البندق والكاكاو مع الحليب الساخن باستخدام الخلاط أو المضرب حتى يذوبا ويصبح المزيج ناعمًا تمامًا."]'::jsonb) WHERE id = '1c2d3ae5-c16d-47ab-acbd-eff8a82af792';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بطاطا حلوة محشوة بالحمص'), description_ar = COALESCE(description_ar, 'وجبة غداء كلاسيكية من الكربوهيدرات المعقدة، مناسبة للرياضيات والمهتمات بالتغذية الصحية، وتمنح شعورًا بالشبع لمدة طويلة.

فوائدها: البطاطا الحلوة غنية بالبوتاسيوم، والحمص غني بالبروتين النباتي. إنها دفعة متكاملة من الطاقة.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["البطاطا الحلوة: 2 حبة (متوسطة الحجم)","الحمص المطهو (يمكن استخدام المعلّب أيضًا): 1 كوب","الطحينة (معجون السمسم): 2 ملعقة كبيرة","عصير الليمون، زيت الزيتون، الكمون (الكراوية)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اثقبي حبات البطاطا الحلوة بالشوكة في عدة مواضع، ثم اخبزيها في الفرن على درجة حرارة 200 درجة حتى تصبح طرية تمامًا (نحو 40 دقيقة). أخرجيها واقطعيها من المنتصف، ثم اهرسي لبّها قليلًا. احشيها بالحمص المتبّل ورشّي فوقها صلصة الطحينة والليمون."]'::jsonb) WHERE id = '1eca4e78-4116-42f3-b2fa-fb5f13684582';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'براوني بالأفوكادو'), description_ar = COALESCE(description_ar, 'براوني أسطوري «خالٍ من السكر»، يُستخدم فيه الأفوكادو بدلًا من الزبدة ودقيق اللوز بدلًا من دقيق القمح.

الفائدة: خالٍ من دقيق القمح والسكر المكرر. يمنح الأفوكادو الحلوى رطوبة مذهلة وقوامًا مخمليًا، من دون أن يظهر طعمه على الإطلاق.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الأفوكادو: 1 حبة كبيرة (ناضجة تمامًا ومهروسة)","دقيق اللوز: نصف كوب","كاكاو طبيعي (غير محلى): نصف كوب","البيض: 2 حبة","العسل أو شراب القيقب: ثلث كوب."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات في الخلاط حتى تحصلي على كريمة شوكولاتة ناعمة تمامًا. اسكبي الخليط في قالب كعك مربع مبطن بورق الخَبز، واخبزيه على درجة حرارة 175 لمدة 25-30 دقيقة. قطّعيه وهو دافئ."]'::jsonb) WHERE id = '64fd534a-ee42-4741-ad1d-2c83048a4d5e';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'قوارب البيض بالأفوكادو'), description_ar = COALESCE(description_ar, 'طبق شهي كيتوني غني بالبروتين ولا يحتوي على المايونيز.

الفائدة: يساعد بروتين بياض البيض ودهون أوميغا الموجودة في الأفوكادو على تبديد ضبابية الدماغ واستعادة الطاقة.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["بيض مسلوق جيدًا: 3 حبات","الأفوكادو: نصف حبة (ناضجة)","بذور الكتان أو الشيا: كمية قليلة جدًا (للتزيين)","عصير الليمون، الملح، الفلفل الأسود."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اقطعي البيض طوليًا إلى نصفين. أخرجي الصفار واهرسيه مع الأفوكادو وعصير الليمون والتوابل حتى تحصلي على قوام كريمي تمامًا. أعيدي حشو أنصاف بياض البيض بهذه الكريمة الخضراء. رشّي بذور الكتان على الوجه."]'::jsonb) WHERE id = 'c93f159c-1f03-4766-a5e7-3350ed9505bf';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كرات اللوز والكتان والشيا'), description_ar = COALESCE(description_ar, 'كرات طاقة مقرمشة تُحضّر من دون خَبز، ومثالية قبل ممارسة الرياضة أو إلى جانب القهوة.

