UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'أرز القرنبيط'), description_ar = COALESCE(description_ar, 'ملك حميات الكيتو والحميات منخفضة الكربوهيدرات. وصفة تحل محل الأرز بنسبة 100% ولا تسبب زيادة الوزن إطلاقًا.

الفائدة: تحتوي الحصة الواحدة على 40-50 سعرة حرارية فقط. ولا تسبب الشعور بالثقل والنعاس الذي يسببه طبق الأرز التقليدي.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["القرنبيط: نصف رأس","الجزر والبازلاء الخضراء: 2 ملعقة كبيرة من كل منهما","البصل: 1 بصلة صغيرة","زيت الزيتون والزبدة."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ابشري القرنبيط أو اطحنيه في الخلاط حتى يصبح بحجم حبات الأرز. شوّحي البصل والجزر والبازلاء في مقلاة مع قليل من الزيت. أضيفي \"أرز\" القرنبيط وقلّبيه لمدة 5-6 دقائق، من دون تركه يطرى أكثر من اللازم."]'::jsonb) WHERE id = '836bc22f-3cef-4e15-bfd2-c877bc04f782';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شوربة البروكلي الكريمية بجبن الشيدر'), description_ar = COALESCE(description_ar, 'واحدة من ألذ الشوربات الشتوية في العالم، وقد اشتهرت بفضل سلسلة مطاعم "Panera Bread" الأمريكية.

