UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سلطة الكينوا على الطريقة المكسيكية'), description_ar = COALESCE(description_ar, 'واحدة من أشهر وصفات ثقافة "Meal Prep" (تحضير الوجبات مسبقًا) في العالم الغربي.

الفائدة: ملوّنة ومشبعة وغنية بكمية كبيرة من البروتين النباتي. وتبقى طازجة في الثلاجة لمدة 3 أيام.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الكينوا (مطبوخة): 1 كوب","الفاصولياء السوداء (معلبة): نصف كوب","الذرة: نصف كوب","طماطم كرزية وبصل أحمر (مفرومان)","كزبرة طازجة، عصير الليمون الأخضر، زيت الزيتون، وفلفل الهالبينو (حسب الرغبة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات في وعاء كبير. وزّعي فوقها صلصة مكوّنة من زيت الزيتون وعصير الليمون الأخضر والكزبرة، ثم اخلطيها جيدًا."]'::jsonb) WHERE id = 'a5af4229-e447-48cc-a6f1-6146ae4643a0';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كعكة الكيتو باللوز'), description_ar = COALESCE(description_ar, 'كعكة خالية من الكربوهيدرات لمن ترغب في الشعور بالخفة وكأنها فوق السحاب.

