UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'السوفلاكي اليوناني مع التزاتزيكي'), description_ar = COALESCE(description_ar, 'ملك حمية البحر الأبيض المتوسط: بروتين نقي، وبروبيوتيك، ودهون صحية.

الفائدة: يحافظ التزاتزيكي (صلصة الزبادي والخيار) على توازن بكتيريا الأمعاء النافعة. أما لحم الدجاج فيمد الجسم بالبروتين ويسرّع عملية الأيض.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["صدر الدجاج: 200 غرام (مقطّع إلى مكعبات ومتبل بالليمون والزعتر)","الزبادي المصفّى (الزبادي اليوناني): 4 ملاعق كبيرة","الخيار: حبة واحدة (مبشورة ومعصورة جيدًا للتخلص من الماء)","نعناع طازج، ثوم، زيت زيتون."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي قطع الدجاج في أسياخ خشبية وحمّريها في المقلاة أو على الشواية. لتحضير صلصة التزاتزيكي، اخلطي الزبادي مع الخيار المعصور والثوم والنعناع وزيت الزيتون. تناولي أسياخ الدجاج بعد غمسها في هذه الصلصة المنعشة."]'::jsonb) WHERE id = 'e067e84f-8a22-4eb0-b5fa-1ae3ae37b95f';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'الراتاتوي الفرنسي'), description_ar = COALESCE(description_ar, 'طبق خضراوات ملوّن من جنوب فرنسا، نباتي بالكامل ومثالي المظهر.

الفائدة: أقل قدر من السعرات الحرارية وأقصى قدر من الألياف والفيتامينات. يحافظ طهي جميع الخضراوات ببطء في عصارتها الطبيعية على قيمتها الغذائية.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الكوسا والباذنجان والطماطم: حبتان من كل نوع (بالحجم نفسه ومقطّعة إلى شرائح رفيعة جدًا)","معجون الطماطم والثوم (لتحضير الصلصة السفلية).","أعشاب بروفانس (الزعتر وإكليل الجبل)، زيت الزيتون."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["وزّعي صلصة الطماطم في قاع صينية فرن دائرية. رتّبي شرائح الخضراوات بحسب ألوانها (الباذنجان، الطماطم، الكوسا) بشكل حلزوني من حافة الصينية نحو المنتصف. رشّي فوقها الأعشاب وزيت الزيتون، ثم غطّيها واخبزيها على درجة حرارة 190 لمدة 45 دقيقة."]'::jsonb) WHERE id = '3a7875bd-9bf1-4570-9e1d-e51c83452192';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'حساء الميسو الياباني'), description_ar = COALESCE(description_ar, 'حساء خفيف ومخمّر، يُتناول صباحًا أو مساءً، ويُعدّ أحد أسرار طول عمر اليابانيين.

