UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'طبق الزبادي المصفّى وبذور الشيا (1 سنة+)'), description_ar = COALESCE(description_ar, 'وجبة غنية بالبروبيوتيك والكالسيوم، مناسبة كوجبة خفيفة أو عشاء خفيف.

الفائدة: يساهم الزبادي في إثراء البكتيريا النافعة في الأمعاء، بينما توفّر بذور الشيا أوميغا-3.'), category_ar = COALESCE(category_ar, 'أغذية تكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['طعام الرضّع']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["زبادي مصفّى أو زبادي يوناني: 2-3 ملعقة طعام","بذور الشيا: نصف ملعقة صغيرة (منقوعة مسبقًا في 1 ملعقة من الماء حتى تنتفخ)","توت العليق أو الفراولة: 2-3 حبة (مهروسة كالبوريه)","عسل: كمية بطرف ملعقة صغيرة (آمن للأطفال فوق عمر 1 سنة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي الزبادي وبذور الشيا المنقوعة وبوريه الفاكهة المهروسة وكمية قليلة جدًا من العسل في وعاء. ستحصلين على حلوى لذيذة سيجذب لونها طفلكِ."]'::jsonb) WHERE id = '90e2d20f-198b-4417-92bb-ccab337989e6';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سلطة المعكرونة (لعمر سنتين+)'), description_ar = COALESCE(description_ar, 'تساعد الألوان والقوامات المختلفة على تنمية المهارات الحركية والفضول لدى الطفل في عمر سنتين.

