UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وافل البطاطا الحلوة (لعمر سنتين+)'), description_ar = COALESCE(description_ar, 'وافل مقرمش يسهل إمساكه باليد للأطفال الذين ملّوا من البان كيك.

