UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ناجتس منزلي (لعمر 4 سنوات+)'), description_ar = COALESCE(description_ar, 'ناجتس مقرمش مخبوز في الفرن ومحضّر منزليًا بنسبة 100%، يساعد على الحد من الرغبة في تناول الوجبات السريعة.

