UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'دونات التفاح (4 سنوات+)'), description_ar = COALESCE(description_ar, 'دونات تُحضَّر من دون عجين أو سكر، ويتحوّل إعدادها إلى لعبة ممتعة للأطفال.

