UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وافل السبانخ (5 سنوات+)'), description_ar = COALESCE(description_ar, 'وافل يجذب انتباه الأطفال بلونه الأخضر ويمنحهم "قوة التنين" في الصباح.

