UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مافن الكنز الذهبي (5 سنوات+)'), description_ar = COALESCE(description_ar, 'مافن بالبيض يحتوي على "كنوز" ملوّنة ويشجّع الأطفال الذين لا يحبون البيض على تناوله.

