UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سوتيه البطاطا الحلوة'), description_ar = COALESCE(description_ar, 'مذاق مميز غني بالألياف والكربوهيدرات المعقدة ويمنحكِ شعورًا بالشبع.

