UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شوربة البروكلي والسبانخ'), description_ar = COALESCE(description_ar, 'أفضل عشاء «سائل» لتستيقظي صباحًا ببطن مسطحة ومرتاحة.

