UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'الدجاج بالليمون والهليون'), description_ar = COALESCE(description_ar, 'وجبة صحية تُحضّر في مقلاة واحدة، تبدو بسيطة لكنها ذات مظهر «فاخر» للغاية.

