UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سحابة البروتين - فطائر الجبن القريش'), description_ar = COALESCE(description_ar, 'فطائر خالية من الدقيق وغنية بالبروتين، تُشبع رغبتكِ في تناول الحلوى بطريقة صحية.

