UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ليمونادة الماتشا'), description_ar = COALESCE(description_ar, 'مشروب ثنائي اللون غني بمضادات الأكسدة، يمنح طاقة متوازنة من دون التسبب بارتفاع مفاجئ في النشاط.

الفائدة: لا تمنح الماتشا دفعة مفاجئة من الطاقة يتبعها الإرهاق كما قد تفعل القهوة، بل تساعد على الحفاظ على نشاط متوازن طوال اليوم.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["مسحوق الماتشا: 1 ملعقة شاي (مخفوق في ماء فاتر حتى تتكوّن الرغوة)","عصير ليمون طازج: ثلث كوب","شراب الأغاف أو العسل: 1 ملعقة طعام","ماء وكمية وفيرة من الثلج."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي مكعبات الثلج في الكوب. امزجي عصير الليمون والعسل والماء واسكبي المزيج فوقها. وفي النهاية، أضيفي الماتشا الخضراء المخفوقة ببطء (وبذلك تتكوّن طبقتان لونيتان في الكوب: صفراء في الأسفل وخضراء في الأعلى)."]'::jsonb) WHERE id = 'cb10f111-6a9d-4baa-9dd6-af7ef8393f1e';
