UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كرات البروكلي والجبن (لعمر سنة فأكثر)'), description_ar = COALESCE(description_ar, 'ألذّ طريقة مقرمشة وممتعة لجعل طفلكِ يحب البروكلي.

