UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'عصيدة الملكة - صباح الملكة'), description_ar = COALESCE(description_ar, 'مزيج يجمع بين طاقة التمر والجوز وقدرة الشوفان على زيادة إدرار الحليب. محفّز للبرولاكتين.'), category_ar = COALESCE(category_ar, 'الإفطار'), ingredients_ar = COALESCE(ingredients_ar, '["الشوفان: 3 ملاعق كبيرة","الحليب: 1 كوب","التمر: 2-3 حبات (منزوع النوى)","الجوز: 1 حفنة","القرفة: رشة"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اطهي الحليب والشوفان في قدر على نار متوسطة مع التحريك","واصلي التحريك حتى يصبح المزيج كثيفًا (5-7 دقائق)","ارفعيه عن النار وأضيفي التمر المقطّع","رشّي الجوز والقرفة","تناوليه ساخنًا، فهو من أقوى وجبات الإفطار لزيادة إدرار الحليب"]'::jsonb) WHERE id = 'e130e1c4-d49f-409f-844e-56265cb3eca7';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'إكسير الديتوكس الأخضر'), description_ar = COALESCE(description_ar, '«عصير أخضر» فائق يساعد على تنقية الكبد والبشرة وتجديد الخلايا.

