UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'خوخ بالقرفة في الفرن'), description_ar = COALESCE(description_ar, 'حلوى خفيفة جدًا تمنحكِ إحساس الآيس كريم، لكن بسعرات حرارية تكاد لا تُذكر.

فوائدها: الخوخ غني بالألياف (ما يساعد على تسريع الهضم)، بينما تساعد القرفة على موازنة مستوى السكر في الدم بسرعة.'), category_ar = COALESCE(category_ar, 'حلويات صحية'), ingredients_ar = COALESCE(ingredients_ar, '["الخوخ: 2 حبة (مقسّمتان إلى نصفين ومنزوعتا النوى)","القرفة: 1 ملعقة صغيرة","الجوز أو جوز البقان: مجروش","لبن زبادي مُصفّى (للتقديم)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["رتّبي أنصاف الخوخ في صينية فرن، ورشّي القرفة والجوز في وسطها. اخبزيها على حرارة 180 درجة لمدة 15-20 دقيقة حتى تصبح طرية. تناوليها دافئة بعد وضع ملعقة من اللبن الزبادي المُصفّى في وسطها."]'::jsonb) WHERE id = 'e7b8a04c-a4fa-4769-bbd9-6735976b643a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'اليقطين وحليب جوز الهند
