UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وعاء الكينوا والخضراوات'), description_ar = COALESCE(description_ar, 'مصدر نباتي بالكامل للطاقة، غني بالألوان ومُشبع.

