UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'الواحة الاستوائية'), description_ar = COALESCE(description_ar, 'أنقى مشروب يساعد على استعادة توازن السوائل في الجسم (الإلكتروليتات) وتقليل الوذمة.

