UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سلطة الأفوكادو والدجاج'), description_ar = COALESCE(description_ar, 'طبق شهي منخفض الكربوهيدرات، يمنحكِ شعورًا بالشبع لفترة طويلة ويغذي العضلات.

