UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'معكرونة بالسبانخ (4 سنوات+)'), description_ar = COALESCE(description_ar, 'صلصة سحرية بالجبن، غنية بالحديد وتجذب الأطفال بلونها الأخضر.

