UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كرات اللحم الخارقة (2 سنة+)'), description_ar = COALESCE(description_ar, 'كرات لحم مخبوزة في الفرن بمفاجأة في داخلها، سيستمتع بتناولها حتى الأطفال الذين لا يحبون اللحم.

