UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'أرز بالخضراوات (4 سنوات+)'), description_ar = COALESCE(description_ar, 'أرز مفعم بأجواء الاحتفال ومليء بالخضراوات الملونة.

الفائدة: وجبة غداء مشبعة تجمع الكربوهيدرات والفيتامينات والألياف في قدر واحد.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["أرز بسمتي أو أرز طويل الحبة: 1 كوب","جزر، بازلاء خضراء، فلفل أحمر حلو، ذرة: 2 ملعقة طعام من كل نوع (مقطعة إلى مكعبات صغيرة)","زبدة ومرق دجاج."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["شوّحي الخضراوات قليلًا في الزبدة. أضيفي الأرز المغسول والمرق، ثم اطهيه حتى يمتص السائل وتنفصل حبات الأرز عن بعضها."]'::jsonb) WHERE id = 'f04550c5-0fdb-4ab9-8b7b-831a4d2f5e5a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شريحة القرنبيط المشوية في الفرن'), description_ar = COALESCE(description_ar, 'أشهر "بديل للحوم" في عالم التغذية النباتية والصحية، ويشبه شريحة اللحم في مظهره.

الفائدة: منخفض جدًا في السعرات الحرارية وغني بالألياف، وعند طهيه في الفرن تتكرمل السكريات الطبيعية الموجودة في القرنبيط، ما يمنحه مذاقًا رائعًا.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["القرنبيط: رأس كامل واحد (كبير جدًا)","زيت الزيتون: ملعقتان كبيرتان","مسحوق الثوم، مسحوق الفلفل الأحمر الحلو (بابريكا)، ملح البحر، فلفل أسود."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اغسلي رأس القرنبيط كاملًا، ثم اقطعي من وسطه شرائح كاملة بسمك 2 سنتيمتر على شكل \"شرائح لحم\". ضعيها في صينية الفرن وادهني جانبيها بزيت الزيتون وخليط التوابل باستخدام فرشاة. اخبزيها على حرارة 200 درجة حتى يتحمر الجانبان (نحو 25-30 دقيقة)."]'::jsonb) WHERE id = 'dbb5731f-3844-4a55-a0b0-63c083018f90';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بيض على شكل قوارب (3 سنوات فأكثر)'), description_ar = COALESCE(description_ar, 'وجبة خفيفة ممتعة على شكل "قارب" للأطفال الذين لا يحبون صفار البيض.

الفائدة: يُعد الكولين الموجود في صفار البيض من أهم العناصر لنمو دماغ الطفل في عمر 3 سنوات وتطور ذاكرته بسرعة.'), category_ar = COALESCE(category_ar, 'التغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['طعام_الطفل']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["بيض مسلوق جيدًا: حبتان","زبادي: ملعقة صغيرة واحدة","فلفل ملون مفروم إلى قطع صغيرة جدًا (ليكون \"كنوزًا\")","جبن: شرائح رقيقة مثلثة الشكل (للشراع) وأعواد أسنان."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اقطعي البيض بالطول إلى نصفين. أخرجي الصفار واهرسيه مع الزبادي، ثم أضيفي إليه قطع الفلفل الملون (الكنوز) وأعيدي حشو بياض البيض بالخليط. ثبّتي مثلث الجبن في عود أسنان واغرسيه في البيضة ليبدو مثل \"الشراع\" (لا تنسي إزالة العود قبل الأكل!)."]'::jsonb) WHERE id = '38175de9-042b-4fc9-8a58-cdff56307d6d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'فطر بورتوبيللو محشو'), description_ar = COALESCE(description_ar, '"قبعات" رائعة تمنحكِ قوام اللحم ومذاقه من دون تناول اللحوم الحمراء.

الفائدة: فطر بورتوبيللو غني بمعدن السيلينيوم الذي يحمي البشرة من الشيخوخة. كما أنه سهل الهضم جدًا ولا يثقل المعدة.'), category_ar = COALESCE(category_ar, 'العشاء'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فطر بورتوبيللو: حبتان كبيرتان (منزوعتا الساق ومُنظفتان من الداخل)","سبانخ: حفنة واحدة (مفرومة)","كينوا (أو برغل): ملعقتان كبيرتان (مطهوة)","جبن فيتا (أو جبن أبيض): ملعقة كبيرة واحدة"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["احشي الفطر بخليط الكينوا والسبانخ والجبن. ضعيه في طبق للفرن ورشّي فوقه قليلًا من زيت الزيتون. اخبزيه على حرارة 180 درجة حتى يصبح الفطر طريًا."]'::jsonb) WHERE id = 'fef93b73-64a7-48d4-94bf-fe08f3ed1adc';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'توست الأفوكادو ببذور الشيا'), description_ar = COALESCE(description_ar, 'نسخة مشبعة من توست الأفوكادو الكلاسيكي، غنية بأوميغا-3 وأكثر قرمشة.

الفائدة: يشكّل مزيج بذور الشيا والأفوكادو تركيبة مثالية من الدهون الصحية التي تساعد على ترطيب البشرة من الداخل.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["خبز أسمر أو خبز من القمح الكامل: شريحة واحدة (محمصة)","أفوكادو: نصف حبة (ناضجة)","بذور الشيا: 1 ملعقة صغيرة","عصير ليمون، ملح بحري، ورقائق فلفل أحمر حار."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اهرسي الأفوكادو بالشوكة واخلطيه مع الليمون والملح. وزّعي كمية وفيرة منه على الخبز المحمص. وأخيرًا، رشي بذور الشيا ورقائق الفلفل الأحمر الحار لإضفاء القرمشة والحصول على فوائد إضافية."]'::jsonb) WHERE id = '87d23e0f-a0db-4aa1-b0fb-794cb2b35b28';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مشروب الورد والتوت الفوّار'), description_ar = COALESCE(description_ar, 'دعم سائل بالكولاجين ومضادات الأكسدة لبشرتكِ. مشروب رقيق ومنعش للغاية.

الفائدة: يساعد التوت على إبطاء شيخوخة الخلايا، بينما يرطّب ماء الورد البشرة من الداخل ويمنحها توهجًا طبيعيًا.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["توت العليق الطازج أو الفراولة: حفنة واحدة","ماء الورد (صالح للشرب ومن دون إضافات): 1 ملعقة كبيرة","ماء فوّار (مياه معدنية): 1 كوب","ليمون أخضر: شريحة واحدة","مكعبات ثلج."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اهرسي التوت بالشوكة في قاع الكوب. أضيفي مكعبات الثلج وماء الورد وعصير الليمون الأخضر. وفي النهاية، اسكبي الماء الفوّار وحرّكي المزيج."]'::jsonb) WHERE id = 'f84c1bc3-0bf2-4206-b695-21d5ec9708da';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'حلوى الكركم'), description_ar = COALESCE(description_ar, 'حلوى إيطالية كلاسيكية مضادة للالتهاب وتمنح البشرة إشراقة.

الفائدة: يساعد الكركم وحليب جوز الهند على علاج حب الشباب من الداخل، بينما يُعد الجيلاتين مصدرًا طبيعيًا للكولاجين الذي يقوّي الأظافر والشعر.'), category_ar = COALESCE(category_ar, 'حلويات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["حليب جوز الهند (معلّب وكثيف القوام): 1 كوب","مسحوق الكركم: 1 ملعقة صغيرة","عسل: 2 ملعقة كبيرة","أوراق جيلاتين: 2 (أو 1 ملعقة صغيرة من الأجار أجار)"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["انقعي الجيلاتين في ماء بارد. سخّني الحليب في قدر (من دون غليه)، ثم أضيفي إليه الكركم والعسل والجيلاتين بعد أن يلين، وحرّكي المزيج. صفّيه في أوعية زجاجية صغيرة واتركيه يتماسك في الثلاجة لمدة 3-4 ساعات."]'::jsonb) WHERE id = '792abbe5-dddc-4848-8d97-bdcb84318aee';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'فطائر الفلامنغو الوردية (3 سنوات+)'), description_ar = COALESCE(description_ar, 'فطور بلون وردي طبيعي يسحر الأطفال، من دون أي ملونات غذائية.

الفائدة: يعزز الشمندر الدورة الدموية ويدعم المناعة، بينما يساعد الشوفان الطفل على الشعور بالشبع والحيوية لفترة طويلة.'), category_ar = COALESCE(category_ar, 'أغذية تكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["هريس الشمندر: 1 ملعقة كبيرة (من شمندر مطهو)","بيضة: 1","دقيق الشوفان: 3 ملاعق كبيرة","الحليب: نصف كوب شاي","العسل: كمية قليلة جدًا (للتحلية)"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات في الخلاط حتى تحصلي على عجينة وردية ناعمة تمامًا. شكّلي منها دوائر صغيرة في مقلاة من دون زيت واطهيها على الجانبين."]'::jsonb) WHERE id = '3c637a80-dd91-4c2f-bf85-45f21dbc4610';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كرات النيازك للطاقة (5 سنوات+)'), description_ar = COALESCE(description_ar, 'وجبة خفيفة بطعم "الشوكولاتة"، خالية من السكر وسهلة الحمل في الجيب عند الذهاب إلى الروضة أو الحديقة.

الفائدة: يوفر التمر والكاكاو طاقة سريعة، بينما تغذي المكسرات أو البندق البشرة والشعر بفضل دهون أوميغا-3.'), category_ar = COALESCE(category_ar, 'أغذية تكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["تمر طري: 8-10 حبات (منزوع النوى)","الشوفان: نصف كوب","كاكاو (غير محلى): 1 ملعقة كبيرة","بندق أو بذور دوار الشمس: 2 ملعقة كبيرة."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات في الخلاط حتى تصبح كتلة متماسكة ولزجة. شكّلي بيديكِ \"نيازك\" صغيرة. يمكنكِ أيضًا رش جوز الهند المبشور عليها. ضعيها في الثلاجة لمدة 30 دقيقة ثم قدّميها."]'::jsonb) WHERE id = '13882a92-abb0-49d4-b8c0-e8f4f9c2ea1b';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بودينغ بذور الكتان والشيا'), description_ar = COALESCE(description_ar, 'بودينغ يستغرق تحضيره دقيقتين فقط، مناسب للفطور أو كوجبة خفيفة، لطيف على الهضم ويساعد على الشعور بالشبع.

الفائدة: تمتص بذور الشيا والكتان كمية من الماء تفوق وزنها عدة مرات فتنتفخ، مما يعزز الشعور بالشبع في المعدة ويساعد على تنظيم سكر الدم.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["بذور الشيا: 2 ملعقة كبيرة","بذور الكتان (مطحونة): 1 ملعقة كبيرة","حليب اللوز (أو حليب جوز الهند): 1 كوب","مستخلص الفانيليا الطبيعي و1 ملعقة صغيرة من العسل."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات جيدًا في مرطبان. بعد 10 دقائق، اخلطيها مجددًا لمنع تشكل الكتل ثم ضعيها في الثلاجة (لمدة ساعتين على الأقل أو طوال الليل). زيّنيها بالفواكه وتناوليها."]'::jsonb) WHERE id = '9a57e53c-6cc6-4002-bebc-5ba8dd87a146';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بسكويت الياقوت'), description_ar = COALESCE(description_ar, 'بسكويت "بصمة الإبهام" بالمربى، خالٍ من الدقيق والغلوتين، مثالي لوقت الشاي.

الفائدة: يغذي دقيق اللوز البشرة بفيتامين E، بينما تساعد "مربى" الشيا المحضّرة منزليًا على تلبية الاحتياج إلى أوميغا-3.'), category_ar = COALESCE(category_ar, 'حلويات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["دقيق اللوز: 1.5 كوب","العسل أو شراب الأغاف: 3 ملاعق كبيرة","زيت جوز الهند: ملعقتان كبيرتان (مذاب)","توت العليق الطازج وملعقة كبيرة من بذور الشيا (لتحضير المربى)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اهرسي توت العليق بالشوكة وامزجيه مع الشيا (اتركيه جانبًا لمدة 15 دقيقة حتى يتكاثف). اعجني دقيق اللوز مع الزيت والعسل وشكّلي كرات صغيرة. اصنعي تجويفًا في وسط كل كرة بإصبعكِ، ثم اخبزيها في الفرن على درجة حرارة 160 لمدة 10 دقائق. أخرجيها واملئي التجاويف بمربى توت العليق والشيا."]'::jsonb) WHERE id = '6b9ff319-0e3b-432c-ae21-5efca3c9d50d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مهروس الشمندر والتفاح
(7 أشهر+)'), description_ar = COALESCE(description_ar, 'مهروس حلو يدعم المناعة ويضفي لونًا ورديًا على وجنتي طفلكِ.

الفائدة: يحتوي الشمندر على عناصر غذائية تدعم تكوين الدم، بينما يخفف التفاح نكهته الترابية.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الشمندر: حبة صغيرة واحدة","التفاح: نصف حبة"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اسلقي الشمندر بقشره أو اخبزيه في الفرن (للحفاظ على فيتاميناته). ثم قشّريه واخلطيه مع التفاح في الخلاط حتى يصبح مهروسًا ناعمًا تمامًا. انتبهي كي لا ينسكب على ملابس طفلكِ!"]'::jsonb) WHERE id = '55df2691-7b63-4f38-bfb6-d946010b6903';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كب كيك قوس قزح المالح (عمر سنتين+)'), description_ar = COALESCE(description_ar, 'كب كيك مالح يبدو كالحلوى، لكنه في الحقيقة محضّر بالخضراوات والجبن.

الفائدة: طريقة عملية لتشجيع الطفل الانتقائي في الطعام على تقبّل أنواع مختلفة من الخضراوات (الفلفل الملون والخضراوات الورقية). كما أنه مثالي لاصطحابه معكِ عند الذهاب إلى الحديقة.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["البيض: حبتان","الزبادي: ملعقتان كبيرتان","زيت الزيتون: ملعقة كبيرة واحدة","الفلفل الأحمر والسبانخ: مفرومان ناعمًا جدًا (1-2 ملعقة كبيرة)","الجبن (مبشور): ملعقتان كبيرتان","الدقيق والبيكنج باودر (حتى تحصلي على عجينة كب كيك كثيفة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخفقي المكونات السائلة (البيض والزبادي والزيت). أضيفي الخضراوات والجبن.","أضيفي الدقيق والبيكنج باودر في النهاية وامزجي المكونات.","وزّعي الخليط في قوالب المافن (الكب كيك)، واخبزيه على درجة حرارة 180 لمدة 20 دقيقة حتى ينتفخ ويكتسب لونًا ذهبيًا."]'::jsonb) WHERE id = '03922c9b-57cd-4e60-9084-3b45e0d48642';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كرات ترافل الماتشا والفستق الحلبي'), description_ar = COALESCE(description_ar, 'مرافق "premium" للقهوة يسرّع عملية الأيض ويجدد شباب البشرة.

الفائدة: شاي الماتشا مضاد أكسدة قوي يسرّع تجدد الخلايا. ويرطب الكاجو والفستق الحلبي البشرة بفضل الدهون الصحية.'), category_ar = COALESCE(category_ar, 'حلويات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["كاجو (نيئ ومنقوع): 1 كوب","تمر: 5-6 حبات","مسحوق الماتشا: 1 ملعقة كبيرة (مع كمية إضافية للتغطية)","فستق حلبي: نصف كوب (مجروش)"]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي جميع المكونات (باستثناء نصف كمية الفستق الحلبي) في الخلاط حتى تتكون عجينة لزجة. شكّليها إلى كرات بيديكِ، ثم غطّي نصفها بمسحوق الماتشا والنصف الآخر بالفستق الحلبي المجروش."]'::jsonb) WHERE id = 'ceb5db8c-58a7-4fde-a771-d2ed012eb9df';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'طاجين الخضراوات المغربي'), description_ar = COALESCE(description_ar, 'طبق من شمال أفريقيا يُطهى ببطء في أوانٍ خاصة، ويجمع بين النكهات الحلوة والمالحة للخضراوات والفواكه.

الفائدة: يوفر الحمص والخضراوات كربوهيدرات معقدة تساعد على تنظيم سكر الدم. ويُحلّى طبيعيًا بالفواكه المجففة دون إضافة السكر.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["حمص (مطهو): 1 كوب","جزر وكوسا وبطاطا حلوة (مقطعة إلى قطع كبيرة).","مشمش مجفف أو زبيب: نصف كوب","قرفة وكمون ومسحوق زنجبيل وزيت زيتون ومرق خضراوات."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["سخّني التوابل مع الزيت في قدر عميق (أو في إناء الطاجين التقليدي). أضيفي الخضراوات والحمص والفواكه المجففة. اسكبي المرق فوقها، ثم غطّي القدر واطهيها على نار هادئة حتى تنضج الخضراوات تمامًا وتصبح طرية (40-45 دقيقة). قدّميها مع الكينوا أو الكسكس."]'::jsonb) WHERE id = '71967587-de0b-4a79-8b91-69af7cbe3013';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وعاء السموذي (لعمر 4 سنوات فأكثر)'), description_ar = COALESCE(description_ar, 'حلوى مرحة تؤكل بالملعقة وتساعد الطفل على الاستمتاع بالخضراوات والفواكه في صورة سائلة.

الفائدة: مزيج غني بالفيتامينات المعززة للمناعة، ومثالي كوجبة خفيفة لطفلكِ في فترة الظهيرة.'), category_ar = COALESCE(category_ar, 'التغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['طعام_الأطفال']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["سبانخ: 1 حفنة","موز مجمد: 1 حبة","كيوي: 1 حبة","زبادي أو حليب: نصف كوب","للتزيين: \"أشواك\" أو عظام ديناصور مقطعة من شرائح الكيوي."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي السبانخ والموز والكيوي والحليب في الخلاط حتى تحصلي على مزيج كريمي كثيف. اسكبيه في وعاء وزيّني سطحه بشرائح الكيوي لتبدو مثل ظهر ديناصور."]'::jsonb) WHERE id = '989c089a-7705-4f4f-aa06-64d202a23310';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شمس توسكانا'), description_ar = COALESCE(description_ar, 'نسخة خفيفة وصحية وغير مقلية من الطبق الإيطالي الشهير "Melanzane alla Parmigiana".

الفائدة: الباذنجان غني بمضادات الأكسدة. ولأنه يُخبز في الفرن بدلًا من قليه بالطريقة التقليدية، فهو منخفض السعرات الحرارية جدًا، ومع ذلك يمنحكِ شعورًا بالشبع بفضل البروتين الموجود في الأجبان الإيطالية.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["الباذنجان: 2 حبة كبيرة (مقطّعة إلى شرائح طولية)","معجون الطماطم الطبيعي: 2 كوب (منكّه بالثوم والريحان)","جبن الموزاريلا والبارميزان: مبشوران","ريحان طازج، وزيت زيتون."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ادهني شرائح الباذنجان بزيت الزيتون، ثم اخبزيها في الفرن حتى تصبح طرية (15 دقيقة). رتّبيها في طبق فرن عميق على شكل طبقات مثل اللازانيا: صلصة الطماطم، ثم الباذنجان، فالجبن والريحان. اخبزيها على درجة حرارة 190 لمدة 20 دقيقة، حتى تذوب طبقة الجبن العلوية وتكتسب لونًا ذهبيًا."]'::jsonb) WHERE id = '9e271ac6-efc7-4123-9cc8-b60e93936503';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ألواح الزبادي بالرمان'), description_ar = COALESCE(description_ar, 'بديل رائع للمثلجات، منعش ومقرمش في الوقت نفسه.

الفائدة: بذور الرمان غنية بالإستروجينات النباتية ومضادات الأكسدة التي تساعد على دعم توازن هرمون الإستروجين لدى النساء. أما الزبادي فهو مصدر للبروبيوتيك.'), category_ar = COALESCE(category_ar, 'حلويات صحية'), ingredients_ar = COALESCE(ingredients_ar, '["الزبادي (اليوناني أو المصفّى): 1.5 كوب","العسل: 1 ملعقة كبيرة","بذور الرمان: نصف كوب","الفستق: 2 ملعقة كبيرة (مفروم)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اخلطي الزبادي مع العسل، ثم افردي الخليط بسماكة 0.5 سم في صينية مسطحة مبطنة بورق الخَبز. انثري فوقه بذور الرمان والفستق، ثم ضعيه في المجمّد لمدة 3 ساعات. بعد أن يتجمّد، كسّريه بيديكِ إلى قطع مثل الشوكولاتة."]'::jsonb) WHERE id = '80d2e83c-c415-4e59-854e-3c904d65b0ff';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'وعاء البروتين بالدجاج والكينوا
(9 أشهر+)'), description_ar = COALESCE(description_ar, 'مصدر للطاقة طويلة الأمد للرضّع الذين ازدادت حركتهم وبدأوا بالحبو.

الفائدة: الدجاج مصدر للبروتين الصافي، أما الكينوا فهي غذاء فائق خالٍ من الغلوتين ومن أعلى الحبوب قيمةً غذائية.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['طعام_الرضع']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["صدر الدجاج: 30 غرامًا","الكوسا: أقل من نصف حبة","الكينوا: 1 ملعقة كبيرة (منقوعة ومغسولة مسبقًا)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اسلقي الدجاج وتخلّصي من ماء السلق الأول. أضيفي الكينوا والكوسا المقطّعة إلى ماء السلق الثاني، واطهيها حتى تصبح جميع المكونات طرية تمامًا. بعد ذلك، اخلطيها بالخلاط أو اهرسيها بالشوكة مع ترك قوام خشن قليلًا."]'::jsonb) WHERE id = '45628e71-5b41-431f-b26f-8283c2b308a2';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كرات اللحم بالخضروات (لعمر 1 سنة فأكثر)'), description_ar = COALESCE(description_ar, 'كرات لحم طرية «تختبئ» بداخلها الخضروات، للأطفال الذين يرفضون تناولها.

الفائدة: يلبّي اللحم الأحمر احتياجات الجسم من الحديد، بينما توفّر الخضروات المخفية الألياف والفيتامينات. وهي مثالية ليمسكها الطفل بيده ويتناولها بنفسه.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["لحم عجل مفروم قليل الدهن: 150 qr","كوسا وجزر: ربع حبة من كل منهما (مبشوران ناعمًا جدًا ومعصوران للتخلص من الماء)","بصل: قطعة صغيرة جدًا (مبشورة)","زيت الزيتون."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اعجني جميع المكونات جيدًا. شكّلي كرات لحم صغيرة بحجم حبة الجوز. اخبزيها في فرن مفروش بورق الخَبز على حرارة 180 درجة لمدة 20-25 دقيقة، مع الحرص على ألّا تجف."]'::jsonb) WHERE id = '2369413b-697e-4e19-93a2-ff9c61cde8f7';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'أصابع الخضروات المخبوزة (لعمر 5 سنوات فأكثر)'), description_ar = COALESCE(description_ar, 'أصابع خضروات ملوّنة ومقرمشة، مخبوزة في الفرن، لتكون بديلًا صحيًا للبطاطس المقلية الضارة.

الفائدة: يُعدّ الجزر والبطاطا الحلوة مصدرين غنيين بفيتامين A والبيتا كاروتين، ويساعدان في الحفاظ على صحة العينين والبشرة.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["بطاطا حلوة وجزر وكوسا: نصف حبة من كل منها","زيت الزيتون: 1 ملعقة كبيرة","نعناع مجفف أو زعتر، وقليل من الملح."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["قطّعي الخضروات بأحجام متساوية على شكل أصابع طويلة كالعصا السحرية. اخلطيها بالزيت والتوابل، ثم رتّبيها جنبًا إلى جنب في صينية الفرن. اخبزيها على حرارة 200 درجة لمدة 20-25 دقيقة، حتى تتحمّر أطرافها."]'::jsonb) WHERE id = 'a67b3fb0-1d8c-4568-bbb8-eea9c5b74c3a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'إكسير الماتشا الذهبي'), description_ar = COALESCE(description_ar, 'مزيج رائع يجمع بين الكركم المضاد للالتهاب والماتشا المعزّزة للطاقة.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة صغيرة من الماتشا، نصف ملعقة صغيرة من الكركم، رشة من الفلفل الأسود، 1 كوب من حليب اللوز الدافئ، 1 ملعقة صغيرة من العسل."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أضيفي جميع المكونات إلى الحليب الدافئ، واخلطيها جيدًا حتى تتكوّن الرغوة."]'::jsonb) WHERE id = '244e5027-cbdf-4e83-8b58-62158b64f304';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'أصابع السمك المقرمشة (لعمر سنتين فأكثر)'), description_ar = COALESCE(description_ar, 'نسخة طبيعية 100% وغير مقلية من أصابع السمك المجمّدة التي تُباع في المتاجر.

الفائدة: يوفّر السمك أحماض أوميغا-3 الدهنية الضرورية لنمو دماغ طفلكِ وعينيه.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فيليه سمك أبيض (مثل القاروص، منزوع العظام): 100 غرام (مقطّع إلى شرائح طولية)","بيضة: 1 (مخفوقة)","دقيق الشوفان (للتغليف)","زيت زيتون وقليل من الملح."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["غمّسي شرائح السمك أولًا في البيض، ثم غلّفيها بدقيق الشوفان.","رتّبيها في صينية فرن مبطنة بورق الخَبز، وادهنيها بكمية قليلة جدًا من زيت الزيتون.","اخبزيها على حرارة 190 درجة لمدة 15 دقيقة حتى تصبح مقرمشة."]'::jsonb) WHERE id = 'cf74a166-77b4-4cd9-978f-5f84fbaf4d6d';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كاساديا سوبرمان (لعمر 5 سنوات فأكثر)'), description_ar = COALESCE(description_ar, 'طبق مكسيكي شهي محشو بالخضروات المخفية، ويحب الأطفال تناوله بأيديهم.

الفائدة: الفاصولياء السوداء والدجاج مصدران للبروتين النقي، والجبن غني بالكالسيوم الذي يقوّي العظام.'), category_ar = COALESCE(category_ar, 'الأغذية التكميلية'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["خبز لافاش مصنوع من دقيق القمح الكامل (تورتيلا): 1","جبن هولندي (مبشور): ملعقتان كبيرتان","فاصولياء سوداء (مطبوخة) وذرة: ملعقة كبيرة","دجاج مفتّت: ملعقة كبيرة","سبانخ (مفرومة فرمًا ناعمًا جدًا): بضع أوراق."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["وزّعي الجبن والدجاج والفاصولياء والذرة والسبانخ على نصف خبز اللافاش. اطوي النصف الآخر فوقه ليصبح على شكل نصف دائرة. حمّريه في مقلاة ساخنة من الجانبين حتى يذوب الجبن ويصبح الخبز مقرمشًا. قطّعيه إلى مثلثات وقدّميه."]'::jsonb) WHERE id = '495abf5b-aca7-4840-8cc2-c8a7f267da78';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'كاري البطاطا الحلوة والعدس'), description_ar = COALESCE(description_ar, 'طبق كلاسيكي من المطبخ الهندي، نباتي وخالٍ من الغلوتين وغني بالتوابل المضادة للالتهاب.

الفائدة: يدعم الكاري والكركم المناعة، بينما تضيف البطاطا الحلوة مذاقًا حلوًا طبيعيًا وقوامًا حريريًا إلى الطبق.'), category_ar = COALESCE(category_ar, 'general'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["بطاطا حلوة: 1 حبة كبيرة (مقطّعة إلى مكعبات)","عدس أحمر: 1 كوب","حليب جوز الهند (الكثيف المعلّب): 1 كوب","مسحوق الكاري: ملعقة كبيرة","سبانخ: حفنة واحدة."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["شوّحي البصل والثوم ومسحوق الكاري في الزيت. أضيفي البطاطا الحلوة والعدس وحليب جوز الهند وكوبين من الماء. اتركي المزيج يُطهى على نار هادئة حتى تنضج الخضروات تمامًا. عند رفعه عن النار، أضيفي السبانخ وقلّبيها."]'::jsonb) WHERE id = '405b0576-a236-4ed8-8698-3423fb1d2ff0';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'القرنبيط على طريقة بافالو'), description_ar = COALESCE(description_ar, 'بديل نباتي 100% وصحي للطبق الأمريكي الشهير "Buffalo Wings" (أجنحة الدجاج).

الفائدة: يُشبع تمامًا الرغبة في تناول الوجبات السريعة المقرمشة، لكن باستخدام القرنبيط الغني بالألياف بدلًا من الدجاج، والفرن بدلًا من القلي.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["القرنبيط: 1 رأس (مقسّم إلى زهرات)","دقيق القمح الكامل والماء: لتحضير خليط بقوام عجينة البان كيك","صلصة بافالو الحارة (أو خليط من أي صلصة حارة مع الزبدة)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اغمسي زهرات القرنبيط في خليط الدقيق والماء، ثم رتّبيها في صينية الفرن. اخبزيها على درجة حرارة 200 لمدة 20 دقيقة. أخرجيها ووزّعي فوقها الصلصة الحارة، ثم أعيديها إلى الفرن لمدة 10 دقائق أخرى حتى تصبح الحواف مقرمشة."]'::jsonb) WHERE id = '287fe4e5-acde-487e-8549-304293001ae7';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'نسيم الأندلس - غازباتشو إسباني'), description_ar = COALESCE(description_ar, 'حساء طماطم بارد ونيّئ وغني بالفيتامينات، قادم من جنوب إسبانيا ويُحضّر من دون طهي.

الفائدة: ديتوكس نقي من "الزهور والخضروات". وبفضل الليكوبين (الطماطم) وفيتامين C (الفلفل)، يساعد على حماية البشرة من أشعة الشمس الضارة من الداخل.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["طماطم حمراء شديدة النضج: 4-5 حبات","خيار: 1 حبة (مبردة)","فلفل أخضر حلو: نصف حبة","بصل أحمر وثوم (كمية قليلة جدًا)","زيت زيتون بكر ممتاز (2 ملعقة طعام) وخل التفاح (1 ملعقة طعام)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي جميع المكونات في الخلاط، ثم أضيفي زيت الزيتون والخل وقليلًا من الملح، واخلطيها حتى تصبح سائلة تمامًا بقوام الحساء. اتركيها في الثلاجة لمدة لا تقل عن 2 ساعة حتى تصبح شديدة البرودة."]'::jsonb) WHERE id = '0732d705-b1b2-4b26-b8dc-748f80e0f06a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ماك آند تشيز الذهبي (لعمر 2 سنة+)'), description_ar = COALESCE(description_ar, 'نسخة صحية جدًا من المعكرونة بالجبن المحببة للأطفال، مع خضروات مخفية بداخلها.

