UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شوربة ليلة النجوم (3 سنوات+)'), description_ar = COALESCE(description_ar, 'مذاق شهي بمرق العظام تسبح فيه النجوم، للأطفال الذين لا يحبون تناول الشوربة.

