UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سحابة الماتشا والفراولة'), description_ar = COALESCE(description_ar, 'المشروب الأكثر رواجًا على شبكات التواصل الاجتماعي. جرعة غنية بمضادات الأكسدة المغذية للبشرة.'), category_ar = COALESCE(category_ar, 'مشروبات صحية'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["1 ملعقة صغيرة من مسحوق الماتشا (مذاب في ماء فاتر)، 4-5 حبات من الفراولة الطازجة (مهروسة)، 1 كوب من حليب اللوز، ثلج."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي هريس الفراولة في قاع الكوب، ثم أضيفي الثلج والحليب. وفي النهاية، اسكبي الماتشا الخضراء المذابة ببطء كي تبقى الألوان على شكل طبقات (الوردي في الأسفل والأخضر في الأعلى)."]'::jsonb) WHERE id = '40f5ac74-8479-42d8-bab7-5b56e15de9ae';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بان كيك اللوز ومربى الشيا'), description_ar = COALESCE(description_ar, 'بديل خالٍ من الغلوتين والسكر لنمط حياة صحي، عوضًا عن البان كيك المحضر بالدقيق العادي.

