UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'السيفيتشي البيروفي'), description_ar = COALESCE(description_ar, 'وصفة منعشة وغنية بالبروتين من أمريكا اللاتينية، يُطهى فيها السمك من دون حرارة، باستخدام حمضيات الحمضيات فقط.

الفائدة: خالية تمامًا من الدهون المضافة وغنية بأقصى قدر من البروتين الصافي. وهي من النكهات المفضلة لدى متّبعي الحميات الغذائية.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["فيليه سمك أبيض (طازج جدًا ومنزوع العظام): 200 غ (مقطّع إلى مكعبات صغيرة)","عصير الليمون الأخضر: نصف كوب (طازج العصر)","بصل أحمر: نصف حبة (مقطّع إلى أنصاف حلقات رفيعة)","كزبرة طازجة، فلفل هالابينو حار (حسب الرغبة)، ملح."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["ضعي مكعبات السمك النيئ في وعاء زجاجي، ثم اسكبي فوقها عصير الليمون الأخضر وأضيفي قليلًا من الملح. سيُغيّر العصير لون السمك إلى الأبيض و«يطهوه». اتركيه في الثلاجة لمدة 20-30 دقيقة. وقبل التقديم مباشرةً، أضيفي البصل والكزبرة واخلطي المكونات."]'::jsonb) WHERE id = '53cbba9d-f39f-4a00-950a-386243d164bd';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'السموربرود الإسكندنافي'), description_ar = COALESCE(description_ar, 'فن إعداد السندويشات المفتوحة على خبز الجاودار الداكن، والقادم من الدنمارك والنرويج.

