UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'تبولة الكينوا (المطبخ اللبناني)'), description_ar = COALESCE(description_ar, 'سلطة شهيرة من الشرق الأوسط، يُستبدل فيها البرغل التقليدي بالكينوا الخالية من الغلوتين والأغنى بالبروتين.

