UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'هريس العدس الهندي'), description_ar = COALESCE(description_ar, 'يخنة هندية ذهبية يعشقها النباتيون، تدفئ الجسم من الداخل بقوة التوابل.

