UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سلطة البطاطس الألمانية'), description_ar = COALESCE(description_ar, 'سلطة ألمانية رائعة وخفيفة بنكهة الخردل والخل، تغنيكِ عن السلطات الثقيلة المحضّرة بالمايونيز.

