UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'ماك آند تشيز شريك (3 سنوات+)'), description_ar = COALESCE(description_ar, 'معكرونة بالجبن بلون أخضر جميل وجذاب، يُخفى بداخلها السبانخ.

