UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'منشّط الإشراقة الذهبية'), description_ar = COALESCE(description_ar, 'منشّط صباحي يساعد على تهدئة الالتهابات في الجسم ويدعم دفاعاته ضد الأمراض.

