UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'أسياخ ملوّنة (5 سنوات+)'), description_ar = COALESCE(description_ar, 'أسياخ تجمع الخضراوات واللحم في طبق واحد وتقدمهما كلعبة ملوّنة.

الفائدة: من أكثر الطرق العملية والمرحة لتقديم البروتين والفيتامينات للأطفال في الوقت نفسه.'), category_ar = COALESCE(category_ar, 'الغذاء التكميلي'), tags_ar = COALESCE(tags_ar, ARRAY['baby_food']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["صدر دجاج: 100 qr (مشوي أو مسلوق ومقطّع إلى مكعبات)","فلفل حلو ملوّن (أحمر وأصفر)، وطماطم كرزية، وخيار (مقطّع إلى قطع سميكة).","أعواد خشبية غير حادة الأطراف (أسياخ)."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["أدخلي في الأعواد بالترتيب: حبة طماطم كرزية، ومكعب دجاج، وفلفلًا أصفر، وخيارًا، ثم دجاجًا مرة أخرى. احرصي على ترتيب الألوان كألوان قوس قزح."]'::jsonb) WHERE id = 'd945cba8-c55e-4693-91cb-3385f3ce8b99';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سباغيتي الكوسا بصلصة البيستو'), description_ar = COALESCE(description_ar, 'طبق رائع يمنحكِ متعة تناول المعكرونة، لكنه لا يسبب زيادة الوزن إطلاقًا.

الفائدة: منخفض السعرات الحرارية جدًا. ويتميز زيت الزيتون والريحان في صلصة البيستو بخصائص قوية مضادة للأكسدة، ما يساعد على حماية الخلايا والحفاظ على حيويتها.'), category_ar = COALESCE(category_ar, 'وجبة الغداء'), tags_ar = COALESCE(tags_ar, ARRAY['general']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["كوسا: 2 متوسطتا الحجم (مقطّعتان كخيوط السباغيتي باستخدام أداة مخصصة)","صلصة البيستو: 2 ملعقة كبيرة (مزيج مهروس من الريحان الطازج وزيت الزيتون والجوز والثوم)","طماطم كرزية: 4-5 حبات."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["شوّحي خيوط سباغيتي الكوسا في مقلاة مع قليل من زيت الزيتون لمدة 2-3 دقائق فقط (لا تفرطي في طهيها كي تبقى مقرمشة). ارفعيها عن النار واخلطيها مع صلصة البيستو وحبات الطماطم المقطّعة إلى نصفين."]'::jsonb) WHERE id = '4562e352-5778-4e1f-951e-cc27bf63469a';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سوتيه البروكلي ولحم البقر'), description_ar = COALESCE(description_ar, 'واحدة من أشهر الوصفات الكلاسيكية الصحية في المطبخ الآسيوي (الصيني)، والمحبوبة في جميع أنحاء العالم.

الفائدة: توفر توازنًا مثاليًا بين الحديد (من اللحم) والكالسيوم/فيتامين C (من البروكلي). كما أنها سريعة التحضير.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["لحم بقر (فيليه، مقطع إلى شرائح رفيعة جدًا): 250 غرامًا","بروكلي: 1 رأس كامل (مقسم إلى زهرات)","صلصة الصويا (قليلة الملح): 3 ملاعق كبيرة","زنجبيل طازج وثوم (مهروسان).","زيت السمسم وبذور السمسم."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["شوّحي اللحم سريعًا في مقلاة الووك على نار عالية، ثم ضعيه جانبًا. أضيفي البروكلي والثوم والزنجبيل إلى المقلاة نفسها، وشوّحيها لمدة 3-4 دقائق (يجب أن يبقى البروكلي مقرمشًا). أعيدي اللحم إلى المقلاة، وأضيفي صلصة الصويا وقلّبي لمدة 1 دقيقة، ثم رشي بذور السمسم وارفعي المقلاة عن النار."]'::jsonb) WHERE id = 'cdafe114-fffe-4d67-b795-0770d33715ea';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'مقرمشات بذور الكتان ودقيق اللوز'), description_ar = COALESCE(description_ar, 'مقرمشات منزلية خالية من الغلوتين بنسبة 100% ومن الكربوهيدرات (كيتو)، وهي بديل لرقائق البطاطس غير الصحية المتوفرة في المتاجر.

الفائدة: دقيق اللوز غني بفيتامين E، بينما تساعد بذور الكتان على تنظيم حركة الأمعاء بكفاءة.'), category_ar = COALESCE(category_ar, 'عام'), tags_ar = COALESCE(tags_ar, ARRAY['عام']::text[]), ingredients_ar = COALESCE(ingredients_ar, '["دقيق اللوز: 1 كوب","بذور الكتان (مطحونة): 3 ملاعق كبيرة","ماء: 3 ملاعق كبيرة","زيت الزيتون: 1 ملعقة كبيرة","ملح وزعتر مجفف."]'::jsonb), instructions_ar = COALESCE(instructions_ar, '["اعجني جميع المكونات في وعاء حتى تحصلي على عجينة. افرديها بالشوبك بين ورقتين من ورق الخَبز حتى تصبح رقيقة جدًا (مثل رقائق البطاطس). قطّعيها إلى مربعات بالسكين، واخبزيها في الفرن على درجة حرارة 170 لمدة 15-20 دقيقة حتى تصبح مقرمشة."]'::jsonb) WHERE id = 'd73926c7-3c66-41bd-88a6-1a28c3a2f959';
UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'سحر الكاكاو والماكا'), description_ar = COALESCE(description_ar, 'مشروب دافئ ولذيذ يساعد على موازنة الهرمونات الأنثوية وتعزيز هرمون السعادة.

