UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'بلوندي بالحمص'), description_ar = COALESCE(description_ar, 'كيك بالكراميل من دون دقيق، لن يصدق أحد أنه يحتوي على الحمص.

