UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'شوربة العدس الذهبي والزنجبيل'), description_ar = COALESCE(description_ar, 'وجبة غداء شتوية تنشّط عملية الأيض وتمنح الجسم الدفء من الداخل.

