UPDATE public.admin_recipes SET title_ar = COALESCE(title_ar, 'البطاطا الحلوة والفاصولياء'), description_ar = COALESCE(description_ar, 'وصفة تساعد على تنظيم الرغبة في تناول الحلويات وتقلبات المزاج خلال فترة ما قبل الدورة الشهرية (PMS).

