UPDATE public.baby_crisis_periods SET title_ar = COALESCE(title_ar, 'عالم العلاقات'), description_ar = COALESCE(description_ar, 'يفهم طفلكِ المسافات والعلاقات بين الأشياء'), symptoms_ar = COALESCE(symptoms_ar, '["قلق الانفصال","الكوابيس","الخجل من الغرباء"]'), tips_ar = COALESCE(tips_ar, '["البقاء بالقرب منه","أغراض تمنحه شعورًا بالأمان","التدرج في فترات الانفصال"]') WHERE id = '5c97a8c2-5724-4bd6-97dd-fe1b7f05c200';
UPDATE public.baby_crisis_periods SET title_ar = COALESCE(title_ar, 'عالم الفئات'), description_ar = COALESCE(description_ar, 'يبدأ طفلكِ في تصنيف الأشياء والأشخاص والمشاعر'), symptoms_ar = COALESCE(symptoms_ar, '["نوبات الغضب","التملك","اختبار الحدود"]'), tips_ar = COALESCE(tips_ar, '["تسمية الأشياء","ألعاب التصنيف","وضع حدود واضحة"]') WHERE id = 'f13911eb-137a-4fe7-be01-bccf1325e4e6';

-- ── baby_daily_info → ar (1457 sətir) ──
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد فترة حمل طويلة، احتضنتِ طفلكِ أخيرًا. وبصفتنا عائلة Anacan، سنكون إلى جانبكِ في كل يوم سعيد تقضينه مع طفلكِ! 😊 لا بد أنكِ لاحظتِ منذ ولادته أنه يقضي معظم يومه تقريبًا نائمًا. وقد ينتابكِ بعض القلق حيال ذلك من حين إلى آخر. لكن عليكِ أن تعلمي أن النوم حاجة أساسية لا غنى عنها لصحة المولود الجديد ونموه وتطوره. فباستثناء الرضاعة وتغيير الحفاض، يقضي طفلكِ معظم وقته تقريبًا في النوم. ويساعد هرمون الميلاتونين الذي يُفرَز في جسمه أثناء النوم على تقوية جهازه المناعي وتحفيز الغدة النخامية على إفراز المزيد من هرمون النمو. لكن مدة نوم طفلكِ ستقل تدريجيًا مع نموه. لذا، من المفيد أن تستغلي هذه الأيام في الحصول على أكبر قدر ممكن من الراحة.') WHERE id = '31cd50a4-c6f5-4862-b0ff-2fa89b11b67b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ لاحظتِ عند الولادة وجود طبقة كريمية بيضاء ودهنية على جلد طفلكِ. تُسمى هذه الطبقة الطلاء الجُبني، وهي مادة واقية ورقيقة تتكون من 80% من الماء وتحتوي على كميات وفيرة من الدهون والبروتينات. وقد يختلف توزيع هذه الطبقة الدهنية على سطح الجلد بحسب أسبوع الحمل الذي حدثت فيه الولادة وطريقة الولادة. وعادةً ما يكون جلد الأطفال المولودين بعد موعدهم قد امتص جزءًا من هذه الطبقة. أما الأطفال المولودون قبل الأسبوع 37، فتكون هذه الطبقة أكثر كثافة على جلودهم. ويحتوي الطلاء الجُبني على خلايا دفاعية قادرة على القضاء على الميكروبات، ونحو 40 نوعًا مختلفًا من البروتينات التي تدعم المناعة الطبيعية في جسم طفلكِ. لذلك، ينبغي ألا تحمّمي طفلكِ لمدة 24 ساعة على الأقل بعد ولادته، وأن تنتظري حتى يمتص جلده هذه الطبقة جيدًا.') WHERE id = '01b8c794-e427-40d5-a912-edbb2df87798';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمتلك طفلكِ منذ لحظة ولادته منعكسات قوية. وأهم هذه المنعكسات بالطبع هو منعكس المص الذي يتيح له التغذي. فعندما تلمسين خديه أو المنطقة المحيطة بفمه، يميل فورًا إلى الالتفات في ذلك الاتجاه والبحث عن مصدر الغذاء. منعكس المص هو حركة آلية تلبّي احتياجات طفلكِ الغذائية والعاطفية. ويبدأ هذا المنعكس في الظهور خلال الأسبوع 14 من نموه وهو لا يزال في رحمكِ، ثم يتطور بفضل اكتمال تجويف الفم وعظم الحنك وبنية عضلات الخدين التي تتيح توليد قوة الشفط. ونظرًا إلى ظهور هذا المنعكس في مرحلة مبكرة جدًا من الحمل، يتمكن طفلكِ من التدرب عليه طوال فترة وجوده في رحمكِ. وبذلك يمتلك منذ اللحظة الأولى لولادته الخبرة والمهارة اللازمتين للتغذي.') WHERE id = '4db7f0d9-f7be-435d-a305-5bea20ce135c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد ولادة طفلكِ، يتعرف إليكِ بالفطرة من بين كثير من الأشخاص. ويُعتقد أن رائحتكِ وصوتكِ من العوامل التي تساعد على تكوّن هذه الغريزة. خلال هذه الأيام الأولى التي تجمعكِ بطفلكِ، احرصي على التدرب كثيرًا على الرضاعة الطبيعية، والتحدث إليه مع التواصل البصري، ولمسه برفق. فكل لحظة تتواصلين فيها جسديًا مع طفلكِ تحفّز إفراز هرمون الأوكسيتوسين في جسمكِ. ويساعد الأوكسيتوسين على انقباض الخلايا العضلية التي تدفع الحليب نحو حلمة الثدي. أما الهرمون الآخر الذي يساعدكِ على إرضاع طفلكِ، فهو البرولاكتين الذي تفرزه الغدة النخامية في دماغكِ. ويعمل هذان الهرمونان معًا بانسجام، فعندما يمص طفلكِ الثدي، يحفزان إفراز الحليب وتدفقه نحو الحلمة.') WHERE id = 'a25dea37-57a2-46fc-889c-23e73ad36d76';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُجري الطبيب فحوصًا صحية لطفلكِ فور ولادته. كما يُعطيه خلال الدقائق التالية للولادة أول لقاح له، وهو لقاح التهاب الكبد B، عن طريق حقنه في ساقه. وإذا كنتِ حاملة لفيروس التهاب الكبد B، فسيُعطى طفلكِ أيضًا الغلوبولين المناعي إلى جانب اللقاح. وباستثناء لقاح التهاب الكبد B، لا يتلقى طفلكِ أي لقاح آخر خلال الشهر 1 الأول. وبعد ذلك، وقبل مغادرته المستشفى، يخضع لفحص صحي شامل يجريه طبيب أطفال. كذلك تقدم لكِ الممرضة التي يحددها المستشفى إرشادات تشرح كيفية العناية بطفلكِ في أيامه الأولى والأمور التي ينبغي الانتباه إليها. وتمنحكِ كل هذه المعلومات نصائح مهمة للغاية حول كيفية رعاية طفلكِ.') WHERE id = '0d9fa9e8-940a-4ec4-b501-2f30433e0030';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمنحنا طول طفلكِ ووزنه فكرة عن حالته الصحية العامة، أما قياس محيط رأسه فمهم جدًا لتقييم وظائف الدماغ. في القياسات الأولى، يتراوح محيط رأس الطفل عادةً بين 32 سم و37 سم. وتشير هذه القيم إلى أن الدماغ ينمو بصورة سليمة. ولأن زيادة محيط الرأس تعد مؤشرًا على نمو الدماغ، فمن الضروري متابعتها باهتمام. كما يجب مراقبة طول طفلكِ ووزنه ومقاسات رأسه بانتظام. لذلك، عليكِ اختيار طبيب أطفال جيد ووضع جدول للمتابعة بالتعاون معه. ولمتابعة نمو طفلكِ، يُنصح بزيارة الطبيب لإجراء الفحوص الروتينية في الأيام 5 و14 و30 تقريبًا بعد الولادة.') WHERE id = '8c627179-a029-49ba-9226-4fa26ffce0a7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يبدأ الأطفال حديثو الولادة بالشعور بالجوع، فإنهم يبدؤون أولًا بالحركة والتململ بدلًا من البكاء. وبعد هذه الحركات، قد يشعرون تدريجيًا بالانزعاج. وإذا ظلوا جائعين بعد هذه الإشارات، يبدؤون بالبكاء، وتزداد شدة بكائهم كلما طالت مدة جوعهم. وقد تؤدي محاولة إطعام طفلكِ مباشرةً في هذه المرحلة، في بعض الحالات، إلى رفضه الثدي أو زجاجة الرضاعة. لذلك، عليكِ أولًا حمل طفلكِ الباكي وتهدئته، ثم إطعامه. وإذا لم يهدأ طفلكِ رغم حمله، فقد تكون الرضاعة وأنتِ واقفة خيارًا بديلًا. وبما أنكما لا تزالان في مرحلة التعرف والتأقلم مع بعضكما، فعليكِ مراقبة استجاباته ومحاولة فهم ما يريده.') WHERE id = '9e7fdf66-075d-494d-b199-11e006ca39c4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ حليب الأم، وهو أهم احتياجات طفلكِ منذ ولادته، بالتدفق من ثدييكِ. لذلك، عليكِ خلال الأسابيع الأولى شرب الكثير من السوائل والابتعاد عن التوتر قدر الإمكان. وابتداءً من هذا الأسبوع، قد تعانين أنتِ وطفلكِ من الغازات. وعادةً ما تُعطى قطرات الغازات التي قد يوصي بها الطبيب لتخفيف مغص الغازات لدى طفلكِ بعد إتمام الشهر الأول. لذلك، حاولي تجنب الأطعمة المسببة للغازات، وأدرجي في نظامكِ الغذائي مشروبات الفاكهة المطهوة من دون سكر، وعصائر الفاكهة الطازجة، وشوربات الخضراوات. قد يسبب الحليب ومنتجات الألبان والبقوليات والفواكه الحمضية، مثل البرتقال واليوسفي، مغص الغازات. لذا، عليكِ تجربة هذه الأطعمة ومراقبة تأثيرها قبل إضافتها إلى وجباتكِ. وإذا كانت منتجات الألبان تسبب الغازات، فيمكنكِ استخدام الحليب الخالي من اللاكتوز.') WHERE id = 'bbfc25e1-805a-4de5-a48e-49b8bc100ff1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يستغرق انتظام نمط نوم طفلكِ بعض الوقت. ففي الأشهر الأولى، ينام طفلكِ ويستيقظ عادةً على مدار اليوم، كما أن عدم قدرته على التمييز بين الليل والنهار من العوامل التي تؤخر انتظام نومه. وقد يؤدي شعور طفلكِ بالتعب الشديد والحرمان من النوم إلى بكائه. ومن المتوقع عادةً أن ينام طفلكِ في الأشهر الأولى مدة تصل إلى 15-16 ساعة يوميًا، ولذلك يشعر بانزعاج شديد عندما لا يتمكن من النوم. كما أن تعرضه لبيئة شديدة الضوضاء وللمحفزات البصرية قد يمنعه من النوم ويؤدي إلى بكائه. يبدأ نمط نوم طفلكِ بالتشكل تدريجيًا بين الأسبوعين 8 و12. كما يساعد ازدياد الفواصل بين الرضعات على انتظامه. ولكن نظرًا إلى اختلاف كل طفل عن الآخر، فمن الطبيعي أن يتأخر بعض الأطفال في التأقلم مع نمط النوم.') WHERE id = 'a4331c8d-b2a0-435c-af06-870f5fad8fab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يكون طفلكِ شديد الحساسية تجاه الأصوات البشرية منذ اللحظة الأولى لولادته. ويُعتقد أن سبب ذلك مرتبط بنطاقات الترددات الصوتية. وإلى جانب ذلك، كانت أكثر الأصوات التي سمعها طوال 9 أشهر في رحمكِ هي الأصوات الصادرة عن عمل أعضائكِ وصوتكِ أثناء حديثكِ. استفيدي من ذلك لتهدئة طفلكِ وتحدثي إليه كثيرًا. فعندما يسمع صوتكِ ودقات قلبكِ أثناء حمله، يشعر براحة وأمان كبيرين. وربما بدأ طفلكِ أيضًا بإصدار بعض الأصوات للتعبير عن مشاعره واحتياجاته. ومن المهم أن تردّي عليه بأصوات تشبه الأصوات التي يصدرها لتتمكني من التواصل معه بفاعلية. وهكذا يبدأ طفلكِ بتعلم الكلام واستخدام الأصوات بهدف التواصل.') WHERE id = '1ec6d652-1eca-417a-9067-3ad2a20a5f4b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يدخل نحو 20% من الأطفال في نوبات بكاء متواصلة رغم تمتعهم بصحة جيدة. وتبدأ هذه الحالة، المعروفة بمغص الرضع، عادةً في ساعات المساء، وقد يتعذر تهدئة الطفل لساعات. وعلى الرغم من أن سبب المغص لا يزال غير معروف تمامًا، فإنه يُعتقد أنه قد يرتبط بعدم اكتمال نمو الجهاز الهضمي أو ببعض ردود الفعل التحسسية أو بالجهاز العصبي. إذا شخّص الطبيب طفلكِ بالمغص، فمن الطبيعي أن تشعري بالقلق. لكن عليكِ أولًا معرفة أن هذه الحالة مؤقتة. فعادةً ما تبدأ نوبات البكاء بالتراجع عند إتمام الشهر الثالث، ثم تتحسن خلال فترة قصيرة. أثناء نوبات بكاء طفلكِ، جرّبي طرقًا مختلفة لتهدئته حتى تجدي الطريقة التي تناسبه. ومن الطرق الشائعة التي يمكنكِ تجربتها: تحميمه بماء دافئ، أو وضع منشفة دافئة على بطنه، أو تشغيل جهاز يصدر صوتًا متكررًا مثل مجفف الشعر.') WHERE id = 'd6246f09-676f-479b-ac15-8f1e83a043b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أتممتِ شهرًا آخر برفقة طفلكِ! في الشهر الأول من جدول تطعيمات طفلكِ، تُعطى الجرعة الثانية من لقاح التهاب الكبد B، بعد أن أُعطيت الجرعة الأولى منه فور الولادة. وقد يظهر احمرار وتورم في الساق التي حُقن فيها اللقاح، ولا داعي للقلق في هذه الحالة. كما قد تلاحظين ارتفاعًا مؤقتًا في حرارة طفلكِ وانزعاجه بعد التطعيم. وهذه آثار جانبية شائعة وغير ضارة. ويظهر الانزعاج، على وجه الخصوص، لدى جميع الأطفال الذين يتلقون اللقاح تقريبًا. وعادةً لا تتجاوز الحرارة بعد التطعيم 38 درجة. وباستشارة طبيبكِ، يمكنكِ استخدام شراب أو تحميلة للحرارة التي لا تنخفض خلال فترة قصيرة. ورغم ندرة حدوث ذلك، إذا اعتقدتِ أن طفلكِ يعاني من أعراض غير معتادة، فلا تنسي التواصل مع طبيبكِ.') WHERE id = '418e11ce-7ef6-4382-bb9b-0ee9fe10e295';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما لاحظتِ عند وضع رضيعكِ للنوم أنه يبقى دائمًا في وضعية منحنية. ولأنه ظل في وضعية الجنين داخل الرحم طوال 9 أشهر، فستستمر هذه العادة لبعض الوقت. ستبدأ هذه الحالة بالتراجع تقريبًا في الشهر 2، وستزول تمامًا في الشهر 3. بعد أن كان في بيئة الرحم الآمنة والمغلقة، قد يبدو له العالم الخارجي مخيفًا ومربكًا. لذلك يرغب في البقاء على تواصل جسدي معكِ باستمرار. امنحيه بعض الوقت خلال هذه الفترة، وسيتأقلم. تذكّري أن حضنكِ الذي تفوح منه رائحتكِ هو أكثر مكان يشعر فيه بالأمان. فذلك الرابط المتين بين الأم وطفلها يبدأ بالتكوّن منذ الأيام الأولى. لا تجعليه ينتظر عندما يجوع أو يحتاج إلى تغيير حفاضه، بل لبّي حاجته فورًا. انسي العالم الخارجي لبعض الوقت واهتمّي بطفلكِ فحسب.') WHERE id = '990edf71-6742-4577-9d2f-dadba792cf8a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أتممتِ الآن أسبوعًا كاملًا برفقة طفلكِ. ما أسرع مرور الوقت، أليس كذلك؟ 😊 طوال فترة الحمل تكون أمعاء الطفل معقّمة ولا تحتوي على أي كائنات دقيقة ضارة. إذا كانت الولادة قيصرية، تبدأ البكتيريا التي تساعد على الهضم بالتكوّن في الفلورا المعوية لطفلكِ اعتبارًا من هذا اليوم. أما في الولادة الطبيعية، فتبدأ هذه العملية منذ اليوم 4. بعض هذه البكتيريا نافعة وبعضها الآخر ضار. ويؤدي وجود كلا النوعين إلى تحقيق توازن في الجهاز الهضمي، ويمنع تكاثر أحدهما بصورة مفرطة. أي إن هذه الكائنات الدقيقة ضرورية للحفاظ على توازن الفلورا المعوية لدى طفلكِ.') WHERE id = 'ea7ac5e6-2b68-47b7-9578-f87a52623334';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تحزني ظنًا منكِ أن حليبكِ قليل، أيتها الأم العزيزة. فعند ولادة الطفل، لا تتجاوز سعة معدته حجم حبة كرز. لذلك لا تقلقي معتقدةً أن حليبكِ لا يكفيه. تكبر المعدة خلال الأيام التالية للولادة، ويصبح حجمها في هذه الأيام بحجم حبة مشمش تقريبًا، أي بسعة تقارب 50 ml. ولهذا فإن كمية الحليب التي تبدو لكِ قليلة تكفيه في الواقع تمامًا ليشبع. ولأن معدته لا تزال صغيرة، سيرغب طفلكِ في الرضاعة بكميات قليلة ولكن بصورة متكررة. إذا تقيأ بعد الرضاعة، فعادةً ما يحدث ذلك عندما يتناول كمية تفوق سعة معدته. أما الاعتقاد الشائع بأن حليبكِ غير مناسب له فليس سوى خرافة، فلا تصدّقيه.') WHERE id = 'f7f368ac-9bca-4520-b0e3-f83cfbd455a4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُسمّى الحليب الذي يدرّ مباشرةً بعد الولادة باللبأ (الكولوستروم). وهو غذاء قيّم جدًا، كثيف القوام ومائل إلى الصفرة، وغني بالأجسام المضادة التي تحمي طفلكِ من العدوى، كما يتميز بقيمته البروتينية العالية. بعد نحو 5-7 أيام من الولادة، يحل محله الحليب الانتقالي. ويحتوي الحليب الانتقالي على نسبة من الدهون واللاكتوز أعلى مما يحتويه اللبأ، أي إنه أعلى في السعرات الحرارية. ويستمر هذا النوع من الحليب حتى اليوم 14 تقريبًا. وبعد مرور 2 أسبوعين على الولادة، يبدأ الحليب الناضج الفعلي في الإدرار. وهذا الحليب غني جدًا بالماء والبروتين والدهون.') WHERE id = '4794b2b1-e590-4e29-b9bf-54af8c8dcab5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تبدو لكِ العناية بطفلكِ مخيفة في البداية، ولا سيما إذا كانت هذه تجربتكِ الأولى مع الأمومة. وإذا كنتِ تظنين أنكِ لن تتمكني من ذلك، فأنتِ مخطئة. 😊 قد تبدو العبارة تقليدية، لكنكِ ستتمكنين مع مرور الوقت من العناية بطفلكِ بسهولة كبيرة. ومن إجراءات العناية هذه الاهتمام بجدعة الحبل السري التي بدأت تجف وأوشكت على السقوط. الحبل السري هو الوسيلة التي كان طفلكِ يحصل من خلالها طوال الحمل على الأكسجين والعناصر الغذائية اللازمة لتغذيته ونموه. يبلغ طول الحبل السري نحو 50 سم، ويقطعه طبيبكِ بعد الولادة مع إبقاء نحو 2 سم منه. تسقط جدعة الحبل السري لدى طفلكِ بين اليوم 5 واليوم 15. وإذا لم تعتني بمنطقة السرة قبل سقوط الجدعة وبعده، فقد يزداد احتمال إصابتها بالعدوى. ولتقليل هذا الخطر، ينبغي مسح منطقة السرة وتهويتها مرتين أو ثلاث مرات يوميًا باستخدام محلول كحولي بتركيز 70 بالمئة وفقًا لتوصية طبيبكِ.') WHERE id = '403ffca4-6096-4cf2-9210-17a6a3a59df5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي تمامًا أن يكون رأس طفلكِ أكبر مقارنةً بجسمه، ولا يعني ذلك وجود أي مشكلة صحية. وقد تظهر أيضًا بعض الاختلافات في تناسق شكل رأسه أو بعض الانحناءات. والسبب هو أن عظام رأس الطفل لم تتصلّب بعد، ما يسهّل عملية الولادة. تتكوّن عظام الجمجمة التي لم تتصلّب بعد من نسيج غضروفي غني بالألياف. وإلى جانب ذلك، يحتاج طفلكِ إلى هذه المساحات المفتوحة كي يستمر دماغه في النمو. في المتوسط، يكتسب رأس الطفل شكله المستدير الطبيعي بحلول نهاية الشهر الذي وُلد فيه. يولد الطفل ولديه 6 يوافيخ، وبحلول نهاية الشهر 2 تُغلق جميعها باستثناء اليافوخ الأمامي العلوي. أما اليافوخ الكبير الموجود في الجزء الأمامي العلوي، فيبدأ بالتصلّب في الشهر 7 من عمر طفلكِ ويُغلق قبل بلوغه عمر 2 عامين.') WHERE id = '878511ba-a575-4d79-8fa5-80ca329e838e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حليب الأم الذي تنتجه الغدد الثديية هو أثمن ما يمكنكِ تقديمه لطفلكِ. فهو يحتوي على نوعين من البروتينات، والدهون، والكربوهيدرات، ومجموعة متنوعة من الفيتامينات، إضافةً إلى الأجسام المضادة التي تساعد طفلكِ على مقاومة الفيروسات والبكتيريا. وتُعد الدهون الموجودة في حليبكِ ضرورية لنمو دماغ طفلكِ، وتزويده بالطاقة، ومساعدة جسمه على امتصاص الفيتامينات الذائبة في الدهون والاستفادة منها. وبفضل جميع هذه الخصائص، يُعد حليب الأم أفضل غذاء يمكنه وحده تلبية جميع الاحتياجات الغذائية لطفلكِ خلال الأشهر 6 الأولى، من دون الحاجة إلى أي غذاء آخر. أما التركيبات المعروفة بالحليب الصناعي، فهي البديل الوحيد لتغذية الطفل عندما لا يكون حليبكِ كافيًا. وتُصنع معظم هذه التركيبات، التي يُعد حليب البقر مكوّنها الأساسي، بإضافة بعض المواد إلى الحليب الطبيعي أو إزالة بعضها منه. لكنها تحتوي على نسبة أعلى من بروتين الكازين مقارنةً بحليب الأم، ولذلك يهضمها طفلكِ ببطء أكبر.') WHERE id = 'a9c4f35f-77e6-4302-9bda-fc0e36e3f3da';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد ينخفض وزن طفلكِ عند الولادة بنسبة 10% خلال الأيام الأولى. وبعد هذا الانخفاض، يُتوقع أن يستعيد وزن ولادته في موعد أقصاه اليوم 10. وتُعد مرحلة حديثي الولادة أسرع مراحل نمو طفلكِ طوال حياته. فقد يزداد طول طفلكِ خلال أشهره الأولى بما يتراوح بين 2 سم و6 سم، وقد يزداد وزنه بما يتراوح بين 700 غرام و1500 غرام. عليكِ أن تتذكري أن هذه القيم قد تختلف باختلاف جنس الطفل، وأن النمو قد يكون أبطأ لفترة معينة لدى الأطفال المولودين قبل الأوان. كذلك تتطور عضلات طفلكِ وردود أفعاله ومهاراته الجسدية بسرعة كبيرة خلال الأشهر الأولى، بالتوازي مع نمو جسمه. لذلك ينبغي لكِ خلال هذه المرحلة توفير المحفزات المناسبة التي تدعم نمو طفلكِ، ومراجعة طبيبكِ بانتظام.') WHERE id = '379e34a9-be36-4930-a59c-af93a24eb449';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدو تنظيف منطقة الحفاض مخيفًا جدًا في البداية للأم الجديدة. عند تغيير حفاض طفلكِ، ينبغي أن تتأكدي من وجود كل ما تحتاجين إليه في متناول يدكِ، وأن تبدئي بغسل يديكِ. وخلال مرحلة الاعتياد، يمكنكِ طلب المساعدة من الممرضات أو المقرّبين منكِ أو أقاربكِ. سيحتاج طفلكِ إلى تغيير حفاضه كثيرًا خلال الأشهر القليلة الأولى بعد ولادته. ومع ذلك، لا داعي لإيقاظه لمجرد تغيير حفاضه ما دام نائمًا وحفاضه غير مبلل جدًا. لذلك، إذا كنتِ تعتقدين أنه لا يشعر بأي انزعاج أثناء الرضعات الليلية، فلا داعي لتغيير حفاضه طوال الليل. فقد يؤدي إزعاج الطفل النائم إلى تقطع نومه، ما قد يصعّب عليه العودة إلى النوم.') WHERE id = 'd0704bed-eb75-4a28-b892-e481bca3aba6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد ولادة طفلكِ، تجف بقايا الحبل السري تمامًا وتسقط خلال نحو 10-14 يومًا. لكن هذه المدة قد تطول في بعض الحالات. إذا لم تسقط بقايا الحبل السري لدى طفلكِ بعد، فعليكِ مراجعة أقرب طبيب أطفال بالتأكيد. وقد يشير عدم سقوطها بعد مرور 20 يومًا إلى وجود بعض المشكلات في جهاز طفلكِ المناعي. عند تحميم طفلكِ، حاولي تجنب تبليل منطقة السرة، واحرصي على تجفيفها جيدًا إذا ابتلت. فبقاء بقايا الحبل السري رطبة قد يؤخر سقوطها في الوقت المناسب، كما قد يؤدي إلى الإصابة بأنواع مختلفة من العدوى. بالإضافة إلى ذلك، ومن أجل سقوطها سريعًا وبصورة سليمة، لا تستخدمي أي دواء أو مستحضر ما لم يوصِ به الطبيب.') WHERE id = '46a30d17-6906-4dd1-9f3a-fa10b39a15db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن ملامسة طفلكِ وإرضاعه كثيرًا خلال اليوم يسهّلان عليه إلى حد كبير التكيف مع عالمه الجديد. ومن المعروف منذ زمن طويل أن أحدث حاضنات الأطفال لا تستطيع توفير رعاية تضاهي قوة ودفء حضن الأم. فالملامسة، إلى جانب أحاسيس اللمس والدفء والرائحة، تقوّي الرابطة العاطفية بينكِ وبين طفلكِ. كما يُعد هذا التواصل عاملًا مهمًا لاستمرار الرضاعة الطبيعية بنجاح. وتساعد الرابطة الحسية القوية التي يكوّنها طفلكِ في هذه المرحلة على تسريع نموه النفسي والجسدي، كما أنها بالغة الأهمية لاكتسابه الشعور بالأمان في المراحل اللاحقة من طفولته. لذا أجّلي جميع أعمالكِ واستمتعي بالكثير من ملامسة الجلد للجلد مع طفلكِ! 😊') WHERE id = 'd3f6fa0e-5b44-4a86-8dac-648c5ea0fb9f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تمتد فترة ما بعد الولادة لنحو 6 أسابيع بعد أن تضع المرأة مولودها. وخلال هذه الفترة، التي تحاولين فيها خصوصًا التأقلم مع طفلكِ وحياتكِ الجديدة، قد تمرين من وقت إلى آخر بتقلبات عاطفية. وفي هذه المرحلة، تبدأ التغيرات التي طرأت على عملية الأيض والجهاز التناسلي طوال فترة الحمل في العودة إلى طبيعتها. فتعود مستويات الهرمونات وحجم الرحم سريعًا إلى حالتهما السابقة للحمل. وقد تؤثر فيكِ نفسيًا عودة التغيرات الفسيولوجية والهرمونية، التي حدثت تدريجيًا على مدى نحو 9 أشهر، خلال فترة قصيرة لا تتجاوز 6 أسابيع. وإذا خضتِ تجربة ولادة صعبة، فقد تكون هذه الفترة أشق عليكِ من المعتاد. عليكِ تقبّل أن هذه المرحلة الصعبة مؤقتة، وإذا كنتِ لا تشعرين بأنكِ بخير، فلا تترددي في طلب المساعدة من المقرّبين منكِ أو من أحد المختصين.') WHERE id = 'ee31cac0-139c-4b54-962e-0e0cfd50ac5a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تولي اهتمامًا أكبر لنظافة المنطقة التناسلية خلال فترة ما بعد الولادة. تذكّري أن هذه المنطقة تصبح بعد الولادة شديدة الحساسية للبكتيريا المسببة للعدوى. وقد تحتاجين إلى العناية بها باستخدام الكريمات المطهرة التي أوصى بها طبيبكِ، خاصةً إذا أُجري شق العجان أثناء الولادة الطبيعية. أما في الأسابيع الأولى بعد الولادة القيصرية، فعليكِ إيلاء عناية خاصة بموضع الغرز. التزمي بتوصيات الطبيب الذي أجرى العملية ولا تهملي مواعيد المتابعة. عند الاستحمام، احرصي على ألا تكون المياه شديدة السخونة، ولا تدخلي للاستحمام إلا بوجود شخص إلى جانبكِ. وإذا كانت ولادتكِ قيصرية، فاحمي مواضع الغرز أثناء الاستحمام واحرصي على وقاية المنطقة من العدوى.') WHERE id = '146cc0cd-e1d3-412a-82e1-01fb76131db8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبكي طفلكِ كثيرًا خلال اليوم، وقد يأتي بكاؤه أحيانًا على هيئة نوبات شديدة. وقد تجعلكِ نوبات البكاء تشعرين بالعجز، خاصةً عندما لا تتمكنين من تهدئته. حاولي الحفاظ على هدوئكِ، وتذكّري أن البكاء هو وسيلة التواصل الوحيدة التي يستطيع طفلكِ استخدامها معكِ. وقد تكون لبكائه أسباب عديدة ومختلفة، منها أن تزعجه ملابسه أو أن يشعر بالبرد أو الحر. وقد تُلبس الأمهات، لا سيما من يخضن تجربة الأمومة للمرة الأولى، أطفالهن ملابس أكثر سماكة من اللازم خوفًا من إصابتهم بالمرض. وللحفاظ على التوازن المناسب، يكفي أن تُلبسي طفلكِ طبقة واحدة إضافية مقارنةً بما ترتدينه أنتِ.') WHERE id = '92bf1f12-3409-4d88-8829-221346b3ee91';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد التلامس الجسدي مهمًا للغاية لنمو الرابطة بينكِ وبين طفلكِ وتعزيزها. فعندما يلامسكِ طفلكِ جسديًا، يهدأ على صوت نبضات قلبكِ، وهو أول صوت سمعه حين كان في رحمكِ. كما تساعده هذه الطريقة على الاستغراق في نوم أعمق وأكثر راحة. وفي كثير من ثقافات العالم، يُوضع الأطفال فور ولادتهم على صدر الأم مباشرةً من دون ملابس. ووفقًا للأبحاث العلمية، يساعد هذا التلامس الجسدي الأول على تلبية الاحتياجات البيولوجية الأساسية للطفل. ويحدث هذا التلامس خلال مرحلة بالغة الحساسية في تشكّل نفسية الطفل وسلوكياته المستقبلية. وتُظهر الدراسات أن معدل الاقتصار على الرضاعة الطبيعية في الشهرين 3 و6 لدى الأطفال الذين يتلامسون مع أمهاتهم كثيرًا يبلغ ضعفي المعدل لدى غيرهم. كما أشارت الدراسة نفسها إلى أن الأطفال، بفضل هذه الطريقة، يبكون بمعدل أقل 12 مرة من غيرهم حتى بلوغهم عمر سنتين.') WHERE id = 'c9ec86c3-ffa1-4c34-8c50-574a23ddec68';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي أن تلاحظي في الأيام الأولى بعد الولادة إفرازات مميزة لفترة النفاس، ذات لون أحمر فاتح وكمية تشبه نزف الدورة الشهرية. وقد تنتهي هذه الإفرازات، التي تُسمى الهلابة، خلال 1-2 أسبوع، أو قد تستمر حتى 6 أسابيع. وتقل كميتها تدريجيًا مع مرور الأيام، كما تطرأ بعض التغيرات على لونها. وقرب نهاية فترة النفاس، تتحول إلى إفرازات مائلة إلى اللون الأبيض. وللعناية بالمنطقة التناسلية خلال هذه الفترة، ينبغي أن تغيّري الفوط الصحية بانتظام وأن تستخدمي منظفات مخصصة للمنطقة الحساسة. وقد يشير النزف الغزير والمستمر خلال فترة النفاس إلى بقاء أنسجة من المشيمة داخل الرحم أو إلى حدوث عدوى. ورغم أن هذه الحالة نادرة، فلا تهمليها إذا ظهرت أعراضها، واحرصي على استشارة طبيبكِ.') WHERE id = '8438f645-667d-4bb4-ad8d-04104669e5fa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحتاج الأطفال حديثو الولادة إلى أمهاتهم بشدة، وتُعد حاسة اللمس أكثر حواسهم تطورًا. وأفضل الأوقات التي يمكن لطفلكِ فيها إشباع حاجته إلى هذا التلامس هي أوقات الرضاعة، حين يشم رائحتكِ. ففي الأشهر الأولى بعد ولادته، لا يرغب طفلكِ في الرضاعة لمجرد شعوره بالجوع. ولأن المكان الوحيد الذي يشعر فيه بالأمان هو حيث يستطيع شم رائحتكِ، فقد يرغب في الرضاعة حتى يغفو. لذلك، لا تقتصر أهمية رغبته في الرضاعة على إشباع جوعه، بل لها أيضًا أهمية عاطفية كبيرة. ولا يبدأ الأطفال التفاعل الاجتماعي إلا بعد عمر ثلاثة أشهر. لذا لا تبتعدي عن طفلكِ بسبب الاعتقاد الخاطئ الشائع بأنه سيعتاد البقاء بين ذراعيكِ. فالإكثار من احتضان طفلكِ خلال الأشهر الأولى يسهّل تكيفه مع العالم الخارجي ويعزز شعوره بالأمان.') WHERE id = 'a82a92d2-bea2-44d6-bcce-77b7bcd63519';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يزال رحمكِ بعد الولادة أكبر بكثير من حجمه الطبيعي قبل الحمل. ويمكنكِ الآن عادةً تحسسه عند مستوى السرة أو أعلى منها بقليل. وخلال نحو 1 شهر، سيعود رحمكِ تمامًا إلى حجمه السابق. فكتلة الرحم، التي تبلغ نحو 1500 غرام وقت الولادة، تتناقص قليلًا كل يوم حتى تعود إلى 60 غرامًا، كما كانت قبل الحمل. وقد تشعرين من وقت إلى آخر، خاصةً أثناء الرضاعة، بآلام ناجمة عن تقلصات في منطقة الرحم بفعل هرمون الأوكسيتوسين. وتكون هذه التقلصات أشد قليلًا خلال الأيام الأولى التي تلي الولادة، ثم تبدأ حدتها في الانخفاض تدريجيًا. وتُعد هذه التقلصات طبيعية، بل يُعتقد أنها تساعد على تنظيف بطانة الرحم.') WHERE id = '79a8c317-465e-48a5-8158-982eb6d5f890';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'طفلكِ، مثل كل الأطفال، شديد الحساسية خلال أشهره الأولى. وبما أن جهازه المناعي لم يكتمل بعد، فقد يكون أكثر عرضة لبعض الأمراض. ورغم سعادتكِ بلقاء صغيركِ الذي انتظرته طوال أشهر، فمن الطبيعي أن تشعري بالحزن والتأثر عندما يكون منزعجًا، وقد يزداد حزنكِ خصوصًا إذا واجه أي مشكلة صحية. لكن لا ينبغي أن تلومي نفسكِ في هذه المرحلة، بل وجّهي كل طاقتكِ إلى طفلكِ وإلى نفسكِ لتجاوز الصعوبات. باختصار، لا تقلقي وحاولي أن تكوني سعيدة. تذكّري أن طفلكِ يستشعر كل ما تشعرين به، وأن حالته النفسية مرتبطة بكِ ارتباطًا مباشرًا.') WHERE id = '90453aab-3c85-45f7-a53b-d1654064425e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عند ضبط وضعية نوم طفلكِ، عليكِ الانتباه إلى خطر القيء والاختناق. لا مشكلة في جعل طفلكِ ينام على بطنه أو ظهره أو جانبه، مع إدارة رأسه إلى أحد الجانبين. لكن نومه مدة طويلة في الوضعية نفسها قد يؤدي إلى تغير شكل عظام جمجمته التي لا تزال ليّنة. لذلك ينبغي أن تغيّري وضعيته من حين إلى آخر أثناء النوم. وعندما تضعينه على جانبه، قد تحتاجين إلى دعم ظهره بوسادة صغيرة لمساعدته على الثبات. وقد يكون اختيار سرير مائل، بعد استشارة طبيبكِ، فكرة جيدة للحد من خطر الاختناق أثناء النوم. كما يمكنكِ استخدام وسادة مخصصة للوقاية من تسطّح الرأس، للمساعدة على منع تسطّح الجزء الخلفي من رأس طفلكِ والحفاظ على شكله المستدير.') WHERE id = '82ca4410-dc4b-42c9-8de1-8024396fe373';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عاش طفلكِ في رحمكِ طوال 9 أشهر ضمن بيئة معقمة تمامًا، ولذلك لم يكتمل استعداد جهازه المناعي للعالم الخارجي بعد. والسبب في عدم اكتمال نمو جهازه المناعي قبل الولادة هو تجنب حدوث تفاعل ضار بينه وبين جهازكِ المناعي. ومع الولادة، يوفّر الحليب الذي يُفرَز بمساعدة الهرمونات مناعة مؤقتة لطفلكِ. وتنتقل الأجسام المضادة من جسمكِ إلى طفلكِ عبر الحليب، وتزداد خصوصًا عند الإصابة بالمرض، فتحمي جسمه. لذلك، ما لم يوجد مانع طبي، ينبغي ألا تقدّمي له أغذية أو مكملات إضافية دون استشارة طبيبكِ. لا توجد قاعدة صارمة بشأن عدد مرات الرضاعة خلال الأشهر الأولى؛ فالعامل الأساسي هنا هو شهية طفلكِ. وإذا شعرتِ بعد إرضاعه بأنه لم يشبع، فتذكّري أن الرغبة في المص خلال الأشهر الأولى هي رد فعل انعكاسي، ولا تعني دائمًا أن طفلكِ جائع.') WHERE id = '376e500c-ed21-4d44-817e-05fcffb83c34';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تبدئي خلال هذا الشهر بإعطاء طفلكِ قطرات فيتامين D التي يمكنكِ الحصول عليها مجانًا من العيادات أو وفق توصية طبيبكِ. تُعد أشعة الشمس المصدر الأساسي لفيتامين D، ويساعد التعرض لها مدة معينة على تلبية 90% من احتياجات الجسم منه. ومع ذلك، تشير الأبحاث العلمية إلى أن نقص فيتامين D من المشكلات الصحية الشائعة. ويسهم فيتامين D في تنظيم جهاز طفلكِ المناعي الذي لا يزال في طور النمو. ويُعد مخزون فيتامين D في الجسم مهمًا، خصوصًا في حالات أمراض المناعة الذاتية. منذ اليوم الأول من حياته، يحصل طفلكِ الذي يتغذى على حليب الأم أو الحليب الصناعي على كميات كافية من جميع الفيتامينات باستثناء فيتامين D، إذ لا يمكنه الحصول على كمية كافية منه عبر الغذاء. لذلك يجب تعويض هذا النقص بمكمل فيتامين D يصفه طبيبكِ.') WHERE id = '4c2feb95-7f80-4a6f-9d8b-18f61f673c70';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُسمى مرحلة عودة التغيرات التي طرأت على جسمكِ طوال الحمل إلى حالتها السابقة بعد الولادة بفترة النفاس. غير أن النفاس يقتصر على أول 40 يومًا بعد الولادة، أي مدة 6 أسابيع. أما مرحلة ما بعد الولادة فتختلف من امرأة إلى أخرى وتستمر مدة أطول من النفاس. وها أنتِ الآن تحملين بين ذراعيكِ تلك المعجزة التي حلمتِ بها طوال 9 أشهر. لكن قلة النوم والإرهاق والآلام الجسدية وعدم القدرة على تخصيص وقت لنفسكِ وللأعمال المنزلية قد تستمر، ما قد يجعلكِ تشعرين بأنكِ عاجزة عن إنجاز كل شيء. وقد تشعرين أحيانًا بالعصبية من دون سبب، أو تتعاملين بحدة مع من حولكِ. باختصار، الحالة النفسية بعد الولادة معقدة، وليس من الصواب حصرها في 40 يومًا فقط. اشرحي مشاعركِ لعائلتكِ واطلبي منهم تفهّمكِ. تذكّري أن هذه المرحلة كلها مؤقتة. كل امرأة هي الأم المثالية لطفلها، وسنكون إلى جانبكِ في كل صعوبة تواجهينها. 😊') WHERE id = 'bad42002-8275-46dc-b1ad-174066cad7e7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تستخدمين وسائل داعمة، مثل مقعد الرضيع، لحمل طفلكِ أو مساعدته على النوم، فيمكنكِ تعليق ألعاب لافتة للانتباه فوقه بطريقة لا تؤذيه. تجذب هذه الأشياء انتباه طفلكِ، فتسهم في تنمية قدرته على الرؤية والإدراك وتعزز مهارات الفهم لديه. وسيستمتع كثيرًا بالألعاب المضيئة والمُصدرة للأصوات وتلك التي يمكنه تحريكها. فاكتشاف أشياء جديدة يثير حماس طفلكِ ويسليه في الوقت نفسه. كما أن تعرضه للمحفزات الملونة المحيطة به يساعده على اكتشاف ذاته. لكن عليكِ توخي الحذر عند اختيارها. فمع أن الأجهزة كثيرة الحركة والألوان والأصوات، مثل التلفاز، تجذب انتباه طفلكِ، فمن المؤكد أن لها تأثيرًا سلبيًا في نموه.') WHERE id = '3ad7f64e-f78d-46bd-a402-26a3f15d1d22';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين في البداية أن طفلكِ ينام أثناء الرضاعة. وقد يسعدكِ ذلك، مثل كثير من الأمهات. لكن انتبهي، فإذا تحول الأمر إلى عادة، فقد يجد طفلكِ صعوبة في النوم من دون رضاعة. وعندما يعتاد هذا النمط، لن يرغب في النوم من دونها. لذلك، بمجرد أن تلاحظي شعوره بالنعاس والانزعاج، ضعيه في مهده وجرّبي طرقًا مختلفة لمساعدته على النوم. قد يبكي طفلكِ في البداية أثناء اعتياده الطرق الجديدة، لكن إذا واصلتِ المحاولة من دون استسلام، فستلاحظين أنه يعتادها مع مرور الوقت. وإذا قاوم طفلكِ النوم بشدة خلال هذه المحاولات، فهدّئيه ثم اتركي له فرصة أخرى لينام بمفرده.') WHERE id = '9210140f-4b86-4445-aa81-e541ebeace13';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفّر رحمكِ لطفلكِ طوال 9 أشهر بيئة دافئة ومريحة للغاية. وقد يشكل انتقاله المفاجئ بعد الولادة إلى العالم الخارجي المليء بالأصوات والأضواء صدمة صغيرة له. لذلك قد يحتاج إلى بعض الوقت كي يعتاد بيئته الجديدة. ولهذا السبب قد تلاحظين أنه لا يزال يتكور أثناء النوم كما كان في الرحم، متخذًا وضعية الجنين. وستلاحظين أن هذه العادة تقل خلال شهر واحد تقريبًا. وخلال فترة التأقلم هذه، يحتاج إليكِ أكثر من أي وقت مضى. فهو يستمتع كثيرًا عندما تحملينه وتقبّلينه وتتحدثين إليه، وباختصار عندما تهتمين به، كما يؤدي ذلك إلى إفراز هرمونات السعادة في جسمه.') WHERE id = 'd3c1171d-ec50-4947-af33-82084d44686e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تمر الأيام سريعًا، وأنتِ تعتادين دوركِ كأم أكثر فأكثر كل يوم. وربما بدأت الرابطة بينكِ وبين طفلكِ تتشكل بالفعل في صورة حب لا يوصف وشعور قوي بالرغبة في حمايته. لكن ليس صحيحًا أن هذا الشعور يجب أن ينشأ فورًا وبالطريقة نفسها لدى كل امرأة. فكما تختلف مشاعر الناس، قد تحتاج بعض النساء إلى وقت حتى تتكون علاقتهن العاطفية بأطفالهن بسبب عوامل مثل ضغوط الولادة وفترة النفاس. إذا شعرتِ من حين إلى آخر بأن طفلكِ غريب عنكِ، فلا تلومي نفسكِ. فقد تؤثر في حالتكِ النفسية التغيرات الحادة التي تطرأ بعد الولادة خلال فترة قصيرة على الهرمونات التي ارتفعت تدريجيًا في دمكِ طوال 9 أشهر. وإذا مرت أسابيع وما زلتِ تشعرين بأن طفلكِ غريب عنكِ، فقد تكونين مصابة باكتئاب ما بعد الولادة. وفي هذه الحالة، ننصحكِ بشدة باستشارة طبيبتكِ والحصول على الدعم النفسي.') WHERE id = '08ca900e-fc32-45d6-bd75-a4633391d4f9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمر الأطفال بعد الولادة في أسابيع معينة بفترات من النمو والتطور السريعين، تُعرف بطفرات النمو. والأسبوع 5 الذي تمران به الآن هو أول أسبوع تحدث فيه إحدى هذه الطفرات. لذلك من الطبيعي تمامًا أن يبكي طفلكِ في هذه الأيام أكثر من المعتاد، أو يصبح متململًا، أو يعاني مشكلات في النوم، أو تتغير شهيته. وقد تزداد شهيته لأنه يحتاج إلى طاقة أكبر للنمو، ولأنه يريد من خلال زيادة الرضاعة تحفيز الهرمونات التي ترفع إنتاج الحليب لتلبية هذه الحاجة. وخلال طفرة الأسبوع 5، يبدأ طفلكِ باستخدام حواسه بنشاط وإدراك كل ما يحيط به. وباختصار، يكتشف أن عالمه لم يعد يقتصر على الرضاعة والنوم فقط. ونتيجة تعرضه لمزيد من المحفزات، قد يزداد انزعاجه أحيانًا. حاولي التعامل مع هذه المرحلة، التي لن تستمر سوى بضعة أيام، بأكبر قدر ممكن من الصبر، وتذكري أنها مؤقتة.') WHERE id = '3c3db532-5b9a-41a9-8a5e-67563130c5c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع إكمال طفلكِ شهره الأول في العالم الخارجي، ربما لاحظتِ أنه أصبح أكثر فضولًا تجاه ما يحيط به. فقد بدأ يهتم خصوصًا بالأشياء المثيرة للاهتمام من حوله، والأشكال الكبيرة، والألوان الزاهية والمتباينة. وبعد أن كان يفتح عينيه لفترات قصيرة خلال الأيام الأولى بعد الولادة، أصبح الآن يبقى مستيقظًا لمدة أطول. وهذا يعني أن طفلكِ بدأ يستخدم حواسه المهمة لاستكشاف محيطه. وخلال فترات يقظته القصيرة، يمكنكِ أن تعرضي عليه أقمشة ملونة أو تجعليه يلمسها، وأن تقومي معه بأنشطة متنوعة. وستلاحظين أنه يستمتع كثيرًا بمثل هذه الألعاب. ولأن قدرته على الإبصار لم تكتمل بعد، قرّبي وجهكِ منه وأتيحي له فرصة تأمل ملامحكِ حتى يتعرف إليكِ بصورة أفضل. 😊') WHERE id = '676e6646-3ff2-4bc0-82e0-4614c3d8096a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قرف اللبن، المعروف أيضًا باسم قبعة المهد، حالة جلدية شائعة في الأشهر الأولى تسبب ظهور بقع متقشرة وقشرية على فروة رأس الأطفال. وقد تمتد هذه البقع الحمراء والمتقشرة إلى الجبهة وخلف الأذنين والرقبة وتحت الإبطين. إذا ظهر قرف اللبن لدى طفلكِ، فلا داعي للقلق، فهو لا يسبب الحكة عادةً ولا يزعج الطفل. وقد تلاحظين أحيانًا عند تغيير حفاضه أن القشور امتدت إلى تلك المنطقة أيضًا. وفي حالات نادرة، قد تصاحب هذه الحالة في منطقة الحفاض عدوى فطرية. ورغم أن السبب الدقيق لقرف اللبن غير معروف، فقد تسهم في ظهوره عوامل مثل الاستعداد الوراثي، والخمائر التي تعيش طبيعيًا على الجلد، والمواد المهيجة، والطقس الجاف والبارد.') WHERE id = 'dc08af3a-ac5d-4bd3-9ab0-537157d76301';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد العثور على وضعية الرضاعة الصحيحة أمرًا بالغ الأهمية كي يستفيد طفلكِ إلى أقصى حد من الحليب، وكذلك للحفاظ على صحة جسمكِ. أثناء الرضاعة، اتخذي وضعية مريحة واسندي ظهركِ وأسفل ظهركِ بوسادة. كذلك، ضعي وسادة مرتفعة تحت ذراعكِ من جهة الرضاعة حتى لا تضطري إلى إبقاء ذراعكِ مرفوعة طوال الوقت. احملي طفلكِ في أثناء الرضاعة بالقرب منكِ قدر الإمكان، مع توجيه وجهه نحوكِ. ومن الأفضل إسناد جسم طفلكِ على الجانب الداخلي من ذراعكِ ووضع رأسه عند ثنية مرفقكِ. ويُعد اختيار الوضعية الصحيحة ضروريًا أيضًا لنمو طفلكِ؛ فإذا واصلتِ إرضاعه في وضعية خاطئة، فقد يبدأ عنقه بالشعور بالألم سريعًا، ما يدفعه إلى التوقف عن الرضاعة في وقت مبكر.') WHERE id = '4be7fa1f-7739-407d-aa85-d7577ebd4d3a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما بدأت آلام الغازات لدى طفلكِ تظهر بصورة مزعجة. راقبي لغة جسده؛ فإذا كان يسحب ساقيه نحو بطنه ويحمرّ وجهه ويبكي ويحرك ساقيه كما لو كان يقود دراجة، فمن المرجح جدًا أنه يعاني من آلام الغازات. وإذا ظهرت هذه العلامات بعد الرضاعة أو تناول الطعام ولم يهدأ طفلكِ، فغالبًا ما تكون الغازات هي السبب. وليس من الصعب ملاحظة ذلك؛ فالطفل الذي يعاني من آلام الغازات يكون منزعجًا ويرغب في الرضاعة، لكنه سرعان ما يبدأ بالبكاء مجددًا. كما يبدو بطن الطفل المصاب بالغازات قاسيًا ومنتفخًا. وقد يساعد تحريكه على الشعور بالراحة، لأن ذلك يساهم في تحريك الهواء داخل أمعائه. ورغم أن آلام الغازات والمغص مزعجة جدًا، فإنها مرحلة مؤقتة. لذلك، حافظي على هدوئكِ وتذكري أنها ستزول. وفي هذه الأوقات، قد يساعد الانتقال إلى غرفة هادئة والتحدث إلى طفلكِ بصوت رقيق وإطفاء الأضواء وتدليك بطنه على تهدئته كثيرًا.') WHERE id = '16924675-e88b-458a-9fb7-e716fc169d02';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تحميم طفلكِ بانتظام مهمًا جدًا لمناعته وصحة بشرته. لكن هناك بعض الأمور التي ينبغي الانتباه إليها ضمن روتين الاستحمام، وأهمها درجة حرارة الماء. يجب أن تكون حرارة ماء استحمام طفلكِ نحو 37 درجة. فالماء الأبرد أو الأكثر سخونة قد يضر بشرته، كما قد يتسبب في مرضه. وحافظي على درجة حرارة الغرفة بين 22-24 درجة. ومن الأمور المهمة الأخرى مستوى الماء في حوض الاستحمام؛ فقد ينزلق طفلكِ من يديكِ في لحظة غفلة، لذا يجب ألا يتجاوز عمق الماء 15 سم. حاولي ألا تبللي رأس طفلكِ وجسمه في الوقت نفسه أثناء غسله، لأن فقدان الحرارة عبر الرأس يحدث بسرعة كبيرة. ولتجنب شعور طفلكِ بالبرد، اغسلي جسمه أولًا، وبعد الانتهاء منه تمامًا اغسلي رأسه واختتمي الاستحمام.') WHERE id = '9a3356cb-31bb-4c91-8c4b-755f5e18597d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يتغذى بصورة أساسية على حليب الأم، فقد يكون برازه رخوًا وسائلًا إلى حد كبير. ومع ذلك، قد يعاني أحيانًا من الإمساك أو الإسهال. وتشيع مشكلات الهضم لدى الأطفال لأن أمعاءهم شديدة الحساسية، لذلك تُعد حالات مثل الإمساك والإسهال والغازات طبيعية من الناحية الفسيولوجية. وقد تسبب الحليب الصناعي الإمساك من حين إلى آخر، إذ يصعب هضمه نسبيًا ويبقى في الجهاز الهضمي مدة أطول مقارنة بحليب الأم. وكما يختلف الأمر بين الأطفال، فإن حركة أمعاء طفلكِ وعدد مرات تبرزه لهما نمطهما الخاص؛ فبعض الأطفال يتبرزون عدة مرات يوميًا، بينما قد يتبرز آخرون مرة كل 5 أيام. إذا كان البراز لينًا، ولا يعاني طفلكِ من الشد أو الإجهاد أثناء التبرز، وكانت زيادة وزنه طبيعية وحالته العامة جيدة، فلا داعي للقلق.') WHERE id = '315efeec-966c-4318-a08f-5aee7f235a22';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن الخروج بطفلكِ في الأيام التي يكون فيها الطقس جميلًا سيساعدكِ على الاسترخاء ويدعم نمو طفلكِ أيضًا. وقد تكون تغيرات الهواء والأصوات في الخارج وتأثير البيئة المحيطة وسيلة مختلفة لتهدئة طفلكِ. قد يبدو الخروج مع الطفل صعبًا لكثير من الأمهات، لكنه في الحقيقة مجرد مسألة تعوّد. فكلما خرجتِ مع طفلكِ أكثر، أصبحتِ أكثر ارتياحًا مع مرور الوقت. ولا تنسي أن تأخذي معكِ الأغراض اللازمة لقضاء وقت مريح وممتع في الخارج. ومن أهمها بالطبع الحفاضات ومفرش تغيير الحفاض والمناديل المبللة، فهي ضرورية دائمًا للعناية بطفلكِ. وقد يكون من المفيد جدًا أيضًا أخذ مريلة احتياطية وطقم ملابس إضافي تحسبًا لتقيؤ طفلكِ. لذا، أجّلي جميع مهامكِ واستمتعي بالهواء النقي برفقة طفلكِ! 😊') WHERE id = '1dffb4b0-c92d-41f6-b1a5-adde26593736';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد كمية الماء التي تشربينها أهم عامل يساعد على زيادة القيمة الغذائية لحليبكِ وكميته. وللحفاظ على إدرار الحليب واستمراره، تناولي ما لا يقل عن 2-3 لترات من السوائل يوميًا، وعوّضي السوائل التي يفقدها جسمكِ بعد كل رضعة. كما أن شرب كمية كافية من الماء وسيلة فعالة جدًا للتخلص سريعًا من الوزن الذي اكتسبتِه أثناء الحمل. وسيساعد حصولكِ على جميع العناصر الغذائية التي يحتاج إليها جسمكِ بكميات كافية على زيادة إدرار الحليب والتخلص من الوزن الزائد أيضًا. ولتلبية احتياجاتكِ اليومية من البروتين، يمكنكِ تناول مصادر البروتين النباتية والحيوانية. لكن بما أن طفلكِ يمر بمرحلة قد يعاني فيها كثيرًا من الغازات، فمن المفيد الانتباه إلى مكونات الأطعمة التي تتناولينها. وتذكري أيضًا أنه كلما زادت مرات إرضاعكِ لطفلكِ، زادت كمية حليبكِ واستمر إدراره.') WHERE id = '8b7bb2b5-f77d-4347-879b-67f02bacb220';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل التطور الكبير الذي تشهده حاسة السمع في هذه المرحلة، قد يستجيب طفلكِ لصوتكِ وللموسيقى الهادئة بالابتسام. وفي المقابل، قد يعبّر عن انزعاجه من الأصوات العالية والمفاجئة خصوصًا، بتغيير تعابير وجهه وشدّ جسمه ومدّ ذراعيه إلى الجانبين ثم ضمّهما إلى صدره والبكاء. فمنذ أن كان طفلكِ في رحمكِ، بدأ يسمع دقات قلبكِ وصوتكِ وصوت والده ومختلف الأصوات المحيطة به ويحفظها في ذاكرته. وبعد ولادته، قد يكون لسماع الأصوات التي احتفظ بها في ذاكرته تأثير مهدئ عليه. لذا فإن تشغيل موسيقى هادئة، خصوصًا في الأوقات التي يشعر فيها بالانزعاج، والتحدث إليه بنبرة رقيقة سيساعدانه على الاسترخاء. ويمكنكِ أيضًا الاستفادة من هذا التأثير المهدئ بالغناء لطفلكِ، ولا سيما عند استعداده للنوم، فهذا مفيد لنموه المعرفي. وبالمناسبة، نود تذكيركِ بأن الأطفال يحبون أكثر التهويدات التي تتكرر فيها الكلمات. 😊') WHERE id = '187e9ca9-650d-40db-aa1f-2e28314ee7e9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون هناك أسباب عديدة ومختلفة لإصابة طفلكِ بالغازات، ومعرفتكِ بهذه الأسباب ستساعدكِ كثيرًا في التعامل مع مغص الغازات. ومن أكثر أسبابه شيوعًا إطعام الطفل بوتيرة متقاربة أكثر من اللازم وعدم انتظام مواعيد الرضاعة. وبما أن النبيت الجرثومي المعوي لدى طفلكِ لا يزال في طور التكوين، فإن وضع نظام منتظم لرضاعته يساعد بكتيريا الأمعاء على العمل في أفضل الظروف، ما يخفف من حدة مغص الغازات لديه. خلال الأشهر الـ6 الأولى، تُفرز معدة الطفل إنزيمات تهضم الحليب فقط. لذلك ينبغي ألا تقدّمي له سوى حليب الأم أو الحليب الصناعي الأقرب في تركيبته إلى حليب الأم. أما الأطعمة الأخرى غير الحليب والمنتجات المحتوية عليه، مثل الماء المحلّى والدبس والعسل والمربى، فلن تفيده، بل ستزيد العبء على جهازه الهضمي. وقد تؤدي بعض الأدوية أيضًا إلى زيادة مغص الغازات، لذا تجنّبي إعطاء طفلكِ أي دواء من دون استشارة طبيبه.') WHERE id = 'a098a0a5-9cf9-4830-b539-70c7b71e29f4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ما أسرع مرور الأيام، أليس كذلك؟ لقد تجاوز طفلكِ الآن مرحلة الأيام الأولى كمولود جديد، وبدأ يدرك العالم المحيط به بشكل أفضل. وفي هذه المرحلة، يستمتع كثيرًا بلمسه وملاطفته واحتضانه. وبالنسبة إلى طفلكِ الذي عاش داخل جسدكِ طوال فترة الحمل، من المرجح أن يكون حضنكِ مكانه المفضل. وخصوصًا عندما يشعر بالخوف أو الانزعاج، فإن ذلك الملاذ الآمن بين ذراعيكِ هو المكان الذي يهدئه بأسرع وقت. وحين ينام في حضنكِ أو حضن والده، يتخذ جسمه شكل جسدكما وكأنه يصنع لنفسه عشًا. أما خلال الشهر أو الشهرين المقبلين، فسيبدأ البحث عن مزيد من الحرية وسيحاول توسيع مساحته الخاصة بدلًا من الاستقرار في حضنكِ. لذلك، ورغم ما قد تنطوي عليه هذه الأيام أحيانًا من صعوبة، حاولي الاستمتاع بكل لحظة تقضيانها متعانقين. :)') WHERE id = '3ff154d9-4a5e-4705-b55a-c139a97509b8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع أن طفلكِ يستيقظ بوتيرة أكبر خلال النهار، فقد بدأ الآن ينام فترات أطول ليلًا. ولكي تساعديه على اكتساب نمط نوم صحي وتعلّم الخلود إلى النوم بمفرده، ضعيه برفق في مهده وهو لا يزال مستيقظًا عندما تظهر عليه علامات النعاس. وترجع هذه التغيرات الإيجابية في نومه إلى أنه أصبح قادرًا على التمييز بين الليل والنهار. ولترسيخ هذه العادة، إليكِ بعض النصائح. أهمها إبقاء الغرفة التي يوجد فيها طفلكِ مضاءة ومفعمة بالحيوية خلال النهار. أما في المساء، فاستخدمي إضاءة خافتة في الغرف والأماكن التي يوجد فيها، وتصرّفي بهدوء أكبر وتحدثي همسًا. هذه التغييرات البسيطة من أهم العوامل التي تساعد طفلكِ على الحصول على نوم منتظم وعالي الجودة.') WHERE id = '854dcb61-ea42-4d37-9176-c3af87b58986';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بما أن فترة النفاس بعد الولادة قد انتهت الآن، فمن المفترض أن تبدأ التقلبات العاطفية والقلق والشعور بعدم الكفاءة التي مررتِ بها بالتراجع تدريجيًا. كما يقل التعب والإرهاق الناتجان عن الولادة، وتعتادين أكثر فأكثر على طفلكِ الذي انضم إلى عائلتكِ. إذا كانت ولادتكِ طبيعية، فقد تشعرين أحيانًا ببعض الانزعاج في غرز شق العجان أو عند استخدام المرحاض، لكن قدرتكِ على التحكم في المثانة والأمعاء تحسنت كثيرًا. ومع ذلك، قد يستمر جفاف المهبل وانخفاض الرغبة الجنسية المرتبط بالتغيرات الهرمونية فترةً أخرى. ورغم أن هرموناتكِ عادت إلى مستوياتها السابقة إلى حد كبير، فإنكِ ما زلتِ بحاجة إلى بعض الوقت للتكيف تمامًا مع حالتكِ النفسية كأم جديدة ومع حياتكِ المتغيرة. وإذا شعرتِ بأنكِ تواجهين صعوبة في التأقلم مع هذه التغيرات، فاطلبي الدعم من طبيبكِ بالتأكيد.') WHERE id = '56bf65a1-60b7-4dfd-848c-0b69df37fbad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا الآن أن تعتني بصحتكِ من أجلكِ ومن أجل طفلكِ أيضًا. والتغذية المتوازنة هي الشرط الأساسي لامتلاك جهاز مناعي قوي قادر على مكافحة العدوى. لا تتّبعي مطلقًا حميات غذائية قاسية وسريعة للتخلص من الوزن المتبقي بعد الولادة. وقد يطلب منكِ طبيبكِ الاستمرار فترةً أخرى في تناول الفيتامينات التي استخدمتها أثناء الحمل. وإلى جانب تلبية احتياجات جسمكِ من فيتامينات A وC وD وE، ينبغي أيضًا الحصول على عناصر غذائية مثل الزنك وأوميغا والحديد للحفاظ على جودة حليبكِ. ولتلبية هذه الاحتياجات، من المهم جدًا تناول الفاكهة والخضراوات الطازجة في مواسمها. ويمكنكِ الحفاظ على قوة جهازكِ المناعي في جميع الفصول، خصوصًا بإدراج الأطعمة الغنية بالزنك والسيلينيوم في نظامكِ الغذائي.') WHERE id = '8b8bfabb-ad49-47f5-ad53-ea528bf3b3c1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى أن عضلات عيني رضيعكِ لم تكتمل بعد، فقد يستمر الحَوَل لديه لبعض الوقت. وقد تنحرف أحيانًا عين واحدة، وأحيانًا كلتا العينين معًا نحو الخارج. وعندما يحاول تتبّع جسم ما، قد لا تتحرك عيناه بالتوازي. يُسمّى هذا الانحراف بالحَوَل الكاذب. وقد ينشأ الحَوَل الكاذب أيضًا بسبب الاتساع الفسيولوجي للجفنين. وعلى عكس ما قد يُعتقد، لا تؤثر هذه الحالة في قدرة رضيعكِ على الإبصار أو في نمو عينيه. ومع نموه وتشكّل عظمة الأنف واستقرار الجفنين في موضعهما، يتحسن هذا المظهر. كما قد يبدو بعض الرضع مصابين بالحَوَل بسبب بنية الوجه، رغم أن عيونهم تكون في الواقع متجهة في الاتجاه نفسه. إذا كانت هذه الحالة تقلقكِ، فيمكنكِ عرض رضيعكِ على طبيب عيون أطفال للاطمئنان.') WHERE id = 'f12655d4-4f11-4cf4-949d-d3c74399a9bf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أكثر أنواع الحساسية الغذائية شيوعًا لدى الرضع هي حساسية الحليب، أي حساسية حليب البقر. وتنجم هذه الحالة عن رد فعل تحسسي يصدره جسم الرضيع تجاه بروتينات بيتا لاكتالبومين الموجودة في حليب البقر. ونظرًا إلى احتواء معظم أنواع الحليب الصناعي على هذا البروتين، فإن هذه الحساسية تُلاحظ كثيرًا لدى الرضع الذين يتغذون عليه. لكن المشكلة لا تقتصر على الحليب الصناعي؛ فقد تنتقل مسببات الحساسية إلى الرضع الذين يرضعون طبيعيًا عبر حليب الأم إذا تناولت الأم منتجات الألبان. كما قد تنشأ لدى كثير من الرضع المصابين بهذه الحساسية حساسية تجاه حليب الماعز والحليب المحتوي على الصويا أيضًا. ومن أبرز علامات حساسية حليب البقر: البكاء المفرط والمغص الشديد بسبب الغازات خلال الأشهر الأولى، والقيء بعد الرضاعة، وعدم اكتساب الوزن، ووجود كتل دموية في البراز، والإمساك. إذا لاحظتِ هذه العلامات لدى رضيعكِ واشتبهتِ في إصابته بحساسية حليب البقر، فعليكِ استشارة طبيبكِ حتمًا.') WHERE id = '06a7caf5-4128-4600-83b6-7c3d296c2485';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'توجد بعض الطرق التي تساعد على الوقاية من مغص الغازات لدى رضيعكِ أو تخفيف آلامه. احرصي قدر الإمكان على إرضاعه طبيعيًا، إذ إن حليب الأم هو الغذاء الأنسب لجهازه الهضمي ويساعد على جعل عملية الهضم أكثر راحة. وبذلك تتجمع أقل كمية ممكنة من الغازات في أمعائه، وتتمكن البكتيريا التي تساعد على تفكيك الغازات من العمل بصورة أفضل. ينبغي أن تجعلي الفاصل بين الرضعات ساعتين على الأقل. فهذا يساعد على زيادة محتوى حليبكِ من الدهون، ما يدعم نمو رضيعكِ، ويسهّل أيضًا هضم الحليب الذي تناوله. وحاولي ألا تُبقيه في بيئات شديدة الحرارة أو البرودة، وألا تُلبسيه طبقات متراكمة من الملابس الضيقة. فقد تؤثر هذه الأمور سلبًا في وظائف الهضم والدورة الدموية لديه، ما قد يؤدي إلى تراكم الغازات في الأمعاء. واحرصي كذلك على مساعدته على التجشؤ بعد كل رضعة للتأكد من عدم بقاء الهواء في معدته.') WHERE id = '37fe650b-ff02-444b-9514-314d6f5df25d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأت مواعيد نوم رضيعكِ تنتظم، وأصبح أكثر حركة وبدأ يتفاعل معكِ. وقد يقوم أيضًا بحركات تدل على أنه يتعرّف إلى والده وإلى الأشخاص الذين يراهم كثيرًا. ومن أهم أسباب ذلك أن بصره أصبح أفضل؛ ولذلك بدأ يتفحّص ما حوله ويتفاعل مع ما يراه. ومع إتمام رضيعكِ شهره الثاني، تبدأ وجنتاه وذراعاه وساقاه بالامتلاء تدريجيًا بما يتناسب مع الوزن الذي اكتسبه. وباختصار، لم يعد مظهره كمظهر حديثي الولادة. ومع ذلك، عليكِ أن تعلمي أن كل رضيع سليم قد ينمو بطول ووزن مختلفين. ولكي يستقر نظام نومه ويحظى بنوم جيد، لم تعودي بحاجة إلى إيقاظه ليلًا قسرًا لإرضاعه. فقد يؤدي إيقاظه للرضاعة ما دام غير جائع، أو لتغيير حفاضه ما دام مرتاحًا، إلى خفض جودة نومه.') WHERE id = '6bb455df-6ea4-41c3-8194-cb7bda47e257';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما لا تُرضعين رضيعكِ في الوضعية الصحيحة، قد تظهر بعض المشكلات ليس لديه فحسب، بل في جسمكِ أيضًا. وأكثر هذه المشكلات شيوعًا التهاب الثدي. والتهاب الثدي مشكلة صحية تنجم عن انسداد قنوات الحليب، وتشمل أعراضها الحمى والوهن والتعب وألم الثديين واحمرارهما. وفي هذه الحالة التي غالبًا ما تصاحبها عدوى، يحدث الانسداد إذا امتلأت قنوات الحليب بالكامل ولم تُفرّغ. إذا واجهتِ هذه الحالة، فيمكنكِ استخدام مسكن ألم مناسب للرضاعة الطبيعية بعد استشارة طبيبكِ. ومن المهم جدًا أيضًا تفريغ الثدي المصاب بالالتهاب رغم الألم. يزول التهاب الثدي خلال فترة قصيرة عند علاجه بصورة صحيحة، ويمكنكِ مواصلة إرضاع طفلكِ بأمان. لكن إذا لم تتلقي العلاج اللازم، فقد يؤدي الانسداد في ثدييكِ إلى توقف جسمكِ عن إنتاج الحليب.') WHERE id = '68a7f9bc-02a4-47e7-80eb-cfc071e562a7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد أتممتِ شهرين مع رضيعكِ. ويمكنكِ الاطمئنان إلى أن الشهر الثالث سيكون أسهل، وستكونين فيه أكثر خبرة مقارنة بالأشهر السابقة. ينمو رضيعكِ بسرعة كبيرة خلال أشهره الأولى بعد قدومه إلى العالم، وقد يزداد وزنه شهريًا بمقدار يتراوح بين 700 غرام و1500 غرام. وبعبارة أخرى، من المتوقع أن يكتسب ما لا يقل عن 150-200 غرام أسبوعيًا. ووفقًا لهذه الحسابات، يتراوح متوسط وزن رضيعكِ بحلول نهاية هذا الأسبوع بين 4 و6 كغ. ويشير تبليل رضيعكِ حفاضه بمعدل 5 مرات يوميًا إلى أنه يحصل على كفايته من الغذاء ولا يحتاج إلى غذاء إضافي. وإذا أخذنا في الاعتبار أن طوله يزداد بمعدل 1.5-2 سم شهريًا، فقد يتراوح طوله حاليًا بين 57 و62 سم. تذكّري أن جميع هذه القيم متوسطة وقد تختلف من رضيع إلى آخر، وأن رأي طبيبكِ هو المعيار الوحيد الذي ينبغي الاعتماد عليه في هذا الشأن.') WHERE id = 'c4b87e12-4678-4aea-8944-a0c3b90a105f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبكي طفلكِ خلال اليوم بطرق مختلفة ولأسباب متعددة. لكن هل لاحظتِ يومًا أن الدموع لا تنهمر من عينيه أثناء البكاء؟ رغم أن القنوات والغدد الدمعية لدى طفلكِ تعمل، فإنها لا تنتج حاليًا سوى كمية من الدموع تكفي لحماية عينيه والحفاظ على رطوبتهما. تدخل الغدد الدمعية لدى الرضيع مرحلة نمو سريعة بعد الولادة مباشرة، وتصبح في المتوسط قادرة على إفراز الدموع عندما يبلغ عمره 2-3 أشهر. وفي بعض الحالات، قد يحدث انسداد في القنوات الدمعية لدى نحو 5-6% من الرضع. وقد يظهر هذا الانسداد على هيئة إفرازات متيبسة في العينين، وزيادة الدموع، والتصاق الرموش، وإفرازات التهابية، وتورم حول العينين. ويرجع انسداد القناة الدمعية إلى عدم انفتاح الغشاء الموجود في الجزء الذي يصل الكيس الدمعي بالأنف. وإذا لم تُعالج هذه الحالة، تصبح عينا طفلكِ أكثر عرضة للعدوى. لذلك، إذا لاحظتِ هذه الأعراض لدى طفلكِ، فعليكِ استشارة طبيب عيون دون تأخير.') WHERE id = 'e03b8fab-73de-4cff-bd15-34280044bd83';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تراودكِ بعض الأسئلة بشأن إعطاء طفلكِ المصاصة من عدمه. يولد طفلكِ بمنعكس مص قوي، ويُسمى ذلك «المرحلة الفموية»، وتستمر حتى عمر سنتين تقريبًا. توصي الأكاديمية الأمريكية لطب الأطفال باستخدام المصاصة حتى عمر سنة واحدة، لاعتقادها بأنها تساعد على الوقاية من متلازمة موت الرضع المفاجئ. ويؤدي منعكس المص القوي لدى الرضيع خلال هذه المرحلة وظيفة تلبي احتياجاته الغذائية والعاطفية معًا. ويمكن اختيار المصاصة لتلبية حاجة طفلكِ الجسدية إلى المص، ومساعدته على الشعور بالأمان والهدوء عاطفيًا، والحد من استخدام ثدي الأم لغير الرضاعة. ومع ذلك، قد يتحول استخدام المصاصة على المدى الطويل إلى عادة. وإذا لم تحددي مدة استخدامها، فقد تتأثر تغذية طفلكِ، ما قد يؤدي إلى تأخر نموه. كما قد يؤدي استخدامها مدة طويلة إلى اضطراب بنية الأسنان وتأخر الكلام.') WHERE id = '9bf80a49-be8d-491a-9e0b-6671644690ad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترضعين طفلكِ طبيعيًا، فربما لم تبدأ دورتكِ الشهرية بعد. قد تعود الدورة الشهرية لدى الأمهات المرضعات بعد نحو ستة إلى ثمانية أسابيع من الولادة، وقد يتأخر ذلك حتى 24 شهرًا. ويختلف موعد عودة الدورة الشهرية من امرأة إلى أخرى. ويرجع ذلك إلى وجود هرموني البرولاكتين والأوكسيتوسين في جسمكِ، وهما المسؤولان عن إنتاج الحليب وإفرازه. فالبرولاكتين، الموجود بمستويات مرتفعة في دمكِ والمسؤول عن إنتاج الحليب، يثبط إفراز الهرمونات التناسلية اللازمة لنمو البويضات. وما دامت المبايض لا تُنضج بويضة، فلا يمكن حدوث الدورة الشهرية. لذلك، لا يمكن تحديد موعد دقيق لعودة الدورة الشهرية لدى الأمهات اللاتي يرضعن أطفالهن بحليبهن.') WHERE id = 'ed5d9752-70a1-4d4a-938d-22777462f998';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تشعرين بالقلق بشأن استخدام الأدوية، ولا سيما خلال فترة الرضاعة الطبيعية. وكما في الحمل، يمتلك جسمكِ خلال فترة الرضاعة خصائص مختلفة تساعد على حماية طفلكِ. حليب الأم غذاء مذهل يُنتَج في جسمكِ بما يلائم جميع احتياجات طفلكِ. ويحتوي جسمكِ على أنظمة حماية تمنع انتقال بعض المواد الضارة الموجودة في دمكِ إلى قنوات الحليب. وتُسمى هذه الخاصية الفسيولوجية التي تمنع هذا الانتقال «الحاجز الدموي اللبني». تستطيع بعض الأدوية عبور هذا الحاجز، في حين لا يستطيع بعضها الآخر اختراقه، فلا ينتقل إلى الحليب. وبينما يتخذ بعض الأطباء موقفًا صارمًا من استخدام الأدوية خلال فترة الرضاعة، يوازن آخرون بين الفوائد والمخاطر. لذلك، يجب عليكِ استشارة طبيبكِ، والاستفسار عن مكونات الأدوية التي ستستخدمينها، والتأكد من مدى توافقها مع الرضاعة الطبيعية.') WHERE id = '23d4091f-e3fa-4f6e-82ab-2f668868b04f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'البكاء أهم وسيلة يتواصل بها طفلكِ. فقد يبكي بسبب الغازات، أو الجوع، أو النعاس، أو الشعور بالبرد، أو التعرق، أو رغبته في أن تحمليه، أو لأسباب أخرى كثيرة. كما تختلف طريقة بكائه باختلاف احتياجاته. وعلى الأرجح أنكِ بدأتِ بالفعل، من خلال مراقبته، في فهم سبب بكائه والاحتياج الذي يحاول التعبير عنه. فإذا كان طفلكِ يبكي بسبب الجوع، فسوف يهدأ عندما تطعمينه. ومن المهم جدًا تنظيم الرضاعة وفقًا لطلب طفلكِ. وقد يفزع أثناء نومه، فيستيقظ باكيًا. وفي هذه الحالة، يمكن أن تساعده طريقة تُسمى التقميط الجزئي، إذ تلفين ذراعيه ببطانية رقيقة من دون إحكام شديد، على الهدوء. وفي بعض الحالات، قد يهدأ بمجرد أن تحمليه ثم يعاود البكاء عندما تضعينه، رغم تلبيتكِ جميع احتياجاته؛ ويكون ذلك ناتجًا عن بحثه عن التلامس الجسدي. فمن الطبيعي أن يبحث الطفل الذي عاش 9 أشهر في رحمكِ عن هذا التلامس الجسدي خلال الأشهر الأولى بعد الولادة. ولا داعي للقلق من أن يعتاد طفلكِ على الحمل. فحضنكِ هو المكان الوحيد الذي يشعر فيه بالأمان ويستشعر رائحتكِ ودفئكِ.') WHERE id = 'd2ed38a5-2867-473a-a048-a7488c8a0f81';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لأن الغدد العرقية لدى طفلكِ لم تكتمل بعد، فلا يستطيع التعرق لتنظيم درجة حرارة جسمه. لذلك، عليكِ تجنب إبقائه في بيئة شديدة الحرارة أو إلباسه ملابس أكثر مما يلزم. تكفي لطفلكِ درجة حرارة غرفة تتراوح بين 22-24 درجة تقريبًا. ولا حاجة إلى إلباسه داخل المنزل طبقات متعددة، مثل سترة بلا أكمام وسترة أخرى وحذاء صوفي فوق الجوارب. يكفي أن تُلبسيه بدلة قطعة واحدة فوق ملابس داخلية رقيقة أو قطعة «بدي»، مع زوج من الجوارب. لكن إذا وُلد طفلكِ قبل أوانه، فقد يحتاج إلى طبقة إضافية من الملابس لأنه لا يستطيع الحفاظ على حرارة جسمه بالكامل. ولمعرفة ما إذا كانت ملابسه كافية، يمكنكِ لمس مؤخرة رقبته أو بطنه. عادةً ما تكون يدا الرضع وقدماهم باردتين، لذلك قد يضللكِ ذلك عند محاولة معرفة ما إذا كان طفلكِ يشعر بالبرد. يفقد الرضيع معظم حرارة جسمه عبر الرأس. وللحد من ذلك، يمكنكِ إلباسه قبعة غير سميكة جدًا داخل المنزل. لكن تذكري أنه يجب حتمًا أن ينام ليلًا من دون قبعة، لأنها قد تعيق تنفسه وتعرضه للاختناق.') WHERE id = '48c1b6b4-184f-478a-85ac-ef677c12d146';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حان الوقت الآن للاستغناء عن القفازات من أجل تنمية التناسق بين يدي طفلكِ وعينيه ودعم تطوره. فقد يؤثر ارتداء القفازات لفترات طويلة سلبًا في تفاعله مع العالم المحيط وفي نموه. وبعد أن بدأ طفلكِ يكتشف يديه ويتفحصهما جيدًا، قد يبدأ بإمساك الأشياء التي تقدمينها له ووضعها في فمه. فعندما يقبض يديه ويحاول وضع كل ما يصل إليهما في فمه، فإنه يسعى بهذه الطريقة إلى التعرف إلى الأشياء. وتؤدي هذه التجارب دورًا بالغ الأهمية في نمو ذكائه. إذ يتشكل الذكاء إلى حد كبير من خلال الخبرات التي يكتسبها طفلكِ بحركاته وسلوكياته النشطة. واليدان هما أول وسيلة يستخدمها لاستكشاف محيطه وجمع المعلومات التي ستسهم في تشكيل ذهنه. لذلك من المهم جدًا أن تشجعيه على ذلك. ويمكنكِ دعم نموه بتقديم ألعاب تلفت انتباهه ويستطيع إمساكها، وقطع قماش ملونة، وأشياء تصدر أصواتًا مثل الخشخيشة.') WHERE id = '42c11358-bbe1-48ad-b54d-e26f562016b7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بلغ نمو دماغ طفلكِ مرحلة تتيح له الاستجابة للتهويدات والأغاني والموسيقى، بل وحتى للأصوات الآتية من الخارج. ولضمان نمو دماغه بصورة صحية وسليمة، احرصي على أن تكون الموسيقى جزءًا من حياتكما اليومية. كما أن غناء الأغاني أو التهويدات له يساعد على تقوية الرابط بينكما. ووفقًا للدراسات، يتطور الدماغ واللغة بوتيرة أسرع لدى الأطفال الذين يستمعون إلى الموسيقى في مراحل مبكرة مقارنة بغيرهم. وقد لوحظ أيضًا أن احتمال اهتمام هؤلاء الأطفال بالآلات الموسيقية مستقبلًا يكون أكبر. ولأن طفلكِ كان قادرًا على تمييز صوتكِ من أصوات الآخرين حتى وهو في رحمكِ، فإن غناء الأغاني والتهويدات له يتيح لكما قضاء وقت ممتع ومميز معًا، ويسرّع أيضًا نمو حصيلته اللغوية وقدراته على اكتساب اللغة. وإذا كان طفلكِ يجد صعوبة خاصة في النوم، فقد تساعده الموسيقى الكلاسيكية أو الهادئة على الاسترخاء والخلود إلى النوم بسهولة أكبر.') WHERE id = '161206e9-2801-48d5-bf23-ba2c2a393a9f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل يبكي طفلكِ من دون سبب، وهل ازداد انزعاجه في الأيام الأخيرة؟ مرحبًا بكِ في فترة الطفرة الثانية التي يمر بها طفلكِ، أي طفرة النمو والتطور. 😊 طفرة الأسبوع الثامن مرحلة ممتعة سيكتسب طفلكِ بعد انتهائها مهارات جديدة. خلال طفرة النمو هذه، سيبدأ بالتعرف إلى جسمه بصورة أفضل واكتشاف يديه وقدميه. وقد تلاحظين الآن أنه يحاول مص يديه وأصابعه، وأنه يستخدم أصابعه بسهولة للإمساك بأي غرض تضعينه في يده. 😊 ومع ازدياد حركته قليلًا مقارنة بمرحلة حديثي الولادة، قد يبدأ طفلكِ بتسلية نفسه عندما تضعينه من حضنكِ على الأرض. وعلى الرغم من أنه لا يزال غير قادر على رؤية الأشياء البعيدة بوضوح، فإن الأغراض ذات الألوان الزاهية والألعاب المزخرفة والأضواء ستبدأ بجذب انتباهه. وبما أن مرحلة أكثر نشاطًا في تفاعله مع العالم الخارجي قد بدأت، فقد يتشتت انتباهه لفترات قصيرة، مما قد يقلل رغبته في الرضاعة. في هذه الحالة، قد يكون من الأفضل إرضاعه في غرفة أكثر هدوءًا وإظلامًا، أو عند استعداده للنوم.') WHERE id = 'ba812bc8-8097-4c97-a28f-220a769e0dd9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن يستجيب لكِ بابتسامات اجتماعية واعية وحقيقية. وبما أن عضلات رقبته تنمو بسرعة خلال هذه الفترة، فمن المهم جدًا لسلامة نمو عموده الفقري أن تجعليه يمارس يوميًا جلسات قصيرة من الاستلقاء على البطن تحت إشرافكِ. ومع تحسن قدرته على الإدراك، أصبح قادرًا على تتبع الأشياء الملونة بعينيه، وقد يبدأ أولى محاولاته للتواصل معكِ من خلال الأصوات الخافتة التي يصدرها. وإذا تلقى طفلكِ لقاحات الشهرين الروتينية في هذه الفترة، فيمكنكِ تهدئة الانزعاج الخفيف وضعف الشهية اللذين قد يظهران بعد التطعيم عبر إرضاعه كثيرًا واحتضانه.') WHERE id = '3c33ef6c-ad69-4a43-8495-e0ff0a641f32';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي أن يولد الأطفال من دون شعر أو بشعر كثيف. وإذا وُلد طفلكِ بشعر، فقد يثير تساقطه السريع، ولا سيما خلال هذه الفترة، بعض القلق لديكِ. تُسمى هذه الحالة لدى طفلكِ «تساقط الشعر الكربي»، وهي مرتبطة بالتغيرات الهرمونية. خلال الحمل، تكون بصيلات شعر الطفل في مرحلة مستمرة من النمو والتطور. أما بعد الولادة، فتدخل البصيلات، بتأثير الهرمونات أيضًا، في مرحلة راحة مؤقتة. وقد يعاني بعض الأطفال من تساقط الشعر إلى درجة ظهور مناطق خالية منه. وإذا كنتِ تجعلين طفلكِ ينام دائمًا في الوضعية نفسها، فقد تلاحظين أن تساقط الشعر يكون أوضح في مناطق الرأس التي تحتك بالوسادة. ويُعد هذا التساقط فسيولوجيًا ولا يرتبط بأي نقص غذائي، وعندما يبلغ طفلكِ نحو 6 أشهر يبدأ عادة بالتراجع، وينمو شعر جديد مكان الشعر المتساقط.') WHERE id = '902d6d84-5a76-4be3-852e-11ae4442029d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تلاحظين هذه الأيام أن طفلكِ في حالة انزعاج مستمرة، ويرغب في الرضاعة كثيرًا لتهدئة نفسه، بل وقد لا يرغب في ترك الثدي. تشير هذه العلامات إلى معاناته من الغازات. ورغم أن هذه الحالة طبيعية من الناحية الفسيولوجية، فإنها قد تكون خفيفة لدى بعض الأطفال، بينما تسبب لدى آخرين مغصًا شديدًا. ومع اكتمال طفرة الأسبوع الثامن وتسارع نمو الدماغ على وجه الخصوص، يبدأ دماغ طفلكِ بإدراك عضلات جسمه ومفاصله وأعصابه. وقبل مرحلة الإدراك هذه، كان يطرد الغازات بصورة لا إرادية وبسهولة. أما الآن، فيحاول التحكم في هذه العضلات بوعي. ويحتاج إلى بعض الوقت ليتعلم كيفية شد العضلات اللازمة لطرد الغازات وإرخائها. ولأنه لا يستطيع التحكم الكامل في هذه العضلات خلال الأشهر الأولى ويبقيها مشدودة باستمرار، فإنه يواجه صعوبة في إخراج الغازات، مما يؤدي إلى آلامها. في هذه اللحظات المزعجة، حاولي تهدئة طفلكِ وتذكّري أن هذه مرحلة مؤقتة. ومع استمرار نمو دماغه خلال الأسابيع المقبلة، سيتعلم التحكم في هذه العضلات وسيتمكن من إخراج الغازات بسهولة أكبر.') WHERE id = 'f2315e81-cb4e-4e16-ad43-3687f3cbaef0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الحقائق المثبتة علميًا أن للألوان تأثيرًا في نفسية طفلكِ وطاقته ونموه. وبما أن طفلكِ بدأ الآن يميّز الألوان، فإنه يصبح منذ هذه المرحلة أكثر حساسية لدرجات الألوان المحيطة به. ولا يقتصر تأثير الألوان على الحالة المزاجية فحسب، بل إن بعض الألوان التي تستخدمينها في غرفته وملابسه وحتى ألعابه تنشّط دماغه، وتؤثر في عادات نومه، وتقوّي ذاكرته. لذلك، من المهم جدًا أن تعرفي لغة الألوان. فعلى سبيل المثال، قد تمنح درجات الأزرق الداكن إحساسًا بالكآبة، بينما تُحدث درجاته الفاتحة تأثيرًا مهدئًا في طفلكِ وتساعد جهازه العصبي على الاسترخاء. وتساعد درجات الطوبي والترابي طفلكِ على الشعور بالسكينة، في حين قد يسبب له اللون الأحمر الداكن التوتر. وبوجه عام، تمنح الألوان الدافئة طفلكِ بيئة مفعمة بالحيوية، بينما تتميز الألوان الباردة بتأثير أكثر هدوءًا وراحة.') WHERE id = '1a3eb5d8-5f3e-4a88-8c08-5b1025f3faf7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا عادت دورتكِ الشهرية، فقد تلاحظين بعض التغيرات في كمية حليبكِ واستجابة طفلكِ لحليب الأم. ويرجع ذلك إلى أن التغيرات الهرمونية التي تنظّم دورتكِ الشهرية قد تؤثر قليلًا في إنتاج الحليب وتركيبته. لكن ينبغي ألا تمنعكِ هذه التغيرات من الرضاعة الطبيعية. فعودة دورتكِ الشهرية لا تعني ضرورة فطام طفلكِ؛ إذ إن الرضاعة الطبيعية خلال هذه الفترة آمنة تمامًا. وخصوصًا في أيام الإباضة، ترتفع كميتا الصوديوم والكلوريد في حليبكِ، بينما تنخفض كميتا البوتاسيوم واللاكتوز. وقد يجعل ذلك مذاق حليبكِ أكثر ملوحة قليلًا أو أقل حلاوة. كذلك، قد تشعرين بامتلاء الثديين وحساسيتهما نتيجة تغيّر مستويات هرموني الإستروجين والبروجسترون خلال فترة الإباضة وقبل بدء نزول الدم.') WHERE id = '94e7a1fa-9551-4f9b-be28-3651b7e35a86';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لأن كل اهتمامكِ ينصبّ على طفلكِ في هذه الفترة، فقد تبدو لكِ فكرة حدوث حمل جديد مخيفة. وعلى الرغم من انخفاض خصوبتكِ خلال فترة الرضاعة الطبيعية، فإنها لا تنعدم تمامًا. ففي الأشهر الأولى بعد الولادة، تتوقف عملية الإباضة لبعض الوقت كما يحدث أثناء الحمل. لكن ليس من الصحيح الاعتماد كليًا على الاعتقاد الشائع بأن "الرضاعة تمنع الحمل" وعدم استخدام وسيلة لمنعه. إذا كان طفلكِ يعتمد على حليب الأم وحده، فقد تتأخر دورتكِ الشهرية مدة 6-8 أشهر. أما إذا كان طفلكِ يتناول الحليب الصناعي، فقد تعود الإباضة والدورة الشهرية بعد 3 أسابيع من الولادة. تذكّري أنه حتى في غياب الدورة الشهرية، يظل احتمال حدوث الحمل نحو 1-2%، وقد تحدث الإباضة قبل أول نزف للدورة الشهرية. لذلك، إذا كنتِ لا تخططين لحمل جديد، فمن المهم استخدام إحدى وسائل منع الحمل في كل مرة تمارسين فيها العلاقة الجنسية.') WHERE id = 'a67e120d-50f6-40f7-8148-f8a30d4ac88d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يثير قلقكِ شعوركِ بخشونة أو وجود شعر عندما تمرّرين يدكِ على ظهر طفلكِ. وعلى الرغم من أن هذه الحالة تُعرف شعبيًا باسم "الشوك"، فإنه ينبغي عدم الخلط بينها وبين شوكة الكعب لدى البالغين، وهي ليست مدعاة للخوف عادةً. ويشيع ظهور هذا الشعر لدى الرضّع، لكنه غالبًا لا يكون ملحوظًا، ويُلاحظ عند الإناث أكثر، وعادةً ما تشعرين به أثناء الاستحمام. ورغم عدم ثبوت تسببه في أي ضرر من الناحية الطبية، يمكنكِ تدليك طفلكِ لتهدئته إذا كانت هذه الحالة تقلقكِ أو كنتِ تعتقدين أنه منزعج. وعند التدليك، عليكِ استخدام زيوت طبيعية خالية من الإضافات الكيميائية ولا تهيّج بشرة طفلكِ الرقيقة. فالتدليك بهذه الزيوت يساعد على تهدئة طفلكِ وقد يساهم أيضًا في تساقط هذا الشعر. ويمكنكِ كذلك استشارة طبيبكِ بشأن الزيوت المناسبة وطريقة العناية.') WHERE id = 'd55543a0-5e2c-48fc-9829-ce7e9fdddd6c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كما هي الحال مع كل رضيع، قد يتحول إلباس طفلكِ إلى مغامرة حقيقية. فبسبب عدم بقائه ساكنًا وتحريكه يديه وقدميه باستمرار، قد يستغرق تبديل ملابسه وقتًا طويلًا، وخصوصًا في أشهر الشتاء. لذلك، من المفيد أن تختاري له ملابس عملية سهلة الإلباس وتوفّر عليكِ الوقت. وعند التسوق، اختاري ملابس ذات فتحات رقبة واسعة تسمح بمرور رأس طفلكِ بسهولة. ولأن بشرة طفلكِ أكثر حساسية بكثير من بشرة البالغين، احرصي على اختيار منتجات مصنوعة من القطن ولا تسبب الحساسية. كما أن السلامة مهمة جدًا؛ لذا تجنّبي الأزرار التي يمكن لطفلكِ ابتلاعها، والسحّابات الصلبة التي لا تكون أطرافها مغطاة بالقماش. فقد ينزع الأطفال هذه الأزرار بدافع الفضول ويضعونها في أفواههم. كذلك، لا تُعدّ الأشرطة والربطات والدانتيل الزائد خيارات مناسبة لهذه المرحلة.') WHERE id = 'b8aa2eab-ff56-4ab9-8b20-121fbd2d3ec4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد فقر الدم الناتج عن نقص الحديد أكثر أنواع فقر الدم شيوعًا في بلدنا. والحديد عنصر بالغ الأهمية لجسم الإنسان، إذ تزداد حاجة الخلايا والأنسجة إليه، وخصوصًا خلال فترات النمو السريع. لذلك، يشيع نقص الحديد لدى الرضّع في الفترة التي يكون فيها نموهم في أسرع مراحله، أي بين عمر 6 و24 شهرًا. وحتى يبلغ طفلكِ عمر 6 أشهر، من المهم أن تُدخلي الأطعمة الغنية بالحديد في نظامكِ الغذائي إذا كان يرضع طبيعيًا. أما إذا كان طفلكِ يتغذى على الحليب الصناعي، فيجب الانتباه إلى كمية الحديد الموجودة فيه، ويمكنكِ استشارة طبيبكِ بشأن ذلك. وبعد الشهر 6، لا يعود حليب الأم وحده كافيًا، لذا عليكِ إعداد قائمة غذائية غنية بالحديد عند بدء تقديم الأطعمة التكميلية. ويُعد صفار البيض الذي تقدمينه في وجبة الإفطار غنيًا جدًا بالحديد. ولا تنسي أيضًا إضافة لحم الضأن أو لحم العجل إلى حساء الخضراوات الذي تحضّرينه لطفلكِ.') WHERE id = 'd050305e-c358-4c29-9151-2db694755a43';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تزال حاسة اللمس أكثر حواس طفلكِ تطورًا. لذلك، فإن الحفاظ على التلامس الجلدي المستمر معه يعزز الرابطة بينكما. وتُعد حاسة اللمس، التي تكتسب أهمية كبيرة خلال الأشهر الأولى من حياة طفلكِ، من أهم العوامل التي تساعده على التواصل مع محيطه وفهمه. ومن هذا المنطلق، تُعد أنشطة مثل تدليك طفلكِ ومداعبته وتأمين التلامس المباشر بين بشرتكِ وبشرته من أكثر الطرق الطبيعية والفعالة لتقوية الرابطة بينكما. يبدأ تواصل طفلكِ مع محيطه عندما يُلمس ويُداعب ويُحمل بين الذراعين، ما يدعم أيضًا نموه النفسي والاجتماعي. أما الاعتقاد الشائع بضرورة عدم حمل الرضيع خوفًا من أن يعتاد على ذلك، فهو خاطئ تمامًا ويضر بالعلاقة بين الأم وطفلها. إن تحفيز حاسة اللمس لدى طفلكِ والحفاظ على التواصل الجسدي معه يدعمان نمو شعوره بالأمان ونجاح الرضاعة الطبيعية من خلال زيادة إنتاج الحليب. كما أظهرت الدراسات أن الأطفال الذين يحظون بتواصل جسدي ويُدلّكون بانتظام يحققون زيادة أكبر في الوزن والطول مقارنة بغيرهم.') WHERE id = 'aa7f3500-7164-43a7-9fa5-208e7d522806';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون عدوى فيروس الروتا، التي تظهر لدى الأطفال على هيئة إسهال كريه الرائحة وقيء متواصل وحمى، شديدة الخطورة على طفلكِ، ولا سيما خلال الأشهر الأولى. وقد سُمّي هذا الفيروس «روتا» بسبب شكله الدائري، وهو قادر على مقاومة أحماض المعدة. وبعد مروره عبر المعدة ووصوله إلى الأمعاء الدقيقة، يصيب فيروس الروتا خلاياها ويبدأ بالتكاثر. وقد يرفع الجهاز المناعي، استجابةً لهجوم الفيروس، درجة حرارة الجسم إلى 39°C. تبدأ أعراض عدوى فيروس الروتا خلال 48 ساعة من الإصابة به. وقد تظهر على هيئة إسهال مائي يزول من تلقاء نفسه، أو إسهال مصحوب بحمى وقيء بدرجة خطيرة، ما يؤدي إلى فقدان شديد للسوائل من الجسم. ونظرًا إلى أن هذه العدوى قد تسبب جفافًا شديدًا، فقد تستدعي دخول المستشفى والعلاج بالسوائل الوريدية، خاصةً لدى الرضع. وعلى الرغم من أن لقاح فيروس الروتا لا يحمي طفلكِ من هذه العدوى بنسبة 100%، فمن المهم جدًا إعطاؤه له لأنه يخفف شدة المرض بدرجة كبيرة. ويوصي جميع الأطباء تقريبًا بشدة بإعطاء هذا اللقاح.') WHERE id = '1b640d9c-64b4-46e3-adef-12469bcc8075';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تشعركِ نوبات القيء الغزير التي تحدث لدى طفلكِ من حين إلى آخر بالقلق. وعادةً ما يحدث هذا القيء خلال الأشهر الأولى، بعد وقت قصير من إرضاع الطفل أو إطعامه. ويرجع القيء الذي يبدأ خلال الأيام القليلة الأولى بعد الولادة إلى عدم اكتمال نضج الجزء المسمى بالعضلة العاصرة (الصمام) بين المعدة والمريء. وقد يتوقف هذا القيء خلال 3-4 أشهر مع نمو طفلكِ، كما قد يستمر حتى بلوغه عامين. وقد يرتد الحليب أو الحليب الصناعي المختلط بالهواء أثناء الرضاعة أو الإطعام إلى أعلى عبر المريء، ما يزيد احتمال القيء. إذا لاحظتِ حالة مشابهة لدى طفلكِ، فمن المفيد مراجعة الطريقة التي تطعمينه بها. فقد تزيد بعض العوامل من شدة القيء، مثل استلقاء الطفل بشكل مسطح تمامًا أثناء الرضاعة الطبيعية أو إعطائه الحليب الصناعي، أو ابتلاعه الهواء، أو رضاعته ببطء شديد أو بسرعة كبيرة. كما أن مساعدتكِ طفلكِ على التجشؤ بعد إرضاعه أو إطعامه ستقلل نوبات القيء بدرجة كبيرة.') WHERE id = '5fefb883-23f7-42f1-b985-be875f76a7d5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أقوى وسائل حماية طفلكِ من العدوى هي حليبكِ واللقاحات التي تحرصين على إعطائها له. فمنذ لحظة ولادته، تساعد الأجسام المضادة التي يحصل عليها من حليبكِ على إرساء أساس جهازه المناعي وحمايته من الأمراض. لكن تذكري أن هذه الحماية الطبيعية تفقد فعاليتها بعد فترة قصيرة. وإذا لم يتلقَّ طفلكِ اللقاحات في هذه المرحلة، فقد لا يكون جسمه قويًا بما يكفي لمقاومة الجراثيم والفيروسات عند التعرض لها. يفقد ملايين الأشخاص حياتهم سنويًا حول العالم بسبب أمراض يمكن الوقاية منها باللقاحات. وتشكل الأمراض المعدية نسبة كبيرة من أمراض الطفولة والرضاعة، وقد يؤدي بعضها إلى أوبئة خطيرة ومضاعفات شديدة. لذلك، من المهم جدًا أن تلتزمي بدقة بجدول تطعيم طفلكِ، كي يتمتع بمناعة قوية مدى الحياة، أيتها الأم العزيزة.') WHERE id = '9a1ea20d-ced6-455d-9f64-c58e6cf75bea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بعد ولادة طفلكِ، ينمو بسرعة مذهلة، خاصةً خلال عامه الأول. وقد تشعرين أحيانًا وكأنه كبر خلال يوم واحد، بل حتى خلال ليلة واحدة. لكن مرحلة النمو هذه لا تمر دائمًا بهدوء؛ إذ تصاحب النمو السريع بعض التأثيرات الفسيولوجية. وقد تلاحظين لدى طفلكِ من وقت إلى آخر اضطرابات في النوم أو نوبات بكاء أو تغيرات في نمط التغذية، وربما تواجهين حالات لا تعرفين سببها. تُعرف هذه الحالات، التي لا يدركها كثيرون قبل أن يصبحوا آباءً وأمهات لكنها تحدث لدى جميع الأطفال تقريبًا، باسم طفرات النمو أو قفزات النمو. وهذه الطفرات التي يمر بها طفلكِ، شأنه شأن سائر الأطفال، طبيعية تمامًا وجزء ضروري من نموه. وخلال فترات طفرات النمو، لا ينمو طفلكِ جسديًا بسرعة فحسب، بل يكتشف أيضًا أمورًا جديدة عن العالم الخارجي أو يكتسب مهارات جديدة.') WHERE id = 'bf8343fd-c467-4ff0-b59e-adf0ca316a49';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بشرة طفلكِ أرق من بشرة البالغين، وهي شديدة الرقة والحساسية تجاه العوامل الخارجية. كما أن طبقة الدهون لديه أقل منها لدى البالغين، ولذلك يكون أقل قدرة على تحمل البرد. لذا ينبغي لكِ توخي الحذر عند إلباسه، خاصةً خلال الأشهر الأولى، والانتباه إلى مكونات ملابسه. وبما أن الملابس تلامس بشرة طفلكِ مباشرةً، فمن الأفضل اختيار الأقمشة القطنية الناعمة والطبيعية. وينبغي أن تكون الملابس التي تختارينها فضفاضة بما يكفي ليتحرك براحة، وألا تقيد حركة ذراعيه وساقيه. ولتفادي التأثير في الدورة الدموية، اختاري أيضًا جوارب ناعمة ذات حواف مطاطية غير ضيقة. وعند التسوق، نوصيكِ بالتأكد من أن أجزاء الملابس المحيطة بالذراعين والرقبة والخصر غير قاسية، والانتباه إلى جودة التفاصيل مثل الكباسات والأزرار.') WHERE id = '03d19ce6-58a4-42e4-a4c9-562747272e51';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أفضل غذاء لكل رضيع هو حليب أمه، لأنه يتكوّن بما يتناسب تحديدًا مع احتياجاته. لكن قد تتعذر الرضاعة الطبيعية على بعض الأمهات لأسباب صحية أو شخصية. وفي هذه الحالات، يكون أفضل بديل هو تركيبات الحليب الصناعي المُعدّة خصيصًا للرضع. وتُنتج هذه التركيبات عبر تعديل مكونات حليب الأبقار أو الماعز باستخدام التقنيات الحديثة لجعله مشابهًا لحليب الأم. وعلى الرغم من أن بنية حليب الأبقار الطبيعي تشبه بنية حليب الأم، فإن الدراسات تُظهر أنه صعب الهضم وأن تركيبته غير مناسبة للرضع. لذلك لا ينصح الأطباء بتقديم حليب الأبقار قبل عمر سنة. وتتوفر في الأسواق أنواع مختلفة من الحليب الصناعي المخصص للسنة الأولى، منها التركيبات المعتمدة على حليب الأبقار، أو الصويا، أو البروتين المتحلل. وتُدعّم التركيبات المعتمدة على حليب الأبقار بالعناصر التي يحتاج إليها الرضيع، بينما يُوصى عادةً بالتركيبات المعتمدة على الصويا للرضع المصابين بحساسية تجاه بروتين حليب الأبقار.') WHERE id = '54371049-7cba-412e-931d-3ce67181ed5e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن أكثر حركة! 😊 ومن أهم أسباب ذلك، بالطبع، نمو عضلاته. وربما بدأتِ تلاحظين منذ الآن أن طفلكِ، الذي يقترب من إتمام شهره الثالث، أصبح أكثر نشاطًا. لقد دخل طفلكِ في هذه المرحلة فترة نمو سريعة، إذ بدأ بإبقاء رأسه مرفوعًا، وأصبح قادرًا على رفع نفسه إلى زاوية تقارب 45 درجة وهو مستلقٍ. ومن الأسباب الأخرى لزيادة حركته رغبته في استكشاف ما حوله. فقد أصبح يميّز الألوان بصورة أفضل، ويرغب في التعرّف إلى محيطه بفضل تطور قدرته على الرؤية. وخلال هذه الفترة المعروفة بشهر الاستكشاف، يُتوقع أن يبدأ بتفحّص يديه، ومحاولة الإمساك بالأشياء التي تعرضينها عليه، وتتبعكِ بعينيه. وقد يزيد طفلكِ تواصله البصري معكِ بعدما بدأ يميّزكِ أنتِ ووالده بوضوح. ومع تطور الانتباه السمعي والبصري لديه، قد تلاحظين هذا الشهر أنه ينظر إليكِ أثناء حديثكِ وكأنه يفهمكِ. وبالطبع، لكل هذه التطورات نتائجها؛ فمثلًا، قد ينام طفلكِ وقتًا أقل لأنه يفضّل استكشاف محيطه. واستعدي أيضًا لصرخات الفرح التي لا تنتهي! 😊') WHERE id = '5ea89e0c-0d1c-402a-8337-a40bace39e26';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حليب الأم غذاء مذهل. فهذا الغذاء الرائع تزداد كميته وتتغير تركيبته مع نمو طفلكِ، بما يلبي احتياجاته. ويبدأ تكوّن قنوات الحليب اللازمة لإنتاجه منذ اللحظات الأولى من الحمل. وتتطور الغدد الثديية طوال الثلث الأول من الحمل، ثم تمتلئ بالحليب، خصوصًا في الأيام القريبة من الولادة، استعدادًا لقدوم طفلكِ. وحتى حدوث الولادة، تنظّم الهرمونات التي تفرزها المشيمة عدم نزول الحليب إلى القنوات وتوقف إنتاج المزيد منه. أما خلال فترة الرضاعة الطبيعية، فتضمن هرمونات الأوكسيتوسين والبرولاكتين التي يفرزها جسمكِ استمرار إنتاج الحليب وعملية الرضاعة. ويلبي حليبكِ جميع احتياجات طفلكِ الغذائية خلال الأشهر الستة الأولى، مثل البروتينات والدهون والحديد والفيتامينات. وبعد عمر 6 أشهر، ينبغي أن تبدئي تدريجيًا بإدخال الأغذية التكميلية لدعم نموه. ومع زيادة سعة معدة طفلكِ واحتياجه إلى السعرات الحرارية، تزداد كمية حليبكِ وكثافة العناصر الغذائية فيه أيضًا. وهكذا يستفيد طفلكِ من حليبكِ إلى أقصى حد حتى انتهاء فترة الرضاعة الطبيعية.') WHERE id = 'e67478e1-350c-4cf1-9917-9b4bd3ed801c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل التقنيات الحديثة والمعرفة الطبية، تتوفر وسائل عديدة ومختلفة لمنع الحمل للنساء اللواتي لا يخططن لحمل جديد. ولا يُنصح بحبوب منع الحمل، وهي من أكثر الوسائل شيوعًا، إذا كنتِ ترضعين طبيعيًا، لأنها تحتوي على الإستروجين وقد تقلل كمية حليبكِ. أما الحبوب الخالية من الإستروجين، فيمكن استخدامها بأمان بعد 6 أسابيع من الولادة. وتحتوي وسيلة منع الحمل المعروفة بالحقنة كل ثلاثة أشهر على البروجسترون، ولا تشكل أي خطر خلال فترة الرضاعة الطبيعية. وعلى خلاف الحقنة التي تُعطى كل ثلاثة أشهر، تحتوي الحقن الشهرية على الإستروجين، لذلك لا يُنصح باستخدامها خلال فترة الرضاعة الطبيعية. أما الغرسة، فهي وسيلة هرمونية توضع تحت الجلد وتوفر الحماية لمدة ثلاث سنوات. وعلى الرغم من انتقال الهرمون الموجود فيها إلى حليبكِ، فإنه لا يؤثر في طفلكِ. ومن أكثر الوسائل التي يوصي بها الأطباء اللولب الرحمي، الذي يتميز بفعالية عالية جدًا في منع الحمل. ويتوفر اللولب بخيارات هرمونية وغير هرمونية، ويمكن تركيبه بعد 6 أسابيع من الولادة.') WHERE id = 'e001d0c5-46e0-40b1-82c7-a4a7f2a5f692';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد اختيار ملابس طفلكِ موضوعًا حساسًا يتطلب الانتباه إلى التفاصيل، شأنه شأن كل ما يتعلق به. ومن أهم الأمور التي ينبغي مراعاتها في الملابس السلامة. فمن الضروري لأمان طفلكِ اختيار الملابس البسيطة ذات الكبّاسات بدلًا من الملابس التي تحتوي على أزرار أو أربطة طويلة. وعند الاختيار، ينبغي أيضًا انتقاء منتجات عالية الجودة لا تتسرب منها الأصباغ التي قد تتراكم في الجسم كمواد سامة وتسبب تأثيرات مسرطنة. ويطوّر جسم طفلكِ آلية دفاعية ضد جميع المواد التي قد تضر به، وتحدث الحساسية نتيجة استجابة هذه الآلية الدفاعية. ونظرًا إلى احتمال تسبب الأصباغ المستخدمة في الملابس بحساسية لدى طفلكِ، ينبغي أن تختاري منتجات حاصلة على شهادات مطابقة للمعايير. إذ تخضع المنتجات الحاصلة على هذه الشهادات لتحليلات للكشف عن المواد المشبوهة التي قد تضر بجسم طفلكِ، وتُصنّع وفقًا لمعايير السلامة. لذلك يمكنكِ إلباس طفلكِ ملابس تستوفي هذه المعايير وأنتِ مطمئنة.') WHERE id = '8bcfa34a-ab3b-47cd-8082-d8d412e4c0f8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إنه شهركما الثالث معًا، أنتِ وطفلكِ! استعدي في هذا الشهر، الذي تدخلين فيه مرحلة جديدة مع طفلكِ، لمفاجآت ستمنحكِ الكثير من السعادة. فقد تطورت مهارات طفلكِ الحركية إلى درجة تمكّنه من الإمساك بالأشياء التي تضعينها في يده، ولو لفترة قصيرة. والأهم أن هذا لم يعد مجرد رد فعل انعكاسي، بل بدأ يتحول إلى سلوك إرادي. وبينما يبدأ منعكس القبض في يدي طفلكِ بالاختفاء، لا يزال منعكس القبض في قدميه بحاجة إلى بضعة أشهر أخرى حتى يزول. وهناك أمر آخر ستلاحظينه خلال الانتقال من ردود الفعل الانعكاسية إلى السلوك الإرادي، وهو مرتبط بتغذية طفلكِ. فحركة فتح الفم عند لمس خدي الطفل، وهي من منعكسات حديثي الولادة، تبدأ تدريجيًا خلال هذا الشهر بالتحول إلى سلوك إرادي. أي إن طفلكِ لن يفتح فمه بعد الآن إذا لم يكن جائعًا. وتحدث هذه التغيرات السلوكية، بالطبع، بفضل النمو السريع لدماغ طفلكِ.') WHERE id = '327fd5ec-447f-4d93-a81c-c3fdb4d5f652';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل يرفع طفلكِ يديه بمحاذاة رأسه لساعات ويتأملهما بانبهار؟ يبدو كأننا نسمعه يقول: "أجل!" 😊 في هذه الأسابيع، تلاحظ كل أم تقريبًا أن طفلها يراقب يديه ليستكشفهما ويضعهما في فمه. من الطبيعي تمامًا أن يُظهر طفلكِ هذا السلوك خلال مراحل نموه، ولا ينبغي لكِ منعه. دعيه يضع يديه في فمه بقدر ما يشاء. 😊 ومع ازدياد اهتمام طفلكِ بيديه وأصابعه، يرفعهما ويحركهما ويتأملهما، خصوصًا عندما يكون مستلقيًا على ظهره. وقد يحرك يديه بسرعة ويتابع حركاته بعينيه ورأسه. ومع اجتياز طفلكِ هذه المراحل، سيتعلم التحكم في يديه واستخدامهما كأداة مفيدة لاستكشاف الأشياء المحيطة به. كل ما عليكِ الانتباه إليه هو التأكد من نظافة يديه وتقليم أظافره كي لا يؤذي داخل فمه. نتمنى له استكشافًا ممتعًا! 😊') WHERE id = 'caffa322-fe7d-4bfd-9362-04360cd00a6c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأت الذكريات والتجارب تترسخ في دماغ طفلكِ الذي بلغ شهره الثالث. وفي المرحلة الأولى، تتكون هذه الذكريات من خلال الحركات المتكررة باستمرار. وبما أن طفلكِ بدأ يتذكر الأشخاص والأشياء وتعبيرات الوجه التي رآها من قبل ويميز بينها، فهو يعرف أن بكاءه سيجذب الانتباه. ومن أجمل التطورات التي تحدث هذا الشهر تعلّمه أن يبادلكِ الابتسام عندما تبتسمين له. استعدي للكثير من الابتسامات. 😊 في الواقع، يبدأ تكوّن ذاكرة طفلكِ وهو لا يزال في رحمكِ. فمنذ تطور حاسة السمع لديه، يبدأ في سماع الأصوات وتخزينها في ذاكرته، ولذلك يستطيع بعد ولادته تمييز صوتكِ بسهولة عن أصوات الآخرين. والآن، بفضل نمو دماغه السريع، أصبح قادرًا على فهم المعلومات التي يحتفظ بها في ذاكرته والتفاعل معها. فعلى سبيل المثال، يستطيع طفل يبلغ من العمر 3 أشهر الاحتفاظ في ذاكرته بصورة غرض عرضته عليه أمه مدة تصل إلى 7 أيام، وقد يُظهر استجابة تدل على تعرفه إليه عند عرضه عليه مجددًا.') WHERE id = 'a7c25396-4991-4496-8a65-64211f7dd866';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل التطور السريع للجهاز العصبي والحواس لدى طفلكِ، بدأ يتفاعل أكثر مع محيطه. لذلك، من الطبيعي ألا يرغب في البقاء ساكنًا، وأن يبكي عندما يُترك بمفرده، وأن يرغب باستمرار في أن تحمليه وتتجولي به. قد يكون هذا الأمر مرهقًا لكِ أحيانًا، لكن حاولي التعامل معه بأكبر قدر ممكن من التفهم وساعدي طفلكِ على استكشاف محيطه. إن حمله بوضعيات مختلفة أثناء التجول به يساعد على تنمية عضلاته، كما أنه يستمتع بذلك كثيرًا. وبهذه الطريقة أيضًا، سيخوض مرحلة صحية من التفاعل الاجتماعي معكِ ومع محيطه. وقد بدأت أنشطة طفلكِ خلال هذا الشهر، مثل النوم واللعب والرضاعة، تتبع نظامًا محددًا. لذلك يُعد الشهر الثالث نقطة تحول لكِ ولطفلكِ على حد سواء. واصلي اللعب مع طفلكِ وقضاء الوقت معه والابتسام له كثيرًا. فالوقت الجيد الذي تقضينه معه يُشعره باهتمامكِ به، وهو بالغ الأهمية لنموه النفسي السليم.') WHERE id = 'c7c7ac0c-0d6e-4513-8d30-65a89768a3af';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما لاحظتِ منذ مدة أن عدد مرات تبرّز طفلكِ قد انخفض. يمكن أن تختلف عادات التبرّز لدى الأطفال كثيرًا، وتُعد معظم هذه الاختلافات طبيعية. إذا كان طفلكِ يتغذى على حليب الأم فقط، فمن الطبيعي أن يتبرّز مرة واحدة في الأسبوع، كما أن تبرّزه 5-6 مرات يوميًا طبيعي تمامًا أيضًا. وعادةً ما يكون براز الطفل الذي يتغذى على حليب الأم أصفر اللون وسائلًا وقليل التحبب. أما إذا كان طفلكِ يتغذى على الحليب الصناعي، فمن الطبيعي أن يتبرّز برازًا لين القوام مرة كل 3-4 أيام، أو حتى 5 مرات يوميًا، ما دام لا يعاني من الإمساك. وقد يكون براز الطفل الذي يتغذى على الحليب الصناعي أصفر أو أخضر اللون. وإضافةً إلى نمط التغذية، قد تحدث بعض التغيرات في عدد مرات تبرّز طفلكِ عند تغيير العلامة التجارية للحليب الصناعي الذي تستخدمينه أو أثناء استعمال المضادات الحيوية. النقطة الأساسية التي ينبغي لكِ الانتباه إليها هنا هي قوام البراز. فإذا كان صلبًا وجافًا ويخرج على هيئة قطع منفصلة، فمن المرجح أن طفلكِ مصاب بالإمساك. وإذا شعرتِ بأنه منزعج وغير مرتاح بسبب هذه الحالة، فمن الأفضل التواصل مع طبيبكِ في أقرب وقت ممكن.') WHERE id = '0aa04f59-8956-4168-94d6-7cbf1b5d04b5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، تطور التناسق بين يد طفلكِ وعينه بدرجة كبيرة. وبفضل قدرته على الإمساك، سيكتشف أنه يستطيع التقاط الألعاب والأشياء بيده، وسيبدأ في تركيز انتباهه على هذه الحركات. فعلى سبيل المثال، لن يُفلت طفلكِ الخشخيشة التي يمسك بها بسهولة ما لم يرغب هو في ذلك. بل قد يحاول هزها أيضًا إذا أدرك أنها تُصدر صوتًا. تُعد هذه السلوكيات من أولى الخطوات التي يخطوها طفلكِ في نموه الذهني من خلال إدراك العلاقة بين السبب والنتيجة. وسرعان ما ستصبح كل هذه الروابط التي يكوّنها أكثر فاعلية، وسيبدأ في الرغبة بوضع الأشياء التي يمسك بها في فمه. في هذه المرحلة التي تُسمى "المرحلة الفموية"، يُلاحظ أن الطفل يضع في فمه كل ما يثير اهتمامه ويرغب في استكشافه، مستعينًا بمنعكس المص، وهو أحد منعكساته الأولى. وتمتد هذه المرحلة حتى بلوغ طفلكِ عامه الأول. وخلال هذه الفترة، يتواصل طفلكِ مع العالم الخارجي عبر سطح جسمه كله، وخصوصًا عن طريق فمه. لذلك، عليكِ إبعاد جميع الأشياء الصغيرة التي قد يبتلعها، وألا تتركيه بمفرده مدة طويلة.') WHERE id = '60021b19-b43c-4324-8e67-4e9b5d399b4d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يبتعد إلى الخلف ويبكي أثناء الرضاعة الطبيعية أو الرضاعة بالزجاجة، فمن المرجح أنكما تمران بحالة رفض الثدي أو رفض الرضاعة. في هذه الحالة، قد لا يرغب طفلكِ في الرضاعة لأسباب مختلفة، حتى إن كان جائعًا. ويُعد احتقان الأنف أحد أكثر الأسباب شيوعًا لذلك. فبسبب احتقان الأنف، يحاول الطفل التنفس من فمه، ولذلك قد يترك الثدي مرارًا أو يرفضه، حتى إن كان جائعًا. إذا كان أنف طفلكِ مسدودًا، فنظّفيه قبل الرضاعة باستخدام شفاط الأنف، أو استخدمي قطرات الأنف التي أوصى بها الطبيب لمساعدته على التنفس براحة. إضافةً إلى ذلك، قد يؤدي اضطراب الروتين الذي اعتاده طفلكِ أو تغيير مواعيد الرضاعة إلى انزعاجه ورفضه الرضاعة. كما أن استخدامكِ طريقة غير صحيحة للرضاعة الطبيعية قد يصعّب عليه التقام الثدي. يمكنكِ مساعدته على الرضاعة مجددًا من خلال التعرف إلى أساليب الرضاعة الطبيعية الصحيحة وتجربة وضعيات مختلفة تمكّنه من التقام الثدي براحة.') WHERE id = '923618b2-185f-4d48-8595-207ec8b1f1d7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ نمو بصيلات شعر الأطفال وهم لا يزالون في الرحم، تقريبًا خلال الثلث الأول من الحمل. وحتى يوم الولادة، يزداد تكاثف الشعر الناعم الذي يُسمى الزغب الجنيني في منطقة رأس الطفل للمساعدة على منع فقدان الحرارة. ونظرًا إلى أن كثافة هذا الشعر ومدة نموه قد تختلفان تبعًا للعوامل الوراثية، فمن الطبيعي تمامًا أن يولد الأطفال بشعر كثيف أو خفيف أو من دون شعر. وفي الواقع، لا تُعد ولادة الطفل بشعر خفيف أو كثيف مؤشرًا على وجود أي مشكلة صحية. وقد يتساقط شعر طفلكِ بكثافة، خصوصًا خلال هذه الأشهر. وربما تلاحظين أيضًا بعض الصلع في الجزء الخلفي من رأسه، عند منطقة القفا. وقد يحدث ذلك بسبب نوم الطفل باستمرار في الوضعية نفسها، أو نتيجة دخول بصيلات الشعر في مرحلة الراحة منذ الولادة وحتى الشهر 6. وعلى الرغم من أنكِ قد لا ترغبين في قص شعر طفلكِ، فإن الخبراء يوصون بقصه عندما يحين الوقت المناسب، سواء أكان كثيفًا أم خفيفًا.') WHERE id = '1a637264-ed95-4fa6-842a-a26e3ce3729a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستمر دماغ طفلكِ في النمو بلا توقف منذ وجوده في رحمكِ، ويتسارع هذا النمو أكثر بعد الولادة. وتمتد أسرع مراحل نمو الدماغ من عمر 0 إلى 48 شهرًا. وخلال هذه المرحلة، يحتاج طفلكِ إلى خوض التجارب كي يتمكن من فهم العالم من حوله، ويتعلم من خلالها. وتُعد الألعاب التي تثير فضوله وتدعم نموه من أهم عناصر هذه التجارب. فالألعاب الملونة والمختلفة الأشكال والمثيرة للاهتمام تنشّط الخلايا العصبية في دماغه وتساعدها على تكوين الروابط، ما يمكّنه من فهم محيطه. وعلى عكس الأشياء التي تستخدمينها يوميًا، تعزز الألعاب المهارات الإبداعية وتفيد كثيرًا في تنمية عالم خياله الذي بدأ بالتشكل. وفي هذه المرحلة، تكون حاسة السمع لدى طفلكِ أقوى نسبيًا من حاسة البصر. لذلك تكون الألعاب التي تتضمن مؤثرات صوتية أكثر فائدة له خلال الأشهر 6 الأولى. ومن أمثلتها الألعاب الخفيفة التي تصدر أصواتًا متنوعة، والألعاب الموسيقية المعلّقة فوق سريره أو بساط اللعب، والخشخيشات التي يستطيع الإمساك بها.') WHERE id = '341dbb77-f89b-4786-ae5e-27fe6c263105';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل لاحظتِ أن يدي طفلكِ، اللتين كانتا عادةً مقبوضتين كقبضة اليد خلال أول شهر أو شهرين، بدأتا الآن تنفتحان؟ في الشهر 3، تبدأ يداه بجذب انتباهه. فيحركهما بوتيرة أكبر، وتصبح مراقبتهما وتحريكهما من أنشطته المفضلة. وبينما يكتشف يديه، تتطور قدرته البصرية أيضًا. ويمكنكِ جعل هذه المرحلة أكثر تشويقًا! يمكنكِ دعم رحلة استكشافه بشراء ألعاب صوتية تُثبَّت حول معصميه. لكن احرصي على استخدام هذه الألعاب تحت إشرافكِ دائمًا، فاليدان الصغيرتان قد تتحركان بسرعة كبيرة.') WHERE id = 'ad6180ec-951a-4399-9c9f-0798090c6244';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يواصل طفلكِ في هذه المرحلة استخدام عدد من المنعكسات الفطرية التي وُلد بها. وتختفي هذه المنعكسات، التي تُسمى الحركات الغريزية، مع نمو الطفل لتحل محلها مهارات حركية أكثر تعقيدًا وحركات إرادية. ومن المنعكسات المهمة لطفلكِ: منعكسا المصّ والبحث عن الثدي، ومنعكس مورو، ومنعكس الرقبة التوتري، ومنعكس الخطو، ومنعكس القبض، ومنعكس بابنسكي، ومنعكس الانثناء، ومنعكسا البلع والتقيؤ. وقد تختفي بعض هذه المنعكسات في هذه المرحلة، بينما يبدأ بعضها الآخر بالضعف. فعلى سبيل المثال، يظهر منعكسا البحث والمصّ عند ولادة الطفل، وينشآن من غريزة التغذية الضرورية للبقاء على قيد الحياة. وبين الشهرين 2 و4 تقريبًا من النمو، تبدأ السلوكيات الإرادية في الحلول محل هذين المنعكسين، ولا سيما خلال النهار. أي إنكِ قد تلاحظين أن طفلكِ لم يعد يفتح فمه عند لمس خده، بل يفتحه عندما تقرّبين إليه طعامه.') WHERE id = 'f9a31ada-1c4c-4cc8-a19f-e08982dace02';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يعتمد قضاء وقت ممتع وذي جودة مع طفلكِ على مدته، بل على فائدة مضمونه وما تقومين به معه من أنشطة تفاعلية ومتبادلة. ومن هذا المنطلق، حتى لو كنتِ وطفلكِ في الغرفة نفسها، فقد لا يُعد ذلك وقتًا ذا جودة في غياب النشاط والاهتمام. ومن أهم شروط قضاء وقت مفيد لنمو طفلكِ أن تتحدثي إليه منذ لحظة ولادته بهدوء واهتمام، وبنبرة لطيفة وكلمات واضحة، وأن تشرحي له ما تفعلينه وتخبريه به. وعلى الرغم من أن طفلكِ لم يبلغ بعد مستوى النمو الجسدي والعقلي الذي يمكّنه من الكلام وفهم كلماتكِ، فإنه يبدأ في هذه المرحلة بتخزين الكلمات المختلفة التي يسمعها في ذاكرته. ويُعد تحدثكِ المتكرر معه واستخدامكِ كلمات متنوعة أمرًا بالغ الأهمية لتطور لغته وقدرته على الكلام ونموه الذهني مستقبلًا. فعلى سبيل المثال، بدلًا من الصمت أثناء تغيير حفاض طفلكِ، اشرحي له خطوة بخطوة ما تفعلينه. وسيساعد تطبيق هذه الطريقة في كل لحظة من حياتكما اليومية على تكوين حصيلة لغوية غنية لدى طفلكِ، كما سيكون عاملًا محفزًا لنمو ذكائه.') WHERE id = 'b5b55ba0-7239-4a48-97b0-39887b3f6198';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تنمو خلايا دماغ طفلكِ كلما اكتسب تجارب جديدة. ولدعم هذا النمو، احرصي على منحه تجارب جديدة بصورة متكررة. فعلى سبيل المثال، ستساعد الألعاب الجديدة التي تلعبينها معه، أو إضافة ألعاب أو حركات مختلفة إلى أنشطتكما، على تسريع تكوين الروابط بين خلايا الدماغ. وحتى تعليمه طريقة أخرى للعب بألعابه الحالية أو تعريفه بأشياء تختلف في بنيتها وملمسها عما اعتاد رؤيته قد يكون وسيلة فعالة جدًا لدعم نموه. وخلال هذه الأنشطة، احرصي على أن يكرر طفلكِ التجارب الجديدة التي تقدمينها له. فكلما كرر تجربة ما، ترسخت هذه الخبرة الجديدة أكثر في ذاكرته. وبما أن طفلكِ دخل مرحلة التعلم النشط، تعاملي معه بإيجابية وحاولي إنشاء روتين محدد له. وقد لوحظ أن الأطفال يميلون أكثر إلى الاحتفاظ في أدمغتهم باللحظات السعيدة وكل المحفزات التي تذكّرهم بها. ولأن طفلكِ يتأثر بشدة بحالتكِ العاطفية، فإن شعوركِ بالبهجة والسعادة أثناء قضاء الوقت معه سينعكس عليه إيجابيًا.') WHERE id = '6974552e-5545-418f-9e3a-c5909451e194';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينمو كل رضيع بوتيرته الخاصة، ويجتاز مراحل النمو في أوقات مختلفة. لذلك، لا معنى لمقارنة نمو طفلكِ بنمو غيره. ورغم أن طفلكِ لا يستطيع بعد التحكم ذهنيًا أو جسديًا في الأعضاء التي ستمكّنه من الكلام، فإنه يقضي جزءًا كبيرًا من وقته في الاستماع إلى صوتكِ. وخلال استماعه إليكِ، يخزّن في ذاكرته مختلف المعلومات المتعلقة باللغة. لذلك، وعلى الرغم من أنه لا يزال بحاجة إلى بعض الوقت حتى يبدأ الكلام، فقد يعبّر عن احتياجاته المختلفة بنبرات بكاء متباينة، أو بالضحك، أو بردود فعل مثل "المناغاة". وقد يتفاعل طفلكِ معكِ أثناء الرضاعة أو تغيير الحفاض، فيركلكِ بقدميه أو يصدر أصواتًا تعبيرًا عن حبه واستجابةً للاهتمام الذي تمنحينه إياه. وقد تظهر هنا بعض الفروق الفردية؛ فبينما يحاول بعض الأطفال باستمرار إصدار أصوات ذات معنى، قد ينتظر آخرون حتى يصبحوا مستعدين تمامًا لذلك. وتشير الدراسات إلى وجود علاقة بين طريقة التواصل مع الأطفال وتطورهم اللغوي. ولدعم نمو طفلكِ، ننصحكِ بالتحدث إليه كثيرًا، واللعب معه، وقراءة الكتب له، واستخدام لغة بسيطة وواضحة عند مخاطبته. 😊') WHERE id = '51f1030e-fc36-4b12-b1d7-a64348ea081b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، توجد أنشطة عديدة ومتنوعة يمكنكِ ممارستها مع طفلكِ لقضاء الوقت معًا ودعم نموه. على سبيل المثال، يمكنكِ تهيئة بيئة تتيح له سماع أصوات مختلفة. حرّكي الألعاب التي تصدر أصواتًا أو الخشخيشة إلى يمين طفلكِ ويساره لتشجيعه على النظر نحو الجهة التي يأتي منها الصوت. ويمكنكِ، خصوصًا عندما يكون سعيدًا ومرتاحًا، أن تجعليه يستمع إلى أصوات حيوانات مختلفة بعد الاستحمام أو الرضاعة. ابدئي بأصوات مألوفة أكثر، مثل القطط والكلاب، ثم انتقلي إلى أصوات حيوانات أخرى، مثل الحصان والنحلة والحمار. ويمكنكِ الاستعانة بالإنترنت والكتب التعليمية لهذا الغرض، بل ويمكنكِ أيضًا تقليد هذه الأصوات بنفسكِ. راقبي ردود فعل طفلكِ تجاه الأصوات المختلفة. سترين كم سيستمتع بهذا النشاط الذي تمارسانه معًا. 😊') WHERE id = 'e2c4c53d-e6ae-41f3-83d4-6473c78c7fb7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المرجح أن طفلكِ قد بدأ بالفعل في التقلّب، بل إن بعض الأطفال يستطيعون فعل ذلك في وقت أبكر. لكن إذا لم يبدأ طفلكِ بالتقلّب بعد، فلا داعي للقلق. فكل طفل فريد، وقد تختلف وتيرة نمو الأطفال بدرجة كبيرة. وتعتمد قدرة طفلكِ على التقلّب بسهولة على نمو عضلات الرأس والرقبة. وعندما يكتسب القدرة على التحكم بهما، يكون قد بدأ أيضًا في وضع الأساس لمهارات حركية أخرى، مثل الجلوس والحبو والمشي. ولتشجيع طفلكِ على التقلّب، يمكنكِ وضعه على بطنه فوق سطح ناعم ومنحه فرصة للتدرّب. وقد يتأخر الأطفال المولودون قبل أوانهم في التحكم بالرأس والرقبة، لأن أجهزتهم العضلية والعصبية لا تعمل بالطريقة نفسها التي تعمل بها لدى غيرهم. إذا وُلد طفلكِ قبل أوانه، فقد يستغرق الأمر حتى الشهر 9 ليبدأ بالتقلّب. ومن يدري؟ ربما يتجاوز مرحلة التقلّب ويبدأ بالجلوس مباشرةً! 😊') WHERE id = '4f657a4a-e832-4fda-9834-e8fa08bd9d44';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيلان اللعاب من فم طفلكِ ومحاولته وضع كل شيء في فمه... لا بد أنكِ تعرفين سبب ذلك. اعتبارًا من هذا الشهر، قد تبدأ مرحلة التسنين لدى طفلكِ. ومن الرائع بالطبع رؤية أسنانه الجميلة وهي تزيّن ضحكته، لكن مرحلة التسنين تكون مؤلمة لدى معظم الأطفال. وقد تسبب لطفلكِ الانزعاج والألم نتيجة تورم اللثة. ومن أشهر علامات التسنين بالطبع زيادة إفراز اللعاب. وتشمل العلامات الأخرى محاولة عض كل ما تصل إليه يداه، والحمى الخفيفة، ورفض الرضاعة أو الطعام. وقد تظهر هذه العلامات قبل بزوغ الأسنان بأشهر، أو قد تظهر أسنانه خلال هذا الشهر من دون أي علامات، تبعًا للعوامل الوراثية. ويرى الأطباء أن ارتفاع درجة حرارة طفلكِ أثناء التسنين إلى 37 درجة أمر طبيعي ولا يحتاج إلى تدخل. لكن إذا ارتفعت حرارته إلى 38 درجة أو أكثر، فلا يُعد ذلك من علامات التسنين، وعليكِ استشارة طبيبكِ.') WHERE id = 'fd702e8d-6a0f-4f31-a1a0-b330e1d04288';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا قررتِ قص شعر طفلكِ في المنزل، فهناك بعض الأمور التي ينبغي الانتباه إليها. أولًا، تأكدي قبل البدء بأن طفلكِ قد شبع ولا يعاني من أي انزعاج، مثل آلام الغازات. فالطفل الذي يشعر بعدم الراحة قد يتململ ويقوم بحركات مفاجئة، ما قد يؤدي إلى إصابات خطيرة أو إلى قص شعره بطريقة غير صحيحة. إذا كان طفلكِ يستطيع الجلوس، فيمكنكِ إبقاؤه ثابتًا بوضعه في مكان مريح، مثل كرسي الطعام، أو بإسناده في حضنكِ. استخدمي مقصًا صغيرًا ذا أطراف غير حادة. كما أن إعطاءه لعبته المفضلة لتشتيت انتباهه والتحدث إليه باستمرار أثناء قص شعره سيساعدانه على البقاء هادئًا. وعند قص الشعر، توخي الحذر الشديد حول الأذنين والرقبة والجبهة. وإذا لزم الأمر، يمكنكِ أن تطلبي من الشخص الذي يساعدكِ تثبيت رأس طفلكِ. لا تتركي طفلكِ بمفرده مع المقص ولا تبتعدي عنه قبل الانتهاء. لذلك، جهّزي مسبقًا جميع الأدوات التي ستحتاجين إليها، مثل المنشفة والمشط، قبل البدء.') WHERE id = '4c05c1b9-816f-4b3a-9570-73a5e8523f06';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا بد أنكِ تتذكرين اليوم الأول الذي احتضنتِ فيه طفلكِ وكأنه كان بالأمس. ما أسرع مرور الوقت، أليس كذلك؟ 😊 لقد بلغ طفلكِ الشهر 4، وبدأ يُشعركِ بأنه يكبر. يريد منكِ أن تمنحيه اهتمامًا مستمرًا، ويذكّركِ في كل فرصة بمدى حبه للعب. عندما يستلقي طفلكِ على بطنه، يستطيع رفع جسمه مستندًا إلى يديه ومرفقيه حتى يرتفع صدره، كما يمكنه رفع رأسه بزاوية 90 درجة أثناء الاستلقاء على بطنه. ويزداد في هذه المرحلة أيضًا ضحكه بصوت مرتفع وصراخه لجذب الانتباه. وقد تلاحظين أن طفلكِ يبذل جهدًا كبيرًا للجلوس. ومع أن بعض الخبراء لا يشجعون جلوس الأطفال قبل الشهر 6، يرى بعض الأطباء أن نمو كل طفل يختلف عن غيره. لذلك، من المهم جدًا أن تراقبي طفلكِ وتحاولي فهم ما يريده. وقد يشعر الطفل المتحمس للجلوس بسعادة كبيرة إذا أجلستِه مع توفير الدعم لمدة قصيرة جدًا. ومع ذلك، وبما أن كل طفل ينمو بطريقة خاصة به، فمن الأفضل استشارة طبيبكِ في هذا الأمر. 😊') WHERE id = '2ec8f436-2faa-47d9-bf8d-3c7a85cda289';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'غالبًا ما يُعدّ تقيؤ رضيعكِ بعد الرضاعة أمرًا طبيعيًا من الناحية الفسيولوجية، لكن من المهم أن تواصلي مراقبته. ففي الأشهر الأولى خصوصًا، قد يتقيأ رضيعكِ كمية تملأ فمه دون اندفاع، بعد وقت قصير من الرضاعة. تقل هذه الحالة مع نموه، وعادةً ما يختفي التقيؤ بعد الرضاعة عند بلوغه الشهر الثامن. وقد يكون سببه ابتلاع رضيعكِ الهواء أثناء الرضاعة، أو الرضاعة بسرعة أو ببطء شديدين، أو عدم مساعدته على التجشؤ بعد الرضاعة. وإذا صُححت هذه الأخطاء في طريقة الرضاعة، فسيتوقف هذا التقيؤ أيضًا. وعادةً ما يحدث التقيؤ بعد تناول الطعام لأن العضلة الموجودة في الجزء السفلي من المريء، والتي تمنع رجوع محتويات المعدة، لم يكتمل نموها بعد من الناحية الفسيولوجية. وعلى الرغم من أن التقيؤ قد يظهر منذ الولادة، فإن وتيرته تزداد قرابة الشهر 4، ويصيب نحو 3 من كل 4 رضع. وعادةً ما يقل بعد الشهر 6، ثم يختفي تمامًا مع البدء بتناول الأطعمة الصلبة.') WHERE id = '94ce13b4-bc4e-480c-a364-11de1e4c0330';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك سببان رئيسيان لمشكلة مغص الغازات لدى رضيعكِ. أولهما الغازات التي تنتجها البكتيريا النافعة في معدته عند تفكيك العناصر الغذائية غير المهضومة الموجودة في حليب الأم أو الحليب الصناعي. أما السبب الآخر فهو الهواء الذي يبتلعه رضيعكِ أثناء البكاء أو البلع أو الرضاعة الطبيعية أو الرضاعة بالزجاجة. وإذا كنتِ ترضعينه طبيعيًا، فقد يؤدي تناولكِ أطعمة تسبب الغازات في جهازكِ الهضمي إلى إصابته بالغازات أيضًا. لذلك، سيكون من المفيد تقليل هذه الأطعمة في نظامكِ الغذائي. وهناك العديد من التدابير التي يمكنكِ اتخاذها للحد من مغص الغازات لدى رضيعكِ، ومنها عدم الانتظار حتى يشتد جوعه. فالرضيع الذي يجوع أكثر من اللازم يشرب الحليب بسرعة، ما يؤدي إلى ابتلاعه كمية كبيرة من الهواء. وإذا كنتِ ترضعينه بالزجاجة، فيمكنكِ تقليل مشكلة الغازات إلى أدنى حد بالتأكد من أن فتحة حلمة الزجاجة ليست صغيرة جدًا أو كبيرة جدًا.') WHERE id = '14cce317-1232-45b9-96bd-2281d87ef8be';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكن لبعض التغييرات في طريقة تغذية رضيعكِ أن تحد من الارتجاع لديه وتقلل إلى أدنى حد من خطر تعرضه لمشكلات مستقبلًا. وأهم هذه التغييرات هو تنظيم وتيرة الرضعات ومواعيدها. احرصي أثناء إرضاعه على إبقائه في وضعية مستقيمة قدر الإمكان. كما أن تقديم رضعات أصغر حجمًا وأكثر تكرارًا يخفف الارتجاع ويساعد على سلاسة عملية الهضم. تجنبي بين الرضعات وبعدها الحركات القوية، مثل قذفه في الهواء أو دحرجته، واحمليه بدلًا من ذلك في وضعية مستقيمة لمدة 20 دقيقة تقريبًا بعد كل رضعة. واحرصي أيضًا عند تغيير حفاضه على ألا يكون ضيقًا جدًا، لأن إحكامه الشديد يزيد الضغط على بطنه وقد يسبب التقيؤ. ويمكن أن يساعد استخدام وسادة رقيقة لرفع رأس رضيعكِ قليلًا أثناء نومه على خروج الغازات بسهولة والوقاية من الاختناق المحتمل. ومن المهم أيضًا تجنب تعريض رضيعكِ لدخان السجائر، إذ قد يسبب الارتجاع إلى جانب أضراره الأخرى.') WHERE id = '4db7b0e8-8a13-4223-9f1c-396106b58bfc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المؤكد أن ذكاء طفلكِ ونمو دماغه من أكثر الجوانب التي تتمنين تطورها أثناء نموه. وتُعد قراءة الكتب له من الوسائل الفعالة جدًا لدعم هذا التطور. فتعرّف طفلكِ إلى الكتب وحبه لها في هذه المرحلة يهيئ أساسًا لنجاحه الأكاديمي ومهاراته الأساسية في التحدث ومعرفته اللغوية وقدرته على الاستدلال عندما يبلغ سن المدرسة. كما ثبت علميًا أن الأطفال الذين يهتمون بالكتب قبل سن المدرسة يحققون نجاحًا أكاديميًا أعلى. وعندما تقرئين لطفلكِ، فإنكِ تضعين أساس مهاراته اللغوية، لأنه يتعلم منكِ الأصوات الأساسية اللازمة للكلام. وإضافة إلى ذلك، عندما تتواصلين معه بفاعلية، سيتعلم أساليب التواصل الصحيحة قبل المرحلة المدرسية بوقت طويل بفضل الرابطة التي يبنيها معكِ. وكلما سمع تراكيب الجمل الصحيحة من الكتب بانتظام واستمرار، بدأ ميله إلى استخدام القواعد النحوية يتطور منذ مرحلة ما قبل المدرسة. لذلك، من المهم جدًا أن تبدئي منذ الآن بقراءة الكتب له قبل أن يتعلم القراءة بنفسه.') WHERE id = '847c3222-1e8f-4ee7-af36-660c53f7b72c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينمو طفلكِ أمام عينيكِ بسرعة مذهلة، ويتعلم كل يوم مهارات جديدة ويستعرضها أمامكِ. 😊 وللألعاب التي تختارينها أهمية كبيرة في مساعدته على اكتساب مهارات جديدة ودعم إبداعه ونمو دماغه. وفي هذه المرحلة، يزداد فضول طفلكِ تجاه ما يحيط به، لذا يمكنكِ التفكير في شراء ألعاب جديدة ومختلفة له أو ابتكار طرق جديدة للعب بألعابه الحالية. وعند اختيار الألعاب، احرصي على أن تكون مناسبة لعمره وفكري في كيفية تأثيرها في سماته الشخصية. تُظهر الدراسات العلمية أن الألعاب التي يلعب بها الأطفال تؤدي دورًا كبيرًا في نموهم. فكل لعبة يستخدمها طفلكِ حتى مرحلة ما قبل المدرسة مهمة لبناء علاقته بالعالم وتطور شخصيته. لذلك، احرصي عند اختيار الألعاب على أن تحفّز جميع حواسه، وتنمّي مهاراته الحركية، وتعزز خياله، وتدعم مهاراته الاجتماعية.') WHERE id = '86e946c1-ab86-4301-9ac4-7f795adc1bfa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبدأ طفلكِ منذ لحظة ولادته في تسجيل كل معلومة، لأنه يمتلك أعضاء حسية متطورة وملايين الخلايا الدماغية الجاهزة للتحفيز. وعندما يولد، لا يمتلك سوى بعض ردود الفعل المنعكسة التي تساعده على البقاء، لكنه سيكتسب خلال وقت قصير العديد من المهارات، مثل الحبو والكلام والمشي. ووفقًا للدراسات، تُعد القيلولة النهارية أحد الأسباب الرئيسية التي تساعد طفلكِ على تعلم هذه المهارات المدهشة بسرعة. فهي تتيح له الراحة وتعلم أشياء جديدة، وتساعده في الوقت نفسه على ترسيخ تجاربه في ذاكرته. كما يساعد انتظام مواعيد نومه على اكتساب المهارات المهمة، مثل المشي والكلام، في الوقت المناسب. ومع مرور الوقت، تقل مدة نوم طفلكِ، وقد يقاوم النوم أحيانًا عندما يبدأ باستكشاف محيطه. وفي هذه الأشهر، يستطيع اكتساب العادات بسهولة، لذلك نوصيكِ بالبدء منذ الآن بتنظيم روتين نومه. 😊') WHERE id = '12adf52f-ce6e-45aa-88f8-a01f2005b356';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون الأسابيع المقبلة صعبة قليلًا عليكِ وعلى طفلكِ. وتُعدّ طفرة النمو الرابعة، التي تمتد من الأسبوع 14 إلى الأسبوع 19، واحدة من أطول مراحل التطور. قد يرفض كثير من الأطفال الرضاعة الطبيعية أو الحليب الصناعي قبيل طفرة النمو هذه. وبينما تظنين أن نمط نوم طفلكِ قد انتظم، قد يبدأ بمقاومة النوم. كما أن رغبة طفلكِ المستمرة في البقاء بين ذراعيكِ وشعوره بالانزعاج قد يرهقانكِ قليلًا. لكن في نهاية هذه الفترة الصعبة، ستبدأ مرحلة جديدة تمامًا لطفلكِ. فقد أصبح الآن قادرًا على اكتشاف تسلسل الأحداث. فعلى سبيل المثال، عندما يرى شيئًا قد يلفت انتباهه، سيرغب في الإمساك به بإحكام واستكشافه. وبعد أن يحتفظ به في يده لبعض الوقت، قد يضعه في فمه ليتعرّف إليه عن قرب. وفي نهاية طفرة النمو هذه، قد تلاحظين أن طفلكِ يتعرّف إلى نفسه عند النظر في المرآة ويبتسم لنفسه. كما أن طفلكِ أصبح يدرك شعوره بالشبع، وقد يبتعد بعد حصوله على كمية كافية من الحليب، ما يساعد على تقليل مشكلة القيء إلى أدنى حد.') WHERE id = '57457675-a7c5-476e-b444-66d0b8d0364f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال فحص الشهر الرابع، يفحص الطبيب طول طفلكِ ووزنه ومحيط رأسه وعينيه وعضلات ظهره ورقبته لتقييم نموه. في هذه المرحلة، ينبغي أن يتراوح وزن طفلكِ بين 4800-9100 qram، وطوله بين 58-69 sm. ولا يعني اقتراب هذه القياسات من الحد الأدنى أو الأعلى أن طفلكِ يعاني من مشكلة في النمو. أما محيط الرأس فيتراوح خلال هذه الفترة بين 39-45 sm. ومن المهم جدًا أن يكون محيط الرأس ضمن هذا النطاق، لأنه أحد مؤشرات نمو الدماغ السليم. وبما أن حاسة البصر قد اكتمل تطورها، أصبح طفلكِ قادرًا على رؤية الأشياء بألوانها الحقيقية. وهذا يجعل العالم الخارجي أكثر إثارة للاهتمام؛ لذا قد يقلّل طفلكِ الوقت الذي يخصصه للنوم والرضاعة ويزداد اهتمامه بما حوله. ومع ذلك، بما أن الشهر الرابع يتضمن طفرة نمو طويلة، فقد يحدث تراجع في النوم بالتزامن مع كل هذه التطورات. لذلك قد تحتاجين إلى منح طفلكِ اهتمامًا أكبر من المعتاد. حاولي الاستمتاع بالوقت الذي تقضيانه معًا. أوقاتًا ممتعة! 😊') WHERE id = '3e04c60c-ae8b-4665-9ca2-95ef5bdb8192';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اللقاحات التي ينبغي أن يتلقاها طفلكِ خلال فحص الشهر الرابع هي الجرعات الثانية من اللقاحين اللذين تلقاهما في الشهر الثاني، باستثناء لقاح السل. وهما لقاح المكورات الرئوية (التهاب السحايا)، واللقاح الخماسي الذي يشمل لقاحات الدفتيريا والسعال الديكي والكزاز والمستدمية النزلية من النوع ب وشلل الأطفال. وإذا تلقى طفلكِ لقاح الفيروس العجلي في الشهر الثاني، فينبغي إعطاؤه الجرعة الثانية هذا الشهر. إذا أصيب طفلكِ بالحمى أو الانزعاج بعد لقاحات الشهر الرابع، فيمكنكِ إعطاؤه خافض الحرارة الذي أوصى به طبيبه. ورغم اختلاف ذلك من طفل إلى آخر، فقد ترتفع درجة الحرارة عادة بعد 2-4 ساعات من التطعيم. وقد تستمر الحمى أحيانًا لمدة 2-3 أيام. كما قد يظهر ألم أو تورم أو احمرار في موضع الحقن بعد أي لقاح. ولتخفيف انزعاج طفلكِ وأعراضه، يمكنكِ وضع كمادة باردة على موضع الحقن واستخدام دواء يحتوي على الباراسيتامول لتسكين الألم بعد استشارة الطبيب.') WHERE id = 'ecec54a9-6b16-4860-9c1c-01c24cd2eac2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن في مرحلة التعلّم النشط، وقد تلاحظين أنه يتفاعل باهتمام مع جميع التجارب الجديدة. ومن بين جوانب التطور في هذه المرحلة وضع أسس مهارة الكلام. فقد أصبح يستجيب لصوتكِ ويحب تقليد الأصوات التي يسمعها. وعندما يكون سعيدًا على وجه الخصوص، قد يطلق صيحات رفيعة النبرة ويضحك بصوت عالٍ ويصدر أصواتًا مثل «آغو». ننصحكِ بالتحدث إلى طفلكِ باستمرار للمساعدة على تطوير قدرته على الكلام. 😊 وبما أن طفلكِ في شهره الرابع شديد الاهتمام بالمؤثرات الخارجية، فقد يتشتت انتباهه كثيرًا. فعلى سبيل المثال، إذا لفت شيء آخر انتباهه أثناء الرضاعة، فقد يتوقف عنها مؤقتًا. وقد يكون هذا أيضًا سبب رفضه النوم من حين إلى آخر. عليكِ التحلي بالصبر، فالعالم كبير جدًا بالنسبة إليه، وهناك الكثير مما ينبغي اكتشافه! 😊') WHERE id = '0479afbe-b14f-457d-b226-70e3d4f9bf7b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يفاجئكِ طفلكِ هذه الأيام بأن يتقلب من وضعية النوم على بطنه إلى جانبه، بل وحتى إلى ظهره. وبفضل تطور عضلات ظهره ورقبته، غالبًا ما تنجح محاولاته في التقلب. وقد يبدأ طفلكِ بالجلوس حتى اعتبارًا من هذا الشهر. ورغم أن بعض الأطباء لا ينصحون بإجلاس الطفل قبل عمر 6 أشهر، فمن المهم تذكّر أن نمو كل طفل يختلف عن الآخر. عندما يصبح دماغ طفلكِ وجسمه مستعدين، أي حين تصل قدرته على التحكم في العضلات والتوازن إلى المستوى الكافي، فسيتخذ وضعية الجلوس بنفسه. إذا كان طفلكِ يرفع نفسه ويحاول الجلوس، فيمكنكِ السماح له بذلك، شرط ألا يبقى في هذه الوضعية وقتًا طويلًا. ستُسعده رؤية ما يستطيع فعله وستشجعه. ومع ذلك، لا تنسي دعم ظهره. ورغم أن بعض الأطفال يبدؤون بالجلوس في هذا الشهر، فمن المهم تذكّر أن عضلات ظهورهم لم تصبح بعد قوية بما يكفي للجلوس دون دعم.') WHERE id = '3e15f79b-7870-4c1b-9ff8-0d7695190d48';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح وزن طفلكِ الآن في المتوسط ضعف وزنه عند الولادة، وإذا كنتِ ترضعينه طبيعيًا، فقد تظنين أحيانًا أن حليبكِ غير كافٍ. وبما أن الشهرين 4 و5 يمثلان مرحلة نمو جسدي سريع لطفلكِ، تزداد حاجته إلى الطاقة. وقد تفكرين في بدء الأطعمة التكميلية لتلبية هذه الحاجة المتزايدة. لكن تذكّري أن النبيت المعوي لدى طفلكِ ليس مستعدًا بعد للأطعمة الصلبة في هذه المرحلة. تُقدَّم الأطعمة التكميلية بكميات صغيرة جدًا بهدف تعويد الطفل على الأطعمة الصلبة، وينبغي بدء هذه العملية بعد الشهر 6 من أجل نمو صحي للأمعاء. توصي منظمة الصحة العالمية خلال الأشهر 6 الأولى بإعطاء الطفل حليب الأم فقط، أو الحليب الصناعي باعتباره البديل الوحيد عند تعذر الرضاعة الطبيعية. وقد يؤدي بدء أي أطعمة تكميلية قبل عمر 6 أشهر إلى إصابة طفلكِ بفقر الدم وعسر الهضم والغازات ومشكلات المعدة والأمعاء. لذلك لا تتعجلي في بدء الأطعمة التكميلية، ماما.') WHERE id = '63dc3b2b-9b88-4480-8d80-226d9607b848';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيتحقق طبيبكِ خلال الفحوصات الروتينية لطفلكِ هذا الشهر من بعض مؤشرات نموه وتطوره. أول هذه المؤشرات وأهمها هو قدرته على تثبيت رأسه. إذ يُفترض أن يتمكن الأطفال الذين أتموا شهرهم الثالث في هذه المرحلة من التحكم برأسهم بسهولة، وإبقائه منتصبًا، ورفعه بزاوية تصل إلى 45 درجة. أما اليافوخ، فينبغي أن يظل لينًا ومفتوحًا. فهذا الانفتاح مهم جدًا لاستمرار نمو دماغ طفلكِ بفاعلية. ويُعد محيط الرأس مؤشرًا آخر على نمو الدماغ. وابتداءً من هذا الشهر، يُفترض أن يتراوح متوسط محيط رأس طفلكِ بين 37 و43 سم. أما القياسات الأخرى التي سيتابعها الطبيب بانتظام فهي الطول والوزن. قد يتراوح وزن طفلكِ هذا الشهر بين 4200 و7500 غرام، وطوله بين 55 و65 سم. تذكّري أن هذه الأرقام قيم متوسطة وقد تختلف من طفل إلى آخر. وما دامت قياسات طفلكِ ضمن الحدين الأدنى والأعلى، فلا داعي للقلق بشأن نموه.') WHERE id = '76c150ee-bf0f-46cc-b728-a8452683e29c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُفترض أن تكون طفرة النمو الثالثة لطفلكِ قد بدأت خلال هذه الأيام. لذلك، لا تقلقي أبدًا إذا لاحظتِ لديه انزعاجًا أو اضطرابات في النوم أو تغيرات في الشهية. تبدأ طفرة النمو الثالثة عادةً في حدود الأسبوع 12، رغم اختلاف موعدها بحسب الفارق بين تاريخ ولادة الطفل الفعلي وموعد ولادته المتوقع. بعد هذه الطفرة، يبدأ طفلكِ في إبداء اهتمام أكبر بالأصوات، وبفضل ازدياد حساسية سمعه يصبح قادرًا حتى على ملاحظة التغيرات في نبرة الصوت. كما تبدأ الخلايا المسؤولة عن السمع في جذع دماغه بالعمل بطريقة تتيح لها تحديد الاتجاه الذي تأتي منه الأصوات والاستجابة له. وهذا يعني أن طفلكِ أصبح قادرًا على تمييز مصدر الصوت والالتفات نحوه. ومن التغيرات الأخرى التي تحدث في هذه المرحلة أن طفلكِ يبدأ باكتشاف صوته. وقد يفاجئكِ طفلكِ، بعد أن يتعرف إلى صوته، بإصدار أصوات مختلفة في طبيعتها وشدتها. استمتعا بوقتكما! 😊') WHERE id = '7157ab6b-c70f-4177-b181-d8ea3a2d459e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ تغذّين طفلكِ بالحليب الصناعي، أو تستخدمينه كمكمل لأن حليبكِ لا يكفيه، فإن اختيار زجاجة الرضاعة يُعد من أهم الأمور. ولا ينبغي أبدًا التهاون في اختيارها لما لذلك من أثر في صحة طفلكِ. فالزجاجة المناسبة تؤدي دورًا كبيرًا في تغذيته، كما تسهّل عليكِ المهمة كثيرًا بفضل سهولة استخدامها. عند الاختيار، ينبغي أن تفضّلي الأنواع التي تتيح لطفلكِ فتح فمه على اتساعه أثناء الرضاعة، تمامًا كما يفعل عند الرضاعة الطبيعية. ويجب أيضًا أن تكون الزجاجة التي تختارينها مريحة لجهازه الهضمي، وأن تكون فاعليتها في تقليل غازات ومغص الرضع مثبتة سريريًا. ومن الجوانب التي ينبغي الانتباه إليها مادة الزجاجة وحجمها وشكلها، وميزة مقاومة المغص، وشكل الحلمة وعدد فتحاتها. في هذه المرحلة، يُنصح باختيار زجاجة لطفلكِ بسعة 240-260 مل، ذات حلمة متوسطة التدفق ومزوّدة بنظام تهوية.') WHERE id = '20a065b0-2b51-4884-b57e-e72acfd3836c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تختلف سرعة نمو طفلكِ وتطوره بحسب عمره. ورغم أن نموه قد يكون أبطأ في بعض المراحل، فإنه يتسارع خصوصًا عند دخوله في طفرة نمو، أي مرحلة تطور سريع. ويُعد انخفاض شهية الطفل في الفترات التي يتباطأ فيها نموه أمرًا طبيعيًا من الناحية العلمية. ينمو الطفل بسرعة كبيرة خلال عامه الأول، ولذلك لا تظهر عادةً مشكلة خطيرة في فقدان الشهية تستدعي التدخل. ومع ذلك، قد تلاحظين فقدانًا مؤقتًا للشهية خلال مرحلة التسنين أو عندما يبدأ باستكشاف محيطه. وتُعد مرحلة التسنين فترة صعبة لدى جميع الأطفال تقريبًا. ومن الطبيعي أن يصبح أكل الطفل غير منتظم وأقل من المعتاد بسبب انزعاجه وشعوره بالألم الجسدي خلال هذه الفترة. لكن من المهم ألّا تخلطي بين تناوله كمية قليلة وفقدانه الشهية. ورغم أن هذا الوضع قد يثير قلق الأم حديثة العهد بالأمومة، فلا داعي للذعر في الواقع. إضافةً إلى ذلك، قد تؤدي تفاعلات الحساسية الناتجة عن عدم جاهزية الجهاز الهضمي لدى الأطفال الذين يبدأون الأطعمة التكميلية مبكرًا إلى فقدان الشهية أيضًا.') WHERE id = '87f56862-dda9-454a-a541-34481c8ca235';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ القيام بالعديد من الأنشطة المختلفة مع طفلكِ. فالاهتمام بطفلكِ، الذي بدأ الآن بالتفاعل بنشاط مع محيطه، من أجمل الاستثمارات التي يمكنكِ تقديمها لمستقبله. ولأن حاسة الشم لديه قوية جدًا، يمكنكِ تعريفه بروائح مختلفة لمساعدة خلايا دماغه على العمل بفاعلية أكبر. ومن الضروري أن تتحدثي وتتواصلي معه باستمرار لدعم تطور النطق لديه. ومن المهم أن تتيحي له سماع أكبر قدر ممكن من الكلمات المتنوعة. تحدّثي مع طفلكِ باستمرار، وناديه باسمه كثيرًا لتساعديه على التعرف إليه، والمسيه وقبّليه. فالطفل الذي يشعر بأنه محبوب ومحاط بالاهتمام ينمو بصحة أفضل جسديًا ونفسيًا. وبدلًا من البقاء في المنزل مع طفلكِ والاكتفاء بتلبية احتياجاته الجسدية، ينبغي أن تتيحي له فرصًا لخوض تجارب جديدة. اخرجا ودعيه يشعر بأشعة الشمس في الهواء الطلق. وعندما لا تتمكنان من الخروج، يمكنكما النظر إلى الخارج معًا من الشرفة أو النافذة. والهدف الأساسي هنا هو توسيع إدراك طفلكِ من خلال الحركة، وتشجيعه على استخدام حواسه بنشاط، وتحفيز ذاكرته.') WHERE id = 'd229dd79-f389-4db8-9b5a-34c760b0f5c0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لاحظتِ تقشّرًا أو احمرارًا أو التهابًا في جلد طفلكِ عند تغيير حفاضه، فقد يكون مصابًا بعدوى فطرية. والفطريات التي تسبب هذه الأعراض كائنات مجهرية تتكاثر بسرعة في البيئات الرطبة، إذ تحتاج إلى الدفء والرطوبة للنمو، وتنتشر بسهولة فور توافر الظروف الملائمة. ويزداد احتمال ظهور الفطريات في المواضع التي تلامس الماء وتظل رطبة، مثل المنطقة الحساسة لدى طفلكِ. لذلك، ينبغي ألّا تتركي المنطقة رطبة بعد تنظيفها، بل جففيها جيدًا. ومن الضروري أن يفحص الطبيب طفلكِ للتمييز بين العدوى الفطرية وطفح الحفاض. ومن العلامات التي يمكن ملاحظتها تقشّر الجلد في المناطق المصابة بالفطريات. ويكون خطر الإصابة بعدوى فطرية مرتفعًا جدًا لدى الأطفال المصابين بطفح الحفاض، خصوصًا عند استخدام المضادات الحيوية دون إشراف الطبيب. لذلك، ينبغي أن تتعاملي بعناية واهتمام مع أي طفح حفاض يظهر على جلد طفلكِ.') WHERE id = 'b63be385-2a69-41af-ad23-38c2f405d961';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كانت لديكِ طفلة، فقد تراودكِ أسئلة حول الوقت الأنسب لثقب أذنيها. لا توجد فترة عمرية محددة بالأشهر لثقب أذني الرضيعة. ورغم أن الأمر يعتمد بدرجة كبيرة على اختياركِ الشخصي، يمكنكِ استشارة طبيبكِ. ولأن غضاريف الرضع لا تزال طرية جدًا، يكون وضع الأقراط في هذه الأشهر أقل إيلامًا. ومع ذلك، لا توصي بعض منظمات طب الأطفال العالمية المعروفة بثقب الأذنين خلال هذه الأشهر، بسبب عدم اكتمال جدول التطعيمات وصعوبة العناية بهما. لكن إذا أُجري ثقب الأذنين وقُدمت العناية اللاحقة بطريقة صحيحة، فإن احتمال تعرض طفلتكِ لأي مشكلة صحية يكون ضئيلًا جدًا. وإذا قررتِ ثقب أذني طفلتكِ، فنوصيكِ بالتأكد من أن الأقراط المستخدمة مصنوعة من الفولاذ المقاوم للصدأ أو من الذهب إن أمكن، للوقاية من الالتهاب.') WHERE id = '622d780e-3a5e-48fd-b009-10a81d465be2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم شيوع رغبة طفلكِ في الرضاعة باستمرار، خصوصًا خلال مرحلة حديثي الولادة، عليكِ أن تتذكري أن هذا الأمر قد يحدث في أي وقت. ووفقًا للمتخصصين، فإن الرضاعة الطبيعية، التي يُنصح باستمرارها حتى عمر سنتين، تُنشئ رابطة مميزة بينكِ وبين طفلكِ. لذلك، قد يرغب طفلكِ في الرضاعة كثيرًا بدافع غريزي للبقاء قريبًا منكِ، وقد يفضل النوم أثناء الرضاعة ولا يرغب في الابتعاد عن الثدي خلال اليوم. ورغم أن مشكلة الغازات تقل بدءًا من الشهر الرابع، فإنها قد تستمر لدى بعض الأطفال حتى الشهر السادس. وعندما يعاني طفلكِ من مغص الغازات، قد يرغب في الشعور بالأمان والهدوء في أقرب مكان إليكِ، أي بين ذراعيكِ وأثناء الرضاعة. كذلك، فإن ازدياد حاجته إلى الطاقة نتيجة زيادة حركته سيزيد رغبته في الرضاعة. ويسهم التواصل الجسدي الذي تقيمينه مع طفلكِ أثناء رضاعته المتكررة خلال اليوم في تعزيز تعلقه بكِ. أي إن رغبته المستمرة في الرضاعة، حتى إن لم تكن لديه أي مشكلة، قد تعني أنه بحاجة أكبر إلى هذا التلامس الجلدي.') WHERE id = '15a9163c-c7da-40c2-a76c-38c778e04718';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا ظهرت على جلد طفلكِ طفوح بأشكال مختلفة، فقد تكون أكزيما تحسسية. تحدث الحساسية عندما يتعامل جسم طفلكِ مع مادة غير ضارة في الأصل على أنها غريبة وخطيرة، فيُبدي رد فعل تجاهها. تذكري أن مسببات الحساسية لا تقتصر بالضرورة على الأطعمة؛ فقد يتسبب غبار الطاولة أو حبوب اللقاح التي تظهر مع تغير الفصول أو حتى دخان السجائر في حدوث رد فعل تحسسي لدى طفلكِ. وإذا لاحظتِ لدى طفلكِ طفحًا جلديًا أو احمرارًا أو نقاطًا من الدم في البراز، فمن الأفضل استشارة طبيبكِ. فقد يسبب طعام أو مادة صحية لمعظم الأطفال مشكلات خطيرة للطفل المصاب بالحساسية إذا لم تُتخذ الاحتياطات اللازمة. وتنشأ الحساسية عادةً بسبب بعض الاضطرابات في جهاز المناعة، كما قد تكون لها عوامل وراثية؛ أي إن الحساسية التي لديكِ قد تظهر لدى طفلكِ أيضًا.') WHERE id = 'e82d9ae2-ed27-40cb-9366-8cbbd0962327';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تغذية طفلكِ مهمة جدًا لنموه وتطوره بصورة صحية. لكنه قد يرفض أحيانًا الرضاعة من الثدي أو الحليب الاصطناعي. وإذا كنتِ أمًا مرضعة على وجه الخصوص، فنوصيكِ بإرضاع طفلكِ بصبر وبصورة متكررة. وقد يرجع رفضه إلى عوامل عديدة، مثل التسنين أو المرور بطفرة نمائية صعبة أو احتقان الأنف. ويمكنكِ خلال الأشهر المقبلة إجراء تغييرات في نظامه الغذائي بما يتناسب مع احتياجاته، لكن لا ينبغي أن تجبريه في هذه المرحلة على اتباع نظام ثابت تمامًا. وعندما يرفض طفلكِ الطعام، تذكري أن هذه المشكلة ستتحسن بعد فترة وستعود الأمور إلى طبيعتها. وفي مثل هذه الحالات، ننصحكِ بعدم البدء مبكرًا بالأطعمة الصلبة خوفًا من أن يبقى جائعًا. تأكدي من البدء بالأطعمة التكميلية بعد إتمام طفلكِ 180 يومًا، وانتظري حتمًا حتى يصبح مستعدًا من خلال متابعة الإشارات التي يُظهرها. لذلك، عليكِ التعامل مع طفلكِ بصبر طوال هذه المرحلة، وفهمه وتلبية احتياجاته.') WHERE id = '63e83115-0a58-4fb8-af8e-8058860fc7f2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد المرحلة العمرية التي يمر بها طفلكِ من 0-12 شهرًا بالغة الأهمية لنمو الدماغ بصورة صحية. فالبيئة التي ينمو فيها خلال هذه المرحلة وطبيعة تواصله مع الأشخاص من حوله، وخصوصًا معكِ، تضعان أسس تكوّن دماغه. ومن هذا المنطلق، يستمر مدى ملاءمة المحفزات التي يتعرض لها طفلكِ وتنوعها في التأثير في نموه المعرفي والعاطفي والاجتماعي والجسدي. ويدرك طفلكِ التواصل بينكما بوصفه محفزًا عاطفيًا. وكلما زادت هذه المحفزات، تطور طفلكِ أكثر. لذلك، ينبغي ألا تحرميه من هذه المحفزات الضرورية لنموه، وأن تتفاعلي معه باستمرار. ووفقًا لبعض الدراسات العلمية، يُعد صوت الإنسان أهم عامل يساعد على نمو دماغ الرضيع. لذا شغّلي اليوم موسيقى هادئة ودلّكي طفلكِ، وأخبريه في أثناء ذلك كيف مضى يومكِ، وما مررتِ به، ومدى حبكِ الكبير له. استمتعا بوقتكما! 😊') WHERE id = 'b51f395b-32bc-4a20-bb23-ec95e7590add';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد الأكزيما الناتجة عن التهاب الجلد التأتبي من أكثر الأمراض الجلدية شيوعًا خلال مرحلتي الرضاعة والطفولة. ومن محفزات هذه الحالة الجلدية البكتيريا والمنظفات وتغير الفصول والمواد المختلفة المسببة للحساسية. ولمنع ظهور هذه الحالة لدى طفلكِ، عليكِ اتخاذ بعض الاحتياطات. ففي هذه المرحلة التي تكون فيها بشرته شديدة الحساسية، ينبغي إبعاده عن الملابس الصوفية والغبار والرمل والصابون ومستحضرات التجميل التي تحتوي على مكونات غير مأمونة والمنظفات. كما قد تظهر هذه الحالة الجلدية عند إلباسه ملابس جديدة قبل غسلها. لذلك، اختاري الملابس القطنية لبشرة طفلكِ الحساسة، وتجنبي فرك بشرته أثناء الاستحمام بطريقة قد تسبب تهيجها. وإذا لم تُتخذ الاحتياطات اللازمة تجاه هذا المرض الجلدي، الذي يظهر في مرحلة الرضاعة على هيئة أكزيما، ولم يُعالج عند ظهوره، فقد يتطور مستقبلًا إلى حساسية في الجهاز التنفسي أو ربو أو أكزيما اليدين.') WHERE id = '31c813fe-83a6-475d-b451-c6545ed0cadd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي تمامًا أن يزداد لعاب رضيعكِ ويسيل من فمه، لأن غدده اللعابية أصبحت أكثر نشاطًا ولأنه لا يزال غير قادر على التحكم في اللعاب. وقد تكون هذه العلامات أيضًا مؤشرًا على اقتراب مرحلة التسنين؛ فقد يضع رضيعكِ يديه في فمه كثيرًا بسبب حكة لثته. ينصح المختصون بعدم منعه من ذلك، بل بإتاحة الفرصة له لاستكشاف يديه. ولكن عليكِ ألا تنسي أن رضيعكِ، الذي يحاول وضع كل ما تصل إليه يداه في فمه، قد يبتلع أشياء صغيرة. ينبغي خصوصًا إبعاد الألعاب التي تنكسر أو تتفكك بسهولة، والتأكد من أن كل ما يلعب به نظيف ومعقم. وقد يضع رضيعكِ، الذي يرغب في عض كل شيء بسبب حكة لثته، أشياء خطرة في فمه عندما لا ترينه. لذلك عليكِ اختيار الألعاب بعناية وتعزيز تدابير السلامة تحسبًا لخطر الاختناق المحتمل.') WHERE id = 'ff292524-4cb1-4b4f-9235-43064f330adc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح رضيعكِ الآن قادرًا على التدحرج والدوران حول نفسه ورفع رأسه بزاوية تصل إلى 45 درجة عند الاستلقاء، وتحريك رأسه وجسمه يمينًا ويسارًا. هذه الحركات جزء طبيعي من مسار نموه. وقد تلاحظين أيضًا أنه يتحرك كما لو كان يزحف إلى الأمام عند وضعه على بطنه. وكغيره من الأطفال، يتحمس رضيعكِ كثيرًا لتعلّم مهارات جديدة وتكرار ما تعلمه باستمرار. لكن تذكري أن نمو كل رضيع فريد من نوعه؛ فلا تقلقي إذا لم يكتسب رضيعكِ بعض هذه المهارات بعد. كما ينبغي لكِ الانتباه إلى بعض التفاصيل لدعم نموه بطريقة صحيحة، ومن بينها استخدام مشّاية الأطفال. فرغم أن رغبة رضيعكِ المستمرة في التحرك واستكشاف ما حوله قد ترهقكِ أحيانًا، ينبغي ألا تلجئي إلى المشّاية. إن إجبار رضيع يقل عمره عن 6 أشهر ولم يصبح مستعدًا للجلوس بعد على استخدامها، أو وضعه فيها، قد يعيق نمو العضلات اللازمة لاكتساب مهارات مهمة مستقبلًا، مثل الحبو والزحف.') WHERE id = 'ea44cd71-5051-4dfc-bbf3-dac92612f0a6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لعل إحدى أكثر المسائل التي تثير حيرتكِ هي كيفية إلباس رضيعكِ قبل نومه ليلًا. وبما أنه أصبح كثير الحركة، فقد يزيح عنه الغطاء أو البطانية التي تضعينها عليه باستمرار. معظم الرضع لا يحبون الحرارة الزائدة عن حاجتهم ويشعرون بالانزعاج عند ارتفاعها. يُعد الحفاظ على درجة حرارة الغرفة التي ينام فيها رضيعكِ بين 22-24 درجة، ومستوى الرطوبة بين 40-60%، أمرًا مثاليًا. وعند تحضيره للنوم ليلًا، يمكنكِ إلباسه كيس نوم قطنيًا مع بيجاما قطنية خفيفة تحته بما يناسب الموسم. ولمعرفة ما إذا كانت ملابسه كافية، يمكنكِ قياس درجة حرارة جسمه من تحت الإبط. إذا كانت درجة حرارته بين 36.2 و37.2 درجة، فهذا يعني أن رضيعكِ لا يشعر بالبرد. أما إذا كانت أقل من هذه القيم، فهذا يشير إلى أنه يشعر بالبرد، ويمكنكِ حينها إلباسه طبقة إضافية.') WHERE id = '3719fbec-0855-4e9e-bd59-1324c629c2ce';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح رضيعكِ الآن قادرًا على تمييز الوجوه المألوفة ويُظهر اهتمامًا بمن حوله. فلا تتفاجئي إذا استجاب بابتسامة، خصوصًا للأشخاص الذين يعرفهم. 😊 في الشهر 4، يكتسب رضيعكِ العديد من المهارات الجديدة التي تشمل النمو الجسدي والعقلي معًا. ومع تطور التنسيق بين يديه وعينيه بدرجة كبيرة، أصبح يستمتع بالتفاعل أكثر من ذي قبل. وهذا ما يفسر تأمله يديه بإعجاب لدقائق، وشده شعركِ، ووضعه كل ما يجده في فمه. يمكنكِ ممارسة العديد من الألعاب البسيطة مع رضيعكِ، الذي بات قادرًا بمساعدتكِ على مد يده نحو الأشياء والإمساك بالألعاب التي يلمسها. وإلى جانب ذلك، سيساعد استخدام ألعاب الأنشطة المصممة بما يتناسب مع نموه الشهري على دعم نموه الجسدي والعقلي. وعند اختيار الألعاب، ننصحكِ بتفضيل الأنواع التي تساعده على فهم علاقة السبب بالنتيجة.') WHERE id = 'aeb00407-e412-4f78-961f-30f7b120bf0d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمثل العالم الخارجي بالنسبة إلى رضيعكِ مساحة استكشاف لا حدود لها، وقد حان منذ وقت طويل أن تتفهمي ذلك. فمن الطبيعي تمامًا أن يرغب دائمًا في البقاء بين ذراعيكِ، أو يرفض النوم أو الرضاعة، أو لا يستقر في مكان واحد، أو يرغب في اللعب كثيرًا. ومع ذلك، تُعد التمارين والحركة مهمتين جدًا لنموه الفسيولوجي. ولمساعدته على ممارسة التمارين، يمكنكِ الإمساك بكاحليه وثني ساقيه برفق وتحريكهما إلى أعلى وأسفل. كما يمكنكِ الإمساك بذراعيه وضمّهما فوق صدره، ثم فتحهما وإغلاقهما بشكل متقاطع. لا تنسي التحدث إليه والابتسام له كثيرًا أثناء هذه الحركات حتى يشعر براحة أكبر. فهذه اللحظات التي تقضيانها معًا من أكثر الطرق الصحية التي تساعد رضيعكِ على التفاعل الاجتماعي.') WHERE id = '77bdf252-33eb-455c-b59d-8af7012e078c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدو كثير من الرضع المولودين بعد اكتمال مدة الحمل مستعدين للأطعمة الصلبة حتى في عمر ثلاثة أشهر. لكن منعكس "دفع اللسان"، الذي يعيق الانتقال إلى الأطعمة الصلبة، يبدأ عادةً بالاختفاء اعتبارًا من الشهر الرابع. فهذا المنعكس، الذي يؤدي في الواقع دورًا مهمًا في عملية المص، يجعل رضيعكِ يدفع بلسانه الأطعمة التي تقدمينها له. واعتبارًا من هذا الشهر، يصبح جهازه الهضمي قادرًا على هضم بعض الأطعمة. لكن هذا جزء تدريجي من نموه ولا يعني أنه أصبح مستعدًا تمامًا للأطعمة الصلبة. وتوصي منظمة الصحة العالمية في هذا الشأن بما يلي: إذا كان الرضيع ينمو بصحة جيدة من دون أن يفقد وزنه، فينبغي الاستمرار في الاقتصار على حليب الأم حتى الشهر 6. أما إذا كان حليب الأم غير كافٍ وكان الرضيع يكتسب أقل من 500 غرام شهريًا قبل بلوغه الشهر 6، فعليكِ ألا تنسي أن الحليب الصناعي ينبغي أن يشكل الجزء الأساسي من تغذيته. وحتى بعد إتمام 6 أشهر، يجب أن يظل حليب الأم غذاءه الأساسي. وتوصي منظمة الصحة العالمية بأن يشكل حليب الأم 70% من تغذية الرضيع في عمر 9 أشهر.') WHERE id = '8360a204-f867-4fb6-bb2c-9a237526ca1c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتدحرج طفلكِ للمرة الأولى خلال هذه الأيام. عادةً ما يبدأ الأطفال بهذه الحركة في الشهر 4 تقريبًا، إذ يتدحرجون من وضعية الاستلقاء على البطن إلى الجانب. وما إن يكتشف معظم الأطفال قدرتهم على فعل ذلك، حتى يرغبوا في تكراره، لتبدأ سلسلة لا تنتهي من التدحرج. ومع ذلك، قد يخاف بعض الأطفال بعد التدحرج ويترددون في المحاولة مجددًا لبعض الوقت. ويساعد شكل بطن طفلكِ المستدير والمرن كثيرًا على أداء هذه الحركة بسهولة. ولتشجيعه على التدحرج وتقوية عضلات ظهره، يمكنكِ تحفيزه على أداء حركات التمدد. فمثلًا، قد تساعده محاولة الوصول إلى لعبة أو غرض ما على التدحرج. لكن عليكِ الانتباه جيدًا كي لا يبقى منبطحًا على وجهه في وضعية تعوق تنفسه، أو يكون في مكان قد يسقط منه، ولا تتركيه بمفرده أثناء هذه التمارين.') WHERE id = '74e1e965-f81e-44cc-a407-7883c6451cc2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظنين أن طفلكِ أصبح يتغذى أقل مقارنةً بالأشهر الأولى. ورغم أن ذلك قد يثير قلقكِ، فإنه في الواقع أمر طبيعي. والسبب الرئيسي هو أن طفلكِ تعلّم الآن كيف يرضع بكفاءة أكبر؛ إذ أصبح قادرًا على الحصول على كمية أكبر من الحليب خلال وقت أقصر، ما يعني أنه يشبع بسرعة. لذلك، قد ينخفض عدد رضعات طفلكِ خلال اليوم إلى 4-5 مرات. كذلك، قد تؤدي طفرة النمو التي يمر بها هذا الشهر إلى بعض التغيرات المؤقتة في نمط تغذيته. وبما أنكِ أصبحتِ قادرة على معرفة شعوره بالجوع بسهولة من خلال مراقبة تصرفاته، يمكنكِ تنظيم أوقات الرضاعة وفقًا لذلك. فمثلًا، ابتداءً من الشهر 4، لا تعودي مضطرة إلى إيقاظ طفلكِ من نومه لإرضاعه. بالإضافة إلى ذلك، فإن ترك فاصل زمني يقارب 4 ساعات حتى موعد الرضعة التالية سيساعد طفلكِ على الاستفادة بصورة أكبر من العناصر الغذائية الموجودة في الحليب.') WHERE id = 'ea6d6e3a-c957-436f-ac9c-f0c52e449526';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يواصل طفلكِ مراقبتكِ ومتابعة وجهكِ وتعابيركِ، وباختصار كل لحظة تتواصلين فيها معه. ويساعد استمرار هذه المراقبة والمتابعة على إثراء اكتشافاته للعالم وتنويعها. فكل اكتشاف جديد يقوم به طفلكِ يساهم في تكوين روابط بين الخلايا العصبية في دماغه، ونتيجةً لذلك يبدأ في الفهم والتعلم بسرعة أكبر بكثير. ويكفي لتكوين هذه الروابط أن تُصدر الخشخيشة التي تضعينها في يده صوتًا، أو أن يتفحص أشكال ألعابه، أو حتى أن يتابعكِ بعينيه. يحاول طفلكِ الآن مراقبة تعابير وجهكِ ونبرة صوتكِ وحتى تصرفاتكِ بمزيد من الانتباه، ما يعني أنه بات يفهمكِ أكثر. لذلك، قد تبدئين منذ هذه الأشهر في رؤية ثمار الاهتمام الذي تمنحينه له. فكل لحظة تتواصلين فيها معه وتعتنين به ستزيد قوة الرابط بينكما.') WHERE id = '170aa164-55dd-45ac-8848-491ec6187f44';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يعاني طفلكِ كثيرًا من انسداد الأنف بسبب نزلات البرد أو تغير الفصول أو الإنفلونزا أو الحساسية. وإلى جانب صعوبة التنفس، قد يؤثر انسداد أنفه سلبًا في نمط تغذيته ونومه. بل يُعد انسداد الأنف أحد أبرز أسباب رفض الرضاعة من الثدي؛ لأن طفلكِ يضطر إلى استخدام فمه للتنفس، ومن الطبيعي حينها ألا يرغب في الرضاعة. وللتخفيف من هذه الحالة التي تسبب له انزعاجًا كبيرًا، يمكنكِ استخدام بخاخات الأنف المخصصة للأطفال التي يوصي بها طبيبه، أو المحلول الملحي الفسيولوجي، أو جهاز ترطيب الغرفة. فالمحاليل الفسيولوجية المعروفة بالماء المالح، والخالية من المواد الكيميائية (كلوريد الصوديوم متساوي التوتر)، تساعد على فتح أنف طفلكِ خلال وقت قصير. وقد تجدين صعوبة في استخدامها، لا سيما إن كانت هذه تجربتكِ الأولى مع الأمومة. وإذا لم يكن المحلول الفسيولوجي كافيًا، يمكنكِ أيضًا الاستعانة بشفاطات الأنف المصممة خصيصًا للأطفال.') WHERE id = '9c8572cd-a48b-4b37-a542-edfc74817a74';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك تمرين يوصي به المتخصصون لدعم النمو الجسدي لطفلكِ واستعداده لمرحلتي الزحف والحبو. ويمكنكِ تنفيذ هذا النشاط، المعروف باسم Tummy time (وقت الاستلقاء على البطن)، بوضع طفلكِ مستلقيًا على بطنه. يساعد ذلك على تنمية عضلات الظهر التي لا يستخدمها عادةً كثيرًا، كما يقوي عضلات الساقين والرقبة والكتفين والبطن. وتسهم هذه الحركات التي تطور المهارات الحركية أيضًا في الوقاية من تشوهات شكل الرأس التي قد تصيب طفلكِ (تسطح الرأس). ويمكنكِ خلال ذلك إحاطة طفلكِ بالألعاب لمساعدة دماغه على تكوين روابط متنوعة. قد يشعر طفلكِ بالملل سريعًا من الاستلقاء على بطنه أو يتشتت انتباهه، لذلك عليكِ البقاء إلى جانبه وجذب اهتمامه إلى اتجاهات مختلفة. وسيسهّل عليكِ التحدث إليه، وإنشاد الأشعار، وعرض ألعابه المفضلة، وتشغيل موسيقى هادئة. استمتعا بوقتكما! 😊') WHERE id = '3d1db687-2705-4040-8e81-a914b3ab0052';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل مليارات الخلايا العصبية الموجودة في دماغ طفلكِ، تمتد الفترة التي يكون فيها أكثر استعدادًا للتعلم منذ الولادة وحتى بلوغه الشهر 48. لذلك، فإن التواصل الجيد والمخطط له الذي تقيمينه مع طفلكِ خلال هذه الفترة سيمنح نموه دفعة كبيرة. ووفقًا للأبحاث، يحقق الأطفال الذين ينمون نموًا سليمًا خلال مرحلة الرضاعة نتائج تعليمية أفضل في سن المدرسة، ما يُحدث فرقًا في حياتهم. فالوقت الذي تقضينه مع طفلكِ منذ ولادته، والتفاعل الجيد بينكما خلاله، لهما العديد من الآثار الإيجابية في نموه الدماغي والعاطفي. كما أن اهتمامكِ بطفلكِ والوقت المثمر الذي تقضيانه معًا يدعمان نمو جهازه العصبي المركزي. ويساعد ذلك على تعزيز إحساسه بذاته، وتكوين روابط آمنة مع الآخرين، وزيادة ثقته بنفسه، وشعوره بأنه محبوب وذو قيمة. فما رأيكِ في تأجيل بعض مهامكِ وقضاء بعض الوقت مع طفلكِ؟ 😊') WHERE id = '4e220ec0-af8b-4430-ab5f-7ff3954ffb65';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الاعتماد على الحليب الصناعي وحده لتغذية رضيعكِ، كما يمكنكِ تقديمه كمكمّل بناءً على توصية طبيبكِ إذا كان حليبكِ غير كافٍ. ولكن إذا كنتِ تستخدمين الحليب الصناعي لطفلكِ بأي شكل، فهناك نقاط مهمة يجب الانتباه إليها. وأهمها بالطبع اختيار الحليب الأقرب في تركيبته إلى حليب الأم. لذلك عليكِ الاستماع إلى نصيحة طبيبكِ ودراسة المكونات جيدًا. وتجنّبي خصوصًا استخدام العلامات التجارية التي لم تسمعي بها من قبل أو التي لم يوصِ بها طبيبكِ، واحرصي على أن تكون الشركة المصنّعة ملتزمة بالقواعد الأخلاقية. لا يزال بإمكانكِ في هذه المرحلة تجربة حليب من علامات تجارية مختلفة. ومع الوقت ستجدين بالتأكيد النوع الذي يفضّله طفلكِ ولا يسبب له مشكلات في الأمعاء. ومن أجل دعم نمو جهازه المناعي والحفاظ على صحة النبيت المعوي، تأكدي من احتواء الحليب الذي تشترينه على البروبيوتيك الذي يضم كائنات دقيقة نافعة مثل العصيات اللبنية والبكتيريا المشقوقة. كما أن وجود الحمض الدهني LC-PUFA في الحليب الذي تستخدمينه لطفلكِ يساعد على تنظيم جهازه المناعي من خلال زيادة إنتاج السيتوكينات.') WHERE id = '20390cc9-8cbc-4417-abec-6230f65f2f2f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك نشاط ممتع جدًا لطفلكِ ومهم للغاية لنموه في الوقت نفسه: النظر في المرآة! 😊 رغم أن الكبار في العائلة يترددون عادةً في جعل الأطفال ينظرون في المرآة، فإن الأطباء يوصون بذلك بشدة. يساهم نظر الطفل إلى المرآة بدرجة كبيرة في نمو دماغه، إذ يساعده على رؤية نفسه واستكشافها. وعليكِ اختيار الوقت المناسب لتجربة هذا النشاط للمرة الأولى؛ فقد يخاف طفلكِ من المرآة إذا كان منزعجًا أو سيئ المزاج. لذلك، تكون الأوقات التي يكون فيها سعيدًا وشبعانًا (ولكن ليس ممتلئ البطن جدًا) مثالية لهذه اللعبة. قفا أمام المرآة، وعرّفي طفلكِ إلى عينيه ويديه وقدميه وذراعيه وفمه بالإشارة إليها. وبعد تعريفه إليها، المسِي كل عضو منها بالترتيب وكرري ذلك. نحن واثقون من أنها ستكون لعبة ممتعة جدًا لطفلكِ. استمتعا بوقتكما! 😊') WHERE id = 'b0d88192-6e24-4e64-b343-6477a77e7840';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تلاحظين أن طفلكِ لا يستطيع استخدام فمه بالشكل الصحيح أثناء الرضاعة، وأن الرضعة تستغرق وقتًا طويلًا، ويتوقف كثيرًا خلالها، ويبدو متوترًا، ولا يكتسب الوزن المتوقع؟ إذا كانت إجابتكِ نعم، فقد يكون لدى طفلكِ رباط اللسان، وننصحكِ بإخضاعه للفحص. بسبب رباط اللسان، قد لا يستطيع الأطفال الإمساك بالثدي جيدًا أثناء الرضاعة، فلا يحصلون على تغذية كافية وقد يفقدون الوزن نتيجة لذلك. وقد تظهر أيضًا بعض اضطرابات التغذية لأنهم لا يستطيعون دفع الحليب أو الغذاء الذي يتلقونه بالرضّاعة إلى الخلف بألسنتهم. رباط اللسان هو شريط نسيجي يربط اللسان بقاع الفم. ولكي يتحرك اللسان بحرية، يجب أن ينفصل هذا النسيج عنه جزئيًا. لكن هذا الانفصال لا يحدث أحيانًا، وخصوصًا بسبب عوامل وراثية، فتغدو حركة اللسان محدودة. قد لا يفحص الأطباء هذه الحالة دائمًا، كما أن ملاحظتها ليست سهلة في جميع الحالات. ولكن حتى لو تأخر طبيب طفلكِ في تشخيصها، فهي حالة قابلة للعلاج.') WHERE id = '2904fd26-1eca-4d37-8e98-2e316a3eec9b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لم يتبقَّ الكثير على بدء ظهور أسنان طفلكِ، وربما لا تزال هناك بضعة أشهر. خلال مرحلة التسنين، قد يشعر طفلكِ بحكة شديدة جدًا في اللثة، ويسيل لعابه، ويضع يديه في فمه باستمرار، ويرغب في مضغ كل ما يجده. يمكنكِ استخدام عضّاضة لتخفيف الحكة، وجلّ للتسنين لتخفيف الألم بعد استشارة الطبيب، ومريلة لامتصاص اللعاب. كما يمكنكِ تسهيل هذه المرحلة الصعبة عليكِ وعلى طفلكِ باستخدام بعض الأدوات الموجودة في المنزل. كيف؟ باستخدام مناشف فم نظيفة! بلّلي المنشفة قليلًا، ثم ضعيها في الثلاجة مدة من الوقت حتى تبرد. عندما تصبح باردة ومتماسكة، ستساعد كثيرًا في تخفيف آلام طفلكِ. وننصحكِ بمراقبته باستمرار عند إعطائها له.') WHERE id = '8cafc042-a915-4258-a3c2-d05a6d6f4956';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سواء كان طفلكِ يتغذى على حليب الأم أو الحليب الصناعي، فقد تتساءلين: هل يحتاج جسمه إلى الماء؟ الرأي العام هو أن الأطفال لا يحتاجون إلى ماء إضافي قبل البدء بالأطعمة التكميلية. ويرجع ذلك إلى أن تقديم الماء إلى جانب التغذية الأساسية خلال الأشهر الستة الأولى يقلل شعور الطفل بالعطش. وعندما يقل شعوره بالعطش، يتناول كمية أقل من حليب الأم أو الحليب الصناعي، ما قد يؤدي إلى نقص الطاقة وتأخر النمو. لذلك، فإن الوقت المناسب لبدء إعطاء طفلكِ الماء بانتظام هو عند الانتقال إلى الأطعمة التكميلية. فكلما زادت كمية الطعام الذي يتناوله وأصبح قوامه أكثر كثافة، ازدادت حاجة جسمه إلى السوائل. وفي هذه المرحلة، يكون الماء الخيار الأكثر صحة لتلبية احتياجاته من السوائل. ولا تنسي استشارة طبيبكِ بشأن كمية الماء التي ينبغي تقديمها له.') WHERE id = '8768c9bb-7bc9-40eb-8d2e-760fead026b4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خمسة أشهر حافلة قضيتماها معًا... ما أسرع مرور الوقت، أليس كذلك؟ 😊 سيكون الشهر الخامس لطفلكِ، الذي ينمو يومًا بعد يوم ويدهشكِ كل يوم، مميزًا ومثيرًا للاهتمام أيضًا. في هذه المرحلة، تكون حواس طفلكِ قد تطورت تقريبًا إلى مستوى حواس الشخص البالغ. وبفضل ذلك، تتقدم مهاراته في التواصل وقدرته على التعبير عن نفسه بسرعة. وهذا يعني أنكِ تستطيعين الآن فهم مشاعره بسهولة ووضوح أكبر من السابق. بدءًا من الشهر الخامس، يبدأ طفلكِ بالتعبير لكِ بوضوح عن سعادته، وما يحبه وما لا يحبه، وانزعاجه، وحبه، ورغبته في جذب انتباهكِ. فعلى سبيل المثال، عندما يراكِ أو يرى رضّاعته (إذا كان يتغذى على الحليب الصناعي)، قد يدرك أن وقت الطعام قد حان فيشعر بالحماس، وقد يحاول التعبير عن سعادته بالصياح. كذلك، ونتيجة لتطور ذاكرته ومشاعره، قد يبدأ بالشعور بالقلق تجاه الغرباء والتعامل معهم بمزيد من الحذر.') WHERE id = '12aa96ec-7101-441e-a8b6-16b0a453ee5a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي أن يزداد وزن طفلكِ هذا الشهر بمعدل أقل مقارنة بالأشهر الأربعة الأولى، لأنه أصبح أكثر حركة. لذلك، لا تتوقعي زيادة في الوزن بمقدار 800-1200 غرام شهريًا كما في الأشهر الأولى. تُعد زيادة تتراوح بين 450-750 غرام كافية لطفل في شهره الخامس، وتشير، باستثناء بعض الحالات، إلى عدم الحاجة إلى دعم إضافي. اعتبارًا من الشهر الخامس، قد يتراوح وزن طفلكِ بين 5100-9000 غرام، وطوله بين 58-70 سم. تذكّري أن هناك فروقًا بسيطة بين الذكور والإناث في تطور الطول والوزن، وأن نمو كل طفل يختلف عن الآخر. إذا كنتِ تعتقدين، استنادًا إلى هذه القيم، أن وزن طفلكِ أو طوله أقل أو أكثر من المتوقع، فننصحكِ باستشارة طبيبكِ. ولا تنسي أيضًا أن أسبوع ولادة طفلكِ وطوله ووزنه عند الولادة قد تؤثر جميعها في هذه المؤشرات.') WHERE id = '57b48e89-533e-4812-870a-767029538ffe';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن يبذل جهدًا أكبر لالتقاط الأشياء التي تلفت انتباهه وتقع ضمن مجال رؤيته. فقد تلاحظين أنه يتحمس لشيء يثير اهتمامه، أو يضحك، أو يحاول مد يده إليه، أو يصفق بيديه. وبفضل التطور الملحوظ في قدرته على الرؤية والإدراك، يساعده تنوع الألوان والأشكال التي يراها على تكوين روابط ذهنية وفهم ما حوله. وستلاحظين أيضًا أن طفلكِ أصبح أكثر تفاعلًا اجتماعيًا هذا الشهر. إذا لم تسمعي ضحكاته بصوت عالٍ في الأشهر السابقة، فمن المرجح جدًا أن تسمعيها هذا الشهر. فقد يضحك طفلكِ ويصرخ عندما تدغدغينه، وقد يصدر من تلقاء نفسه أصواتًا مرحة عندما يكون سعيدًا. ومن الطرق الأخرى لإضحاك طفلكِ أن تقابلي ابتسامته بالضحك. يستمتع الأطفال في هذا العمر كثيرًا بتبادل الضحكات. وقد يستمتع طفلكِ أثناء مصّ زجاجة الرضاعة، أو عندما تتحدثين مع شخص آخر، أو تشغّلين أغنية، أو عندما يسمع أي صوت. إن أصوات المناغاة مثل "آغو" والصيحات والقهقهات هي أولى خطوات طفلكِ نحو الكلام. 😊') WHERE id = '57cd3a11-aa81-4f90-bfb2-f69a0e71ee24';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يزداد انتباه طفلكِ قليلًا لما يحدث من حوله، ويبدأ في تمييز الأصوات والتفاعل معها. واعتبارًا من هذا الشهر، تصبح حالته النفسية من الأمور التي ينبغي أن توليها اهتمامًا خاصًا. فعندما يرغب طفلكِ في الاهتمام، أو يشعر بالملل، أو يريد التواصل معكِ، قد يصدر صرخات مفاجئة أو يبكي بصوت مرتفع لجذب انتباهكِ. وتشير هذه المحاولات إلى أنه أصبح قادرًا على فهم العلاقة بين السبب والنتيجة. لذلك، عندما تتحدثين إليه بهدوء وتبدئين بالاهتمام به، قد يتوقف فجأة عن البكاء ويبتسم لكِ. هذا السلوك ليس طبعًا سيئًا لدى طفلكِ، ولا داعي للقلق بشأنه. ولأنه لم يكتسب بعد القدرة الكاملة على الكلام، فهو يحاول بهذه الطريقة لفت انتباهكِ والتعبير عما يزعجه.') WHERE id = 'c9b55f11-f202-4070-8d6a-fc7359809c90';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد متابعة محيط رأس الطفل مهمة بقدر أهمية متابعة طوله ووزنه. وقياس محيط الرأس إجراء روتيني يعطي فكرة عن نمو دماغ طفلكِ. اعتبارًا من هذا الشهر، ينبغي أن يتراوح محيط رأس طفلكِ بين 39 سم و45 سم. ويُعد نمو محيط الرأس ضمن النطاقات المتوقعة مؤشرًا على نمو الدماغ بشكل سليم. وغالبًا ما تُكتشف بعض المشكلات المتعلقة بنمو الدماغ لدى الأطفال عندما يختلف قياس محيط الرأس عن المعدل الطبيعي. لكن لا تدعي زيادة محيط رأس طفلكِ أو نقصانه عن المتوقع تثير قلقكِ فورًا. فهذا الأمر لا يمكن ربطه بالتغذية، كما أن الأرقام المذكورة ليست قواعد قطعية. فكما هو الحال لدى جميع الأطفال، يتمتع طفلكِ أيضًا بقدرات نمو خاصة به. قد يكون محيط رأس الأطفال ذوي البنية الصغيرة وراثيًا أقل من المتوسط رغم تمتعهم بصحة جيدة، بينما قد يكون محيط رأس الأطفال الأكبر بنيةً أعلى من المتوسط بسبب بنيتهم العظمية.') WHERE id = '7475597a-0083-4ac8-af52-e9ec4b5f2395';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يستلقي طفلكِ على ظهره، أصبح الآن يرفع ساقيه في الهواء ويتأملهما بانبهار! وقريبًا جدًا سيبدأ طفلكِ، الذي يحاول اكتشاف قدميه، في الإمساك بهما. سترين ذلك بنفسكِ 😊 في هذه المرحلة، من المهم جدًا اختيار ألعاب تحفّز حواس طفلكِ لدعم نموه. كما ستكون الألعاب التي تساعده على التعرف إلى جسمه مفيدة جدًا في هذه الفترة. انزعي جوربي طفلكِ ودغدغي باطن قدميه برفق، وسترين أنه سيبادلكِ بابتسامة. 😊 تخلق الدغدغة والضحك المتبادل الناتج عنها وسيلة للتواصل والترابط الاجتماعي، مما يعزز الدفء والقرب بينكِ وبين طفلكِ. كما أن سماع ضحكاته أثناء دغدغته سيقوي الرابط العاطفي بينكما. لكن تذكّري أن الإفراط في أي شيء قد يكون ضارًا! :)') WHERE id = '85434c2c-c541-44d1-bc15-24301977fe06';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا تزال تغذية طفلكِ ليلًا مهمة الآن كما كانت في الأشهر الأولى. إذا كان طفلكِ يستيقظ ليلًا، فعليكِ إرضاعه طبيعيًا أو إطعامه بزجاجة الرضاعة كل 3-4 ساعات بحسب حاجته. لكن إذا كان طفلكِ نائمًا ولا يعاني أي مشكلة صحية، فلا ننصحكِ بإيقاظه من النوم لمجرد إطعامه، فهو سيُشعركِ عندما يجوع. ولمساعدته على اكتساب نمط نوم صحي في المستقبل، قد تحتاجين إلى تجنب إطعامه مباشرة قبل النوم أو بعد الاستيقاظ منه. لذلك، شجّعي طفلكِ على أن ينام بنفسه وقدّمي له الدعم اللازم. إذا كنتِ قد عوّدتِ طفلكِ على النوم أثناء الرضاعة، فامنحيه بعض الوقت وتحلّي بالصبر. اطمئني، ستنتظم الأمور خلال وقت قصير! :)') WHERE id = '25c161ab-8831-4065-a3ec-22240c22edb0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد اكتشف رضيعكِ الآن تمامًا قدرته على إصدار الأصوات. وقد يحاول هزّ كل ما تقع عليه يداه لإصدار صوت، ويمكنكِ مساعدته في هذا الاكتشاف. وتُعدّ الخشخيشات من أكثر الألعاب التي يستمتع الرضّع بإصدار الأصوات بها. يمكنكِ العثور في المتاجر على خشخيشات بألوان وأشكال مختلفة. وإلى جانب ذلك، يمكنكِ بسهولة صنع لعبة لطفلكِ باستخدام أغراض منزلية. يكفي لذلك كوبان بلاستيكيان. يمكنكِ وضع بعض الحبوب الجافة المتوفرة في المنزل داخل الكوبين (مثل الأرز والعدس وغيرهما). أغلقي فوهتي الكوبين بإحكام باستخدام شريط لاصق شفاف حتى لا تنسكب محتوياتهما. ويمكنكِ استخدام حبوب كبيرة وأخرى صغيرة للحصول على أصوات مختلفة. فعلى سبيل المثال، ستُصدر حبات الأرز صوتًا أكثر رقة، بينما ستُصدر حبات الفاصولياء صوتًا أغلظ.') WHERE id = 'c96c4837-c392-4247-ae1b-3dcef1d0e562';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ألا تلاحظين أن رضيعكِ أصبح كثير الحركة في الأيام الأخيرة؟ لقد ازدادت قوة عضلات ذراعيه وساقيه كثيرًا خلال هذه المرحلة. ومع تعلّمه الزحف والتقلّب والتحرك مستعينًا بالإمساك بالأشياء، ستواصل عضلاته التطور كلما تحرك. وبما أنه أصبح كثير الحركة، فعليكِ إبقاؤه ضمن مساحة آمنة ومحددة. فلا تتركيه وحده في مكان مرتفع مثلًا، وأبعدي عنه الأدوات الحادة والقاطعة. يستطيع رضيعكِ الآن التقاط كل ما يثير فضوله بإبهامه وبقية أصابعه كما لو كان يستخدم ملقطًا. وسيحاول وضع الأشياء التي يمسكها في فمه لاستكشافها. لذلك نوصيكِ بعدم ترك الألعاب الصغيرة أو العملات المعدنية أو الأغراض الشبيهة بالخرز في متناول يديه، لأنها قد تشكّل خطر الاختناق.') WHERE id = '5d03d27f-629c-43d8-acc3-6fa2f69ef287';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رضيعكِ شديد الحساسية للمساتكِ وللتواصل الذي تجمعينه به. توجد في جلده ملايين النهايات العصبية الدقيقة التي تنبّه دماغه وجهازه العصبي عند تنشيط حاسة اللمس. وتتركز هذه النهايات العصبية بصورة أكبر في المناطق الأكثر حساسية، مثل الإبطين وباطن القدمين والبطن والرقبة. وعندما تلمسين هذه المناطق تحديدًا، تُحفَّز النهايات العصبية، فيستجيب الدماغ بردود فعل مثل الشعور بالدغدغة والقشعريرة والضحك. وعندها يرتفع ضغط دم رضيعكِ، وتتسارع ضربات قلبه ويصبح دماغه أكثر نشاطًا. فدغدغة رضيعكِ، مثلًا، ممتعة وتساعده أيضًا على إدراك حاسة اللمس بصورة أفضل. تذكّري أن الضحك هو الخطوة الأولى في تطور حس الفكاهة لدى رضيعكِ. 😊') WHERE id = '541bc5b2-12fd-4d41-9d69-7d5b93ee3f92';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحب رضيعكِ عادةً البقاء في وضعية الجلوس خلال هذه الأشهر. وحتى إن لم يبدأ بمحاولة الجلوس بعد، فالأمر مجرد مسألة وقت! 😊 يستخدم رضيعكِ يديه للحفاظ على توازنه وإسناد نفسه عند الجلوس، وقد يبدو ظهره منحنيًا قليلًا لأن عضلات ظهره لم تكتمل قوتها بعد. لا ينصح بعض الأطباء ببدء تمارين الجلوس قبل عمر 6 أشهر. ومع ذلك، قد يتبع بعض الاختصاصيين نهجًا أكثر مرونة تبعًا لرغبة الرضيع وتطوره. ومع هذا، من الأفضل لسلامة رضيعكِ أن تكون محاولات الجلوس قصيرة، وأن تُجلِسيه في حضنكِ. ورغم أنه يزداد قوة يومًا بعد يوم، فإن محاولة إجلاسه دون دعم في الوقت الحالي قد تؤدي إلى بعض المضاعفات. طبيبكِ هو من سيقدم لكِ أدق المعلومات المتعلقة بتطوره. لذلك عليكِ استشارة طبيبكِ واتباع إرشاداته في موضوعات مثل الجلوس والأغذية التكميلية والفيتامينات. 😊') WHERE id = '3d5e88a5-68ba-47fd-b5a0-88c276587011';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'التغذية السليمة ضرورية جدًا لنمو رضيعكِ وتطوره بصحة جيدة. فمنذ ولادته، يجب أن يحصل على البروتينات والكربوهيدرات والدهون والفيتامينات والمعادن بصورة متوازنة وبكميات تناسب عمره. ولأن الفترة بين 0-12 شهرًا هي مرحلة النمو الأسرع، تكون حاجته إلى الطاقة أكبر. وخلال هذه الفترة، تزداد حاجته إلى البروتينات والمعادن والفيتامينات بسبب تكوّن أنسجة جديدة في جسمه ونمو عضلاته. وبما أن نمو أنسجة الجسم يتطلب تصنيع البروتين باستمرار، فمن الضروري أن يحصل رضيعكِ على بروتين عالي الجودة. ويُعدّ حليبكِ مصدرًا رائعًا للبروتين بالنسبة إليه، إذ قد تصل قابلية هضم البروتينات الموجودة فيه إلى 95%. لذلك، من المهم جدًا لاستمرار نمو رضيعكِ أن تلتزمي أنتِ أيضًا خلال فترة الرضاعة الطبيعية بنظام غذائي صحي ومتوازن.') WHERE id = '896cbb45-0cf7-4486-ad2b-a52c32d44051';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حتى إن لم يكن رضيعكِ يمر حاليًا بأي مرحلة صعبة، فقد يواجه صعوبة في الاستغراق في النوم. وقد يضطرب نمط نوم الرضيع في عمر 5 أشهر قليلًا بسبب اكتسابه مهارات حركية جديدة كل يوم. وقد يرفض رضيعكِ النوم والرضاعة ليتدرّب على هذه المهارات الجديدة، كما قد يوقظكِ في وقت مبكر صباحًا. إذا كان لا يبكي عند الاستيقاظ، بل يلعب بمفرده في سريره ويمضي بعض الوقت بهدوء، فيمكنكِ وضع لعبة مألوفة مرتبطة بالنوم بجانبه عند تنويمه مساءً. وبعد مدة، سيبدأ رضيعكِ بالشعور بالنعاس كلما رأى هذه اللعبة التي تضعينها إلى جانبه. ولكي تتكوّن هذه العادة بصورة صحيحة، ينبغي ألا تُخرجي لعبة النوم من السرير، وألا تضعيها بجانبه إلا عند حلول موعد النوم. وعند اختيارها، تأكدي من أنها مصنوعة من خيوط أو أقمشة عضوية، وألا تحتوي على أصباغ ضارة أو أجزاء صغيرة قد يبتلعها.') WHERE id = '1fa3a9be-2b21-41b0-8e90-923545dc6c0e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اللعب والوقت الذي يقضيه طفلكِ فيه ليسا مجرد نشاط ممتع للغاية، بل هما أيضًا عملية بالغة الأهمية لنموه. لذلك، لا ينبغي لكِ النظر إلى اللعب على أنه مجرد نشاط تقضين فيه وقتًا ممتعًا مع طفلكِ. فالوقت الذي تقضيانه في اللعب فرصة تعليم وتعلّم لا تُقدّر بثمن. وبما أن حواس طفلكِ أصبحت متطورة بشكل جيد، يساعده اللعب على تفريغ طاقته بالطريقة الأنسب والتعرّف إلى العالم من حوله. ومن وظائف اللعب الأخرى أنه يساعد طفلكِ على التعرّف إلى الأشياء والمفاهيم وأوجه التشابه والاختلاف بينها. ولذلك يكتسب طفلكِ بعض المهارات ويتعلّمها أثناء اللعب. كما أن تمكّنه من إدراك الألوان والأشكال والأسماء والأحجام بما يتناسب مع عمره يساعده في السنوات المقبلة على تعلّم العلاقات والأدوار الاجتماعية والمحاكاة، وبالتالي تطوير شخصيته.') WHERE id = '64ce3005-26f0-4a9c-b4db-77907d346329';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل يعاني طفلكِ من ارتفاع طفيف في درجة الحرارة، أو رغبة في وضع كل ما تطاله يداه في فمه ومضغه، أو فرك أذنه، أو انخفاض الشهية، أو سيلان اللعاب بغزارة؟ إذا كانت إجابتكِ نعم، فتهانينا! أنتِ على وشك رؤية زوج من الأسنان اللؤلؤية. 😊 هذه علامات التسنين، ومع دخول طفلكِ شهره الخامس قد تبدأ أسنانه في الظهور في أي وقت. وقبل ظهور الأسنان الأولى، قد تسبب اللثة المؤلمة والمحمرة والمتورمة انزعاجًا لطفلكِ. تظهر هذه الأعراض قبل نحو ٣-٧ أيام من اختراق السن المستعد للظهور للثة، وهي العملية التي تُعرف ببزوغ الأسنان. والخبر السار هو أن هذه الأعراض المزعجة تزول سريعًا بمجرد ظهور السن عبر اللثة للمرة الأولى. لكن تذكّري: إذا لم تكوني متأكدة من أن الأعراض التي تلاحظينها لدى طفلكِ مرتبطة بالتسنين، فعليكِ حتمًا استشارة طبيبكِ.') WHERE id = 'd5ac321f-14e0-45ad-ab92-652807702fa6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من نمو طفلكِ السريع خلال فترة قصيرة، فإن الكائنات الحية الدقيقة النافعة التي تحمي جسمه من العوامل الضارة، أي الفلورا الجلدية، لم تكتمل بعد. ولا تزال درجة حموضة بشرته (pH) مرتفعة، كما أن طبقة الكيراتين الواقية التي تغطي الجلد لم تتطور بالكامل. وهذا يجعل بشرة طفلكِ، التي لا تزال منخفضة الحموضة ولم يكتمل حاجزها الواقي بعد، أكثر حساسية تجاه الجراثيم والمواد الكيميائية. لذلك عليكِ إيلاء عناية خاصة لدرجة حرارة غسل الملابس التي تلامس بشرة طفلكِ، وكذلك لاختيار منظف الغسيل ومنعّم الأقمشة. فعلى سبيل المثال، من المهم اختيار منظفات ذات مكونات طبيعية عند غسل الملابس لتجنّب احمرار بشرة طفلكِ الحساسة أو إصابتها بالحكة. كما ينبغي لكِ تجنّب منعّمات الأقمشة لاحتوائها على العديد من المواد الكيميائية، مثل العطور. ولا تنسي كيّ ملابس طفلكِ بعد غسلها للمساعدة على التخلص تمامًا من الجراثيم الموجودة عليها.') WHERE id = 'd86eb88e-f066-48c6-be2d-d43e207dbd2c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان لديكِ ولد، فمن المحتمل أن تدور في ذهنكِ بعض الأسئلة حول موعد ختانه. يُعد الختان من أقدم العمليات التي تُمارس في العالم، وهو إجراء تُقطع فيه وتُزال طبقة الجلد التي تغطي رأس القضيب. ووفقًا للإحصاءات، فإن واحدًا من كل ثلاثة رجال في العالم مختون. ومن المهم جدًا تحديد متى وكيف وعلى يد من يُجرى الختان. وتوجد آراء مختلفة حول السن المثالية لإجراء الختان، وهو موضوع يُطرح منذ لحظة ولادة الطفل. وعلى الرغم من عدم وجود دليل علمي قاطع يحدد الفئة العمرية الأنسب، يوصي بعض المتخصصين بإجرائه في سن مبكرة، خصوصًا لتجنّب التعرض لصدمة نفسية.') WHERE id = '05f311d5-ad4e-4d35-963b-6bea5a4bcff4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تترددين في لمس منطقة اليافوخ الموجودة في رأس طفلكِ. ولأن مناطق اليافوخ الست الموجودة في الرأس ليست صلبة مثل بقية أجزائه، تخشى الأمهات عادةً لمسها. لكن اليافوخ يتكون من نسيج ضام قوي يحمي دماغ طفلكِ بأمان. لذلك لا داعي للقلق أو تجنّب لمس هذه المنطقة عند تحميم طفلكِ أو تمشيط شعره أو إسناد رأسه. وإلى جانب أهمية اليافوخ لسلامة طفلكِ، فإنه يؤدي أيضًا دور خوذة واقية من إصابات الجمجمة. وينغلق اليافوخ عادةً من تلقاء نفسه بين عمر ٩ و١٨ شهرًا، من دون الحاجة إلى أي تدخل. وقد تمتد هذه المدة حتى عمر ٢٤ شهرًا أو قد ينغلق في وقت أبكر. ولا تسبب هذه الحالات مشكلة في العادة، لكن من المفيد استشارة طبيبكِ للاطمئنان.') WHERE id = '8c311ff4-c1cb-4399-88d9-4dbb31f984b6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطور إدراك طفلكِ كثيرًا نتيجة تكوّن الروابط بين خلايا دماغه. وبفضل ذلك، بدأ طفلكِ يكتسب مهارات جديدة. وأكثرها إثارة للاهتمام أنه أصبح يفهم أنكِ تنطقين اسمه وتنادينه! 😊 فمناداته باسمه منذ لحظة ولادته تساعده على تسجيل هذه الأصوات في دماغه وحفظها. وبفضل سماعه الأصوات نفسها مرارًا، أصبح طفلكِ قادرًا على التعرّف إلى اسمه. ومن النتائج الأخرى لنموه أنه بات يستطيع التمييز بين أفراد العائلة والغرباء. لذلك، قد يشعر طفلكِ بالغرابة عند رؤية شخص لا يعرفه، وقد يضم شفتيه ويحاول فهم الموقف ثم يبكي، بل قد يقيم الدنيا ولا يقعدها. فكوني مستعدة، لقد حذّرناكِ! 😊') WHERE id = '2af2018e-44d1-408e-a2eb-5673d76e91c6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينتظركِ أنتِ وطفلكِ هذا الشهر كثير من التجارب والتغيّرات الجديدة. ومن المهم جدًا الالتزام بإعطاء طفلكِ لقاحاته في مواعيدها منذ الولادة لحمايته من الأمراض. فمن خلال اللقاح، يُدخَل إلى جسم طفلكِ شكل مُضعَّف من بكتيريا أو فيروس المرض المراد الوقاية منه. وتهدف هذه العملية إلى تحفيز المناعة، فيبدأ جسم طفلكِ بإنتاج أجسام مضادة لهذا المرض. وهكذا، عندما يتعرّض طفلكِ مستقبلًا لهذه الميكروبات، سيكون جسمه قد كوّن بالفعل آلية دفاع قوية. ويتضمن جدول لقاحات الشهر السادس الجرعة الثالثة من لقاح التهاب الكبد B، والجرعة الثالثة من اللقاح الخماسي المركّب، والجرعة الأولى من لقاح شلل الأطفال الفموي (OPA). كما يشمل لقاح شلل الأطفال (التهاب سنجابية النخاع)، الذي سيتلقاه طفلكِ للمرة الأولى. وبذلك يكتمل جدول لقاحات طفلكِ خلال الأشهر الستة الأولى.') WHERE id = '95f9ad1b-63d6-45ba-b708-bf282b104620';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تُسبب اللقاحات أحيانًا الانزعاج أو القيء أو الحمى أو البكاء، لكنها ضرورية للغاية لحماية طفلكِ من الأمراض الخطيرة التي سنذكرها أدناه. أولًا، يسبب فيروس "البوليو" شلل الأطفال (التهاب سنجابية النخاع). وقد يُلحق هذا الفيروس ضررًا بالجهاز العصبي، ما قد يؤدي إلى شلل دائم أو حتى الوفاة. وعلى الرغم من أنه قد يصيب الأشخاص في أي عمر، فإن الأطفال دون سن الثالثة، الذين لم تكتمل مناعتهم بعد، هم الأكثر عرضة للخطر. ولحسن الحظ، أُحيط هذا المرض بقدر كبير من الوقاية بفضل الرقابة الصارمة التي تفرضها الجهات الصحية وحملات التطعيم. أما الدفتيريا فهي مرض خطير قد يُلحق الضرر بالجهاز التنفسي والجهاز الهضمي والقلب، وقد يؤدي إلى الوفاة. والكزاز مرض خطير قد ينشأ عند الإصابة بجروح ناجمة عن معادن صدئة أو تربة ملوثة أو أدوات حادة، ويؤثر مباشرةً في الجهاز العصبي. أما التهاب السحايا فقد يؤدي، إلى جانب ارتفاع خطر الوفاة، إلى عواقب وخيمة مثل الإعاقة والتأخر الذهني والصمم والعمى. لذلك تُعد اللقاحات الدرع الأكثر موثوقية لضمان مستقبل صحي لطفلكِ.') WHERE id = '2ec370c7-9d55-4f76-86f5-a1d0c2080600';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُدهشكِ طفلكِ كل يوم بحركات جديدة، ومع تطور عضلات ظهره، أصبح يستعد الآن للجلوس من دون دعم. إذا شعرتِ بأنه مستعد للجلوس وكنتِ متأكدة من ذلك، فيمكنكِ مساعدته قليلًا. في البداية، أجلسيه في حضنكِ وأمسكي يديه، مع التأكد من إبقائه رأسه منتصبًا. بعد ذلك، يمكنكِ إجلاسه على الأريكة ووضع وسائد حوله لمساعدته على الحفاظ على توازنه. لا تقلقي إذا شعر طفلكِ بالتعب ومال إلى أحد الجانبين أحيانًا أثناء هذه التمارين. فكلما قويت عضلاته وتطور إحساسه بالتوازن، ازدادت المدة التي يستطيع خلالها الجلوس. وبعد فترة، سترين أنه يحافظ على توازنه بنفسه ويجلس من دون دعم. وعندها لن تعودي بحاجة إلى الوسائد! 😊') WHERE id = '4613232a-c667-47df-9951-c91586b62ee3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمثل الشهر السادس نقطة تحوّل مليئة بالتجارب الجديدة والمفاجآت لكِ ولطفلكِ. ونعلم مدى حماسكِ لأنكِ ستبدئين بتعريف طفلكِ على الأغذية التكميلية! توضح منظمة الصحة العالمية وخبراء الصحة أن الجهاز الهضمي للرضيع يصبح مستعدًا للأغذية التكميلية بعد إتمامه 180 يومًا. خلال الأشهر الستة الأولى، كنتِ تُطعمين طفلكِ حليب الأم أو الحليب الصناعي فقط. أما الآن، فسيتعرّف جسمه على أطعمة ذات مكونات مختلفة، ولذلك قد تظهر بعض ردود الفعل التحسسية. لذا ننصحكِ بالانتقال إلى الأغذية التكميلية تدريجيًا وبرفق، وعدم التسرع كي لا ترهقي جهازه الهضمي. سيساعدكِ قسم "الوصفات" لدينا كثيرًا في هذه المغامرة اللذيذة. بالهناء والشفاء! 😊') WHERE id = '1057a1b2-3687-4581-b2fe-6f0fca8b4778';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد حان وقت الأغذية التكميلية الممتع لكِ ولطفلكِ! لكن هل كل شيء جاهز؟ إن أهم مؤشر على استعداد طفلكِ للأغذية التكميلية هو، بالطبع، قدرته على الجلوس. لذلك ستحتاجين إلى كرسي طعام جيد. ولا ينبغي لكِ اعتبار كرسي الطعام مجرد كرسي؛ فهو ليس مجرد مكان يتناول فيه طفلكِ طعامه. فهناك أسباب مهمة عديدة لتعويده على تناول الطعام في كرسي الطعام. وأهمها أن هذه الكراسي تتيح لطفلكِ الجلوس معكم إلى المائدة نفسها. كما أن وجوده إلى المائدة مع أفراد الأسرة يساعدكِ على التواصل معه أكثر وتقوية الرابطة بينكما. وعند اختيار كرسي الطعام لطفلكِ، احرصي على أن يكون آمنًا ومريحًا وخفيفًا ومصنوعًا من مواد عالية الجودة.') WHERE id = 'f8f5f75d-b030-4498-b7d5-7b4bc417016c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، يبلغ إجمالي مدة نوم طفلكِ يوميًا نحو 13 ساعة. ويُتوقع أن يأخذ قيلولتين خلال النهار، وقد ينام ليلًا مدة 6-7 ساعات متواصلة. ومع نمو طفلكِ، ستقل حاجته إلى النوم قليلًا؛ إذ تُفرَز الهرمونات المسؤولة عن النمو خلال النوم ليلًا. وفي هذه المرحلة، يُتوقع أيضًا أن يعتاد طفلكِ النوم بمفرده. لذلك، إذا كنتِ ما زلتِ تساعدينه على النوم عن طريق هزّه أو إرضاعه أو المشي به، فننصحكِ بتقليل ذلك تدريجيًا والتوقف عنه قريبًا. ينصح بعض الخبراء بعدم التدخل في كل مرة يبكي فيها الطفل، حتى يتمكن من اكتساب نمط نوم ليلي صحي. لذا، إذا كنتِ متأكدة من أن طفلكِ شبعان وحفاضه نظيف ولا يعاني أي مشكلة، فلا تتدخلي فورًا كلما بكى. فالطفل الذي يُحمَل في كل مرة يبكي فيها قد لا يتعلم أن ينام بمفرده.') WHERE id = '790745e1-b64b-4611-b8ea-ced2bd5bd141';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تبدأ مرحلة التسنين لدى الأطفال عادةً اعتبارًا من الشهر 5. وإذا لم تبدأ أسنان طفلكِ بالظهور بعد، فقد تواجهين آلام التسنين خلال هذا الشهر. التسنين عملية طبيعية، لكن طفلكِ قد يشعر بانزعاج شديد خلالها. وينتج هذا الانزعاج عن حكة اللثة، وقد يسبب له الألم من حين إلى آخر. عادةً ما تظهر الأسنان الأولى في فم الطفل بين الشهرين 5-9. وبينما قد تظهر السن الأولى لدى بعض الأطفال في الشهر 3، قد تتأخر هذه العملية لدى آخرين حتى الشهرين 13-14. إذا لم تكن لدى طفلكِ أي مشكلة صحية، فلا توجد علاقة مباشرة بين سرعة التسنين ونموه وتطوره. ويعتمد هذا الأمر بدرجة أكبر على العوامل الوراثية، ومن المرجح أن تسير عملية التسنين لديه بطريقة مشابهة لما مررتما به أنتما الوالدان في طفولتكما.') WHERE id = '2b63b86d-359a-4b54-8d2d-d3bc2859ca20';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'شعر طفلكِ حساس وناعم للغاية، لذلك ينبغي أن تكون العناية به جزءًا مهمًا من النظافة اليومية. قد يكون طفلكِ قد وُلد بشعر كثيف أو خفيف، وربما وُلد بلا شعر وبدأ شعره بالنمو حديثًا. وفي جميع الأحوال، يحتاج شعر طفلكِ وفروة رأسه إلى عناية خاصة. يمكنكِ تحميم طفلكِ يوميًا في أشهر الصيف، ومرة كل يومين أو ثلاثة أيام في أشهر الشتاء. وللوقاية من الحساسية أو الاحمرار أو الحكة، عليكِ تجنب المنتجات التجارية التي تحتوي على مواد كيميائية. واستخدمي منتجات خالية من البارابين والكبريتات والعطور الاصطناعية والمواد الضارة التي قد تهيّج بشرة طفلكِ. وإذا واجهتِ صعوبة في العثور على منتجات ذات مكونات نقية، فيمكنكِ أيضًا اختيار أنواع عالية الجودة من الصابون الطبيعي الصلب أو صابون قشتالة السائل.') WHERE id = '9f4a8a9d-785a-42f3-bcb2-0880d1571c96';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحين موعد بدء تقديم الأغذية التكميلية لطفلكِ بعد 180 يومًا من تاريخ ولادته المتوقع. وهذا يعني أن نهاية الشهر 6 هي أنسب وقت لتعريفه بالأغذية التكميلية. وفي بعض الحالات، يمكن البدء بها في وقت أبكر بناءً على نصيحة الأطباء، إذ يكون الأطفال قد اكتسبوا بالفعل منعكس البلع. ومع ذلك، ومن أجل صحة البكتيريا النافعة في الأمعاء، يُفضّل الانتظار قليلًا إذا لم يكن هناك أي تأخر في نمو طفلكِ. يجب أن تكون الأغذية التكميلية التي يمكنكِ تقديمها لطفلكِ في الشهر 5 سائلة تمامًا، وينبغي الانتظار قليلًا قبل تقديم الطعام المهروس. وقد يكون مرق حساء الخضراوات المحضّر طبيعيًا وعصائر الفاكهة غير المسببة للحساسية مناسبين لطفلكِ. ونظرًا إلى خطر الإصابة بحساسية الطعام، يُنصح بأن تقدمي لطفلكِ الطعام الذي سيتذوقه للمرة الأولى بكمية صغيرة جدًا، مثل 1 ملعقة صغيرة.') WHERE id = '57b7991c-272a-4ed5-898c-f9700be1db2a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يساعد تدليك طفلكِ على تنشيط دورته الدموية وتحسين نمو عضلاته وعظامه. كما يساعد على تهدئته من خلال تخفيف الغازات والمغص الذي قد يصيبه. والهدف الأساسي من تدليك الطفل هو منحه الاسترخاء باستخدام التقنية الصحيحة، ودعم نموه وتطوره الذهني والحركي بصورة إيجابية من خلال التدليك المنتظم. وتُعد التمارين البسيطة، خصوصًا بعد الشهر 4، مهمة جدًا لنمو طفلكِ. عليكِ تدليك طفلكِ يوميًا في وقت لا يكون فيه جائعًا، ويكون هادئًا ومستعدًا للتدليك. وأنسب وقت لذلك هو بعد الرضاعة أو تناول الطعام بمدة 1-1.5 ساعة. قبل بدء التدليك، لا تنسي خلع المجوهرات من يديكِ، وتأكدي من أن أظافركِ ليست طويلة وأن يديكِ نظيفتان ودافئتان. كما ينبغي ضبط درجة حرارة الغرفة جيدًا أثناء التدليك، وألا تتركي طفلكِ وحده مطلقًا. استمتعا بوقتكما! 😊') WHERE id = '98edcdb5-d642-4617-8cc5-e7bd1fc8f734';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُستخدم جلّات التسنين كثيرًا لمساعدة الأطفال على اجتياز مرحلة التسنين براحة أكبر. ولكن توجد وسائل فعالة عديدة لتخفيف أعراض التسنين من دون اللجوء إلى مسكنات الألم أو الجلّات. تُعد عضّاضات التسنين من الوسائل المساعدة التي سيحبها طفلكِ كثيرًا وستفيده. ولا تنسي أنها تكون أكثر فعالية عند تبريدها في الثلاجة. 😊 كما أن ملامسة هذه العضّاضات للثة قد تمنحها تأثيرًا شبيهًا بالتدليك وإحساسًا بالبرودة، ما يساعد على تخفيف آلام طفلكِ. وكطريقة أخرى، يمكنكِ وضع منشفة تنظيف فم طفلكِ في الثلاجة لمدة نصف ساعة، سواء كانت رطبة أو جافة، ثم إعطاؤها له ليمضغها. قد تساعد ملامسة جسم بارد للثة على تخفيف الألم والتورم والشعور بالضغط لدى طفلكِ. لكن في كلتا الطريقتين، ننصحكِ بالتعقيم الجيد لتجنب احتمال انتقال الجراثيم إلى طفلكِ. 😊') WHERE id = '61a39689-4f67-40ed-b7d3-3829e2076603';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يقضي طفلكِ خلال هذا الشهر نحو 15 ساعة من وقته في النوم في المتوسط. وعادةً ما ينام 10 ساعات ليلًا و5 ساعات نهارًا. لكن قد ينام طفلكِ أقل من ذلك لبعض الأسباب، أو يجد صعوبة في الاستغراق في النوم، أو يستيقظ مرارًا أثناء نومه. يُعد تحميم طفلكِ قبل النوم من أفضل العادات الروتينية التي تسهّل انتقاله إلى النوم. ويمكنكِ أيضًا أن تضيفي إلى روتين النوم تدليكًا مهدئًا قبل النوم، أو قراءة قصة، أو تصفح صور كتاب ملوّن معًا. ويساعد إبقاء الإضاءة خافتة في الغرفة أثناء الاستعداد للنوم طفلكِ كثيرًا على الاستغراق فيه. وفي الظروف الطبيعية، قد يستيقظ طفلكِ ليلًا للرضاعة أو تناول الطعام إذا شعر بالجوع. ولا تزال الرضعات الليلية مهمة جدًا لنمو طفلكِ. لذلك، لا داعي للقلق، وتذكّري أن طفلكِ لا يزال في مرحلة نمو سريع.') WHERE id = '388b1d4a-2870-47fb-8a38-2987cb7bbaf9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بما أن طفلكِ أصبح قادرًا على الجلوس باستقامة أكبر، يتسع مجال رؤيته ويتمكن من التفاعل مع محيطه بنشاط أكبر. ويساعد ذلك أيضًا على تطور مهاراته الحسية والحركية. ومع استمرار نموه، يزداد اهتمامه بكل ما يتيح له فرصة اللعب والاستكشاف. فعلى سبيل المثال، مع بدء تطور مهاراته الحركية الدقيقة، يصبح طفلكِ قادرًا على التقاط الأشياء الصغيرة بأصابعه أو بإبهامه. كما يمكنه نقل الأشياء التي يمسكها من يد إلى أخرى. وقد يمد يده نحو الألعاب البعيدة عنه والواقعة ضمن مجال رؤيته محاولًا التقاطها. وإذا لم يتمكن من التقاط لعبة أسقطها أو تركها، فقد يشير إليكِ ويطلب منكِ إعطاءها له. ومع ذلك، قد لا تلاحظين لدى طفلكِ بعض هذه المراحل التطورية بعد. ويرجع ذلك إلى اختلاف وتيرة نمو كل طفل، لذا لا داعي للقلق.') WHERE id = '6730fee9-c4d4-4db1-af73-50d999349b75';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي لكِ خلال هذا الشهر البدء بإعطاء طفلكِ مكمل الحديد، بعد استشارة طبيبه أو الحصول عليه من العيادة. ويُعد نقص الحديد أكثر أشكال نقص العناصر الغذائية شيوعًا في العالم، كما يمثل مشكلة صحية مهمة، ولا سيما في البلدان النامية. ومن أبرز المشكلات التي يسببها نقص الحديد، إلى جانب فقر الدم، تأثيره السلبي في التطور الذهني لدى الرضع. فقد يؤدي نقص الحديد خلال مرحلة الرضاعة، حين ينمو الدماغ بسرعة ويكتسب الطفل المهارات النفسية الحركية الأساسية، إلى إبطاء تطوره الذهني. ووفقًا للدراسات، قد ينخفض معدل الذكاء بصورة دائمة بنحو ٥ نقاط عن المستوى المتوقع. لذلك توصي منظمة الصحة العالمية بإعطاء مكملات الحديد للرضع الذين تتراوح أعمارهم بين ٦ و١٢ شهرًا. كما توصي الأكاديمية الأمريكية لطب الأطفال بإجراء فحص دم للرضع مرة واحدة بين عمر ٩ و١٢ شهرًا للتحقق من مستويات الحديد لديهم.') WHERE id = 'da861e51-ae52-40b6-a6f0-c4e0e3afd9bf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظهر مشكلة الإمساك كثيرًا عند بدء إدخال الأطعمة التكميلية، ولا سيما لدى الرضع الذين كانوا يتغذون على حليب الأم سهل الهضم أو الحليب الاصطناعي. إذا كنتِ تشكين في إصابة طفلكِ بالإمساك، فننصحكِ بقراءة النقاط التالية بعناية. أولًا، لا يتطور الجهاز الهضمي لدى جميع الأطفال بالوتيرة نفسها. فقد يحدث الإمساك رغم البدء بإدخال الأطعمة التكميلية بعد إتمام الشهر السادس. لذلك يمكنكِ إيقاف الأطعمة التكميلية مؤقتًا، ثم المحاولة مجددًا لاحقًا. وخلال هذه الفترة، يمكنكِ تقديم الحساء الخفيف أو عصائر الفاكهة لطفلكِ. وعند بدء الأطعمة التكميلية، انتبهي إلى أطعمة مثل الموز والبطاطس، إذ قد تسبب الإمساك. وإذا لاحظتِ حدوث الإمساك بعد تقديم هذه الأطعمة، فينبغي إيقافها لفترة. كذلك، إذا لاحظتِ أن طفلكِ يعاني من الإمساك وصعوبة في التبرز، فقد يكون لديه شق شرجي. ومن المهم في هذه الحالات التواصل مع طبيبه.') WHERE id = '9037133c-00b1-4728-bfa8-d12451129dad';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكاد الفلورا المعوية لدى طفلكِ، المعروفة باسم الميكروبيوتا، تكتمل. وهناك بعض الأمور التي ينبغي لكِ الانتباه إليها للحفاظ على توازنها. إذا كانت ولادتكِ قيصرية، تبدأ البكتيريا المساعدة على الهضم بالظهور في الفلورا المعوية لطفلكِ اعتبارًا من اليوم الثامن، أما إذا كانت الولادة طبيعية فتبدأ اعتبارًا من اليوم الرابع. وتتكون هذه الكائنات الموجودة في الفلورا المعوية من بكتيريا نافعة وأخرى ضارة. ويساعد وجود كلا النوعين على منع التكاثر المفرط لأي منهما، مما يحافظ على توازن الجهاز الهضمي. ويمكنكِ دعم الفلورا المعوية لطفلكِ باستخدام البروبيوتيك والبريبايوتيك. كما تحفز هذه المكملات إفراز السيروتونين، المعروف أيضًا باسم هرمون السعادة. ويمكنكِ إدخال الأطعمة التي تحتوي على هذه البكتيريا النافعة ضمن غذاء طفلكِ، أو استشارة طبيبه بشأن مستحضرات البروبيوتيك المعبأة والمتوفرة في الأسواق.') WHERE id = '9e82ffd7-d409-49b6-a002-4b2672efef01';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُكسب اللقاحات المدرجة في جدول تطعيم طفلكِ جسمه مناعةً مكتسبة. وتتشكل هذه المناعة من خلال إدخال كائنات دقيقة مسببة للمرض إلى جسمه، مما ينبه جهازه المناعي وينشطه. لذلك قد يشعر طفلكِ بانزعاج خفيف عند دخول هذه الميكروبات إلى جسمه للمرة الأولى، لكنه يكتسب في الوقت نفسه مناعة ضد ذلك المرض. وبفضل خلايا الذاكرة المناعية، لا يُصاب بالمرض نفسه مرة أخرى. ففي التطعيم، تُدخَل إلى جسم طفلكِ كائنات دقيقة مُضعفة أو مقتولة، مما ينبه جهازه المناعي ويجعله مستعدًا للدفاع بفاعلية عندما يواجه الميكروب الحقيقي مستقبلًا. وعلى الرغم من أن اللقاحات لا تحمي طفلكِ من الأمراض بنسبة 100%، فإن وجود أجسام مضادة جاهزة في جسمه يساعده على تجاوزها بأعراض أخف بكثير.') WHERE id = '6a597987-e8b8-4f14-a6ec-55936a1409ea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد ينام طفلكِ في عمر ٦ أشهر نحو ١١ ساعة يوميًا. ولا يعني متوسط مدة النوم هذه أنه سينام ليلًا فقط، إذ لا تزال القيلولة النهارية مهمة جدًا له. ووفقًا للأكاديمية الأمريكية لطب الأطفال، يبدأ اعتبارًا من هذا الشهر الوقت المناسب لانتقال الطفل إلى غرفته والنوم منفصلًا عنكِ. ويرجع ذلك إلى أن اعتماد الطفل على حليب الأم يقل نسبيًا مقارنةً بالأشهر الأولى بعد بدء إدخال الأطعمة التكميلية. لكن إجراء هذا الانتقال بسرعة كبيرة قد يسبب بعض الاضطرابات في تطوره النفسي. ومن الحالات الشائعة خصوصًا أن يستيقظ الطفل ليلًا خائفًا ويبكي. لذا امنحي طفلكِ الوقت الكافي للتكيف مع هذا الوضع الجديد، وأديري هذه المرحلة تدريجيًا وبصبر.') WHERE id = '68a677bc-c6fd-496b-bd7c-d65d75f316ae';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أنكِ تواجهين صعوبة في تنويم طفلكِ خلال هذه الفترة. ففي مرحلة حديثي الولادة، كان إشباع طفلكِ والحفاظ على نظافة حفاضه كافيَين لينام جيدًا. لكن قد يصبح تحضير طفلكِ للنوم أصعب قليلًا الآن، بعد أن أصبح أكثر وعيًا بالعالم الخارجي وتطورت حواسه. لذلك، لم يعد تلبية احتياجاته الجسدية وحدها كافية لينام من تلقاء نفسه. وعند تحضير طفلكِ للنوم، يكون دماغه في حالة نشاط كبير، لذا عليكِ عزله عن جميع أنواع الضوضاء. فقد يبقيه صوت التلفاز أو أصوات الحديث مستيقظًا. ومن الضروري التخلص من هذه العوامل حتى يتمكن طفلكِ من الاستغراق في النوم براحة. كذلك، قد تؤدي حرارة الغرفة الشديدة أو برودتها الشديدة إلى تأخير نومه وتقليل جودته. ويُعد الحفاظ على درجة حرارة الغرفة التي ينام فيها طفلكِ بين 22-24°C مثاليًا. أحلامًا سعيدة! 😊') WHERE id = '1a8c9918-d018-4b4c-8f7f-c8a0898c2b43';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من الأنشطة التي يمكنكما القيام بها معًا خلال هذا الشهر بما يتناسب مع تطور طفلكِ. نتمنى لكما وقتًا ممتعًا من الآن! 😊 أولًا، ما رأيكِ في ممارسة ألعاب المرآة مع طفلكِ الذي يُبدي اهتمامًا كبيرًا بالمرايا؟ أمسكي مرآة، وقفي أمامها، ثم أعطي طفلكِ كرةً صغيرةً بالتناوب بين يديه. وهكذا، سيتعلم بعد فترة نقل اللعبة من يد إلى أخرى. وفي نشاط آخر، اجعلي كرةً ملونةً تجذب انتباه طفلكِ ترتد صعودًا وهبوطًا على الأرض. وسيتعلم طفلكِ خلال وقت قصير تتبع الكرة التي لفتت انتباهه بعينيه. بعد ذلك، دحرجي الكرة التي في يدكِ نحو الحائط لتصطدم به وتعود إليكِ. وسيتعلم طفلكِ من خلال مشاهدة ارتداد الكرة عن الحائط.') WHERE id = 'd9644453-95a5-4346-bbea-e0599b06e143';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه الأيام التي اقتربتما فيها كثيرًا من مرحلة إدخال الأطعمة التكميلية، من أهم الأمور التي عليكِ الانتباه إليها حصول طفلكِ على كمية كافية من البريبايوتيك. تساعد البريبايوتيك على تعزيز وظائف المناعة في جسم طفلكِ، وتزيد مقاومته للأمراض، كما تفيد جهازه الهضمي. كذلك، تدعم البريبايوتيك التي يحصل عليها مع الأطعمة التكميلية وظائف حليب الأم، وهو أغنى مصادر البريبايوتيك. ويأتي الزبادي في مقدمة الأطعمة الغنية بالبريبايوتيك والبروبيوتيك. والزبادي منتج ألبان أبيض وكثيف القوام ينتج عن تخمير الحليب. وهو حليب متخثر ينتج عن تحوّل اللاكتوز، وهو سكر الحليب، جزئيًا إلى حمض اللاكتيك بفعل بادئ الزبادي. وبفضل غناه بالكالسيوم والبروتين وفيتامينَي B12 وB6، يُعد الزبادي، إلى جانب حليب الأم، من أهم الأطعمة التي تساعد على تعزيز مقاومة جسم طفلكِ.') WHERE id = '67e55468-7559-4a60-ab60-67f55f552e34';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض الأمور التي عليكِ مراعاتها عند غسل ملابس طفلكِ. ومن أهمها خصائص منتجات الغسيل التي ستستخدمينها وكيفية اختيارها. وإذا أخذنا في الاعتبار أن بعض منظفات الغسيل وأنواع الصابون المتاحة في الأسواق قد تسبب الحساسية حتى للبالغين، فإن الخطر يكون أكبر عند التعامل مع بشرة طفلكِ الحساسة. ويؤكد المختصون خصوصًا أن بعض المواد الكيميائية المستخدمة خلال مرحلة الرضاعة قد تسبب تفاعلات تحسسية حتى بعد مرور سنوات. لذلك، عليكِ تجنب منعمات الأقمشة والمبيضات والمنتجات المعطرة المهيجة للبشرة عند غسل ملابس طفلكِ. وتتوفر في الأسواق منظفات كثيرة أو أنواع صابون حبيبي مصممة خصيصًا للأطفال. وسيساعد اختيار المنتجات الخالية من العطور من بينها على الوقاية من تهيجات البشرة المحتملة.') WHERE id = 'abaadbfc-c35e-4cb0-b8bc-31d98a9f8ecf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد القيلولة مهمة جدًا لطفلكِ، وينبغي في هذه المرحلة أن يخصص لها 4-5 ساعات من يومه. ووفقًا للدراسات، تبيّن أن الطفل الذي يحصل على قسط كافٍ من القيلولة بما يتناسب مع عمره يستطيع النوم لفترة أطول بكثير ليلًا. وبحسب المختصين، تُعد القيلولتان الأوليان من اليوم الأكثر فائدة خصوصًا. فهاتان القيلولتان تمنحان طفلكِ قدرًا أكبر من النشاط، وتساعدان جسمه على استعادة حيويته. كما يستطيع الأطفال الاستغراق في القيلولة الأولى من اليوم بسهولة أكبر مقارنةً ببقية القيلولات. لذلك، لا تفوّتي هذه الفترة المثالية للنوم في الساعات الأولى من اليوم، وساعدي طفلكِ على النوم بمجرد أن تظهر عليه علامات النعاس. لكن عليكِ أن تتذكري أن نوم طفلكِ نهارًا أكثر مما يحتاج إليه قد يؤثر سلبًا في نومه ليلًا.') WHERE id = '59732708-2d13-4639-9614-435d122c79cb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الشهر 6 إحدى أهم نقاط التحول في حياة طفلكِ. فبعد أن أصبح يدرك أنه كيان مستقل، بدأ يتعلم أيضًا تفاصيل التواصل مع الآخرين. ومن هذا المنطلق، يبدأ طفلكِ للمرة الأولى في اكتشاف ملامح شخصيته. وهذا تطور ذهني بالغ الأهمية. 😊 وعلى الرغم من أنه يستخدم حواسه بفاعلية، فإنه بدأ الآن يستخلص استنتاجاته الخاصة استنادًا إلى التجارب المخزنة في ذاكرته. فعلى سبيل المثال، يمكنه الآن اختيار لعبته المفضلة من بين ألعابه وإفهامكِ أنها المفضلة لديه. كذلك، رغم أن طفلكِ بدأ يرى بوضوح منذ فترة، فإنه أصبح منذ هذا الشهر قادرًا على إدراك الصور المعقدة للغاية. وبفضل ذلك، سيتمكن أيضًا من التمييز بفاعلية بين الأشكال والملامس الجديدة.') WHERE id = 'b6d7faf8-f7c6-4e9e-a7ff-43facd4aa9db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يزال حليبكِ أو الحليب الصناعي أهم مصدر غذاء لطفلكِ. وخلال مرحلة إدخال الأطعمة التكميلية، ينبغي ألا تهملي الرضاعة الطبيعية مطلقًا أو تقلّلي منها. ما لم يوصِ الطبيب بخلاف ذلك، تُقدَّم الأطعمة التكميلية بين عمر ٦ و٨ أشهر بهدف التذوق والانتقال التدريجي فحسب، بينما يظل حليب الأم الغذاء الأساسي خلال هذه الفترة. وعند البدء بالأطعمة التكميلية، عليكِ أيضًا مراقبة بعض علامات النمو لدى طفلكِ. فعلى سبيل المثال، يُتوقع في هذه المرحلة أن يتمكن من إبقاء رأسه منتصبًا والجلوس، وأن يتطور التناسق بين يديه وعينيه. وقد يدفع طفلكِ الطعام بلسانه أو يرفض تناوله عند تعرّفه إلى نكهات مختلفة للمرة الأولى. وهذا طبيعي تمامًا، فهو رد فعل انعكاسي سيزول بمرور الوقت. وتدريجيًا، ستتطور لديه مهارات فتح الفم والبلع والمضغ. لذلك، لا تجبري طفلكِ خلال هذه المرحلة، وتذكّري أن الأطعمة التكميلية التي تقدمينها له ليست سوى مكمّل لحليب الأم.') WHERE id = '28ae02f7-da1a-49dd-85b2-b82676a86611';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتقدم طفلكِ في هذه المرحلة بخطوات سريعة جدًا من حيث النمو الجسدي والإدراكي واللغوي. ولا شك أن كل حركة أو سلوك جديد يكتشفه يثير حماسكِ كثيرًا. وعلى عكس البالغين، يستطيع الأطفال اكتساب مهارات مهمة في نموهم خلال وقت قصير جدًا. فمثلًا، قد ترين اليوم طفلكِ الذي لم يكن يستطيع الجلوس من دون مساعدة بالأمس جالسًا بمفرده! 😊 ومع ذلك، ربما يكون طفلكِ قد حقق بعض مراحل النمو المتوقعة لدى الأطفال في عمر ٦ أشهر، بينما لم يحقق بعضها الآخر بعد. ولا ينبغي أن يثير ذلك قلقكِ، لأن كل طفل ينمو وفق وتيرته الخاصة. إذا كنتِ تعتقدين أن طفلكِ لا يزال غير قادر على الجلوس دون دعم أو الحفاظ على توازنه جيدًا، فتحلّي بالصبر؛ فسترين أنه سيكتسب هذه المهارات خلال وقت قصير جدًا! 😊') WHERE id = '6188303f-604c-4619-8980-cdb921290253';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ اتخاذ بعض التدابير للحد من إصابة طفلكِ بالإمساك خلال مرحلة إدخال الأطعمة التكميلية. أولًا، استشيري طبيبكِ للتأكد مما إذا كان الإمساك مرتبطًا بأي مشكلة صحية أو نمائية. كما يمكن أن يساعد تحميم طفلكِ بالماء الفاتر وتدليك بطنه على تنشيط حركة الأمعاء. وبناءً على توصية طبيبكِ، يمكنكِ إضافة أطعمة تساعد على تخفيف الإمساك إلى قائمته الغذائية، مثل المشمش المجفف والقراصيا والخضروات الورقية الخضراء الداكنة والكمثرى. وقد يكون من المفيد أيضًا نقع الفواكه المجففة في ماء فاتر وإعطاؤه هذا الماء خلال اليوم. وطوال هذه الفترة، عليكِ إرضاع طفلكِ كثيرًا. وإذا كنتِ لا ترضعينه طبيعيًا، فلا تقلّلي كمية الحليب الصناعي وراقبي حصوله على كمية كافية من السوائل. ولا يُنصح أيضًا بتحفيز منطقة الشرج لمساعدة طفلكِ على التبرز، لأن ذلك قد يتحول إلى عادة، لذا ينبغي تجنّبه.') WHERE id = 'e2db0876-de2c-4046-9525-ff64acf7b248';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون طفلكِ البالغ من العمر ٦ أشهر قادرًا الآن على الجلوس بدعم أو من دونه، والتدحرج، وحتى الوقوف لفترة وجيزة جدًا. ولأن هذه الحركات تتطور في أوقات مختلفة لدى كل طفل، فقد تحتاجين عند حلول الوقت المناسب إلى دعمه ببعض الأنشطة. يمكنكِ وضع طفلكِ مستلقيًا على ظهره على الأرض أو السرير ومساعدته على التدحرج في أثناء وجودكِ بجانبه. احتضني صغيركِ عندما يحاول مد ذراعيه نحوكِ، وأظهري له تقديركِ لنجاحه. وإذا لم يتحرك، فيمكنكِ تشجيعه بقلبه على بطنه ثم إعادته إلى ظهره. بالإضافة إلى ذلك، تساعد ألعاب اليدين على تنمية حاسة اللمس، كما أنها نشاط رائع ليستمتع به بمفرده. يمكنكِ إجلاس طفلكِ قبالتكِ، ثم رفع أصابعكِ إلى مستوى عينيه تمامًا، وعرضها عليه بالتتابع وعدّها واحدًا تلو الآخر. وقتًا ممتعًا! 😊') WHERE id = '8d36fd03-563f-4c3d-92c7-c802cd459f32';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه الفترة التي تبدئين فيها بإدخال الأطعمة التكميلية، يمكنكِ أن تقدمي لطفلكِ مهروس وعصير فواكه مثل التفاح والخوخ والكمثرى، وكذلك مهروس خضروات مثل البطاطس والجزر واليقطين. ويمكنكِ أيضًا، بعد استشارة الطبيب، إضافة مسحوق البروبيوتيك الذي تشترينه من الصيدلية إلى الزبادي الذي تحضّرينه بنفسكِ في المنزل. ويأتي حليب البقر والأطعمة المحتوية على السكر أو الملح في مقدمة الأطعمة التي ينبغي تجنّبها عند إدخال الطعام التكميلي. فقد يتسبب حليب البقر في نزف خفي في الأمعاء خلال المراحل المبكرة. كما لا ينبغي تقديمه قبل عمر سنة، بسبب عدم احتوائه على كمية كافية من الحديد واحتمال تسببه بالحساسية نتيجة البروتينات الغريبة الموجودة فيه. ولا تنسي أيضًا أن الأطعمة المصنّعة الجاهزة لا مكان لها في قائمة طفلكِ الغذائية. وإلى جانب ذلك، يُفضّل أن تُحلّي الأطعمة التي تقدمينها لطفلكِ بدبس الفاكهة أو الفواكه بدلًا من السكر.') WHERE id = 'bdbf69c9-7362-46c7-9230-c6195ba35de7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أظهرت الدراسات أن الأطفال ينمون بصورة أفضل في بيئة يتعرضون فيها لمقدار معتدل من المحفزات. لذلك، فإن تعريف طفلكِ إلى أنسجة وأشكال وأصوات مختلفة يتيح تدفق معلومات جديدة إلى دماغه. وتُعد أنشطة الإدراك الحسي التي تقدمينها لطفلكِ البالغ من العمر ٦ أشهر مهمة جدًا لنموه الذهني. وفي هذه المرحلة، ستكون لعبة الغميضة والتهويدات ذات القوافي ودمى الأصابع ممتعة، وستسهم أيضًا في نمو طفلكِ. ينبغي أن تتيحي لطفلكِ فرصة استكشاف كل غرض جديد تضعينه أمامه بنفسه، وأن تمنحيه الوقت الكافي للتعرف إلى خصائصه. فقد يكون هذا الغرض، مثلًا، كوبًا زجاجيًا وملعقة. دعيه يتفحص الغرضين اللذين تضعينهما في كلتا يديه، وساعديه على اكتشاف كيفية إصدار الأصوات بهما. نحن واثقون من أن طفلكِ سيستمتع كثيرًا بهذا النشاط. لعبًا ممتعًا! 😊') WHERE id = 'e926ea15-a8f6-4559-a5e9-18bd81abc58e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل التقدم الكبير في نمو طفلكِ العقلي، أصبح الآن قادرًا على إخباركِ من خلال سلوكياته إن كان يريد تناول الطعام أم لا. من المهم جدًا أن تكوني دقيقة الملاحظة لهذه السلوكيات وأن تحاولي فهم طفلكِ. فعادةً ما يصبح متململًا أو منزعجًا وقد يبكي عندما يشعر بالجوع. وإذا اشتد جوعه وتأخر موعد إطعامه، ثم بكى أثناء الطعام أو أدار رأسه إلى الجهة الأخرى، فلا تصرّي عليه؛ انتظري قليلًا ثم حاولي مجددًا. في كثير من الأحيان، قد يبكي الأطفال في بداية الوجبة ويتصرفون كما لو كانوا لا يعرفون ماذا يفعلون بسبب شدة جوعهم. إذا واجهتِ هذا الموقف مع طفلكِ، فحافظي على هدوئكِ. فعلى الأرجح سيهدأ بعد تناول بضع لقمات بفضل تصرفكِ الهادئ. أما عندما يشبع طفلكِ أو لا يعود راغبًا في طعام معين، فسيدير وجهه ورأسه إلى الجهة الأخرى. عندها ننصحكِ بالتوقف عن إطعامه حتى لا ينفر من الطعام.') WHERE id = 'b20385d7-4579-4424-bf85-74e142637de4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن طفلكِ بدأ بالتعرف إلى الأطعمة التكميلية، لا تنسي أن المصدر الأساسي لغذائه في هذه المرحلة لا يزال حليبكِ أو الحليب الصناعي. وقد تحتاجين أيضًا إلى توخي الحذر بشأن عصائر الفاكهة التي تقدمينها لطفلكِ خلال هذه الفترة. فإذا بدأت أسنانه بالظهور، قد يتسبب الفركتوز الموجود في عصائر الفاكهة بتسوس الأسنان. لذلك ننصحكِ بتقديم هذه الأنواع من الأطعمة المحتوية على السكر بالملعقة، لا بزجاجة الرضاعة، وتحت إشرافكِ. ويمكنكِ أيضًا إطعام طفلكِ بالملعقة مهروس الطعام والأطعمة السائلة ذات القوام الحبيبي التي تحضرينها له، مع مراقبته أثناء الأكل. يمكنكِ الآن تقديم مهروس الفواكه مثل الموز والتفاح والخوخ، ومهروس الخضراوات مثل البطاطس والجزر والبروكلي، إلى جانب عصائد الحبوب والزبادي. والأهم من ذلك ألا تضيفي الملح أو السكر أو التوابل إلى هذه الأطعمة مطلقًا. بالهناء والشفاء! 😊') WHERE id = '6bf67fbd-887e-4592-8237-816fbe1d635c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ شديدة الحساسية تجاه النظافة، فقد تتعبين قليلًا مع طفلكِ الذي بدأ بتناول الأطعمة التكميلية. ففي هذه المرحلة، لا بد أن يوسخ الأطفال أنفسهم وما حولهم. وهذا أمر ينبغي السماح به حتى يتمكنوا من استكشاف العالم. تذكري أن المبالغة في الحرص على النظافة وردود فعلكِ السلبية تجاه الفوضى التي تحدث أثناء الطعام قد تشعر طفلكِ بالتوتر. بالطبع، لا مانع من اتخاذ تدابير بسيطة مثل استخدام مريلة الطعام، لكنه رغم ذلك سيتمكن من تلطيخ كل ما حوله. وفي المستقبل، عندما يبدأ بإمساك الكوب واستخدام الملعقة وتناول الطعام بأصابعه، ستزداد الفوضى من حوله. وبالنسبة إلى كثير من الأطفال، يُعد خلط الأطباق والملاعق والطعام معًا وإلقاؤها على الأرض لعبة ممتعة تحفز الشهية. لذلك ننصحكِ بألا تفرضي قيودًا كثيرة على طفلكِ، وأن تفرشي بساطًا أو غطاءً على الأرض لتسهيل التنظيف فحسب! 😊') WHERE id = 'f21f46f4-fb93-42c1-b00e-d167770d53ea';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'منذ ولادة طفلكِ وحتى بلوغه الشهر الثامن، يخزن في ذاكرته طويلة المدى كل كلمة تستخدمينها في حياتكِ اليومية. وتُسهم هذه الكلمات المحفوظة بدرجة كبيرة في تطور لغته، وبالتالي في نموه العقلي. ولجعل ذلك أكثر فاعلية، يمكنكِ التحدث كثيرًا مع طفلكِ واستخدام كلمات متنوعة لم يسمعها من قبل أثناء هذه الأحاديث. فعلى سبيل المثال، عندما تذهبان معًا إلى المتجر لشراء احتياجات المنزل، يمكنكِ أن تعرضي عليه المنتجات وتشرحيها له. ويمكنكِ تعريفه بكلمات جديدة من خلال الحديث عن لون الأشياء التي تعرضينها وشكلها وحجمها! وفي الأيام التي لا تتمكنين فيها من الخروج، يمكنكِ أن تقرئي له كتابكِ المفضل أو تدندني أغنية جديدة أو تروي له حكاية قصيرة. وهكذا ستطورين قدرة طفلكِ على الاستماع، وتستثمرين في مستقبله بينما تستمتعان معًا! 😊') WHERE id = '6715507c-2cf7-4220-9f23-3cb7294e08b4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم مدى حبكِ لطفلكِ وحرصكِ الشديد على صحته. ولكن مهما حرصتِ على تغذيته بطريقة صحية، فقد لا يتقبل جهازه المناعي جميع الأطعمة بسبب الحساسية الغذائية التي تزداد شيوعًا في أيامنا هذه. لذا عليكِ مراقبة طفلكِ بعناية من هذه الناحية، ولا سيما خلال مرحلة الأطعمة التكميلية حين يتعرف إلى أطعمة متنوعة. قد تظهر أعراض الحساسية فور تناول الطعام أو خلال 72 ساعة. وقد تتجلى الحساسية الغذائية لدى طفلكِ في صورة طفح جلدي، أو احمرار في منطقة الشرج، أو ازرقاق الشفتين، أو أزيز أثناء التنفس، أو مشكلات في الجهاز الهضمي. وقد يتفاعل الجهاز الهضمي عند تعرضه لطعام مسبب للحساسية بأعراض مثل القيء أو الإسهال أو البراز المصحوب بالدم أو الإمساك. لذلك ننصحكِ بتوخي الحذر عند تقديم أي طعام جديد لطفلكِ للمرة الأولى، والتواصل مع طبيبكِ فورًا إذا لاحظتِ أي أعراض غير طبيعية.') WHERE id = 'd5afcb47-37bb-45af-b1be-9bc9b6cc67d8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أنتِ في شهر تبلغ فيه رغبة طفلكِ في الاستكشاف وفضوله ذروتهما. ورغم أنه لا يزال متعلقًا بكِ، فقد بدأ الآن بتوسيع مساحة استقلاله. وقد ترين خلال هذا الشهر ثمرة محاولاته للحبو 😊 وأثناء هذه المحاولات، سيزداد إدراك طفلكِ أنه كيان مستقل. وإلى جانب الحبو، هناك تطور جديد آخر، وهو أنه أصبح أكثر قدرة على مد يده نحو الأشياء. ومع اتساع نطاق حركة طفلكِ، تزداد رغبته في الاستكشاف أيضًا. لكن تذكري أنه يمر حاليًا بالمرحلة الفموية، أي إنه سيرغب في وضع كل شيء يريد التعرف إليه في فمه. لذلك نود تذكيركِ باتخاذ تدابير السلامة اللازمة.') WHERE id = '79d6e9ac-e4be-4d51-9c67-149f74a4f03c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال بحثكِ عن الأطعمة التكميلية، لا بد أنكِ صادفتِ مفهوم BLW. تُعد هذه الطريقة، التي تُعرف باسم "Baby Led Weaning" أو اختصارًا BLW، من أكثر الموضوعات التي يبحث عنها الوالدان في السنوات الأخيرة. ويمكن ترجمة BLW إلى "الفطام الذي يقوده الطفل". يعتمد هذا النهج على مبدأ أن يُطعم الرضيع نفسه بنفسه. تناسب طريقة BLW الرضع القادرين على تثبيت رؤوسهم والجلوس دون دعم على كرسي الطعام ووضع الأطعمة المقدمة لهم في أفواههم بأيديهم. وهكذا يستطيع رضيعكِ تناول الطعام الذي يريده وبالكمية التي يرغب فيها دون الحاجة إلى المساعدة. وعلى الرغم من أن BLW طريقة حديثة نسبيًا، فإن الملاحظات تشير إلى أن لها تأثيرًا إيجابيًا في نمو الرضع.') WHERE id = '3224c721-5217-4489-ba14-724ab5302d3d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كم ينمو رضيعكِ بسرعة أمام عينيكِ، أليس كذلك؟ لا تتفاجئي إطلاقًا إذا رأيتِه يبدأ بالحبو! 😊 فرغم أن ذلك نادر، قد يبدأ بعض الرضع بالحبو في هذا الشهر. ولكن إذا لم تلاحظي ذلك بعد، فلا يعني هذا أن رضيعكِ متأخر، لذا لا تقلقي. لقد أصبحت عضلات ذراعيه وساقيه وظهره أقوى بكثير، وبفضل ذلك أوشك على إتقان الالتفاف حول نفسه تمامًا. كما يمكنه رفع رأسه فجأة عندما تضعينه على بطنه، والاستناد إلى يديه ليتقلب بسهولة. وقد لا يتمكن بعض الرضع في هذه الأشهر من الجلوس دون دعم بعد، وهذا أيضًا لا يعني أن رضيعكِ متأخر. فعادةً ما تكتمل القدرة على الجلوس دون دعم لدى الرضع في حدود الشهر الثامن.') WHERE id = '2f3bbf20-95fe-4b29-88f7-dede7edfcc73';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'وفقًا للدراسات، يتمكن الرضع الذين يغني لهم والداهم الأغاني والتهويدات كثيرًا من استيعاب إيقاع الكلام بصورة أفضل في الأشهر اللاحقة. ولأن رضيعكِ يتعلم كل شيء، بما في ذلك الكلام، عن طريق التقليد، فمن المهم جدًا أن تستخدمي الكلمات بطريقة صحيحة وفي سياقها المناسب. على سبيل المثال، في يوم بارد يمكنكِ أن تقولي إن الجو بارد وتتظاهري بأنكِ تشعرين بالبرد. بهذه الطريقة، يحفظ رضيعكِ الكلمة بصورة أدق ويتمكن من فهم العلاقة بين السبب والنتيجة بسهولة أكبر. ولكي تكوني قدوة جيدة لرضيعكِ، ينبغي ألا تتحدثي معه بلغة طفولية أو تحرّفي الكلمات، مهما بدا ذلك لطيفًا. دعيه يحفظ الكلمات التي يسمعها بوضوح وبطريقة مفهومة. ولجعل هذه العملية أكثر متعة، يمكنكِ تكرار الأصوات التي يصدرها رضيعكِ. سيستمتع بذلك كثيرًا، وستقضيان معًا وقتًا ممتعًا.') WHERE id = '015590a4-be89-40bd-9634-b5bb65d23d50';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيسهم تطبيق طريقة BLW (الفطام الذي يقوده الطفل) خلال مرحلة إدخال الأطعمة التكميلية إسهامًا كبيرًا في نمو رضيعكِ. ولهذه الطريقة بعض القواعد؛ إذ تعتمد أساسًا على أن يُطعم الرضيع نفسه بنفسه، لا أن تُطعمه الأم كما في الطريقة التقليدية. إذا كان رضيعكِ قد تناول حليب الأم أو الحليب الصناعي فقط خلال الأشهر الـ6 الأولى، فلا ينبغي أن تبدئي فورًا بتقديم الأطعمة التكميلية له 3 مرات يوميًا، ولا سيما في بداية المرحلة الانتقالية. كذلك، لا تحاولي إجباره على تناول هذه الأطعمة ولا تلحّي عليه إذا رفضها. ابدئي بمرة واحدة يوميًا ثم زيدي العدد تدريجيًا، وحضّري الأطعمة التي ستقدمينها له بشكل يتيح له إمساكها بسهولة بيده. وطوال هذه الفترة، يجب ألا تتركي رضيعكِ وحده مطلقًا، وأن تراقبي كل خطوة بعناية. تهدف هذه الطريقة إلى مساعدة الرضيع على اكتشاف النكهات بنفسه، وتطوير التناسق بين اليد والعين، وتعلّم تناول الطعام باستقلالية.') WHERE id = 'b805a548-3277-455e-8a43-b5228959fd35';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل تطور إدراك رضيعكِ، أصبح الآن قادرًا على إبلاغكِ بوضوح عندما يكون سعيدًا ومرتاحًا أو منزعجًا. وقد بدأ بالتعبير عن ذلك من خلال حركاته وتعبيرات وجهه. كما يواصل إصدار أصوات تدل على سعادته أو انزعاجه بهدف التواصل. إذا كان البكاء وسيلة التواصل الأساسية لرضيعكِ حتى الآن، فقد يبدأ مع تطور لغته بنطق بعض المقاطع غير المفهومة للتعبير عن نفسه. وبما أنه بدأ باستخدام حركات فمه بفاعلية أكبر استعدادًا للكلام، فإنه ينطق هذه المقاطع بوضوح أكبر. وتُعد قدرته على إصدار مقاطع صوتية مختلفة، حتى وإن كانت بلا معنى، مرحلة مهمة في تطوره. فهذه الأصوات هي بداية الحوارات الحقيقية بالنسبة إليه؛ إذ يجرّب الأصوات التي يصدرها، ويتفاعل مع الآخرين، ويبدأ ببناء علاقات اجتماعية.') WHERE id = '811dc858-78e1-4c23-aea6-584681b23792';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال مرحلة إدخال الأطعمة التكميلية، وخصوصًا في بدايتها، قد يكون اختناق رضيعكِ أحد أكبر مخاوفكِ. عندما يعيق شيءٌ تنفّسه، سيبذل رضيعكِ كل ما يستطيع للتخلص منه. إذا علِق الطعام الذي تناوله في حلقه، لكنه ما زال قادرًا على السعال والبكاء وإصدار الأصوات، فهذا يعني أن مجرى الهواء غير مسدود بالكامل. وعلى الأرجح سيتمكن رضيعكِ من التعامل مع الموقف بنفسه. وأفضل ما يمكنكِ فعله في هذه الحالة هو الحفاظ على هدوئكِ وطمأنته. ولكن إذا ظهرت على رضيعكِ علامات اختناق أكثر خطورة، فاتصلي بخدمات الطوارئ المحلية وابدئي فورًا بتقديم الإسعافات الأولية المناسبة لفتح مجرى الهواء. لذلك، من المهم جدًا أن تتعلمي قواعد الإسعافات الأولية للرضع من مصادر موثوقة.') WHERE id = '880904da-8e52-4e39-93ed-5f35ec843a62';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يتضمن جدول تطعيم طفلكِ أي لقاح خلال هذا الشهر. ومع ذلك، سيقيس الطبيب وزنه وطوله ومحيط رأسه خلال الفحوصات الروتينية. اعتبارًا من الشهر 7، يتراوح وزن الطفل عادةً بين 5900 غرام و9000 غرام. أما متوسط وزن الأطفال بعمر 7 أشهر فهو 8100 غرام. لكن عليكِ أن تتذكري أن هذا المتوسط قد يكون أقل، لا سيما لدى الأطفال المولودين قبل أوانهم. خلال هذا الشهر، يتراوح طول طفلكِ بين 61 سم و75 سم، ويبلغ المتوسط نحو 67 سم. أما محيط الرأس، الذي يوفر معلومات عامة عن نمو دماغ طفلكِ، فيتراوح هذا الشهر بين 42.8 سم و44 سم. إذا كنتِ تعتقدين أن نمو طفلكِ الجسدي لا يقع ضمن هذه القيم، فيمكنكِ استشارة طبيبكِ للحصول على أدق المعلومات.') WHERE id = '7ae42d6a-0c42-4144-b394-cfd8c4804b24';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تبدأ آلية الشعور بالجوع والشبع لدى طفلكِ بالعمل منذ لحظة ولادته، وسيحرص حتمًا على إبلاغكِ بذلك بطريقة ما. لذا، ينبغي ألا تجبريه على تناول الطعام أو تشعري بالذعر عندما يرفضه. رغم أن طفلكِ بدأ منذ مدة بتناول الأغذية التكميلية، فقد يظل بحاجة إلى بعض الوقت للتكيف معها تمامًا. فبعد اعتياده على حليب الأم أو الحليب الصناعي منذ ولادته، قد لا يتقبل الأطعمة الصلبة والنكهات المختلفة على الفور. إذا كنتِ تعتقدين أن وزن طفلكِ منخفض أو أنه لا يتغذى بما يكفي، فلا ينبغي أن تكثري من تقديم أطعمة مرتفعة السعرات الحرارية وعديمة الفائدة لمجرد زيادة وزنه. فنمو طفلكِ لا يُحدد فقط وفق كمية السعرات الحرارية التي يتناولها أو وزنه. لذلك، قدّمي له أطعمة صحية مرتفعة القيمة الغذائية بدلًا من الأطعمة التي تحتوي على سعرات حرارية فارغة.') WHERE id = 'c7406d7d-33c9-4160-91a7-a354953cf5b3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح جلوس طفلكِ بمفرده ومن دون دعم أسهل بكثير خلال هذه الفترة. وسيبدو لطيفًا جدًا في عينيكِ عندما يبدأ بالجلوس واللعب بألعابه بصورة مستقلة من دون الحاجة إلى دعمكِ. تُعد هذه الفترة مرحلة نمائية مهمة لطفلكِ الذي اكتشف الجلوس وأصبح قادرًا عليه بحرية، إذ يكتسب خلالها منظورًا جديدًا وقدرًا من الاستقلالية. وبفضل ذلك، ستُفتح أمامه أبواب اكتشافات جديدة، وسيبدأ برؤية ما حوله من زاوية مختلفة. بعد أن أصبحت عضلات ظهر طفلكِ ورقبته أقوى، بات قادرًا على التحكم برأسه وساقيه بدرجة كافية. وهذا سيسهّل عليه مستقبلًا أنشطة مثل الحبو والوقوف والمشي. لكن لا تقلقي إذا رأيتِ أنه لا يستطيع البقاء منتصبًا مدة طويلة وأنه يقع أحيانًا. 😊') WHERE id = 'c06b62a5-8d7b-4555-9d57-8340da61ad39';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بحلول هذا الشهر، يكون طفلكِ قد أكمل شهره الأول في مرحلة تناول الأغذية التكميلية. وفي نهاية هذه التجربة التي استمرت شهرًا، ربما يكون قد اكتسب مهارات مثل المضغ والبلع ووضع الطعام الذي يمسكه في فمه وإطعام نفسه. إذا لم تتقدم هذه المرحلة كما تخيلتِ، فلا تقلقي فورًا. فلا توجد قاعدة تنص على أن جميع الأطفال سيمرون بهذه العملية بسهولة. واعلمي أن هناك كثيرًا من الأمهات اللواتي يشعرن مثلكِ. إذا كنتِ تعتقدين أن طفلكِ لا يُقبل على الأغذية التكميلية بشهية، فيمكنكِ ممارسة بعض الألعاب معه لتشجيعه على تناول الطعام بحماس أكبر وبناء علاقة جيدة معه. فعلى سبيل المثال، يمكنكِ لعب لعبة «ها هي الطائرة قادمة» أو إطعامه مع الأغاني. ومن أهم القواعد الذهبية في هذا الصدد: عندما يرغب طفلكِ في التوقف، عليكِ التوقف أيضًا وأخذ استراحة لبعض الوقت.') WHERE id = 'ca27271b-d34b-4ce7-b5f9-f4505e118771';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'سيشهد هذا الشهر تطورًا ملحوظًا في تفاعل طفلكِ الاجتماعي. لذلك، سيبدأ بمراقبة أفراد العائلة الذين يتواصل معهم باهتمام. وبفضل المعلومات التي خزّنها في ذاكرته حتى هذه المرحلة، يتعلم طفلكِ الربط بين السبب والنتيجة. فلا تتفاجئي إذا حاول تقليد حركات الذراعين والساقين وحتى تعابير الوجه! 😊 وبالطبع، يحمّلكِ ذلك مسؤولية أيضًا، وهي أن تكوني قدوة حسنة! ففضول طفلكِ قوي جدًا، وهو يبذل جهدًا كبيرًا لاكتشاف كل شيء. يمكنكِ وضع حدود في المواقف التي قد تسبب له الأذى، لكن ينبغي ألا تبالغي في ذلك. فعلى سبيل المثال، إذا لفت انتباه طفلكِ جسم صغير يمكنه ابتلاعه وأمسكه ليتفحصه، فعليكِ مراقبته عن كثب والتدخل فقط عند الضرورة الفعلية، بدلًا من انتزاعه من يده فورًا أو إبداء رد فعل قاسٍ.') WHERE id = '84211613-fc78-4c1f-a816-22b155e0b89d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لأن الشهر 7 لا يزال فترة تستمر فيها تجربة الأطعمة، فإن طفلكِ ما زال في مرحلة الانتقال إلى الأغذية التكميلية. وهذه المرحلة بالغة الأهمية والحرجة، إذ ستؤثر في عاداته الغذائية خلال السنوات المقبلة، بل وحتى في مرحلة البلوغ. قد يرفض طفلكِ أحيانًا طعامًا يجربه للمرة الأولى. وهذا لا يعني أنه لن يحبه أبدًا. عندما تواجهين موقفًا كهذا، ضعي ذلك الطعام جانبًا وقدّميه له مجددًا بعد بضعة أيام. وقد يفيد أيضًا تغيير طريقة تقديمه أو طهوه، حتى في اليوم نفسه. خلال هذه الفترة، يستطيع طفلكِ سحق الأطعمة ذات القوام المتكتل بلثته وتناولها، حتى لو لم تكن أسنانه قد ظهرت بعد. لذلك، لا تترددي في إدراج هذه الأطعمة ضمن قائمته الغذائية. كما أن تناولها سيساعد على تطوير عضلات الفم واللسان، ما يفيد طفلكِ أيضًا في تعلم الكلام.') WHERE id = 'b07bfb17-d3e7-4626-8576-6365ec3ad72a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما صادفتِ خلال بحثكِ عن عملية إدخال الأطعمة التكميلية ما يُعرف بـ"قاعدة الأيام الثلاثة". تُعد قاعدة الأيام الثلاثة مهمة للغاية لتحديد احتمال ظهور رد فعل تحسسي لدى طفلكِ تجاه الأطعمة عند بدء التغذية التكميلية. وبفضلها، إذا ظهرت على طفلكِ أي حساسية، يمكنكِ بسهولة معرفة الطعام الذي تسبب بها. ومن خلال تطبيق هذه القاعدة، يمكنكِ مراقبة طفلكِ لمدة 3 أيام لمعرفة ما إذا كان الطعام الذي قدمتِه له قد سبب أي تأثير سلبي. كذلك، بما أنكِ ستقدمين له نوعًا واحدًا فقط من الطعام، فسيكون من السهل معرفة ما إذا كان يحبه أم لا. وقد تظهر ردود الفعل التحسسية بعد تناول الطعام التكميلي على شكل احمرار أو طفح جلدي. كما قد تشمل علامات الحساسية المحتملة المغص والغازات وما يصاحبهما من بكاء، والقيء، والإسهال، والانزعاج، وآلام المعدة.') WHERE id = 'e67b6585-697c-442b-94c4-f4bcc520b28d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لم يعد طفلكِ يحب البقاء ساكنًا، ولذلك من الطبيعي تمامًا أن يكون دائم الحركة! 😊 في هذه المرحلة، تستمر يدا طفلكِ وقدماه في جذب انتباهه. فقد يتفحص يديه وأصابعه واحدة تلو الأخرى، ويستمتع باكتشاف ما يمكنه فعله بها. أما رفع قدميه في الهواء ومحاولة الإمساك بهما بيديه، فهو من أنشطته المفضلة. لذا يمكنكِ شراء جوارب ملونة تُصدر أصواتًا لجعل هذه اللعبة أكثر متعة. سيحاول طفلكِ الوصول إلى الجوارب المرحة في قدميه، وسيستمتع باللعب بها لبعض الوقت. ولا تنسي أيضًا إلباس صغيركِ المحب للحركة ملابس فضفاضة ومريحة! 😊') WHERE id = '6e15d298-df96-4ac7-b6a2-ef5c565ec39c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كشفت الدراسات المفصلة التي أُجريت في السنوات الأخيرة حول صحة الأمعاء عن أهمية مفهوم البروبيوتيك. ونظرًا إلى أن الأمعاء أصبحت تُسمى الدماغ الثاني لما لها من تأثير في الجسم بأكمله، فإن صحتها مهمة لنمو طفلكِ السليم. تساعد البروبيوتيك على الحفاظ على توازن البكتيريا النافعة في الأمعاء، وتمنع تكاثر الكائنات الحية الدقيقة الضارة. وإلى جانب حليب الأم، تسهم البروبيوتيك في تكوين الجهاز المناعي والحفاظ على الاتزان الداخلي لطفلكِ، المعروف بالاستتباب. كما تعزز امتصاص بعض المعادن والفيتامينات، وتنظم مستويات الدهون ونفاذية الأمعاء. وللاستفادة من هذه الفوائد، يُنصح بتناول منتجات البروبيوتيك بانتظام وبكميات مناسبة. وخلال مرحلة التغذية التكميلية، يُعد تناول طفلكِ بانتظام أطعمة غنية بالبروبيوتيك، مثل الزبادي والكفير وشوربة الطرخانة، أمرًا مهمًا جدًا لصحة أمعائه.') WHERE id = '092895c9-69ca-40db-8ca1-d44efd327a7d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ البالغ من العمر 6 أشهر يستجيب للتغيرات في نبرة الصوت، كما أن كل ما يُصدر صوتًا يجذب انتباهه كثيرًا! وقد تطور طفلكِ ذهنيًا وأصبح أكثر قدرة على ملاحظة تعابير الوجه ومحاولة فهم معناها. وهذا يعني أنه قد يستجيب الآن عندما تقولين له "لا". فمن خلال تعابير وجهكِ، يمكنه أن يدرك أن كلمة "لا" تحمل معنى سلبيًا. ولكن إذا أكثرتِ من قول "لا" لطفلكِ، فقد يبدأ في إدراك العالم على أنه مكان سلبي. وقد نسمعكِ تقولين عند هذه النقطة: "لا يزال صغيرًا جدًا ولن يفهم". لكن هذه حقيقة مثبتة علميًا. فعلى الرغم من أن طفلكِ لا يستطيع بعد فهم كل ما يسمعه ويراه ويشعر به فهمًا كاملًا، فإن دماغه يسجل هذه الأشياء ليستفيد منها لاحقًا. لذلك، فإن تقييد طفلكِ باستمرار وتعويده على سماع كلمة "لا" قد يجعله عندما يكبر شخصًا سلبيًا ومترددًا في تولي دور قيادي.') WHERE id = '2d11a5b6-a9e7-427f-af80-602cab8874a2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يرفض طفلكِ، الذي اعتاد منذ ولادته وحتى هذا الشهر على تناول الحليب فقط، الأطعمة الصلبة في هذه المرحلة التي يبدأ فيها الانتقال إلى التغذية التكميلية. لذلك، لا ينبغي أن تكسبيه عادات خاطئة، مثل إجلاسه أمام التلفاز لتشتيت انتباهه أثناء إطعامه. يجب أن تكون بداية التغذية التكميلية مرحلة تمنحين فيها طفلكِ الوقت وتتعاملين معه بتفهّم. فعلى سبيل المثال، يساعد ذكر أسماء الأطعمة وألوانها أثناء إطعامه على تنمية إدراكه ويشجعه على تناول الطعام بحماس أكبر. ويكفي أن تتحلي ببعض الإبداع حتى يحب طفلكِ تناول الطعام. فالأشكال التي تصنعينها بالطعام ستجذب اهتمامه وتساعدكما على قضاء وقت ممتع ومفيد. وبما أنكما في مرحلة استكشاف النكهات، فمن المهم تقديم الأطعمة المختلفة في أوعية منفصلة حتى يتمكن طفلكِ من تمييز مذاق كل منها. كما سيكون استخدام أطباق وشوك وملاعق غير قابلة للكسر أكثر أمانًا خلال هذه الفترة.') WHERE id = 'b5fa9ff8-3ed0-4d85-920b-ca982ac76fc8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نعلم أن طفلكِ قد يضعكِ أحيانًا أمام تحديات كبيرة. وهذا طبيعي، خاصة إذا أخذنا في الاعتبار أنه يمر بمرحلة يكون فيها كثير الحركة ويرغب دائمًا في اكتشاف أشياء جديدة. ولكن مهما كان الأمر صعبًا، لا تنسي أنه لا يزال رضيعًا لديه مشاعر ويعتمد عليكِ اعتمادًا كاملًا. وكجميع الكائنات الحية، يمتلك طفلكِ قدرة محدودة على التعامل مع التوتر بطريقة معينة ولفترة معينة. فعلى سبيل المثال، عندما تتسخ حفاضته أو يشعر بالجوع، يتعامل جسمه تلقائيًا مع ذلك باعتباره تهديدًا. يبدأ طفلكِ أولًا بالحركة والشعور بالانزعاج، وإذا لم تُلبَّ حاجته، يفرز جسمه هرمون الكورتيزول. وتؤدي آلية التوتر هذه إلى ارتفاع ضغط الدم وزيادة سرعة تدفقه في جسم طفلكِ. وفي هذه الأشهر التي يمر فيها طفلكِ بمرحلة نمو كبيرة، قد يؤدي الإفراط في إفراز هرمون الكورتيزول، بمرور الوقت، إلى شعوره بالإرهاق والانطواء والانسحاب.') WHERE id = '79821ac2-93ff-4cf4-a7f8-8aab07a2bcca';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكون أعضاء الحس لدى طفلكِ مع دخوله شهره السابع قد تطورت تقريبًا إلى مستوى مماثل لما لدى الشخص البالغ. ومن هذه الناحية، يمكن القول إن قدرته على الإبصار قد اكتملت بالفعل. وبفضل ذلك، يستطيع رؤية الأشخاص والأشياء البعيدة بوضوح وتمييزها، كما يمكنه متابعة الأحداث السريعة والمعقدة التي تجري من حوله وإدراكها بدقة. ولأن إدراكه للعمق قد ترسخ تمامًا، يمكنه تتبّع جسم يقترب منه من بعيد والاندفاع إلى الأمام للإمساك به. كذلك أصبحت حاسة السمع لدى طفلكِ في عمر 7 أشهر متطورة بقدر حاسة البصر. فهو الآن يدرك فورًا مصدر الصوت ويتجه نحوه مباشرة. ومع ذلك، قد يظل هادئًا من دون إبداء أي رد فعل لبعض الوقت كي ينصت إلى الأصوات الخافتة والبعيدة.') WHERE id = 'e80c4140-2676-446b-a5dc-f1e0f240ee47';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من أكثر الأخطاء شيوعًا عند بدء إدخال الأطعمة التكميلية تقديم أطعمة سائلة، مثل الحساء، للرضيع في كل وجبة تقريبًا. ولا شك في أن فوائد الحساء المُعدّ بمرق العظام كثيرة، لكن ينبغي ألّا تجعلي الحساء المكوّن الأساسي في تغذية طفلكِ. فتأخير تقديم الأطعمة ذات القوام المتكتل التي تساعد طفلكِ على المضغ أكثر من اللازم قد يؤدي إلى بعض الآثار السلبية؛ لأن هذا النوع من الطعام لا يساعد على تنظيم عادات الأكل لدى طفلكِ فحسب، بل يُنمّي أيضًا عضلات الفم واللسان. لذلك، من الضروري ألّا تطيلي مدة الاعتماد على نظام غذائي يتكوّن من أطعمة مخفوقة بالخلاط ومهروسة تمامًا. وإلا فقد يصعب الانتقال إلى الأطعمة الصلبة خلال مرحلة التسنين، وقد يرفض طفلكِ تناول الأطعمة ذات القطع الصغيرة لأنه غير معتاد عليها.') WHERE id = '0eb37995-3090-4435-b8b9-edf48f0b68fb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لم يعد طفلكِ يستخدم أصوات حروف العلة أو الحروف الساكنة منفردة كما كان يفعل في الأشهر السابقة. ففي شهره السابع، أصبح يجمع بين أصوات حروف العلة والحروف الساكنة ليكوّن مقاطع صوتية، ويمكنه إصدار أصوات مثل babababa وmamamama وkakakaka. وهناك بعض الأنشطة التي يمكنكِ القيام بها لتعزيز هذا التطور اللغوي وتشجيعه. فمثلًا، يمكنكِ تقليد الأصوات التي يصدرها طفلكِ عندما يكون في مزاج جيد. يراقب طفلكِ طريقة كلامكِ بعناية عندما ينظر إليكِ ويحاول تقليدكِ. ومن المهم أن تبالغي قليلًا في حركات النطق حتى يتمكن من ملاحظة حركة لسانكِ وشفتيكِ وحنككِ أثناء إصدار الأصوات. لذا، أجّلي أعمالكِ لساعة أو ساعتين واستعدّي لقضاء وقت ممتع مع طفلكِ! استمتعا بوقتكما 😊') WHERE id = '50599786-43fc-4007-9b26-bc49949f135e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن بتناول الأطعمة التكميلية إلى جانب حليب الأم أو الحليب الصناعي، ولذلك قد تعتقدين أنه ينبغي أن يكتسب وزنًا أكبر. لكن الأمر ليس كذلك تمامًا؛ فقد أصبح طفلكِ كثير الحركة، وعلى الرغم من استمرار نموه، لا يُتوقع أن يزداد وزنه بالمقدار نفسه الذي كان يزداد به خلال الأشهر الأولى. سيكتسب طفلكِ هذا الشهر ما معدله 350-400 غرامًا. وهذه الأرقام مجرد مؤشرات متوسطة لمتابعة نموه. تذكّري أن كل طفل ينمو بطريقة مختلفة، وأن العوامل الوراثية والجنس ومعدل الأيض قد تُحدث فروقًا. أما القاعدة العامة المتعارف عليها فهي أنه يُتوقع أن يصبح وزن طفلكِ عند بلوغه 5 أشهر ضعف وزنه عند الولادة، وأن يصبح عند بلوغه 12 شهرًا ثلاثة أضعاف وزن الولادة.') WHERE id = '0bf43d37-a329-4f54-80f4-b9fdb2e13965';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد عرّفتِ طفلكِ حتى الآن إلى العديد من النكهات الجديدة، لكن قد تراودكِ أسئلة عن سبب عدم جواز تقديم بعض الأطعمة له بعد. ويرتبط ذلك كليًا بمدى تطور جهازه الهضمي واستعداد أمعائه. ومن الأمور التي يتساءل عنها كثير من الوالدين، مثلًا، سبب أهمية تجنب إدخال حليب البقر إلى نظام الرضيع الغذائي. فعلى الرغم من غنى حليب البقر بالفيتامينات والمعادن، فإنه يضع عبئًا زائدًا على كليتي طفلكِ اللتين لم يكتمل نموهما بعد ويُجهدهما. كذلك، لا يستطيع حليب البقر تلبية احتياجات جسم طفلكِ من الفيتامينات بصورة كاملة، ما قد يؤدي إلى تأخر التطور وتباطؤ النمو. إضافةً إلى ذلك، يحتوي حليب البقر على كميات قليلة من اليود والزنك، ما قد يؤثر سلبًا في نمو طفلكِ الذهني. ولهذه الأسباب جميعها، يُفضل البدء بإدخال حليب البقر تدريجيًا إلى نظام طفلكِ الغذائي بعد إتمامه 12 شهرًا.') WHERE id = 'e49d6509-b260-4b7c-8420-cc63289843b1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد قطع طفلكِ شوطًا كبيرًا في نموه خلال وقت قصير، وسيواصل إدهاشكِ! 😊 لكن، للأسف، قد لا تُسعدكِ هذه التغيرات كلها دائمًا. فقد تلاحظين، مثلًا، أن طفلكِ لم يعد يرغب في الابتعاد عنكِ وأنه يُبدي رد فعل شديدًا عند انفصاله عنكِ. وقد يكون هذا الأمر مقلقًا لكِ، لكنه يشير إلى بدء ظهور قلق الانفصال لدى طفلكِ. وعلى الرغم من أنه قد لا يبدو مشكلة لبعض الأمهات، فقد يسبب صعوبات في المستقبل إذا لم تُتخذ التدابير المناسبة. وقد يؤدي ذلك، مع مرور الوقت، إلى شعوره بالتعاسة وعدم الأمان عندما لا تكونين بجانبه. وللوقاية من ذلك، استعيني بأفراد أسرتكِ في رعاية طفلكِ وساعديه على الاعتياد على هذا الوضع. فمثلًا، دعي زوجكِ يقدّم لطفلكِ وجبة العشاء اليوم بدلًا منكِ، ثم يقضي معه بعض الوقت على انفراد بعد الوجبة.') WHERE id = 'ee5d1f29-7924-4191-bd02-dbcf16926418';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان عليكِ العودة إلى العمل، فقد تراودكِ بعض المخاوف بشأن الحالة النفسية لطفلكِ ورعايته. عادةً ما يبدأ قلق الانفصال لدى الأطفال في الشهر 6 ويبلغ ذروته في الشهر 12. لا ينبغي أن تشعري بالسوء حيال ذلك، فهو جزء طبيعي من نمو طفلكِ. عندما يقترب موعد عودتكِ إلى العمل، قد يكون من المفيد إجراء تدريبات قصيرة على الانفصال. حتى إن لم يدرك طفلكِ أنكِ ستغادرين، ودّعيه بطريقة لطيفة ومرحة وأخبريه بأنكِ ستعودين. خلال هذه التدريبات، يمكنكِ ترك طفلكِ مع شخص مقرّب يعرفه كل منكما، حتى لا يشعر بالغربة. كما أن قضاء بعض الوقت مسبقًا برفقة الشخص الذي ستعهدين إليه برعاية طفلكِ سيُسهّل هذه العملية كثيرًا.') WHERE id = '99e99257-b0ed-4e0f-b789-5eb260e3fd9d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد تناول الطعام من أهم الاحتياجات الجسدية لطفلكِ. لذا فإن التغذية السليمة والكافية شرط أساسي لنموه الصحي وتجنّب تأخر تطوره. لكن طفلكِ قد لا يتقبّل تناول الطعام دائمًا دون اعتراض. وقد ينتهي أحيانًا الطعام الصحي الذي أعددتِه له بحماس في سلة المهملات من دون أن يلمسه. أول ما ينبغي لكِ فعله في هذه الحالة هو تجنّب الدخول في صراع معه. فإذا عاندتِه، فقد تنفّرينه أكثر من تناول الطعام، مع أنه حاجة طبيعية وفسيولوجية. وقد يؤدي ذلك أيضًا إلى توتر العلاقة بينكِ وبين طفلكِ. لذلك تحلّي بالصبر واستشيري طبيبكِ بشأن ما يمكنكِ فعله عند الحاجة.') WHERE id = '2f28f952-bd75-47db-822c-9ba614e24ba2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد توقيت جلوس طفلكِ إلى مائدة الطعام عاملًا مهمًا في مرحلة اكتسابه عادات التغذية وآداب المائدة. ويرى المختصون أنه ينبغي للأطفال الجلوس إلى المائدة مع والديهم في موعد أقصاه الشهر 9. لذلك، عندما يحين وقت الطعام، وخصوصًا إذا كانت الأسرة تجتمع حول المائدة، يمكنكِ إشراك طفلكِ أيضًا. ويُعد تخصيص كرسي طعام له إلى جانب المائدة خيارًا مثاليًا. فجلوس طفلكِ في كرسي الطعام ومشاهدته لكِ ولأفراد الأسرة الآخرين أثناء تناولكم الطعام سيكون تجربة تعليمية مفيدة جدًا له. ووفقًا للمختصين، تُعد الملاحظة والمحاكاة من أهم وسائل تعلّم الأطفال. كما أن عدم تشغيل التلفاز في أثناء تناول الطعام وتهيئة أجواء ممتعة حول المائدة سيشجعان طفلكِ أكثر على تناول الطعام.') WHERE id = '2c9b0188-9d07-406a-bc48-6a8ce20aef72';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تبدأ سجادة اللعب التي أحبها طفلكِ كثيرًا خلال الأشهر الأولى بعد ولادته في إثارة ملله، بعدما أصبح صغيركِ يتطلع إلى تجاوز حدودها. فالطفل الذي بدأ يتحرك بنشاط وأصبح اكتشاف الأشياء الجديدة نشاطه المفضل، يجد التقييد أمرًا مزعجًا للغاية. لذلك قد لا يرغب في البقاء على سجادة اللعب عندما تضعينه عليها، وقد يعترض! في هذه المرحلة، اعتبري رفع صوته مطالبًا بحرية الحركة أمرًا طبيعيًا، وأتيحي له حرية التعبير عن اعتراضه. يمكنكِ جعل إحدى غرف منزلكِ، أو المنزل بأكمله إن أمكن، مكانًا آمنًا لا يعرّضه للأذى. لكن حتى لو كانت البيئة التي أعددتِها آمنة، فعليكِ أن تبقي متيقظة وتراقبيه باستمرار. وإذا كنتِ تجدين صعوبة في إنجاز مهامكِ مع طفلكِ كثير الحركة، فيمكنكِ إنجاز بعضها في أثناء نومه أو عندما يتولى شخص آخر رعايته.') WHERE id = '45a8e0d6-4932-4235-9823-06f0b7e8f85a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد الشهر 7 من الأشهر التي تتطور فيها قدرات طفلكِ الحركية الجديدة بدرجة ملحوظة. لذلك عليكِ الانتباه خصوصًا إلى الأشياء الخطرة في المنزل، لأن صغيركِ متحمس جدًا للاستكشاف. ويمكنكِ تغطية مقابس الكهرباء التي قد تشكل خطرًا على طفلكِ، فهو يرغب في تفحّص كل ما يلفت انتباهه. كذلك احرصي على عدم ترك الأرضيات مبللة، وأزيلي تمامًا المخاطر مثل الأسلاك الكهربائية والأدوات الحادة التي قد تسبب له أذى شديدًا. ويمكنكِ استخدام واقيات مناسبة السعر للزوايا الحادة في الأثاث وحواف النوافذ. وإذا وُجد في منزلكِ درج يستطيع طفلكِ الوصول إليه، فعليكِ تركيب بوابات أمان عند مدخله ومخرجه. والهدف من اتخاذ جميع هذه التدابير هو تمكين طفلكِ من الاستكشاف بحرية ضمن الحدود الآمنة التي تحددينها.') WHERE id = '616cd1ae-8a43-46fd-8952-aef7ae090d0b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال مرحلة إدخال الأطعمة التكميلية، قد ترغبين في تقديم الأطعمة الأعلى قيمة غذائية لطفلكِ من أجل نموه وصحته. لكن بعض الأطعمة المفيدة لكِ قد تضر طفلكِ أكثر مما تنفعه. لذلك التزمي بالخطة التي وضعتِها مع طبيبكِ، وراعي مستوى تطور جهاز طفلكِ الهضمي. فمثلًا، من منا لا يفكر في إضافة قليل من الملح إلى البطاطس المهروسة ظنًا منه أنها ستكون بلا مذاق؟ لكن المختصين يشددون بشدة على عدم تقديم الملح للأطفال حتى يبلغوا عمر 1 سنة. ففي هذه المرحلة، تكفي طفلكِ الأملاح الموجودة طبيعيًا في الخضراوات. وقد تؤثر زيادة كمية الملح الداخلة إلى جسمه سلبًا في وظائف كليتيه. فانتبهي جيدًا!') WHERE id = '6b656aed-9031-4b22-b6b9-5ed9b49d2799';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ قادرًا على تعلّم ألعاب جديدة وبسيطة تناسب مستوى نموه بسهولة. لذا لن نكون مخطئين إذا قلنا إنكِ دخلتِ رسميًا مرحلة اللعب. نتمنى لكِ السهولة من الآن فصاعدًا! 😊 ولتطوير هذه المهارة لدى طفلكِ، يمكنكِ اللعب معه كثيرًا. سيراقبكِ باهتمام ويستمع إليكِ بانتباه. كما أن طفلكِ، الذي تطورت مهاراته اليدوية كثيرًا، يستطيع الآن التقاط اللعبة التي يجدها على الأرض عن قصد واللعب بها بسهولة. ولأنه أصبح يشعر باستقلالية أكبر مقارنةً بالأشهر الأولى، فإنه يبحث عن الألعاب التي أضاعها أو أسقطها، ويستطيع التقاطها بنفسه بدلًا من طلبها منكِ. وقد يهز الألعاب والأشياء التي يجدها من حوله أو يضربها أو يرميها ليتحقق مما إذا كانت تُصدر صوتًا. بل إذا لم يكن قد انتهى من اللعب بها، فلن يسمح لكِ بأخذها من يده وسيعترض.') WHERE id = 'fe525d42-0a0a-48cc-aa11-ecad88d56b2a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون لديكِ أسئلة حول الوقت المناسب لبدء استخدام كوب التدريب لطفلكِ. ولا يمكنكِ معرفة أن الوقت المناسب قد حان إلا من خلال مراقبته. إذا اختفى لدى طفلكِ منعكس دفع الأشياء باللسان، فهذا يعني أنه أصبح مستعدًا لاستخدام كوب التدريب. ويعني هذا المنعكس أن الرضيع، خلال الأشهر الأولى، يدفع تلقائيًا بلسانه أي جسم غريب يدخل فمه إلى الخارج. في الواقع، لهذا المنعكس أهمية حيوية لطفلكِ، إذ يحميه من خطر الاختناق. ويبدأ هذا المنعكس في التراجع عادةً اعتبارًا من الشهر 4، ثم يختفي تمامًا بين الشهرين 6 و8. كما أن اختفاءه يُعد أول علامة على استعداد طفلكِ لشرب الماء من الكوب بدلًا من الرضّاعة.') WHERE id = '52c260d9-9803-4e1b-9fc5-0c188ff2d7d3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يبلغ متوسط وزن الأطفال في عمر 8 أشهر نحو 8000 غرام. ومع ذلك، قد يتراوح وزن الطفل بين 6300 و11000 غرام. لكن زيادة الوزن قد تتباطأ خلال هذا الشهر تحديدًا بسبب ازدياد نشاطه، وقد تُظهر الميزان في نهاية الشهر زيادة تتراوح في المتوسط بين 250 و650 غرامًا. إذا وُلد طفلكِ قبل موعده، فقد يلحق بأقرانه، وإن لم يكن قد لحق بهم بعد فلا تقلقي، فما زال الوقت مبكرًا. ويرتبط هذا النطاق الواسع للوزن أيضًا بالفروق بين الإناث والذكور في نمو الطول والوزن. يجب ألا تتخذي أي إجراء بشأن زيادة وزن طفلكِ أو تباطئها من دون علم الطبيب. وتذكّري أن نمو كل طفل يختلف عن غيره؛ فحتى الأطفال الذين تقع قياساتهم عند الحد الأدنى أو الأعلى قد يكونون أصحاء تمامًا.') WHERE id = '639ac35e-714a-47fc-b5c3-a25af9dcd029';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد اعتاد طفلكِ إلى حد كبير على مرحلة إدخال الأطعمة التكميلية التي بدأتِها منذ مدة، لكنه لا يزال يتناول حليب الأم أو الحليب الصناعي. وقد يكون من المرهق، خصوصًا خلال هذه الفترة، حساب كمية الطعام التكميلي التي ينبغي لطفلكِ تناولها أو كمية الحليب التي ينبغي له شربها. لكن يجب ألا تنسي أن حليبكِ أو الحليب الصناعي سيظل غذاءه الأساسي لبعض الوقت. واعتبارًا من هذا الشهر، يحتاج طفلكِ إلى نحو 850 سعرة حرارية يوميًا في المتوسط، مع اختلاف ذلك بحسب مستوى نشاطه وسرعة الأيض لديه. وللحفاظ على صحة أمعائه، ينبغي أن يحصل على أكثر من نصف هذه السعرات الحرارية من الحليب. وللحفاظ على هذا التوازن وتجنّب الارتباك، أرضعي طفلكِ أو قدّمي له الحليب أولًا عندما يجوع. ثم حضّري له وجبة متوازنة من حيث القيمة الغذائية وبحصة ليست كبيرة جدًا. ويمكنكِ في هذه المرحلة زيادة الحصة وفقًا لاحتياجات طفلكِ.') WHERE id = 'aaf40c8d-b2ab-4458-8b62-ca1e766f4975';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ بدأ بتناول الأطعمة التكميلية منذ نحو شهرين، فإن حليب الأم يظل غذاءه الأساسي حتى عمر سنتين. أما الأطعمة التكميلية التي تقدمينها له، فهي تحل فقط محل الوجبات الخفيفة. لذلك، قد يؤدي تقليل الرضاعة إلى إبطاء نمو طفلكِ. وإذا كنتِ تعتقدين أن شهية طفلكِ ضعيفة هذه الأيام، فنود تذكيركِ بأنكِ لستِ وحدكِ. 😊 فبعد دخوله مرحلة اللعب النشط، قد لا يرغب طفلكِ في تخصيص وقت طويل لاحتياجاته مثل الطعام والنوم. لذلك يمكنكِ الجمع بين نشاطه المفضل، وهو اللعب، ووقت تناول الطعام! ولجعل الطعام ممتعًا، يمكنكِ إعداد أطباق جذابة له وممارسة ألعاب مثل الغميضة أو لعبة «الطائرة قادمة» أثناء إطعامه. كما يمكنكِ الاستعانة بدمى الأصابع. نتمنى لكما وقتًا ممتعًا! 😊') WHERE id = 'd21c1f6a-5fc9-4cad-8563-f3edc47a4f56';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اعتبارًا من هذا الشهر، يبلغ الحد الأدنى لمحيط رأس طفلكِ 41 سم، بينما يبلغ الحد الأعلى 47 سم. ويبلغ متوسط محيط رأس الطفل في عمر 8 أشهر نحو 44 سم. ونظرًا إلى أن زيادة محيط الرأس تُعد مؤشرًا على نمو الدماغ، فينبغي قياسه بانتظام. وقد يتراوح طول الطفل في الشهر 8 بين 62 سم و77 سم. كما قد تلاحظين خلال هذه الفترة أن يافوخ طفلكِ بدأ ينغلق. فعادةً ما يُتوقع أن يُغلق اليافوخ بين عمر 12 و18 شهرًا، إلا أنه قد يبدأ بالانغلاق لدى بعض الأطفال في الشهر 8. وإذا كان نمو الدماغ مستمرًا، فتُعد هذه الحالة طبيعية من الناحية الفسيولوجية ولا داعي للقلق.') WHERE id = '4019cfbc-4717-4ff6-83d7-b0dd34ad99d7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تظنين أن طفلكِ لا يُظهر بعض المهارات النمائية المتوقعة لعمره. وقد يختلف هذا الأمر لأن لكل طفل وتيرته الخاصة في النمو والتطور. ويُقصد بتأخر النمو أن تتطور مهارات مثل الجلوس والحبو والمشي والوقوف باستقامة والكلام بوتيرة أبطأ. وغالبًا ما يكون هذا التأخر مؤقتًا، ويتمكن معظم الأطفال من تدارك الفارق خلال مدة قصيرة. وعلى الرغم من أن اكتساب المهارات الجديدة يسير وفق تسلسل معين، فمن المهم ألا تنسي أن لكل طفل إيقاعه النمائي الخاص. فمثلًا، قد تتطور لدى بعض الأطفال المهارات الحركية الكبرى، مثل الجلوس، في وقت أبكر، بينما تتطور لدى آخرين مهارات الإمساك بالأشياء واستيعابها بسرعة أكبر. ومع ذلك، يمكنكِ مناقشة الأمور التي تقلقكِ مع طبيبكِ للاطمئنان.') WHERE id = '66787d5e-85c6-4974-9795-692e078d138d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يستغل طفلكِ معظم وقت استيقاظه في القيام باكتشافات جديدة. وإذا كان يقف مستعينًا بشيء ما أثناء هذه الاستكشافات، فمن المهم أن يلامس كعب قدمه الأرض. فهذا مهم جدًا لنمو عضلات ساقيه، وعلى عكس الاعتقاد الشائع، لا يسبب تسطح القدمين. ولكن يمكنكِ إلباسه حذاءً منزليًا بنعل مانع للانزلاق كي لا ينزلق على الأسطح الملساء وللوقاية من الحوادث. وعند الخروج، قد يحتاج طفلكِ إلى حذاء لحماية قدميه من الحرارة والبرودة، حتى لو لم يكن قد بدأ المشي بصورة كاملة بعد. وفي هذه المرحلة، ليس من الضروري شراء حذاء خاص بالخطوات الأولى. يكفي أن يكون الحذاء الذي تختارينه ملائمًا لقدم طفلكِ، وأن يحيط بكاحله ويدعمه.') WHERE id = 'b84764db-feb1-47bf-b057-d7266054d43f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما كان لون عيني طفلكِ من أكثر الأمور التي أثارت فضولكِ طوال فترة الحمل. 😊 بعد الولادة، يكون لون عيني الطفل عادةً بدرجة تتراوح بين الرمادي والأزرق. ورغم جمال هذه الدرجات، فإنها تكون مؤقتة للأسف. ويرجع ذلك إلى أن القزحية، وهي الجزء الملوّن من العين، لم يكتمل نموها بعد، ولذلك تعكس الضوء كما يصل إليها. وابتداءً من هذا الشهر، توشك عينا طفلكِ على اكتساب لونهما الحقيقي نتيجة اكتمال التصبغ تقريبًا. فإذا تحوّل لون عينيه إلى البني، فلن يتغير إلى لون آخر. أما إذا ظلتا بلون فاتح، فتذكري أن لونهما قد يتغير حتى يُكمل طفلكِ عمر 12 شهرًا.') WHERE id = 'afcad808-5171-4e03-8941-cb9235ad0674';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع انخفاض كمية حليب الأم أو الحليب الصناعي التي يتناولها طفلكِ، قد تقلقين بشأن حصوله على ما يكفي من الفيتامينات من الطعام. أولًا، من الضروري أن تستشيري طبيبكِ قبل إعطائه أي فيتامينات أو مكملات غذائية. وفي الوقت نفسه، تجنبي تقديم نظام غذائي أحادي لطفلكِ، واحرصي على أن تكون قائمته الغذائية متنوعة وملونة. وترتبط احتياجات طفلكِ من الفيتامينات والمعادن ارتباطًا مباشرًا بتناوله الفواكه والخضراوات الموسمية على وجه الخصوص. تذكري أن فيتامين D والأدوية الداعمة لتكوين الدم (قطرات الحديد) تُعطى عادةً بصورة روتينية، وهذا إجراء معتاد. وإذا وُلد طفلكِ مبكرًا، أو كان وزنه منخفضًا، أو كان يعاني تأخرًا في النمو، فقد يقترح الطبيب مكملات إضافية. لكن لكل طفل حالته الخاصة، لذا فإن أدق نصيحة ستحصلين عليها هي من طبيبكِ المطلع على حالتكِ وحالة طفلكِ.') WHERE id = 'a7e33135-d849-4e1d-b626-072569cf1acd';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن قادرًا على الجلوس بمفرده من دون الحاجة إلى دعم. وتمهد هذه المهارة لتمكّنه من الاستدارة والانحناء والحبو بسهولة أكبر. وربما يكون قد بدأ الحبو بالفعل. 😊 لكن من الطبيعي تمامًا أيضًا أن يتجاوز بعض الأطفال مرحلة الحبو ويبدؤوا المشي مباشرةً. سيحاول صغيركِ دائم الحركة الزحف أو التوجه نحو أي شيء يلفت انتباهه. وعندما يصل إلى الشيء الذي أثار فضوله، سيحمله بيده ويتفحصه ثم يضعه في فمه للتعرف إليه. ولهذا السبب تحديدًا، عليكِ مراقبته بعناية أكبر من المعتاد واتخاذ تدابير السلامة اللازمة في المنزل إن لم تكوني قد فعلتِ ذلك بعد.') WHERE id = 'f711661c-b42b-4a2c-9389-6ca7cb481b26';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما لا يزال طفلكِ يمر بمرحلة طفرة في النمو، لذا فمن الطبيعي أن تواجهي بعض الصعوبات. وقد يؤدي النمو السريع واكتساب مهارات جديدة أحيانًا إلى فقدان الشهية، بينما تُلاحظ لدى بعض الأطفال، على العكس، زيادة كبيرة فيها. لذلك قد يرغب صغيركِ في الرضاعة منكِ بوتيرة أكثر تكرارًا خلال اليوم. ويمكنكِ أيضًا تقديم الطعام التكميلي له بالقدر الذي يرغب فيه خلال هذه الفترة، لأن جسمه يحتاج إلى طاقة إضافية لمواكبة نموه السريع، وقد يشعر بالانزعاج إذا لم تُلبَّ هذه الحاجة. كذلك، قد لا يرغب في ابتعادكِ عنه بسبب ازدياد قلق الانفصال خلال هذه المرحلة. وفي مثل هذه اللحظات، ننصحكِ بأن تحاولي تفهّمه وتتحلي بالصبر، مراعاةً لصحته النفسية. 😊') WHERE id = 'a8e0d4f7-6afa-42e9-8b05-07856071a068';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتغير نمط نوم طفلكِ خلال بعض الفترات. في هذا الشهر، ينام طفلكِ نحو ١٤-١٥ ساعة يوميًا، ويكون الجزء الأكبر منها خلال الليل. ومع ذلك، فهو يحتاج أيضًا إلى القيلولة نهارًا، لما لها من تأثير إيجابي في نموه ومساعدته على اكتساب مهارات جديدة. تُظهر الأبحاث الحديثة أن أول قيلولتين يأخذهما الرضيع خلال النهار تؤديان دورًا مهمًا بوجه خاص في نموه. وبما أن كثيرًا من الأطفال يكونون نشيطين للغاية طوال اليوم، فقد أصبح بإمكانهم النوم ليلًا من دون استيقاظ. إذا كان طفلكِ لا يزال يستيقظ ليلًا، فلا تقلقي، فهذا طبيعي تمامًا أيضًا.') WHERE id = '71a3cc6c-7792-4d5e-b2d9-206c74922dd9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يزال طفلكِ في مرحلة الانتقال إلى الأطعمة الصلبة، وكل طعام جديد يتذوقه يُعد اكتشافًا جديدًا بالنسبة إليه. إذا كنتِ تتبعين طريقة BLW (الفطام بقيادة الطفل)، فقد تكون هذه المرحلة أكثر متعة لكما. ففي هذه الطريقة، يكتشف الطفل الأطعمة بنفسه من خلال تجربتها بصورة طبيعية. ورغم أن العملية قد تكون فوضوية ومتسخة بعض الشيء، فإن صغيركِ يتعلم بفاعلية أكبر التمييز بين مذاق الأطعمة وقوامها ورائحتها. وبفضل هذه العملية، يستوعب مفاهيم مثل الحجم والشكل والوزن والملمس بصورة أفضل مما قد توفره له ألعاب تعليمية كثيرة باهظة الثمن. كما أن تطوير طفلكِ للتنسيق بين اليد والعين بهذه الطريقة يمهّد لاكتساب المهارات الحركية الدقيقة مستقبلًا. والأهم من ذلك كله أنكِ تدعمين طفلكِ في اكتساب الثقة بنفسه! 😊') WHERE id = '55eccf49-79d1-4243-b6f7-4417e0ce8446';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الآن شراء كوب تدريبي لطفلكِ! 😊 عمومًا، قد يكون انتقال الطفل من زجاجة الرضاعة إلى الكوب صعبًا بعض الشيء، لأنه اعتاد مص أصابعه قبل ولادته، ثم اعتاد بعد الولادة الرضاعة منكِ أو من زجاجة الرضاعة. لكن استخدام زجاجة الرضاعة لفترة طويلة قد يضر ببنية فم الطفل وأسنانه بعد عمر معين. لذلك، ينبغي لكِ استخدام وسائل تشجيعية مثل الكوب التدريبي لمساعدته على الابتعاد تدريجيًا عن زجاجة الرضاعة والانتقال إلى شرب الماء من الكوب. ينصح المتخصصون عادةً بتقليل استخدام زجاجة الرضاعة بدءًا من الشهر التاسع. لكن إدخال الكوب التدريبي إلى حياة طفلكِ من الآن سيساعد على جعل الانتقال أكثر سلاسة.') WHERE id = 'b7595fc9-0616-4fd7-9f1c-a33935df996a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد بلغ الجهاز الهضمي لطفلكِ وإنزيماته مستوى أكثر تطورًا من حيث القدرة على العمل. وهذا يعني أن الوقت قد حان لتعريف طفلكِ بأطعمة جديدة! 😊 فعلى سبيل المثال، وبعد استشارة طبيبه، يمكنكِ هذا الشهر إضافة الزيتون والفلفل والفاصولياء الخضراء والقرنبيط واللوبيا والتوابل الطبيعية إلى نظامه الغذائي. ويرى كثير من الأطباء أنه يمكن أيضًا إدخال منتجات الدقيق ضمن غذاء الطفل في هذا الشهر. لكن بما أن طبيبه هو الأدرى بتطوره ونموه الجسدي، فننصحكِ بعدم تقديم هذه الأطعمة قبل الحصول على موافقته. كذلك يمكنكِ تقطيع الخضراوات المفيدة جدًا، مثل البروكلي والقرنبيط، إلى قطع صغيرة وتقديمها لطفلكِ بعد طهيها على البخار حتى تصبح طرية. وعند تقديم هذه الخضراوات، دعيه يمسكها ويأكلها بنفسه. بالهناء والشفاء! 😊') WHERE id = '8e3dae32-3e2f-4ba0-b882-845b799e8f32';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أن التسنين لا يسبب أي مشكلة لبعض الأطفال، فقد تكون هذه المرحلة مزعجة للغاية لمعظمهم. عادةً ما تظهر الأسنان الأولى لدى الأطفال بين عمر ٤ و٨ أشهر، لكن هذا التوقيت قد يختلف لأن كل طفل فريد. وربما تكون الأسنان التي تبدو كحبات اللؤلؤ في فم طفلكِ قد ظهرت بالفعل منذ فترة. خلال مرحلة التسنين، سيرغب طفلكِ في وضع يديه وكل ما يجده في فمه، لأنه يحاول تخفيف انزعاج لثته التي تسبب له الحكة عبر الضغط عليها للحصول على راحة مؤقتة. ولمساعدة طفلكِ خلال هذه الفترة، يمكنكِ تقديم أطعمة صلبة وباردة له بعد وضعها في الثلاجة لبعض الوقت. ومن الجيد أيضًا إبقاء عضّاضة أسنان في متناول يدكِ دائمًا لتسهيل هذه المرحلة.') WHERE id = 'fb599c82-fab1-4307-ae9d-156ed7a53d22';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل تطور مهارات طفلكِ الحركية الدقيقة، أصبح الآن قادرًا على الإمساك بالأشياء بيديه. وخلال هذه المرحلة، قد تلاحظين أنه يحاول إمساك الملعقة التي تضعينها أمامه واستخدامها. وعلى الأرجح لن يتقن ذلك تمامًا بعد، وقد يمل بعد فترة ويعود إلى استخدام يديه. إن هرس طفلكِ للطعام بيديه ومحاولته استكشافه خلال هذه المرحلة يساعدانه على الاعتياد على قوام الأطعمة. لذلك، لا داعي إلى منعه من تناول الطعام بيديه لبعض الوقت. يمكنكِ السماح ببعض الفوضى من حوله، لكن لا بأس بوضع مريلة حول عنقه وفرش غطاء أسفل مقعده أثناء تدرّبه على تناول الطعام. ونود تذكيركِ بأن تتركي طفلكِ يتحرك كما يشاء داخل هذه المساحة التي حددتِ حدودها، وألا تتدخلي إلا عند الحاجة. 😊') WHERE id = '42d35bcf-5e08-438b-ab99-312796c2146c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عندما يبدأ رضيعكِ بالكلام، يبدأ في الوقت نفسه بتطوير مهاراته اللغوية. في البداية، قد لا يدرك كثيرًا ما يقوله أو كيف يقوله، لكن بعض الأصوات التي لا معنى لها ستتحول مع مرور الوقت إلى كلمات حقيقية. ولا تسرّع هذه المناغاة نموه الذهني فحسب، بل تساعده أيضًا على اكتساب الخبرة في تقليد الأصوات وتذكّرها. وهكذا يدخل رضيعكِ مرحلة يبدأ فيها بالتريث ليقرر ما سيقوله، ويتعلم كيفية استخدام الكلام والإيماءات للتعبير عن رغباته واحتياجاته. ومع ذلك، قد يحتاج إلى بعض الوقت قبل أن يستخدم كلمات حقيقية. وخلال هذه الفترة، يواصل تعلم قواعد اللغة من خلال مراقبتكِ وتقليدكِ. لذلك، من المهم جدًا أن تستخدمي كلماتكِ بصورة صحيحة وواضحة وفي موضعها المناسب.') WHERE id = '8f6d0ab5-b074-476e-95ce-1532c933bec4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يمكن أن يكون الهيكل العظمي لرضيعكِ قويًا إلا من خلال نمو صحي للعظام. تبدأ عملية النمو هذه قبل الولادة، وتتسارع كثيرًا، ولا سيما خلال السنة الأولى من العمر. وبما أن رضيعكِ يبدأ بتناول الأطعمة التكميلية اعتبارًا من الشهر 6، فعليكِ اتخاذ الخطوات اللازمة منذ الآن لتقوية عظامه. وعلى الرغم من أن غذاءه الأساسي في هذه المرحلة لا يزال حليب الأم أو الحليب الصناعي، فإنه ينبغي أن يحصل مع الأطعمة التكميلية على أغذية غنية بالكالسيوم. ومع التقدم في مرحلة التغذية التكميلية، تنخفض قليلًا كمية الفيتامينات والمعادن التي يحصل عليها رضيعكِ من حليبكِ. لذلك، يُعد الكالسيوم مهمًا جدًا، فهو معدن يسهم بدرجة كبيرة في تقوية عظامه. ولضمان حصول جسم رضيعكِ على ما يكفي من الكالسيوم، يمكنكِ إعداد قائمة طعام له تتضمن أطعمة مثل الزبادي والخضراوات الورقية الخضراء.') WHERE id = '2697c6e2-7952-4ec2-98c7-54307a2fe921';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تكون حياتكِ في هذه المرحلة أكثر ازدحامًا وفوضى من المعتاد. ومع رضيعكِ الذي أصبح كثير الحركة، قد تشعرين بأنكِ لا تعرفين كيف ستلحقين بكل شيء، وقد تجدين صعوبة في تنفيذ خططكِ. هناك نصائح كثيرة يمكنها تسهيل حياتكِ في هذه المرحلة، وقد يساعدكِ تطبيق بعضها على الشعور بقليل من الراحة. ابدئي بمحاولة تنظيم أمور العناية برضيعكِ والعناية بنفسكِ والأعمال المنزلية. خصصي مكانًا ثابتًا للأغراض التي تستخدمينها بانتظام للعناية برضيعكِ. ويمكنكِ أيضًا تخصيص مساحة في المنزل لتغيير حفاضه فقط، حتى لا تضطري في كل مرة إلى البحث عن الحفاض والمناديل المبللة ومفرش تغيير الحفاض، كلٍّ على حدة. كذلك، لا تنتظري حتى لحظة مغادرة المنزل لتجهيز الأغراض التي ستحتاجين إليها عند الخروج مع رضيعكِ. يمكنكِ الاحتفاظ بحقيبة الأم والطفل جاهزة دائمًا في مكان قريب من الباب.') WHERE id = 'f71171e4-2818-49d6-8552-7761b12126d4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يدخل رضيعكِ في هذه الأيام مرحلة طفرة نمو طويلة. لذلك، قد تلاحظين رفضه للنوم والطعام، وزيادة انزعاجه ورغبته المستمرة في الاحتضان. تحدث طفرة النمو السادسة بين الأسبوعين 34-37، ابتداءً من تاريخ الولادة المتوقع لرضيعكِ. أما الكلمة المفتاحية لهذه الطفرة فهي «التصنيف». فقد أصبح رضيعكِ منذ مدة مستكشفًا يتفحص كل ما يراه حوله من كائنات حية وأشياء جامدة، وأصبح الآن قادرًا على تصنيفها ذهنيًا ضمن فئات. على سبيل المثال، صادفتما كلبًا معًا، فأشرتِ إليه وقلتِ لرضيعكِ: «هَو هَو». عندها يصنفه في ذهنه بطريقته الخاصة. وبعد بضعة أيام، عندما تصادفان قطة في الخارج، قد تلاحظين أنه ينظر إليها أيضًا ويقول: «هَو هَو»، لأنه وضع كل كائن يمشي على أربع في الفئة نفسها وفق فهمه. نعرف أنكِ قد تقولين له إن هذا غير صحيح، لكن عدم قدرته في الوقت الحالي على التمييز بهذا القدر أمر طبيعي ومقبول.') WHERE id = '18fded6c-68c1-4a2f-8a8c-2cce06aa19e7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ تحديد كمية السوائل التي تقدمينها لرضيعكِ بناءً على نصيحة طبيبكِ وملاحظاتكِ. وقد تشكّين في إصابته بالجفاف إذا بدا خاملًا خلال اليوم، أو تقيأ، أو رفض تناول الطعام. كذلك، ترتفع درجة حرارة جسمه فسيولوجيًا عند إصابته بالجفاف، لذلك قد يفيدكِ كثيرًا قياس حرارته على فترات منتظمة. وتشمل علامات الجفاف عمومًا: قلة التبول وكون البول داكن اللون، وجفاف الفم، والبكاء من دون دموع. كما أن التقليل الشديد من حليب الأم أو الحليب الصناعي خلال هذه المرحلة قد يؤدي إلى إصابة رضيعكِ بالجفاف. ومن أهم ما عليكِ فعله للوقاية من الجفاف الحرص على حصوله على حاجته اليومية من السوائل بانتظام.') WHERE id = '61c2e7d6-1d91-41c2-969b-396148013b25';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يواصل رضيعكِ نموه بلا توقف وبسرعة مذهلة! ومع دخولكما الشهر 8 في هذه الأيام، أصبح أكثر وعيًا وبدأ يتصرف بصورة مباشرة وهادفة. بعبارة أخرى، أصبح رضيعكِ قادرًا على التعبير عن مختلف رغباته من دون بكاء. فعلى سبيل المثال، بدلًا من أن ينزعج أو يتذمر أو يبكي عندما يجوع، قد تسمعينه يقول بوضوح كلمة تشير إلى الطعام، مثل «نَم نَم». وعندما يعطش، يفرح برؤية كوبه، وعندما يجوع، يشعر بحماس شديد حين يراكِ تحضّرين طعامه. تمثل هذه المرحلة نقطة تحول بالنسبة إلى رضيعكِ، إذ أصبح قادرًا على إخباركِ بما يريده بطريقة بسيطة. وعندما يطلب منكِ شيئًا بعينيه البريئتين، يستطيع فهم معنى إجابتي «نعم» و«لا». ومع ذلك، فما سيفعله بعد سماع إجابتكِ يعود إليه تمامًا. 😊') WHERE id = '1886ab50-5a60-4760-b927-fa91d9c42779';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إلى جانب إتقانه اللعب، أصبح طفلكِ أيضًا مراقبًا جيدًا. فهو يراقبكِ أنتِ وبقية أفراد الأسرة باهتمام، ويستطيع تقليد السلوكيات والأصوات خلال وقت قصير. فعلى سبيل المثال، قد يلفت انتباهه تلويحكِ لوالده مودّعةً إياه عند ذهابه إلى العمل، فيلوّح هو أيضًا لمن يغادر. فالأصوات التي يصدرها وتعابير وجهه بدأت تحمل معنى بالنسبة إليه. لذلك يزداد تكراره للمقاطع الصوتية عندما يحتاج إلى شيء ما. ومع ازدياد وعي طفلكِ بمن حوله وبما يحدث، حلّت الحركات الواعية والهادفة تمامًا محل ردود الفعل الفطرية التي وُلد بها. وهذا دليل على مدى سرعة تطوره خلال فترة قصيرة. 😊') WHERE id = '980f8f43-3138-49d0-a45d-59c21bfd0cd3';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ أكثر حركة من أي وقت مضى، وقد لا يحب تغيير حفاضه إطلاقًا، شأنه شأن جميع الأطفال الآخرين. 😊 فعند تغيير حفاض طفلكِ، يشعر بالراحة فور نزع الحفاض المتسخ. لذلك، عندما يرى أنكِ ستضعين له حفاضًا نظيفًا، قد يقاومكِ بذراعيه وساقيه. 😊 وإذا كان طفلكِ قد بدأ بالزحف، فقد تضطرين إلى ملاحقته قليلًا حتى تتمكني من إغلاق حفاضه. وقد يتسبب الإصرار والعناد مع طفلكِ المقاوم في شعوره بالتوتر. لذا يمكنكِ تسهيل مهمتكِ بجعل تغيير الحفاض أكثر متعة. وأبسط طريقة لذلك هي، بالطبع، تشتيت انتباهه. فالغناء له أثناء تغيير الحفاض، ووصف ما تفعلينه، وإشغاله بلعبة يحبها، سيجعل مهمتكِ أسهل بكثير. 😊') WHERE id = 'fe2747a5-5b02-4aab-bf69-6b7fa1ec81f8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'دخل طفلكِ الآن إحدى أكثر مراحل نموه نشاطًا من الناحية الذهنية. فإلى جانب سماعه الأصوات القريبة بوضوح، تطورت حواسه بحيث أصبح قادرًا على تمييز الأصوات البعيدة مثل البالغين. وتستمر مرحلة الاستكشاف سريعًا لدى طفلكِ بعد أن تطورت لديه بدرجة كبيرة حواس البصر والسمع وإدراك العمق. لذلك تتحرك يداه وذراعاه وساقاه باستمرار. ويمكنه استخدام جميع أصابعه لتحقيق غرض معين والإمساك بالأشياء بإحكام. كما بدأ يستخدم سبابته بنشاط لدفع كل ما يستطيع دفعه والعبث بالفتحات الصغيرة. ولهذا قد تحتاجين إلى اتخاذ تدابير وقائية، خصوصًا تجاه الأشياء التي قد تشكل خطرًا على طفلكِ، مثل مقابس الكهرباء.') WHERE id = '0856b508-32f1-46be-891e-90f4409ee60b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن معتادًا إلى حد كبير على مرحلة إدخال الأطعمة التكميلية. وإذا كنتِ لا تزالين تقدمين له الطعام مهروسًا، فيمكنكِ الآن الانتقال إلى أطعمة ذات قوام أكثر تكتلًا. ويوصي المتخصصون بالبدء في تقديم أطعمة أكثر صلابة اعتبارًا من هذا الشهر، لأن الأطفال يكتسبون القدرة على المضغ. وقد يؤدي الاستمرار مدة طويلة في تقديم الأطعمة المهروسة أو ذات القوام شبه الناعم إلى اضطرابات في تغذية طفلكِ مستقبلًا. لكن من الأفضل ألّا تزيدي كثافة الأطعمة التي تقدمينها بشكل مفاجئ، لأن الانتقال السريع قد يؤدي إلى الإمساك وبعض مشكلات الجهاز الهضمي. لذلك ينبغي أن تجعلي قوام الطعام أكثر تكتلًا قليلًا كل يوم لضمان انتقال تدريجي وسلس.') WHERE id = '72760305-9a29-4db8-960b-c7c0f371cc22';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'اعتبارًا من هذا الشهر، قد يتمكن طفلكِ من الجلوس بمفرده بحرية ومن دون أي مساعدة. وبفضل ازدياد قوة عضلات ذراعيه وساقيه، أصبح الزحف أسهل بالنسبة إليه. لكن تذكّري أن هذا لا يعني أن كل طفل سيزحف بالضرورة؛ فإذا لم يزحف طفلكِ، فلا يُعد ذلك تأخرًا. وإذا كان في منزلكم درج، فعليكِ أيضًا اتخاذ تدابير السلامة المناسبة، لأن التسلق يصبح أسهل مع ازدياد حركة طفلكِ. وقد يحاول طفلكِ هذا الشهر النهوض من وضعية الجلوس مستندًا إلى أحد الأشياء، ويتمكن عادةً من الوقوف مدة قصيرة بمساعدة ما يستند إليه. ورغم أنه لا يستطيع المشي بعد، فقد يُظهر منعكس الخطو عندما تمسكين به من تحت إبطيه. لكن لا ينبغي أن تجبريه على ذلك؛ فرغبة طفلكِ واستعداده هما أفضل دليل لكِ في هذا الشأن.') WHERE id = 'a563d702-5875-4391-a1d5-846178e0f653';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ الآن إضافة البقوليات المجففة والعدس والسمك إلى نظام طفلكِ الغذائي. فمع تطور قدرته على المضغ واستمرار نضج جهازه الهضمي يومًا بعد يوم، أصبح طفلكِ مستعدًا لتناول هذه الأطعمة. وتُعد البقوليات المجففة مهمة جدًا لأنها تساعد على تلبية احتياجاته من البروتين، كما أنها مصدر غني بالفيتامينات والمعادن. أما العدس فهو غني بالحديد وفيتامينات B وحمض الفوليك ومعادن متنوعة. وبفضل قيمته الغذائية التي تكاد تعادل قيمة اللحوم الحمراء، يُعد العدس عنصرًا مهمًا في التغذية الصحية لطفلكِ. وإضافةً إلى ذلك، يحتاج طفلكِ الذي يكتسب مهارات جديدة إلى أحماض أوميغا-3 الدهنية. ويحتوي السمك الذي ستضيفينه إلى نظامه الغذائي على كميات وفيرة من أحماض أوميغا-3 الدهنية، إلى جانب فيتاميني A وD.') WHERE id = '5436fc4f-86ab-41cc-af9e-5a2f20f1be86';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ متحمسًا جدًا للوقوف والمشي. 😊 وقد تظنين في هذه المرحلة أنه يحتاج إلى حذاء خطواته الأولى. يُعد اختيار الحذاء الأول للطفل الذي بدأ المشي مهمًا جدًا لنمو قدميه وعموده الفقري. فمع بدء طفلكِ، الذي ينمو جسمه وجهازه الهيكلي بسرعة، بالمشي، سيحتاج إلى حذاء يدعم هذا النمو. لكن من المهم ألا تتعجلي كثيرًا في إلباسه الحذاء. ينصح الخبراء بأن يمشي الأطفال حفاة داخل المنزل خلال مرحلة الاستعداد للمشي. وهكذا يستطيع طفلكِ الإحساس بالأرض وخوض هذه المرحلة الانتقالية براحة أكبر.') WHERE id = '073f0168-833f-4ba2-9b9a-e5fecf81e92a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما تكون مراقبة طفلكِ أثناء تناوله الطعام مسلية جدًا لكِ، كما هي الحال لدى كثير من الأمهات. لكن خلايا دماغ طفلكِ مستعدة للغاية لمعالجة المعلومات، وهو أكثر تقبلًا من أي وقت مضى لتعلّم المشاعر. لذلك من المهم جدًا أن تنتبهي إلى تعابير وجهكِ وردود أفعالكِ أثناء مراقبته. فمثلًا، إذا ظل طفلكِ يلعب مدة طويلة بدلًا من تناول الطعام، فقد يدفعه رد فعلكِ إلى اللعب بالطعام أكثر. وبالمثل، إذا كان يرمي الطعام من حوله ويشعر بالسعادة بذلك، فقد يزداد الأمر سوءًا إذا واجه رد فعل مختلفًا أو حادًا منكِ. إن المبالغة في رد الفعل مثيرة جدًا لاهتمام طفلكِ، وقد يرمي المزيد من الطعام لمجرد أن يشاهد رد فعلكِ مرة أخرى. وإذا كنتِ لا تريدين أن يتحول ذلك إلى عادة، فيمكنكِ إبعاد الطعام عنه لبعض الوقت أو إطعامه بنفسكِ.') WHERE id = '27035cad-7cd4-42d9-90d6-1a67f36eaafc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تفكرين في شراء مشاية أطفال لمساعدة طفلكِ على المشي؟ إن شراء المشاية فور بدء الطفل بالوقوف خطأ كبير. فقد أظهرت الدراسات أن المشاية لا تساعد إطلاقًا على تسريع المشي، بل قد تؤدي، على العكس، إلى تأخره قليلًا. وقد يصاب الأطفال الذين يوضعون في المشاية بمشكلات في العمود الفقري بسبب وضعية الجسم الخاطئة والتوزيع غير المتوازن للوزن. كما قد تظهر مشكلات أخرى، مثل النمو غير المتوازن لعضلات الساقين، نتيجة الضغط الواقع على مفصل الورك والدفع بأطراف الأصابع بسبب عدم وصول قدمي الطفل إلى الأرض بصورة مناسبة. وفي دراسة أُجريت في الولايات المتحدة الأمريكية، تبيّن أن حوادث مشايات الأطفال كانت السبب في 90% من حالات إصابات الجمجمة التي تعرض لها الأطفال خلال عامهم الأول. كما يتفق جميع أطبائنا تقريبًا على معارضتهم لاستخدام مشايات الأطفال.') WHERE id = '98a525b0-85c4-44ad-bd1f-bf93b8cfb809';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، يبدأ نظام طفلكِ الغذائي بالاعتماد على الأطعمة الصلبة. وإذا كنتِ لا تزالين تقدمين بعض الأطعمة على شكل مهروس، فعليكِ الآن تقديمها بقوام صلب وبشكل يستطيع طفلكِ الإمساك به بنفسه. وبهذه الطريقة، يمكنكِ تطوير قدرته على المضغ والإمساك، إلى جانب تقوية عضلات يديه وأصابعه. قد تسبب بعض الأطعمة الصلبة ردود فعل غير متوقعة في جسم طفلكِ. لذلك ينبغي أن تقدمي كل نوع من الأطعمة الصلبة على حدة، وأن تنتظري ثلاثة أيام على الأقل للتأكد من عدم حدوث رد فعل تحسسي قبل الانتقال إلى طعام آخر. تظهر الحساسية عادةً في صورة طفح جلدي على جسم طفلكِ أو تغيرات في قوام برازه. لذا عليكِ تجنب الأطعمة التي ثبت أنها قد تسبب له الحساسية، وتعريفه بالأطعمة الجديدة واحدًا تلو الآخر.') WHERE id = 'e4b85e6a-69c4-455d-9f99-5bcc0f9dfafa';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا شك أن رؤية طفلكِ ينمو بسرعة مذهلة تمنحكِ أنتِ والمقربين منكِ سعادة كبيرة. فما بالكِ حين تنضم ضحكاته إلى ابتساماته؟ 😊 لقد اكتسب طفلكِ في هذه المرحلة تحديدًا كثيرًا من المهارات الجديدة، وقد يصعب عليكِ متابعة كل هذه المهارات المختلفة. فمثلًا، أصبح طفلكِ الآن قادرًا على الجلوس بسهولة من دون طلب أي مساعدة أو الحاجة إلى دعم. وبما أنه اعتاد الحبو جيدًا، فمن الطبيعي أن يرغب في ممارسة هذا السلوك الجديد باستمرار. تقول أمهات كثيرات خلال هذه الأسابيع إن أطفالهن يستطيعون الوقوف لفترة قصيرة مع التمسك بشيء ما. لكن توقيت الوقوف قد يختلف من طفل إلى آخر بحسب نمو عضلاته. لذلك ننصحكِ بألا تجبري طفلكِ على ذلك ما دام لا يحاول القيام به بنفسه. 😊') WHERE id = 'e8faa9c0-7a4a-4a69-af25-bd6473750397';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أنتِ الآن في الأشهر التي سيبدأ فيها طفلكِ تدريجيًا بالاستمتاع بشعوره بالاستقلال. وإذا كان طفلكِ قد بدأ الحبو، فتنتظركِ مرحلة مليئة بالحركة. أما إذا لم يبدأ الحبو بعد، فمن المرجح أن يبدأ خلال هذا الشهر. ومع الحبو، أصبح طفلكِ قادرًا على الوصول إلى ألعابه وقتما يشاء واللعب بها بالطريقة التي يريدها. لكن ابتداءً من هذه الأشهر، قد يبدأ بعض الأطفال بالشعور بالملل من الألعاب التي اعتادوا اللعب بها منذ مدة. أي إن ألعابه المعتادة إذا لم تعد تجذب انتباهه، فقد يبدأ بفتح كل خزانة ودرج يكتشفهما في المنزل والعبث بمحتوياتهما! فطفلكِ يبحث الآن عن اكتشافات جديدة، وهو شديد الحماس للتعرف إلى كل غرض لم يسبق له رؤيته. لذلك ننصحكِ بإعطاء الأولوية لسلامة طفلكِ ومراقبته قدر الإمكان.') WHERE id = '5cb2c5a3-52c5-4353-87cf-7a048de6a6ae';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يشعر طفلكِ ببعض الانزعاج خلال هذه الفترة بسبب التسنين. وسيساعد وجودكما في بيئة هادئة ومريحة قدر الإمكان على تسهيل هذه المرحلة. يمكنكِ تدليك لثة طفلكِ باستخدام عضّاضات التسنين. ونظرًا إلى أن الأشياء الباردة تمنحه الراحة، فاختاري العضّاضات المملوءة بالماء التي يمكن حفظها في الثلاجة. قد يضطرب نظام تغذية طفلكِ ونومه خلال فترة التسنين، ما قد يضعف جهازه المناعي ويجعله أكثر عرضة للعدوى. إذا لاحظتِ لدى طفلكِ أعراضًا مثل ارتفاع درجة الحرارة فوق ٣٨ درجة، أو الانزعاج الشديد، أو الإسهال، فاحرصي على استشارة الطبيب. فعلى عكس الاعتقاد الشائع، قد لا تكون هذه الأعراض مرتبطة دائمًا بالتسنين.') WHERE id = 'fd3bdcfc-5254-4510-b9f7-837898a606a0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُعد العلاقة الجيدة التي يبنيها الرضيع مع الشخص الذي يعتني به بالغة الأهمية لنموه. ومن المشكلات الشائعة لدى كثير من الآباء والأمهات عدم معرفتهم بكيفية بناء هذه العلاقة الجيدة أو قضاء وقت ممتع مع رضيعهم. في الواقع، حتى لعبة بسيطة مثل «الغميضة» تلعبينها مع طفلكِ يمكن أن تحقق هذا الهدف. فاللعب نشاط يدعم تطور الوظائف الذهنية لدى الرضيع، بل وقد تكون له آثار علاجية أيضًا. واللعب مع طفلكِ مهم جدًا لنموه الاجتماعي والعاطفي والجسدي والذهني واللغوي. إضافةً إلى ذلك، فإن تواصلكِ المتكرر معه وغناء الأغاني والتهويدات له، بل وحتى ابتسامتكِ الصادقة، كلها تحفّز ذهنه. وتسهم هذه المحفزات الذهنية إسهامًا كبيرًا في نمو الدماغ. لذلك ننصحكِ باغتنام كل فرصة تتاح لكِ.') WHERE id = '8bad6496-e337-421c-9a82-679470e2639c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع بلوغ الشهر التاسع، يحتاج طفلكِ إلى تناول المزيد من الأطعمة ذات القوام الحبيبي والمقطّعة إلى قطع صغيرة كي يتطور منعكس المضغ لديه. لذلك ينبغي أن تُعدّي الأطعمة التكميلية التي تقدمينها لطفلكِ بطريقة تمكّنه من إمساكها بسهولة بيده وتناولها على شكل لقم. وبهذه الطريقة سيطوّر طفلكِ أيضًا مهارات تناول الطعام. إذا لم تظهر أسنان طفلكِ بعد، فقد تظنين أنه لن يتمكن من المضغ من دون أسنان. لكن هذا الاعتقاد غير صحيح؛ إذ يستطيع طفلكِ هرس أطعمة مثل الخضراوات والفواكه المطهوة بسهولة باستخدام لثته وحنكه. ومن هذا المنطلق، تُعد الأطعمة ذات القوام الحبيبي والمقطّعة إلى قطع مفيدة جدًا لتنمية مهارتي المضغ والإمساك لدى طفلكِ. ولتحقيق ذلك، يمكنكِ اختيار الأطعمة المستخدمة خصوصًا في طريقة BLW (الفطام الذاتي بقيادة الرضيع).') WHERE id = '01dbba01-d87e-4015-9ad4-7f2d6dcf5bd6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يتغير تمامًا، بدءًا من هذا الشهر، نظام تغذية طفلكِ الذي حاولتِ تنظيمه حتى الآن. ويرجع السبب الرئيسي في ذلك إلى بدء ظهور محاولاته للاستقلالية. وإذا بدأت الأطعمة التي يستطيع تناولها بنفسه تحل محل الأطعمة المهروسة التي كنتِ تطعمينه إياها بالملعقة، فقد يتطلب ذلك وضع نظام جديد. لا يستطيع بعض الأطفال التكيف بسهولة مع هذه المرحلة. لذلك قد يرفض طفلكِ الطعام الذي تقدمينه له بشدة، أو قد لا يرغب في استخدام الملعقة. وهنا ينبغي أن تتحلي بالكثير من الصبر، وأن تتفهمي رغبة طفلكِ إذا أراد تناول الطعام بنفسه. يمكنكِ تهيئة بيئة مناسبة له ووضع جزء من الطعام أو كله أمامه. وقد لا يتمكن طفلكِ في البداية من تحديد حجم اللقم المناسب. ويمكنكِ مساعدته حين تشعرين بأنه يحتاج إلى الدعم.') WHERE id = 'f4238778-2de3-481f-be1b-95a62161c1ba';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينمو طفلكِ بسرعة بفضل الألعاب التي يلعبها والمهارات الجديدة التي اكتسبها، مثل الحبو. ففي أثناء قيامه بهذه الحركات، تعمل عضلات مختلفة في جسمه باستمرار. وتبدأ مهاراته الحركية الدقيقة أيضًا بالتطور، ولا سيما من خلال الألعاب التي تُشغّل مجموعات العضلات الصغيرة، مثل تركيب الأشياء ونزعها أو إغلاق الأزرار. أما تشغيل مجموعات العضلات الكبيرة فيمهّد لاكتساب حركات مستقبلية مثل المشي والقفز وصعود الدرج. ومع ازدياد عمق التنفس ومعدله أثناء الحركة، تدخل كمية أكبر من الأكسجين إلى جسم طفلكِ. كذلك يؤدي تسارع الدورة الدموية خلال هذه التغيرات الأيضية إلى نقل مزيد من العناصر الغذائية إلى الأنسجة. وبناءً على ذلك كله، يمكننا القول إن اللعب بكثرة مهم جدًا لنمو طفلكِ الذهني والجسدي على حد سواء.') WHERE id = 'a8bbe7da-d7ed-4f71-bc81-f38a911b0996';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدءًا من هذا الشهر، يمكنكِ البدء بإشراك طفلكِ في مائدة العائلة. ولا شك في أن ذلك سيكون ممتعًا للغاية! 😊 إن اعتياده الجلوس معكم حول المائدة يجعله يشعر بأنه جزء من العائلة، وهذا يساعده على تنمية مهاراته الاجتماعية. كما أن رؤية أفراد العائلة الآخرين وهم يتناولون الطعام قد تشجعه على عدم رفض الأطعمة التي تقدمينها له. وقد يرغب طفلكِ لبعض الوقت في مراقبة كيفية تناول الآخرين للطعام بدلًا من أن يأكل. في هذه الحالات، لا ينبغي أن تجبريه على تناول الطعام. يمكنكِ التوقف قليلًا ثم تقديم الطعام له مجددًا حتى تتأكدي من شبعه. وتذكّري أن جلوس طفلكِ معكم إلى المائدة نفسها لا يعني أنه يستطيع تناول كل ما يُطهى في المنزل. فتقديم الأطعمة المناسبة لجهازه الهضمي، ولا سيما حتى بلوغه سن ٣ سنوات، يساعد على الوقاية من كثير من المشكلات الصحية التي قد تظهر مستقبلًا.') WHERE id = '88647028-f25e-4ac9-8691-df916cfbec6e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ قد قطع شوطًا كبيرًا في نموه خلال فترة قصيرة، فإنه لا يزال في مرحلة الرضاعة. وفي هذه المرحلة، يكون نشاطه المفضل هو اللعب بأجزاء جسمه والأشياء المثيرة للاهتمام من حوله. لذلك يمكنكِ إضافة أشياء ملوّنة ومتحركة وتصدر أصواتًا إلى المكان الذي يوجد فيه. ومن الأنشطة الجميلة التي يمكنكما القيام بها معًا أن تتيحي لطفلكِ بعد الاستحمام فرصة استكشاف جسمه من دون ملابس. دعيه يتفحّص أصابع قدميه واحدًا تلو الآخر ويحاول التعرّف إليها بوضعها في فمه. يساعد استكشاف طفلكِ لجسمه على إدراك حدوده واكتساب الثقة بقدراته. وبعد ذلك، يمكنكِ أن تغنّي له وتدلّكيه برفق لمساعدته على الاسترخاء. استمتعا بوقتكما! 😊') WHERE id = '15555c9e-8608-4e1e-a198-d3137b747de5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يواصل طفلكِ النمو والتطور بسرعة، وإن لم يكن ذلك بالوتيرة نفسها التي كان عليها في الأشهر الأولى. ولدعم نموه والحفاظ على صحته، عليكِ أن تختاري بعناية الأطعمة المناسبة لعمره. وينبغي أن يظل حليب الأم أو الحليب الصناعي يشكّل الجزء الأكبر من نظامه الغذائي. وإلى جانب ذلك، يمكنكِ إضافة الفواكه والخضراوات ذات القوام المتكتل غير المهروس، والمعكرونة المصنوعة من الحبوب الصحية، والبسكويت الذي تحضّرينه في المنزل، وأي أطعمة سهلة الهضم يمكنه الإمساك بها بيده إلى قائمته الغذائية. ومن الضروري أيضًا تقدير احتياجه اليومي من البروتين بشكل صحيح لدعم عضلاته سريعة النمو. ويمكنكِ إدراج مصادر البروتين مثل السمك، واللحوم المطهية جيدًا، والعدس، والفاصولياء ضمن نظام طفلكِ الغذائي. وفي هذه المرحلة، من الأفضل تقديم طعام جديد واحد فقط في كل مرة والتدرّج في ذلك، حتى تتمكّني من ملاحظة ما إذا كانت لديه حساسية تجاه أي طعام جديد.') WHERE id = '89bec816-5357-4575-bfde-092fc39e99a9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'عند إطعام طفلكِ أو جلوسكما معًا إلى مائدة الطعام، عليكِ إبعاد كل ما قد يشتّت انتباهكما. ولا تقتصر هذه القاعدة على المرحلة الحالية التي يتعلّم فيها طفلكِ بنشاط، بل تنطبق في جميع الأوقات. فمائدة الطعام، ولا سيما عندما يشارك فيها طفلكِ، تشكّل بيئة تعزّز التواصل بين أفراد الأسرة وتساعد على الانتباه إلى كمية الطعام المتناولة. لذلك احرصي على إطفاء التلفاز وقت الطعام، وألّا يكون في يد طفلكِ هاتف أو جهاز لوحي. كذلك أبقي طفلكِ بالقرب منكِ ليرى مراحل التحضير التي تسبق تناول الطعام، لأن ذلك يمثّل تجربة تعلّم حية لطفلكِ الذي يتمتع بقدرة كبيرة على التقليد. فغسل اليدين قبل الطعام، وتجهيز المائدة وترتيبها بمشاركة الأسرة، وتناول الطعام في أجواء مبهجة، كلها سلوكيات يمكنكِ أن تكسبي طفلكِ إياها من دون بذل جهد خاص، بل بمجرد أن تكوني قدوة له.') WHERE id = '6cc71e92-a6d5-4d2d-bf55-9c74e24a03af';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمكنكِ ممارسة ألعاب التطور الحسي مع طفلكِ لتحفيز وظائفه الذهنية. قد يبدو هذا المصطلح معقدًا للوهلة الأولى، لكنه في الواقع أسلوب يدعم نمو طفلكِ على أفضل نحو، بل ويمكن أن تكون له فوائد علاجية أيضًا. ومن خلاله، يمكنكِ مساعدة طفلكِ على التعلّم النشط والتطور في مجالات مختلفة. دعيني أوضح لكِ ذلك بمثال بسيط: يمكنكِ مثلًا وضع طفلكِ في المنتصف والتحرّك حوله، أو الوقوف أمامه وتحريك أشياء مثيرة للاهتمام بالسحب والدفع. ويمكنكِ أيضًا تمديده على ظهره وربط بالونات بقدمه ليحاول ركلها. ولتنمية حاسة اللمس لديه، يمكنكِ تعريفه إلى أسطح ناعمة الوبر وذات أنسجة مختلفة. أنا واثقة من أن طفلكِ سيستمتع كثيرًا! 😊') WHERE id = '69152415-f884-484c-9ae7-d7f46f63d572';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن الجهاز الهضمي لطفلكِ أصبح مستعدًا، فمن المهم جدًا ألّا يتناول بعض الأطعمة بعد، حتى ينعم بحياة أكثر صحة في المستقبل. فعلى سبيل المثال، يُعدّ تجنّب جميع الأطعمة المصنوعة من الدقيق الأبيض في نظام طفلكِ الغذائي من أولى قواعد التغذية الصحية. ويمكنكِ اختيار الخبز والمعكرونة المصنوعين من الحبوب الكاملة أو الجاودار. كذلك فإن عدم تعريف طفلكِ في هذه المرحلة إلى الأطعمة الجاهزة المعبأة والحلويات سيجعل مهمتكِ أسهل بكثير مستقبلًا. فلا ينبغي مثلًا أن تضيفي السكر إلى طعامه لأنكِ تعتقدين أنه يرفض بعض الخضراوات لعدم استساغة مذاقها. فحاسة التذوق لدى طفلكِ لم تتعرّف بعد إلى النكهات بالكامل، وقد يحب شيئًا ترينه أنتِ بلا مذاق. وإذا قدّمتِ لطفلكِ في البداية أطعمة محلاة بالسكر، فسيصبح الحد منها لاحقًا صعبًا، بل ربما مستحيلًا.') WHERE id = 'f1f06dfe-2ed9-46d2-a946-2592a01f6371';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم يكن طفلكِ قد بدأ الحبو بعد، فمن المرجّح جدًا أنه شرع في بعض التدريبات استعدادًا له. وخلال هذه التدريبات، ستبدو لكِ محاولاته للحبو طريفة وممتعة للغاية على الأرجح. 😊 والسبب هو أن طفلكِ لم يتقن مهارة الحبو بالكامل بعد. وسيبحث عن الوضعية الأنسب له، وكغيره من الأطفال سيحاول في البداية الزحف باستخدام ذراعيه فقط. ويرجع ذلك بالطبع إلى أن عضلات ذراعيه أقوى من عضلات ساقيه. وسيتغيّر هذا التوازن قريبًا لصالح ساقيه، لكن طفلكِ لا يزال بحاجة إلى بعض الوقت. لذلك لا داعي للقلق عندما ترينه يزحف على الأرض ثم يستريح عليها قليلًا حين يتعب.') WHERE id = '53bde760-576b-4b67-a81b-6b925c4d3fda';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تُصدر منظمة الصحة العالمية بانتظام توصيات بسبب تفشي الأوبئة في بلدان مختلفة من الإقليم الأوروبي. واستنادًا إلى قرارات المجلس الاستشاري للتحصين، يجري تقييم تطعيم الرضع الذين تتراوح أعمارهم بين 9 و11 شهرًا ضمن استراتيجية المكافحة. ووفقًا للإرشادات المعتمدة، يمكن إعطاء الرضع الذين تزيد أعمارهم على 9 أشهر وتقل عن 12 شهرًا جرعة إضافية من لقاح الحصبة بناءً على توصية الطبيب. تُعطى هذه الجرعة بفاصل زمني لا يقل عن أربعة أسابيع عن جرعة لقاح الحصبة السابقة. ولأنها ليست جرعة روتينية، فعادةً ما تُسجَّل في النظام باعتبارها جرعة تطعيم إضافية. لا تنسي استشارة طبيب طفلكِ للحصول على أدق المعلومات حول هذا الموضوع.') WHERE id = 'b6d3d34d-c066-4ccc-9ded-29b02d7dbff4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يطلب الطبيب هذا الشهر إجراء بعض التحاليل خلال الفحوصات الروتينية للاطمئنان إلى الحالة العامة لطفلكِ. وقد يطلب بعض الأطباء هذه التحاليل في الشهر 12 أيضًا؛ إذ يعتمد ذلك كليًا على وتيرة نمو طفلكِ وتطوره. سيقيس الطبيب أولًا طول طفلكِ ووزنه. إذا لاحظتِ أن زيادة وزنه قليلة، فلا تقلقي مطلقًا. تنخفض وتيرة زيادة وزن الأطفال كثيرًا خلال هذه الأشهر، لأنهم يصبحون أكثر حركة من أي وقت مضى ويستكشفون ما حولهم. وبسبب حركته المستمرة، يحرق طفلكِ جزءًا كبيرًا من السعرات الحرارية التي يتناولها. يبلغ متوسط وزن الطفل في عمر 9 أشهر 8400 غرام، لكن هذا الوزن قد يتراوح بين 6600 غرام و10.000 غرام. ومن الطبيعي أن يزداد وزنه خلال الشهر بنحو 250-600 غرام. تذكّري أن كل طفل يختلف عن الآخر، وقد تختلف هذه الأرقام من طفل إلى آخر.') WHERE id = '4fead597-2916-4787-ba40-6051f71308e8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المفيد أن تقدّمي لطفلكِ أطعمة طرية مهروسة خلال مرحلة الانتقال إلى الأغذية التكميلية، حتى يعتاد على هذه العملية. لكن جهازه الهضمي ومهاراته الحركية أصبحا منذ فترة مستعدين أيضًا لتناول الأطعمة الأكثر صلابة. فعلى سبيل المثال، يُعد الموز المقطّع بطريقة تتيح لطفلكِ إمساكه بيده خيارًا رائعًا، كما أنه سهل التحضير ولا يحتاج إلى الطهي. ويُعد التفاح أيضًا من الفواكه التي تستخدمها الأمهات كثيرًا خلال هذه المرحلة. ولأنه أكثر صلابة من الموز، يمكنكِ طهيه قليلًا على البخار حتى يلين، ثم تقطيعه وتقديمه لطفلكِ بوفرة. أما في وجبة العشاء، فستكون قطع كرات اللحم المحضّرة خصيصًا له خيارًا شهيًا للغاية. بالهناء والشفاء! 😊') WHERE id = '366b1717-cbe7-42c2-825f-799a14209342';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، قد تلاحظين تقدمًا كبيرًا في مهارات طفلكِ اللغوية. يبدأ جميع الأطفال تقريبًا خلال هذه المرحلة باستخدام الكثير من الكلمات، سواء كانت ذات معنى أم مجرد أصوات غير مفهومة. وإذا استيقظ من النوم ولم يجدكِ بجانبه، فقد يبكي وهو يناديكِ بوعي قائلًا: «ماما». استعدي! 😊 فقد تطورت قدرته على التعبير عن نفسه كثيرًا خلال هذه المرحلة. فعلى سبيل المثال، عندما تُظهرين له حبكِ، قد يبادلكِ التعبير عن حبه، وعندما يحزن سيجعلكِ تشعرين بذلك. وإذا رآكِ حزينة، فقد يقترب منكِ ويراقبكِ محاولًا فهم ما يحدث. ورغم أنه لا يزال عاجزًا عن نطق الكثير من الكلمات، فهذا لا يعني أنه لا يعرف معانيها! 😊') WHERE id = '248a2f1b-11a9-4475-98d2-8e5dbff40ba0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تصبح لثة طفلكِ شديدة الحساسية خلال هذه الأسابيع، خصوصًا إذا كان في مرحلة التسنين. لذلك قد يسبب احتكاك الملعقة أو الطعام بلثته شعورًا بالانزعاج. وقد يرفض طفلكِ الطعام لهذا السبب، بل قد يرفض الرضاعة أيضًا. وبوجه عام، يُعد فقدان الشهية أمرًا طبيعيًا لدى الأطفال خلال فترة التسنين. وإذا لم تستمر هذه الحالة فترة طويلة جدًا، فلا داعي للقلق. عندما يرفض طفلكِ تناول الطعام، فلا تجبريه مطلقًا على الأكل رغمًا عنه. فقد يؤدي ذلك إلى تكوّن نفور شديد لديه من الطعام، وقد تواجهين مشكلات في تغذيته مستقبلًا. ولتجاوز هذه المرحلة الصعبة براحة أكبر، يمكنكِ تقديم الحساء بالزبادي وعصائر الفاكهة الطازجة.') WHERE id = '2db32885-0a8a-4d2a-bc4e-74c38a2ae5a1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لدعم النمو الذهني لطفلكِ هذا الشهر، يمكنكِ اختيار ألعاب تعليمية مناسبة لعمره. وستساعده خصوصًا الألعاب التي يمكن تركيب أجزائها وفصلها على فهم مفهوم الأحجام. وسيكتشف طفلكِ أصواتًا جديدة من خلال ضرب هذه الألعاب بيده أو طرق بعضها ببعض. كما ستتطور مهاراته الحركية الدقيقة كثيرًا أثناء تركيب القطع معًا. لكنكِ لستِ مضطرة إلى شراء ألعاب باهظة الثمن لتحقيق كل ذلك. فعلى سبيل المثال، يمكنكِ الوقوف مع طفلكِ أمام المرآة وإظهار أصابعكِ واحدًا تلو الآخر وتسميتها. وبفضل هذا النشاط الذي تمارسانه معًا، سيستمتع طفلكِ ويتعلم في الوقت نفسه. وقتًا ممتعًا! 😊') WHERE id = '39e8f843-aca7-42e5-9c7e-60770bf6f46e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطور الجهاز الهضمي لطفلكِ كثيرًا، ولم يعد هناك ما يمنع تخصيص مكان له على مائدة الإفطار العائلية. فعلى سبيل المثال، بعد إرضاعه طبيعيًا (أو مع كوب من الحليب الصناعي إذا كان يتغذى عليه)، يمكنكِ تقديم الجبن والزيتون وخبز الحبوب، بل وحتى الزبدة الطبيعية لطفلكِ. لكن طفلكِ ليس مستعدًا بعد لتناول كل شيء. لذلك ينبغي لكِ في هذه المرحلة أيضًا تجنب تقديم الباذنجان وبياض البيض والعسل وحليب الأبقار والماعز، وكذلك الفواكه المعروفة بأنها مسببة للحساسية. ولتقليل خطر إصابة طفلكِ بالحساسية إلى أدنى حد، عليكِ تجنب الأطعمة المعدلة وراثيًا أو التي تعرضت لمبيدات حشرية قوية أو التي تحتوي على منكهات قد تسبب التعلق بها ومواد حافظة. فالأطعمة التي تخضع لهذه العمليات تفقد طبيعتها تمامًا، وتصبح مواد غريبة على عملية الأيض لدى طفلكِ. ومن بين أكثر الأطعمة المسببة للحساسية: المعلبات المصنّعة، وبعض منتجات القمح المعدلة وراثيًا، والفواكه التي تحتوي على مواد كيميائية، ومنتجات الألبان. لذا من المهم جدًا أن تتجنبي الأطعمة المعلبة لطفلكِ، وأن تختاري الفواكه والخضراوات الطبيعية لتقليل خطر الحساسية.') WHERE id = '7dcfd4f4-9aee-4c8d-9828-a2d3f2df221d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا اضطررتِ إلى السفر برفقة طفلكِ، فعليكِ الاستعداد لمواجهة بعض الصعوبات البسيطة. فقد اعتاد الآن كثيرًا على محيطه ومنزله وأفراد أسرته الذين يراهم كل يوم، وكوّن لنفسه روتينًا ضمن هذه البيئة. وقد يبدو له في البداية التنقل والابتعاد عن البيئة التي اعتاد عليها والذهاب إلى أماكن جديدة أمرًا مخيفًا بعض الشيء. كما أن رؤية الكثير من الغرباء قد تجعله لا يشعر بالأمان وتسبب له القلق. ولتهدئة طفلكِ أثناء السفر، يمكنكِ أن تأخذي معكِ بعض الأشياء التي تشتت انتباهه، مثل الكتب المصورة، والألعاب التي تصدر أصواتًا، ودمى الأصابع، وبعض الأطعمة التي يحبها. وإذا ظل طفلكِ منزعجًا رغم كل ذلك، فيمكنكِ التحدث إليه ومحاولة شرح الموقف له قدر استطاعتكِ، حتى وإن لم يكن قادرًا على استيعاب مفهوم السفر تمامًا.') WHERE id = '4ae1b5f1-3350-4a7e-9ecb-70e54028f264';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك موضوع آخر لا يقل أهمية عن تغذية طفلكِ وصحته ونموه الجسدي، وهو حصوله على تعليم جيد في المستقبل. فالتعليم مهم جدًا لمستقبل طفلكِ، ونعلم أنكِ تفكرين فيه كثيرًا منذ الآن. لكن هل تعرفين ما يمكنكِ فعله في هذا الشأن؟ إذا لم تكوني قد سمعتِ بعد بمصطلح مونتيسوري، فنود أن نعرّفكِ إلى هذا النظام التعليمي. نظام مونتيسوري التعليمي هو منهج يُطبَّق وفقًا لاختلاف سرعة تعلم الطفل ومهاراته ومجالات اهتمامه. إذا قررتِ تطبيق هذا الأسلوب، فعليكِ إعداد مواد تعليمية منظمة ومصنفة بعناية في محيط طفلكِ. ويمكن أن تشمل هذه المواد أنشطة ربط العُقَد وفكها، وتركيب المكعبات ذات الأشكال، والأكواب الملونة المتداخلة. والنقطة المهمة هنا هي تصنيف المواد التي أعددتِها بطريقة صحيحة ووضعها في أماكن يستطيع طفلكِ الوصول إليها.') WHERE id = 'b4fbd7bc-5bea-4328-9444-1bbb7e0b93ab';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد كبر طفلكِ في غمضة عين، ومع انتهاء الشهر 9 الذي بدأ فيه تناول الأطعمة التكميلية إلى جانب حليب الأم، تكونان قد تجاوزتما بالفعل المرحلة الانتقالية من ناحية التغذية. وبدءًا من هذا الشهر، يمكنكِ تعريف طفلكِ إلى أطعمة محضّرة بالقمح، وحبوب متنوعة، والبيض، وكذلك اللحوم والأسماك. ويُعد البروتين مهمًا للغاية في تغذية طفلكِ الذي تنمو عضلاته بسرعة. لذلك يمكنكِ الحرص على تقديم اللحوم أو منتجاتها لطفلكِ مرة واحدة يوميًا ضمن برنامجه الغذائي. لكن عليكِ أن تتذكري أن وتيرة نمو طفلكِ تختلف، كما هي الحال لدى جميع الأطفال. ففي هذه المرحلة المهمة، قد يكون بعض الأطفال منفتحين على الطعام ومتحمسين له، بينما قد يكون آخرون عازفين عنه. بل يُعد رفض طفلكِ للأطعمة التي يتعرف إليها حديثًا أمرًا طبيعيًا في هذه المرحلة. لذلك عليكِ مراقبة طفلكِ جيدًا والتعامل معه وفقًا لاحتياجاته. ويمكنكِ الاستمرار في تقديم كل طعام جديد لطفلكِ وفق قاعدة الأيام الثلاثة، مع مراقبة استجابة جسمه. كما يُعد ظهور مشكلات مثل الإمساك والغازات والارتجاع مع زيادة كمية الأطعمة التكميلية أمرًا طبيعيًا، إلا أن هذه المشكلات ستقل بمرور الوقت.') WHERE id = '38f9d9e1-4776-4187-abf9-e1f1ad116098';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم يكن طفلكِ قد اكتسب مهارة الحبو حتى هذه المرحلة، فيمكنكِ مساعدته على ذلك. ومن أشهر الطرق لتشجيع طفلكِ على الحبو وضع أشياء مثيرة للاهتمام أو لعبته المفضلة على مسافة يستطيع بلوغها. ويمكنكِ أيضًا إتاحة وقت كافٍ له للعب على الأرض خلال اليوم. ولتحقيق ذلك، ضعي طفلكِ على سطح ليس شديد الصلابة ولا شديد الليونة، واتركيه يفعل ما يشاء ضمن مساحة آمنة حددتِ حدودها. كما أن تقوية عضلات ظهره ستساعده كثيرًا على الحبو، ويمكنكِ لهذا الغرض تشجيعه على ممارسة أنشطة الاستلقاء على البطن. وإضافة إلى ذلك، ننصحكِ بتجنب أدوات مثل مشايات الأطفال التي قد تؤخر الحبو.') WHERE id = 'c3473c70-f7b4-432f-afbf-5ede71de258f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مرحبًا بكِ في أشهر مليئة بالحركة والركض! يبدو وكأن طفلكِ وُلد بالأمس فقط... ما أسرع مرور الوقت، أليس كذلك؟ وبينما تبدئين بتخيّل ما ستفعلينه لحفل عيد ميلاد طفلكِ المرتقب، قد يفاجئكِ هذا الشهر بالوقوف على قدميه. وقد يبدأ طفلكِ خلال هذا الشهر بالوقوف منتصبًا من دون دعم لبضع ثوانٍ، وربما يخطو خطوة أو خطوتين. ومع هذا التطور، ستبدو الأشياء التي كانت تظهر ضخمة في عينيه أصغر، وستزداد ثقته بنفسه. بل قد يبدأ بعض الأطفال بالمشي خلال هذا الشهر. لكن لا يزال الوقت مبكرًا للمشي، ولا ينبغي لكِ إجبار طفلكِ عليه. ومع ذلك، إذا كان طفلكِ يبذل جهدًا كبيرًا للمشي، فربما تبحثين عن بعض الوسائل التي تساعد على دعم هذا التطور. لذلك يمكنكِ، بعد استشارة طبيبكِ، الاطلاع على المنتجات التي تُباع باسم عربة الخطوات الأولى أو مساعد المشي.') WHERE id = '8ad14916-224e-43df-b050-f067ba32923b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، تصل ذاكرة طفلكِ إلى مرحلة متقدمة من التطور. لذلك توجد بعض الأمور التي تتطلب منكِ مزيدًا من الانتباه. أصبح طفلكِ قادرًا على تذكّر معلومات محددة، مثل أماكن ألعابه. كما يمكنه تذكّر أحداث رآها منذ فترة وتقليدها. فمثلًا، إذا رآكِ تستخدمين الملعقة وقت الغداء، فقد يحاول في المساء تناول الطعام بملعقته بدلًا من استخدام يده. ويتذكّر الصندوق الذي تجمعين فيه ألعابه أو الدرج الذي تضعينها فيه، وقد يتحرك للوصول إليها عند أول فرصة. ورغم أن هذه تبدو علامات تطور مبهجة، فإنها تعني أيضًا دخوله مرحلة تنطوي على بعض المخاطر. فمثلًا، إذا رأى طفلكِ شخصًا يدخن، فقد يحاول لاحقًا تقليده بوضع شيء يشبه السيجارة في فمه. لذلك عليكِ أن تكوني أكثر انتباهًا من أي وقت مضى، وأن تبذلي قصارى جهدكِ لتكوني قدوة حسنة لطفلكِ.') WHERE id = 'e01a8401-6796-4fd1-8eb2-bb5e93fe04db';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'منذ فترة، لم يعد طفلكِ يقضي أيامه كما كان يفعل بعد ولادته، مكتفيًا بالأكل والنوم. لقد مرّت 9 أشهر كاملة منذ أن أبصر النور، وبدأ يومًا بعد يوم في أن يصبح أكثر تفاعلًا اجتماعيًا وأن يتواصل معكِ ومع الأشخاص المحيطين به بطريقة يمكنكِ ملاحظتها بوضوح. كما بدأ يكتسب عادات خاصة به، وهذا يعني أن شخصيته تتشكل بوتيرة أسرع. إذا لم يكن طفلكِ يمر بطفرة نمو أو مرحلة التسنين، ولم تكن لديه أي مشكلة صحية، فربما بدأ نومه الليلي ينتظم. ونظرًا إلى أنه ينفق طاقته بنشاط خلال النهار، فإنه عادةً لا يستيقظ ليلًا أو يستيقظ مرات قليلة جدًا. لذلك، إذا لم يكن روتين نوم طفلكِ قد استقر بعد، فنود تذكيركِ بأن هذه فترة مناسبة جدًا لتأسيسه. وقد يحتاج طفلكِ إلى مساعدتكِ في تحديد موعد نومه. فمثلًا، يمكنكِ اصطحابه إلى غرفته في الموعد نفسه كل يوم والبقاء بجانبه لبعض الوقت حتى ينام.') WHERE id = '4172e48e-6df4-4725-923e-07d5217e37c6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، يشكّل حليب الأم (أو الحليب الصناعي) 50% من تغذية طفلكِ اليومية، بينما تشكّل الأغذية التكميلية 50% الأخرى. إذا كنتِ تقدمين لطفلكِ الأغذية التكميلية مرتين يوميًا حتى الآن، فيمكنكِ زيادة العدد إلى ثلاث مرات. وإذا لم يوصِ الطبيب بخلاف ذلك، فلا مشكلة في السماح لطفلكِ بتناول الكمية التي يرغب فيها مع الانتباه إلى إشارات الشبع لديه. لكن مع زيادة كمية الأغذية التكميلية، قد تقل استفادته من حليب الأم إذا كنتِ ترضعينه طبيعيًا. ولتفادي ذلك، يمكنكِ إرضاع طفلكِ قبل موعد وجبة الطعام التكميلي بساعة واحدة على الأكثر. وتذكر بعض الأمهات أنهن يضفن القليل من حليبهن المسحوب إلى مهروس الخضراوات والفواكه الذي يحضّرنه. بهذه الطريقة تقدمين لطفلكِ وجبة مغذية، وقد يتناول الطعام المحضّر بهذه الطريقة بشهية أكبر.') WHERE id = 'da5cb5a7-cf3b-4e4d-80b2-ebbc83c6520d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطور الإدراك الانتقائي لدى طفلكِ بدرجة كبيرة. ونتيجة لذلك، أصبح قادرًا على تمييز مصدر الصوت حتى من دون أن يدير رأسه ويبحث عنه. وإذا لم يكن قد بدأ بذلك بعد، فقد يصبح ابتداءً من هذا الشهر متحفظًا تجاه الغرباء ويشعر بعدم الارتياح لوجودهم. قد يُظهر الأطفال في هذه المرحلة سلوكيات مختلفة ومثيرة للاهتمام، لكنهم عمومًا يشعرون بالقلق تجاه الأشخاص الذين لا يعرفونهم ويعبّرون عن ذلك بالبكاء. هذه مرحلة مؤقتة في حياة طفلكِ، وخلالها ينبغي ألا تجبريه على الاقتراب من الغرباء الذين يستجيب لوجودهم بالبكاء. خاصةً إذا شعر طفلكِ بعدم الارتياح عند دخول مكان ما ولم يرغب في أن يحمله أحد، فعليكِ احترام قراره والتأكد من احترام الآخرين له أيضًا. ومن الطبيعي تمامًا في هذه المرحلة ألا يرغب طفلكِ في وجود أحد بجانبه سواكِ ووالده. ومع ازدياد قلق الانفصال لديه، ننصحكِ بألا تتركيه وحده مدة طويلة، بل أن تبقي قريبة منه عند الحاجة.') WHERE id = '21e5fb9b-957f-4246-8c1d-e631e7b5dd81';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يمرض كثيرًا، فلا تلومي نفسكِ ولا تشعري بأنكِ مقصّرة. لأن جهازه المناعي لم يكتمل نموه بعد، فقد تتكرر إصابته بنزلات البرد والإنفلونزا. ويصاب معظم الأطفال بنزلات البرد نحو عشر مرات خلال العامين الأولين. قد تبدو هذه المرحلة صعبة في الأشهر الأولى، لكنها غالبًا لا تسبب لطفلكِ سوى شعور مؤقت بالانزعاج. ومهمتكِ لمساعدته على تجاوزها بأيسر طريقة هي توفير أكبر قدر ممكن من الراحة له. فمثلًا، يحتاج جسم طفلكِ إلى مزيد من النوم أثناء المرض، وقد يساعده تدليك لطيف ومريح بعد الاستحمام على الخلود إلى النوم بسهولة أكبر. وإذا كان أنفه مسدودًا، فلا تضعي وسادة تحت رأسه ولا ترفعيه أثناء النوم؛ ضعيه على ظهره فوق سطح مستوٍ وصلب وخالٍ من الوسائد والأغراض، ويمكنكِ استخدام قطرات المحلول الملحي المناسبة للرضّع بعد استشارة الطبيب. وتذكّري أن حاجة طفلكِ إلى السوائل تزداد أثناء نزلة البرد، لذا احرصي على حصوله على ما يكفي من السوائل المناسبة لعمره، إلى جانب حليب الأم (أو الحليب الصناعي).') WHERE id = '0c97a7c0-87cb-4c6d-bccc-18d59ae9a64f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نظرًا إلى التقدم الكبير في مهارات طفلكِ الحركية وحواسه وتطوره الذهني، فقد دخل مرحلة سيكون فيها شديد النشاط. وفي هذه المرحلة، قد يكتسب مهارات جديدة، منها الإمساك بكل ما تصل إليه يداه. وقد يبدأ بهزّ كل غرض يملك القوة لرفعه، وضرب الأشياء بعضها ببعض، وإسقاطها على الأرض أو رميها. وعندما يدرك أنه قادر على التأثير في الأشياء بهذه القوة، فقد يكرر الحركات نفسها مدة طويلة من دون ملل. لذلك تذكّري أنكِ في مرحلة تتطلب منكِ قدرًا كبيرًا من الانتباه. تحدث نسبة كبيرة من إصابات الرأس خلال هذه الأشهر، لذا يمكنكِ وضع بعض الحدود الآمنة لطفلكِ داخل المنزل. فمثلًا، لا تسمحي له بالخروج وحده من الغرفة التي توجدين فيها، ويمكنكِ البدء بإبعاد الأغراض الموجودة في الغرفة التي يُحتمل أن تسبب له الأذى.') WHERE id = 'af4167d5-e075-447d-a653-bf92fb79d76e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تظل سرعة نمو طفلكِ هذا الشهر مماثلة تقريبًا للشهر الماضي. فلا تقلقي إذا لم يعد ينمو بالسرعة نفسها التي كان ينمو بها خلال الأشهر الأولى. ونظرًا إلى أن طفلكِ أصبح كثير الحركة، فقد يزداد وزنه خلال هذا الشهر بمعدل يتراوح بين 300 و500 غرام. ووفقًا لمنظمة الصحة العالمية، يبلغ متوسط وزن الطفل في عمر 10 أشهر نحو 8800 غرام. لكن هذا الرقم قد يختلف تبعًا لجنس طفلكِ ومستوى نشاطه ووزنه عند الولادة وخصائص نموه. أي إن وزن طفلكِ قد يبلغ 6500 غرام، وقد يتجاوز أيضًا 12500 غرام. وابتداءً من هذا الشهر، يستمر طول طفلكِ في الازدياد بمعدل 1 سم تقريبًا، كما ينمو محيط رأسه بالمعدل نفسه.') WHERE id = '789568fd-44f2-4cb3-9877-cd0130c94687';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن نشيطًا للغاية، فلا تنتهي ابتساماته وتقلباته وحبوه ومحاولاته للكلام! 😊 ومنذ لحظة ولادته، تدهشكِ المهارات الجديدة التي يكتسبها وتملؤكِ حماسًا وسعادة. ومحاولاته للوقوف ومرحلة استعداده للمشي من بين هذه التطورات المثيرة أيضًا... وكما هو الحال دائمًا، تظلين أنتِ وزوجكِ أكبر داعمين لطفلكِ في هذه المرحلة. ويمكنكما مساعدته على الاستمتاع أكثر بمرحلة تعلم المشي وتشجيعه على اتخاذ خطواته بشجاعة وثقة. ومع مراعاة الحوادث البسيطة التي قد تقع خلال هذه الفترة، من الضروري اتخاذ بعض تدابير السلامة. ويمكنكِ البدء، مثلًا، بعدم ترك طفلكِ بمفرده في الأماكن المرتفعة، كالسرير وطاولة تغيير الحفاضات والأريكة، من دون اتخاذ الاحتياطات اللازمة. 😊') WHERE id = 'b038be51-87de-40aa-81e8-34eb440fed27';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن يستمر طفلكِ في هذه المرحلة في تناول حليب الأم أو الحليب الصناعي من 3 إلى 5 مرات يوميًا. وتذكّري أنه لا يزال بحاجة إلى بعض الوقت قبل الانتقال بالكامل إلى الأطعمة الصلبة. ويمكنكِ خلال هذه الفترة إعداد نظام غذائي تكميلي لطفلكِ يتكوّن من 3 وجبات رئيسية و3 وجبات خفيفة. وإذا كنتِ ترضعينه طبيعيًا، فيمكنكِ إرضاعه بقدر ما يرغب خلال اليوم. أما الأطفال الذين يتغذون على الحليب الصناعي، فيكفيهم تناول 200 مل منه ثلاث مرات يوميًا على الأقل. وقد تعتقد بعض الأمهات أن أطفالهن يحصلون بالفعل على ما يكفي من حليب الأم، فيرغبن في تقليل الرضاعة تدريجيًا. لكن هذا اعتقاد خاطئ، إذ لا يزال طفلكِ قادرًا على الاستفادة كثيرًا من حليبكِ. وتغيّر الغدد الثديية تركيبة حليبكِ بما يتناسب مع نمو طفلكِ؛ فمثلًا تكون نسبة الدهون في حليبكِ خلال هذه الأشهر أعلى بكثير مقارنةً بالأشهر الأولى.') WHERE id = '40235f48-568d-4e7c-b429-24fa27331c60';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تزداد شهية طفلكِ فجأة أو تنعدم أحيانًا، وقد لا يرغب في النوم إطلاقًا أو ينام لساعات طويلة، بل قد يتغير مزاجه فجأة أيضًا. إذا بدت لكِ هذه الحالات مألوفة، فلها سبب واحد: ما زلتما تمرّان بمرحلة طفرة النمو! قد تبدو هذه المرحلة، التي تُسمى مرحلة "الأزمة" أو "الطفرة" أو "النمو"، مخيفة بسبب اضطراب الروتين خلالها. لكن لكل ذلك سبب؛ ففي كل طفرة نمو، يكتسب طفلكِ مهارات جديدة وتتطور قدراته الذهنية. وباختصار، يمكننا القول: "النمو ليس سهلًا!" لذلك يمكنكِ اجتياز هذه المراحل براحة أكبر من خلال التركيز على جوانبها الإيجابية والمهارات الجديدة التي سيكتسبها طفلكِ. فعلى سبيل المثال، قد يبدأ طفلكِ خلال طفرة النمو هذه بالشعور بالغيرة عليكِ. يبدو ذلك لطيفًا جدًا، أليس كذلك؟ قد ينزعج طفلكِ عندما تقبّلين زوجكِ لدى عودته من العمل، لأنه لا يريد مشاركتكِ مع أي شخص آخر.') WHERE id = 'b4a75895-ae96-4823-9d66-151563acf366';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تقدّمي لطفلكِ خلال هذا الشهر ما لا يقل عن 500 مل من حليب الأم يوميًا. وفي حال تعذّر توفير حليب الأم، عليكِ استشارة طبيبكِ لاختيار أنسب حليب متابعة صناعي له. لقد تطور جهاز طفلكِ الهضمي إلى حد كبير، وأصبح قادرًا على التكيف مع الانتقال من الأطعمة السائلة إلى الصلبة. ومع ذلك، ينبغي ألا يتناول يوميًا أكثر من كمية تعادل 3 عبوات من طعام الأطفال التكميلي، حتى لا تُجهَد أمعاؤه. فقد يؤدي تقديم كمية أكبر من الطعام التكميلي إلى منعه من الحصول على ما يكفي من حليب الأم، وهو غذاؤه الأساسي. وبعد تحقيق التوازن بين الأطعمة الصلبة وحليب الأم، أو حليب المتابعة الصناعي في حال عدم توفره، عليكِ إعداد نظام غذائي مثالي يساعد طفلكِ على النمو بصحة جيدة. ولا تقل أهمية الطريقة الصحية لإعداد الطعام عن كميته. لذلك، عند تحضير وجبات طفلكِ، اختاري طرق الطهي الصحية مثل الطهي على البخار أو السلق أو الخَبز في الفرن.') WHERE id = '2fad46fb-e452-4335-9758-a95de808e8f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يحبو طفلكِ منذ مدة، وربما بدأ يشعر بالملل من البقاء في المكان نفسه طوال الوقت. وعندما يرى جميع من حوله يمشون، سيبدأ هو أيضًا في محاولة النهوض والوقوف. وفي البداية، سيحاول الوقوف مستندًا إلى شيء ما. وقد لا تنجح محاولاته لبعض الوقت، أو ربما ينجح من المحاولة الأولى. فهذا يختلف تبعًا لخصائص نمو كل طفل وبيئته. وستلاحظين أن طفلكِ يحاول أولًا الوقوف مستندًا إلى قطع الأثاث القريبة. وعندما يدرك أنه قادر على ذلك، سيحاول الوقوف من دون مساعدة، لكنه لا يزال بحاجة إلى بعض الوقت لتحقيق ذلك. ولدعم طفلكِ خلال هذه المرحلة، يمكنكِ وضع ألعاب تجذب اهتمامه فوق أشياء يستطيع التمسك بها، مثل المقعد أو الكرسي.') WHERE id = '02985c47-f203-4125-957b-15eb60906ec2';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون تغيير ملابس طفلكِ كثير الحركة، الذي لا يهدأ ويتمتع بطاقة لا تنفد، أمرًا مرهقًا لكِ كما هو الحال لدى الأمهات الأخريات. فعلى الأرجح لا يحب طفلكِ ارتداء الملابس، وقد تتحول كل مرة تغيّرين فيها ملابسه إلى مباراة مصارعة بينكما. 😊 هناك بعض الحيل التي قد تساعدكِ على التعامل مع هذا الوضع. بما أن طفلكِ بدأ بتناول الأطعمة التكميلية، فمن الطبيعي أن تتسخ ملابسه كثيرًا. لذلك، فإن اختيار أقمشة لا تحتفظ بالبقع عند شراء الملابس سيسهّل عليكِ الأمر كثيرًا. ولتشتيت انتباهه أثناء إلباسه، يمكنكِ إعطاؤه لعبته المفضلة أو غرضًا يثير اهتمامه. ومن المفيد أيضًا الحرص على أن تكون فتحة الرأس في القمصان التي تشترينها واسعة أو مصنوعة من قماش مرن قابل للتمدد.') WHERE id = '80933d1b-7705-420b-8df2-38fff58443d1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'العناية بالأسنان مهمة لطفلكِ بقدر أهميتها للجميع. ومن الضروري خصوصًا أن تنمو الأسنان الحديثة الظهور بصحة جيدة، لما لذلك من أهمية كبيرة لمستقبله. ولمساعدة طفلكِ على اكتساب عادة تنظيف أسنانه، ينبغي البدء من الآن وجعلها جزءًا من روتينه اليومي. قد تراودكِ في البداية بعض الأسئلة حول كيفية العناية بأسنانه. عند ظهور سن طفلكِ الأولى، يمكنكِ تنظيفها باستخدام قطعة من الشاش أو فرشاة إصبع. وبعد بلوغه عمر 1 سنة، يمكنكِ إعطاؤه فرشاة أسنان والوقوف أمامه لتريه كيفية استخدامها. وحتى إن لم يتمكن طفلكِ من ذلك في البداية، فسيتعلمه خلال وقت قصير من خلال تقليدكِ. لكن تذكّري أنه لا يزال من المبكر استخدام معجون الأسنان.') WHERE id = '37f66307-1b67-498c-b0b6-20e87a8898b8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي لكِ اتخاذ بعض الاحتياطات لحماية طفلكِ كثير الحركة من الحوادث. فعلى سبيل المثال، عليكِ جمع الأدوية المتساقطة على الأرض وحبات المكسرات والأزرار المنفصلة والعملات المعدنية وغيرها من الأشياء الصغيرة، والحذر من احتمال ابتلاع طفلكِ لها. كما قد تشكل الزوايا الحادة للأثاث، مثل الطاولات وطاولات القهوة، خطرًا على طفلكِ الذي يحاول الوقوف مستندًا إلى الأشياء. لذلك، يمكنكِ إخراج قطع الأثاث هذه من الغرفة التي يوجد فيها طفلكِ أو تغطية زواياها بواقيات خاصة. وبما أن طفلكِ يحب استكشاف كل شيء، يمكنكِ تركيب أغطية واقية للمقابس الكهربائية. وعليكِ أيضًا إبعاد سلال الألعاب العميقة التي قد يسقط داخلها، والأكياس البلاستيكية التي قد يضعها فوق رأسه، والأسلاك التي قد تسبب الاختناق. كذلك، يساعد إبقاء الأبواب مغلقة وتركيب أقفال أمان على النوافذ والخزائن والأدراج في إزالة المخاطر المحتملة.') WHERE id = '6dba7d69-27ca-40ac-b3c1-c74bcff813bb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هرس البطاطا التي أمضيتِ وقتًا في طهيها، ووضع يده في الحساء، ورمي الجزر الذي قدمتِه له على الأرض... هل تبدو لكِ كل هذه الأمور مألوفة؟ لا تقلقي، فلستِ وحدكِ في ذلك! 😊 في هذه المرحلة، قد لا يكون تناول الطعام بالنسبة إلى طفلكِ مجرد وسيلة للشبع، بل قد يتحول أيضًا إلى لعبة. وقد يحيركِ أن يتناثر الطعام الذي أعددتِه بعناية في كل مكان بدلًا من أن يصل إلى معدته. لكن إبداء رد فعل قاسٍ تجاه طفلكِ بسبب ذلك قد يجعله ينفر من الطعام. لذا، قد ترغبين في أخذ الطعام من أمامه وإطعامه بنفسكِ. ومع ذلك، تذكّري أن كل هذا جزء من مرحلة طبيعية، وأن طفلكِ يتعلم أشياء جديدة بفضل هذه الاستكشافات.') WHERE id = 'cffb22db-240d-4023-8834-7c4c580e8149';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، تبلغ سعة معدة طفلكِ في المتوسط نحو 230 ml. لذلك، لا داعي للقلق والاعتقاد بأنه لا يأكل بما يكفي. فما زال طفلكِ يحتاج إلى تناول كميات صغيرة من الطعام على فترات متكررة، ولن يتمكن من إنهاء كل ما أعددتِه دفعة واحدة. وبدلًا من محاولة إطعامه كميات كبيرة، يمكنكِ وضع نظام غذائي متوازن يعتمد على أطعمة ذات قيمة غذائية عالية. فعلى سبيل المثال، يحتاج طفلكِ خلال هذه الفترة إلى 1.02 غرام من البروتين يوميًا لكل كيلوغرام من وزنه. وهذا يعني أن الطفل الذي يبلغ متوسط وزنه 9000 غرام يحتاج إلى تناول 9.2 غرام من البروتين يوميًا. ويحتوي كل 100 غرام من حليب الأم على نحو 1 غرام من البروتين. وقد تختلف هذه النسبة في الحليب الصناعي. كما يمكنكِ تلبية احتياجات طفلكِ اليومية من البروتين من خلال البقوليات ومنتجات اللحوم.') WHERE id = '338a7b7c-cd77-4384-ba83-6dc7af52489b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ قلقة لأن طفلكِ لا يستطيع الوقوف بعد ولم يحاول المشي، فاعلمي أنه لا داعي لهذا القلق. يختلف العمر الذي يبدأ فيه كل طفل بالمشي، لذلك لا يمكن تسريع هذه العملية أو اختصارها. وقد يستمتع طفلكِ كثيرًا عندما تمسكين بذراعيه وتساعدينه على الوقوف على قدميه ومحاولة اتخاذ خطوات. يمكنكِ القيام بهذه الحركات لفترة قصيرة على هيئة لعبة، لكن لا ينبغي أن تتوقعي منه الوقوف أو المشي مبكرًا. لا ينصح الأطباء عادةً بتعريض ساقي الطفل لضغط مستمر قبل بلوغه عمر 1 سنة، أو تدريبه على اتخاذ خطوات أثناء إبقائه واقفًا. فهذه التمارين لا تفيد النمو العضلي العام للطفل، بل قد تؤدي أيضًا إلى بعض الاضطرابات التشريحية. لذلك، ننصحكِ بعدم الضغط على طفلكِ كثيرًا في هذا الأمر.') WHERE id = '4cd9c678-a1f8-4663-9ede-462dc0cff3d9';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض الأطعمة التي ينبغي عدم تقديمها لطفلكِ لفترة إضافية حفاظًا على صحة أمعائه. ويُعد تجنّب هذه الأطعمة أحد العوامل التي تساعد على تقليل خطر الإصابة بالحساسية إلى أدنى حد. فعلى سبيل المثال، تُعد المكسرات والبذور الزيتية المفيدة جدًا، مثل البندق والفول السوداني والكاجو واللوز والجوز، من الأطعمة التي يصعب امتصاصها في أمعاء طفلكِ وهضمها. كما ينبغي تجنّب مجموعة أخرى من الأطعمة، مثل الباذنجان والفول، لأنها قد تُسبب بعض التأثيرات السامة في جسم طفلكِ. ومهما أحب طفلكِ الحلويات والأطعمة السكرية، فإنها تُعد مصدرًا لـ«السعرات الحرارية الفارغة» التي تكاد تخلو من أي قيمة غذائية له. لذلك، كلما تأخرتِ في تعريف طفلكِ على الأطعمة التي تحتوي على هذه السعرات الحرارية الفارغة، كان ذلك أفضل لصحته. إضافةً إلى ذلك، ينبغي ألا تقدّمي لأمعائه التي لا تزال في طور النمو منتجات اللحوم المصنّعة، مثل النقانق والسجق، لما قد تحمله من خطر الإصابة بداء المقوسات.') WHERE id = 'ac0487c0-d4c6-4175-ad05-4bab8a727217';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ينبغي أن تمنحي طفلكِ في هذه المرحلة فرصة للتعرّف على مفهوم التصنيف. يبدأ بعض الأطفال بتعلّم التجميع من خلال الأشياء، بينما يتعلّمه آخرون من خلال الأشخاص الذين يرونهم كثيرًا من حولهم. وبعد أن يكتشف طفلكِ فئة أو فئتين أساسيتين، سيصبح تعلّم الباقي أسهل بكثير بالنسبة إليه. وبينما يحاول طفلكِ خلال هذه الفترة فهم معنى التجميع، يبدأ أيضًا باكتشاف خصائص هذه العناصر في ذهنه. فعلى سبيل المثال، عندما يبدأ طفلكِ بتصنيف الأطعمة، سيتعلّم من تلقاء نفسه أن بعضها يؤكل بالشوكة وبعضها الآخر باليد. وفي هذه المرحلة، يحاول طفلكِ التعرّف على الأشياء التي يرغب في استكشافها من خلال لمسها بيديه. وهكذا، يستطيع تصنيفها وفق خصائص مثل الخشونة واللزوجة والبلل والصلابة والليونة. ويمكنكِ خلال هذه الفترة دعم هذا الجانب من نمو طفلكِ من خلال تعريفه على أشياء مختلفة! 😊') WHERE id = '12e7c82f-2e58-40ab-94b2-fcc7a8bcfde0';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض الأمور التي ينبغي أن تنتبهي إليها لدعم نمو طفلكِ كثير الحركة وحمايته من المخاطر المحتملة. فعندما يستيقظ طفلكِ الآن، قد يرغب في النهوض من سريره بمفرده. لذلك، قد يكون من المفيد اختيار سرير منخفض ووضع سجادة ناعمة أو قطعة إسفنج بجانبه لحمايته عند السقوط. ويجب الانتباه إلى أن الأسرّة المرتفعة تزيد من خطر تعرض طفلكِ لإصابات في الرأس إذا سقط منها. وإذا كان يحاول منذ فترة الوقوف مستندًا إلى ما حوله، فعليكِ أيضًا إزالة الأشياء القابلة للسقوط والموضوعة فوق المفارش التي يستطيع الوصول إليها من مكانه. وإذا كانت الأبواب والنوافذ في أماكن يمكن لطفلكِ الوصول إليها بطريقة ما، فيمكنكِ تركيب أدوات حماية أو مصدّات عليها. وإذا كان طفلكِ، مثل سائر الأطفال، يحب العبث بالأدراج، فيمكنكِ إزالة مقابض الأدراج التي يفتحها ويتسلقها مؤقتًا. ولضمان سلامة طفلكِ، عليكِ إزالة الطاولات الزجاجية وقطع الأثاث المنخفضة ذات الزوايا الحادة، وكذلك التحف الصغيرة والإكسسوارات الموضوعة على الرفوف السفلية التي قد يتمكن من ابتلاعها.') WHERE id = '2dd356c6-11e2-445d-9935-897ed781f383';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل تتساءلين عن الأنشطة المناسبة للنمو الذهني لطفلكِ التي يمكنكما ممارستها معًا؟ هناك وسائل تخاطب حواسه وتتيح لكما في الوقت نفسه قضاء وقت ممتع ومفيد معًا. فعلى سبيل المثال، قد تكون الكتب المصوّرة والتفاعلية التي تصدر أصواتًا وتتضمن عناصر متحركة، والمتوفرة في الأسواق، هي الوسيلة التي تبحثين عنها تمامًا! ستجذب الصور الموجودة في الكتاب انتباه طفلكِ، ويمكنكِ عندها البدء بشرح معانيها له. وإضافةً إلى ذلك، يمكنكِ خلال هذه الفترة قراءة حكايات مختلفة لطفلكِ، ولا سيما عند الاستعداد للنوم. وبما أن طفلكِ لا يدرك معاني الكلمات بالكامل بعد، فقد لا يفهم دائمًا ما تقولينه، وقد يملّ أحيانًا من الاستماع إليكِ. لذلك، ننصحكِ بمواصلة القراءة له بصبر. فجلسات القراءة هذه ستكون بداية رائعة تساعد طفلكِ على حب الكتب في المستقبل.') WHERE id = '55011ab1-9f0a-4b61-aab6-1ab8d3c3412e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كنتِ ترضعين طفلكِ رضاعة طبيعية أو تقدمين له الحليب الصناعي، فلا يزال الحليب في هذه المرحلة يوفر نحو نصف احتياجاته اليومية من السعرات الحرارية. وتتكون القيمة الغذائية لحليب الأم في المتوسط من 88% ماء و55% دهون و37% كربوهيدرات و8% بروتين. ويحتوي حليبكِ بصورة أساسية على نوع من الكربوهيدرات يُسمى اللاكتوز. وتوفر هذه المادة نحو 40% من السعرات الحرارية التي يحصل عليها طفلكِ من الحليب. وإلى جانب كون هذا النوع من الكربوهيدرات مصدرًا غنيًا بالطاقة، فإنه يُنشئ أيضًا بيئة حمضية في أمعاء طفلكِ تحدّ من تكاثر البكتيريا الضارة. كما يدعم تكوّن ميكروبيوم معوي متوازن من خلال تسريع نمو البكتيريا النافعة في الأمعاء. لذلك، من المهم أن تواصلي إرضاع طفلكِ، الذي لا يزال في مرحلة نمو سريع، لأطول مدة ممكنة. وفي حال عدم توفر حليب الأم، يوصي المختصون بمواصلة تقديم تركيبات الحليب المخصصة للمرحلة التالية بالطريقة نفسها حتى يبلغ طفلكِ عمر سنة واحدة على الأقل.') WHERE id = '005de367-3aa8-4500-87f0-c7f5b37b1fe4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'كم نما طفلكِ بسرعة كبيرة، أليس كذلك؟ عندما تنظرين إلى الوراء، تدركين أنكما قطعتما شوطًا طويلًا، ومع ذلك مضى الوقت سريعًا كالماء الجاري. لم يمضِ عام واحد بعد على ولادة طفلكِ، لكنه أحرز خلال هذه الفترة تطورًا مذهلًا. فعلى سبيل المثال، انتقل طفلكِ من مرحلة البكاء إلى إصدار الأصوات، ثم من تلك الأصوات إلى نطق كلمات ذات معنى. وها هو موعد الكلام يقترب أكثر فأكثر. ويمكنكِ مساعدته على الاستعداد لهذه المرحلة التي تقترب سريعًا. فعلى سبيل المثال، يمكنكِ تسمية كل شيء تستخدمانه أو تصادفانه، سواء كنتما في المنزل أم خارجه. ويمكنكِ أيضًا استخدام بعض التشبيهات لمساعدة طفلكِ على تذكّر أسماء تلك الأشياء بسهولة أكبر. فمثلًا، عندما ترين كلبًا، يمكنكِ الإشارة إليه وقول «كلب»، ثم تقليد نباحه بقول «هو هو».') WHERE id = '19fabca3-1b22-4b94-9659-be47ebeb9069';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يواصل طفلكِ النمو والتطور بسرعة. وقد تلاحظين أنه في هذه المرحلة أكثر حركة من أي وقت مضى. ولضمان النمو الصحي لطفلكِ، الذي أصبح يحب اللعب كثيرًا، يُتوقع أن تكون مهاراته اللغوية والعقلية والحركية الدقيقة والكبيرة، إلى جانب مهاراته الاجتماعية، ملائمة لعمره. وتُعد الأنشطة المناسبة لعمره التي تمارسينها معه في كل مرحلة من أهم العوامل الداعمة لهذا التطور. نعلم أنكِ تحبين طفلكِ كثيرًا وترغبين في حمايته من جميع المخاطر المحتملة. لكن اتباع نهج أبوي مفرط في الحماية يشكّل عائقًا كبيرًا أمام نموه. فعلى سبيل المثال، عدم تركه يتحرك بحرية في الخارج خوفًا من سقوطه قد يبطئ نموه ويجعله يشعر بعد مدة بأنه غير قادر على الاعتماد على نفسه. لذلك، عليكِ السماح له بممارسة الأنشطة التي تساعده على اكتساب المهارات المناسبة لمرحلة نموه، وتجنّب التدخل ما لم يكن ذلك ضروريًا.') WHERE id = '037a24b5-120f-42ab-b763-b5da751da157';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تتغير الألعاب المناسبة لطفلكِ في كل مرحلة بما يتوافق مع تطوره والمهارات الجديدة التي يكتسبها. فعلى سبيل المثال، قد يكون شراء أقلام تلوين وكتب تلوين فكرة رائعة لطفلكِ الذي بدأت مهاراته الحركية الدقيقة في التطور خلال هذه المرحلة! 😊 فهذه الأنشطة لا تمنحه الكثير من المتعة فحسب، بل تساعده أيضًا على فهم كيفية استخدام أصابعه بصورة أفضل، ما يطوّر مهاراته الحركية الدقيقة ويعزز إبداعه. وإلى جانب ذلك، يمكنكِ اختيار مكعبات ليغو كبيرة الحجم لا يستطيع طفلكِ ابتلاعها، وألعاب قابلة للفك والتركيب لدعم نموه العقلي. وفي هذه المرحلة، يحب طفلكِ قضاء الوقت معكِ بقدر ما يحب اللعب بألعابه. لذلك، يمكنكما الوقوف معًا أمام المرآة وتقليد تعبيرات وجه مضحكة. وهكذا سيستمتع طفلكِ كثيرًا، كما ستتاح له فرصة اكتشافكِ واكتشاف نفسه ومحيطه بمزيد من التفصيل. نتمنى لكما وقتًا ممتعًا! 😊') WHERE id = '27c8f700-edb4-4233-8b6f-05e91bb19bd4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد التهاب الأذن من أكثر المشكلات شيوعًا لدى الرضع، وقد يسبب ألمًا في أذن طفلكِ ويجعله منزعجًا. ومن المهم جدًا أن تعرفي أعراضه لتتمكني من ملاحظة إصابة طفلكِ به. إذا ظهرت عليه أعراض مثل الانزعاج أو البكاء أو الحمى أو خروج إفرازات من الأذن أو صعوبة الحفاظ على توازنه أثناء الجلوس، فقد تحتاجين إلى التواصل مع طبيبكِ في أقرب وقت ممكن. كما أن شد طفلكِ لأذنه باستمرار أو الإمساك بها بيديه من أكثر العلامات شيوعًا لالتهاب الأذن. ولحماية طفلكِ من التهاب الأذن، وهو حالة قد تكون مؤلمة جدًا، عليكِ الاهتمام بالرضاعة الطبيعية أو الحليب الصناعي على النحو المناسب. وبالإضافة إلى ذلك، اختاري ضمن وجبات الأغذية التكميلية أطعمة غنية بالمعادن والفيتامينات التي تدعم مناعته. واحرصي على عدم تأخير لقاحاته الروتينية، وأبعديه عن الأماكن شديدة الضوضاء وعن البيئات التي يوجد فيها دخان السجائر.') WHERE id = '5293d4ac-e8d7-4284-a254-315f58215b5f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تكتسب نوعية غذاء طفلكِ ونظام تغذيته أهمية كبيرة لنموه الجسدي والعقلي. يحتاج طفلكِ في كل وجبة إلى حليب الأم والأطعمة الصلبة، وفي حال تعذّر تقديم حليب الأم، ينبغي الاستمرار في إعطائه الحليب الصناعي. خلال هذا الشهر، يجب ألا تتجاوز كمية الأطعمة الصلبة التي يتناولها طفلكِ 3 أكواب شاي صغيرة. وبما أن سعة معدته حاليًا تتراوح بين 230-250 ml، فهذا لا يعني أنه سيتناول حصصًا كبيرة جدًا. ومن الطبيعي أن يرفض بعض الأطفال الأغذية التكميلية لبعض الوقت. لكن إذا استمر هذا الوضع بدءًا من الشهر 8، فقد تحتاجين إلى طلب الدعم من مختص. إذا كان طفلكِ يمر بهذه الحالة، فيمكنكِ إعطاؤه كمية قليلة من الطعام التكميلي ثم تقديم الحليب له أو إرضاعه. وبعد فترة قصيرة، يمكنكِ تقديم كمية إضافية صغيرة من الطعام التكميلي حتى يعتاد طفلكِ على هذا النمط من التغذية المختلطة.') WHERE id = 'c996cd60-4f83-4508-84b8-0749f1791d8f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد حليب البقر والبيض والفول السوداني والقمح وبعض أنواع الأسماك من الأطعمة التي تسبب الحساسية الغذائية الشائعة لدى الرضع. وتُعد حساسية البيض واحدة من أكثر أنواع الحساسية الغذائية شيوعًا لديهم بعد حساسية حليب البقر، وقد تظهر على أجسامهم بأشكال مختلفة جدًا. كما تُعد حساسية الفول السوداني من أنواع الحساسية الغذائية الشائعة بين الرضع، وقد يعاني الأطفال المصابون بها أيضًا من حساسية تجاه البقوليات عمومًا. أما حساسية القمح، فعلى الرغم من الخلط بينها عادةً وبين عدم تحمّل الغلوتين، فإنهما حالتان مختلفتان. وقد تظهر هذه الحساسية لدى بعض الأطفال، لكنها تزول تمامًا في المتوسط بحلول عمر 3 سنوات. في المقابل، لا تختفي حساسية الأسماك بعد مدة محددة كما قد يحدث مع أنواع أخرى من الحساسية، وتشير النتائج العامة إلى أنها قد تستمر مدى الحياة. ويُعد سمك السلمون والتونة من أكثر الأنواع تسببًا في حساسية الأسماك. إذا كنتِ أنتِ أو زوجكِ تعانيان من أي من أنواع الحساسية المذكورة، فعليكِ إبلاغ الطبيب المتابع لحالة طفلكِ بذلك، وإيلاء تغذيته اهتمامًا أكبر من المعتاد.') WHERE id = '4a785b8e-be1a-4a99-b508-d2a08ac29f86';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هل بدأتِ التحضير لعيد الميلاد؟ 😊 أوشكت السنة الأولى التي قضاها طفلكِ معكِ على الانتهاء. لذلك، إذا كنتِ تفكرين في إعداد احتفال بعيد ميلاده يرضيكِ ويُسعدكِ، فننصحكِ ببدء التحضيرات من الآن. وبالطبع، ستكون أولويتكِ الأساسية عند البدء هي العمل وفق خطة وبرنامج منظّمين. لذا يمكنكِ في بداية الطريق التفكير في الميزانية التي ستخصصينها للاحتفال. تتوفر في الأسواق منتجات بتصاميم متنوعة جدًا لمفاهيم حفلات أعياد الميلاد، وبأسعار تناسب مختلف الميزانيات. ومن خلال التخطيط السليم، يمكنكِ تنظيم احتفال يعجبكِ من دون إرهاق ميزانيتكِ. كما أن إعداد قائمة بالمدعوين سيساعدكِ كثيرًا على حساب تكلفة المنتجات التي ستشترينها والأطعمة التي ستحضّرينها بسهولة.') WHERE id = 'd15257f7-39ad-4735-966b-96fe4a154fa1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من الطبيعي تمامًا ألا يرغب طفلكِ في تناول بعض الخضراوات المفيدة، خصوصًا خلال مرحلة البدء بالأطعمة الصلبة، فقد تشكلت حاسة التذوق لديه منذ مدة، ولذلك قد يرفض الأطعمة التي لا يحب مذاقها. في مثل هذه الحالات، يوصي بعض الأطباء بالاستعانة بحليب الأم أو الحليب الصناعي الذي يعرفه طفلكِ جيدًا. وهكذا يؤدي الحليب دورًا في تحسين النكهة، ما قد يساعد طفلكِ على تناول الأطعمة التي كان يرفضها. ولتطبيق ذلك، يمكنكِ أولًا إضافة كمية صغيرة جدًا من الطعام الذي يرفضه إلى الحليب، بحيث لا تغيّر مذاقه، ثم زيادة الكمية تدريجيًا مع مرور الوقت. على سبيل المثال، إذا كان طفلكِ لا يحب الجزر، فيمكنكِ تجربة هذه الوصفة: اخلطي كمية من الماء الفاتر مع دقيق الشوفان واطهي المزيج. بعد أن يصبح قوامه كثيفًا، أضيفي الزبدة، وعندما يبرد قليلًا خففي قوامه بحليب الأم أو الحليب الصناعي. وعلى الأرجح لن يلاحظ طفلكِ كمية الجزر الصغيرة التي ستضيفينها إليه. بالهناء والشفاء!') WHERE id = 'b6baae80-bfde-4969-a04d-a53ffef941a8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع مرور الوقت، وإذا لم يكن طفلكِ يعاني من أي مشكلة، فسيصبح نظام نومه أكثر انتظامًا. وإذا كان نوم طفلكِ يتقطع كثيرًا ويجد صعوبة في العودة إلى النوم، فلدينا خبر سار لكِ: اعتبارًا من هذا الشهر، لن يتقطع نومه إلا نادرًا! 😊 وهناك أسباب كثيرة لانتظام هذا الروتين؛ فعلى سبيل المثال، أصبحت مراحل النوم في دماغ طفلكِ تستغرق وقتًا أطول حتى تكتمل. وهذا سيساعده على الاستيقاظ مرات أقل، خصوصًا ليلًا، والعودة إلى النوم بسهولة أكبر عند استيقاظه. وقد يواجه طفلكِ أحيانًا صعوبة في الاستغراق في النوم خلال فترات طفرات النمو أو في الأيام التي يشعر فيها بالانزعاج لسبب آخر. إذا واجهتِ هذا الموقف، فننصحكِ بتهدئته وقضاء بعض الوقت معه في غرفة ذات إضاءة خافتة نسبيًا. كما أن إعطاءه حمامًا دافئًا ومريحًا قبل النوم، ثم تدليكه بالزيوت، سيساعدانه على الاستغراق في النوم بسهولة أكبر.') WHERE id = '9263dfdf-7d11-40a3-a89c-aa51842213c4';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'العناية بأسنان طفلكِ مهمة جدًا. ولأن أسنانه شديدة الحساسية، فعليكِ اختيار المنتجات التي ستستخدمينها للعناية بها بعناية. أولًا، احرصي عند اختيار فرشاة الأسنان على أن تكون مناسبة لفم طفلكِ؛ فالفرش المصنوعة للبالغين لا تناسب فمه مهما كانت جودتها عالية. كذلك، ما دامت لثة طفلكِ شديدة الحساسية، فعليكِ اختيار فرشاة ذات شعيرات ناعمة. وقد تكون فرش الأسنان المخصصة للرضع، والتي تُلبس على الإصبع، مفيدة جدًا لكِ خلال هذه المرحلة. وإذا كان طفلكِ لا يحب تنظيف أسنانه، فيمكنكِ استخدام ألعابه المفضلة لجذب انتباهه أثناء العناية بها. وإلى جانب العناية بصحة فمه في المنزل، من المهم جدًا اصطحابه بانتظام إلى طبيب الأسنان الذي يوصي به طبيبه، حتى يتمتع بأسنان صحية في المستقبل.') WHERE id = '56bcb0b3-2ef0-42fc-b5f4-45a3b8d99519';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن يرى ما حوله بوضوح كبير، بل يمكنه خلال هذا الشهر تمييز الأشخاص الذين يعرفهم من مسافة تقارب 5-6 أمتار. وإلى جانب التطور الملحوظ في قدرته على الحركة، أصبحت مهارة الاستماع لديه أكثر انتباهًا وتركيزًا. ونتيجة لذلك، باتت حواس طفلكِ تعمل بتناغم مع بعضها. فعندما يتحدث شخص ما مثلًا، يستطيع طفلكِ مراقبته ومتابعة كلامه في الوقت نفسه. ويُعد ذلك من أهم العوامل التي تساعده على فهم ما يحدث حوله بصورة أدق، كما سيعزز التواصل بينكما. خلال هذه المرحلة، لن تحتاجي إلى بذل جهد كبير حتى يستمع إليكِ أو لجذب انتباهه. وعندما تريدين توضيح شيء له، أو عندما يقوم بتصرف قد يكون خطيرًا، يمكنكِ النزول إلى مستوى عينيه والتحدث إليه وأنتِ تنظرين مباشرة في عينيه.') WHERE id = '34bce004-091a-42c4-b036-d6f0fb49caaf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ لديه استعداد للإصابة بالحساسية، فقد يكون تناول الطعام المسبب لها أو لمسه أو حتى استنشاق رائحته أمرًا خطيرًا. في هذه الحالات، ما إن يتعرض طفلكِ لمسبب الحساسية حتى يتعامل جهازه المناعي مع تلك المادة على أنها ضارة بالجسم. وينتج جسمه أجسامًا مضادة تؤدي إلى حدوث رد فعل تحسسي بهدف مكافحة المواد التي يظن أنها ضارة. أي إن الحساسية تحدث عندما يخطئ الجهاز المناعي في اعتبار مادة غير ضارة مادة خطيرة كالفيروس. وقد تظهر الحساسية لدى طفلكِ بسبب العوامل الوراثية أو البيئة أو التغذية غير الصحية. وعلى الرغم من أن أسبابها غير معروفة بدقة، يُعتقد أن العامل الأهم هو إصابة أحد الوالدين أو كليهما بالحساسية. فعلى سبيل المثال، إذا كنتِ أنتِ وزوجكِ تعانيان من حساسية تجاه البنسلين، فقد يرتفع خطر إصابة طفلكِ بها إلى 70%.') WHERE id = 'e455730e-1689-4a02-baeb-f13c6f81e7b6';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يبكي أثناء التبول، وكانت رائحة بوله كريهة، وتنتابه نوبات بكاء متكررة، فينبغي الاشتباه في إصابته بعدوى المسالك البولية. وعدوى المسالك البولية حالة تحدث عندما تسبب البكتيريا الضارة التهابًا في مجرى البول. وعلى الرغم من أن هذا النوع من العدوى يصيب الجنسين، فإنه يكون عادة أكثر شيوعًا لدى الإناث، لأن مجرى البول لديهن أقصر منه لدى الذكور. وعند الاشتباه في الإصابة، يجب عليكِ استشارة طبيب طفلكِ وإجراء تحليل بول كامل وزرع للبول. وإذا أظهرت الفحوص علامات التهاب، يبدأ العلاج بمضاد حيوي واسع الطيف. وتستمر مدة هذا العلاج 10 أيام على الأقل. وبعد انتهاء العلاج، يجب الانتظار 3 أيام حتى يزول تأثير المضاد الحيوي، ثم إعادة تحليل البول للتأكد من تعافي طفلكِ تمامًا.') WHERE id = 'a8d0a258-4dfc-44d2-9a7b-064e2b1e8568';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا توجد في جدول تطعيمات طفلكِ أي لقاحات مقررة خلال هذا الشهر. ومع ذلك، قد يدعوكِ الطبيب إلى فحص روتيني لمتابعة حالته العامة. خلال هذه الأشهر، يُتوقع أن يكون محيط رأسه ضمن نطاقات معيارية محددة، لكن الأمر لا ينطبق بالطريقة نفسها على الطول والوزن. فقد تختلف نسب الطول والوزن بين الأطفال اختلافًا كبيرًا تبعًا لنموهم وعواملهم الوراثية وجنسهم. فعلى سبيل المثال، يُلاحظ عادةً أن الأولاد أثقل وزنًا وأطول قامةً من البنات. ابتداءً من الشهر 11، قد يتراوح وزن طفلكِ بين 7000 غرام و11.000 غرام، وطوله بين 65 سم و82 سم. ووجود هذه القياسات عند الحد الأدنى أو الأعلى لا يعني أن طفلكِ يعاني من مشكلة في النمو. كذلك، قد يرى الأطباء أن انخفاض هذه المؤشرات قليلًا أمر طبيعي في حال إصابة الطفل سابقًا ببعض الأمراض أو ولادته قبل الأوان.') WHERE id = '96a6abff-366a-4a26-9826-e1f53726a843';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المحتمل أن طفلكِ ينام معكِ منذ يوم ولادته، وقد تراودكِ بعض الأسئلة حول الوقت المناسب لنقله إلى غرفة منفصلة. في الواقع، لا توجد حدود زمنية صارمة لعملية فصل غرفتكِ عن غرفة طفلكِ. وربما لا ترغبين أنتِ أيضًا في النوم بعيدًا عنه حتى الآن. لكن الخبراء ينصحون بعدم تأخير هذه الخطوة كثيرًا. وكما هي الحال مع كل عادة جديدة لدى الأطفال، لا يُتوقع أن يعتاد طفلكِ النوم منفردًا بسهولة. ويُعد اكتساب القدرة على النوم منفردًا قبل فوات الأوان أحد العوامل التي ستؤثر إيجابيًا في شخصيته مستقبلًا. لذلك، إذا كنتِ تفكرين في تخصيص غرفة منفصلة له، فلا ضرر من البدء تدريجيًا من الآن. وأهم ما ينبغي أن تنتبهي إليه هو تنفيذ هذه العملية على مراحل حتى لا تتحول إلى تجربة مؤلمة نفسيًا لطفلكِ.') WHERE id = 'ca8c37f8-65b8-4e4c-a7a3-3378e6f4aec7';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يستطيع طفلكِ لفترة طويلة استيعاب التناسق بين اليد والعين بشكل كامل. لذلك يستخدم عينيه ويديه كما لو كانتا منفصلتين؛ فقد يلمس الأشياء من دون النظر إليها، أو يكتفي بالنظر إليها من دون لمسها. وخلال هذه المرحلة، التي تُسمى المرحلة السلبية، لا يدرك عقل طفلكِ بعد أن التنسيق بين النظر واللمس يتطلب مهارة. ويُعد تحقيق هذا التناسق تحديدًا من أصعب المهارات التي يحتاج طفلكِ إلى تطويرها. وفي هذا السياق، توجد بعض الأنشطة التي يمكنكِ ممارستها لمساعدته على تنمية مهاراته الحركية الدقيقة وتحسين التناسق بين اليد والعين. فعلى سبيل المثال، يمكنكِ شراء ألعاب يمكن دفعها له، أو اللعب بالكرة معه، أو أن تطلبي منه إحضار لعبة لكِ من سلة الألعاب. والأهم هو اختيار ألعاب تناسب مستوى طفلكِ وتعزيز شعوره بأنه قادر على النجاح.') WHERE id = 'c4276da3-ca88-407e-9c07-409f5af9f487';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد اختيار الحذاء المناسب والمقاس الملائم أمرًا بالغ الأهمية لصحة قدمي طفلكِ. ففي هذه المرحلة، لا تزال عضلاته وعظامه في طور النمو، بل إن قدميه تتكونان إلى حد كبير من أنسجة غضروفية. ولأن الأنسجة الغضروفية أكثر حساسية من العظام، فقد يؤدي اختيار حذاء غير مناسب بسهولة إلى تشوه بنية قدمي طفلكِ. لذلك، عند شراء الحذاء، احرصي على ألا يضغط على قدمه وأن يترك فراغًا يبلغ نحو 1 سم أمام أطراف أصابعه. وينبغي أن يكون الحذاء الذي تختارينه ناعمًا ومرنًا ومقاومًا للتمدد. فهذه الخصائص مهمة حتى يتمكن طفلكِ من الحفاظ على توازنه بسهولة. كذلك، لا تشتري الحذاء من دون تجربته، وتجنبي الحركات التي قد تؤلم طفلكِ عند إلباسه إياه. وبعد خلع الحذاء، افحصي قدميه وتأكدي من عدم وجود آثار للضغط عليهما.') WHERE id = 'f60eb2d0-e0ee-46f9-817c-d2b511759488';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'في هذه المرحلة، تزداد أهمية كمية الحديد التي يحصل عليها جسم طفلكِ. فالحديد معدن ضروري لنقل الأكسجين في الجسم، كما يساعد على تقوية جهازه المناعي. وعندما تكون مناعة طفلكِ قوية، تقل احتمالية إصابته بالأمراض، وهو أمر بالغ الأهمية لاستمرار نموه الصحي. لقد نما طفلكِ نموًا مذهلًا خلال العام الماضي، وقد تبدأ حاجته المتزايدة إلى الحديد في الظهور نتيجة هذا النمو السريع. وبالطبع، تُعد التغذية أفضل وسيلة للوقاية من نقص الحديد. وبما أن طفلكِ أصبح قادرًا الآن على تناول معظم الأطعمة تقريبًا، فإن التغذية الجيدة توفر له مخزونًا كافيًا من الحديد. لكن قد يرغب المختصون في دعم هذه العملية لمنع الإصابة بفقر الدم وتجنب تأخر النمو. وإذا أظهرت التحاليل حاجته إلى ذلك، فسيكون إعطاؤه مكمل الحديد الذي أوصى به طبيبكِ بانتظام مفيدًا جدًا له.') WHERE id = '73aac64a-d992-45f0-aa07-1a1807c3ef3b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يستيقظ كثيرًا ليلًا، فاعلمي أن معظم الأمهات يمررن بالتجربة نفسها. ويُعد استيقاظ الأطفال ليلًا أمرًا شائعًا جدًا خلال العام الأول. وعندما تكتشفين سبب المشكلة، يصبح حلها أسهل. ويأتي الجوع وابتلال الحفاض في مقدمة أسباب الاستيقاظ. فإذا كنتِ تعتقدين أن أحدهما هو السبب، فسيكون التعامل مع الأمر سهلًا. أما إذا كان طفلكِ يستيقظ لأسباب أخرى غير هاتين الحاجتين الجسديتين، فننصحكِ بمراجعة عادات نومكما. فعلى سبيل المثال، إذا اعتاد طفلكِ أن ينام عند هزّه أو إرضاعه، فسيربط النوم بهذه العادات ويطلب تكرارها كلما استيقظ. كما أن عدم تحقيق التوازن بين نوم النهار والليل قد يؤدي إلى استيقاظه المتكرر ليلًا. ومن المتوقع أن يضطرب نوم الطفل ليلًا إذا نام خلال النهار مدة قصيرة جدًا أو طويلة جدًا. لذلك، ينبغي لكِ تنظيم أساليب النوم والتوازن بين نوم النهار والليل بصورة صحيحة.') WHERE id = '23e7e900-4096-428a-bdc0-1aa6763f7f56';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد موضوع اللهاية مثيرًا للجدل إلى حد كبير، ولكل مختص رأي مختلف بشأنه. إذا كان طفلكِ يستخدم اللهاية، فربما تتساءلين: إلى متى يمكنه استخدامها؟ وكيف تساعدينه على تركها؟ بما أن الغرض من اللهاية هو إشباع منعكس المص، فإنها تكون مفيدة جدًا في أوقات الانزعاج. لكن حتى المختصين الذين يؤيدون استخدامها يتفقون على أن استعمالها لفترة طويلة قد يسبب مشكلات. فقد يؤدي استخدام اللهاية طويلًا إلى اضطراب في بنية فك طفلكِ، وقد يسبب مستقبلًا مشكلات في النطق والبلع. لذلك يوصي المختصون بالتوقف عن استخدامها تمامًا قبل بلوغ عمر سنتين. ومع ذلك، ينبغي أن تتم هذه العملية تدريجيًا وألا تكون مفاجئة، حتى لا تسبب التوتر لطفلكِ. فإذا كان يستخدم اللهاية عند النوم مثلًا، فقد يكون سحبها برفق من فمه بعد أن يغفو بداية جيدة.') WHERE id = 'ea3db4c3-dcac-405e-b393-93a579b49517';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ بالفعل باستخدام بعض الكلمات ذات المعنى، وأصبح قادرًا على التعبير لكِ عما يريده بطريقة أو بأخرى. ومع ذلك، لا تزال المحاكاة وسيلة تعلم مهمة جدًا بالنسبة إليه. لذلك، تسهم كل كلمة تقولينها له في إثراء حصيلته اللغوية. وعلى الرغم من تسارع النمو الجسدي خلال هذه المرحلة، فإن التطور الذهني يبرز بصورة أكبر. تذكري أن طفلكِ يمر بمرحلة تتطور فيها قدراته اللغوية والكلامية بسرعة. فقد أصبح يفهم التعليمات البسيطة التي تعطينها له، أو أنه على وشك فهمها. وهناك بعض الأساليب المفيدة لتنمية مهاراته اللغوية والكلامية. فعلى سبيل المثال، يُعد قول "شكرًا" له عندما تطلبين منه شيئًا بداية جيدة. وعندما يفعل شيئًا لا تريدين منه فعله، فبدلًا من قول "لا" بصرامة والتدخل مباشرة، يمكنكِ توجيهه بعبارات مثل "من فضلك"، أو "ما رأيك أن نهتم بهذا في وقت آخر؟"، أو "تعال نلعب معًا". سيساعد ذلك على منع طفلكِ من الاعتراض باستمرار وتحويل هذا السلوك إلى عادة.') WHERE id = '177ea1b8-c76a-4b5a-9e15-051e313ce518';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ازدادت كثيرًا كمية الأطعمة الصلبة التي يتناولها طفلكِ وتنوعها. لكن هناك حقيقة لا تتغير: حليب الأم. فعلى الرغم من زيادة ما يتناوله طفلكِ يوميًا من الأطعمة التكميلية، يظل حليبكِ مهمًا جدًا لنموه. إذا كنتِ لا ترضعينه طبيعيًا في هذه المرحلة، فربما أصبحت الأطعمة الصلبة أساس نظامه الغذائي. لكن احتياج طفلكِ اليومي من الأطعمة الصلبة خلال هذه الفترة يعادل تقريبًا 3-4 عبوات من طعام الأطفال. وقد يؤثر تناوله كمية أكبر من الأطعمة الصلبة سلبًا في جهازه الهضمي وفلورا الأمعاء، اللذين لا يزالان في طور النمو. كما قد يؤدي ذلك مستقبلًا إلى مشكلات صحية عديدة، أبرزها السمنة. لذلك، إذا كنتِ لا ترضعين طفلكِ طبيعيًا، فمن الضروري للغاية استخدام البديل الوحيد لحليب الأم، وهو الحليب الصناعي المخصص للرضع.') WHERE id = '1a9bf277-b2e7-4c8a-a929-8d4f4f669610';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا قررتِ أن ينام طفلكِ في غرفة منفصلة، فعليكِ أن تكوني أكثر حزمًا من المعتاد. يرى بعض المختصين أن الانتقال إلى غرفة منفصلة ينبغي أن يتم قبل بلوغه عمر سنة. فبعد هذه المرحلة، يصبح إكساب طفلكِ عادة جديدة أكثر صعوبة، وقد تظهر نوبات البكاء ورفض النوم والخوف من الهجر. سيوفر الانتقال التدريجي إلى الغرفة المنفصلة مزيدًا من الراحة لكِ ولطفلكِ. أولًا، عندما تشعرين بأنكِ مستعدة وتعتقدين أن الوقت المناسب قد حان، عليكِ التمسك بقراركِ. عند بدء هذه العملية، يُعد الانتظار في غرفة طفلكِ حتى ينام، والذهاب إليه ليلًا عند استيقاظه وانتظار عودته إلى النوم بدلًا من إحضاره إلى جواركِ، خطوة صحيحة. كما أن تهيئة غرفته بطريقة يحبها ستساعده على التحمس للنوم فيها. ويمكنكِ أيضًا استخدام إضاءة خافتة، مثل المصباح الليلي، لبعض الوقت كي لا يشعر بالخوف إذا استيقظ ليلًا.') WHERE id = '2cdfd82a-b781-4b01-bce5-c70071e76784';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'من المهم جدًا أن يركز طفلكِ تمامًا على ما يأكله حتى يكتسب عادات غذائية سليمة، ماما. لذلك ينبغي ألا يتشتت انتباهه بأشياء أخرى أثناء تناول الطعام. ولا ينصح المختصون إطلاقًا بإطعام الطفل في مكان يكون فيه التلفاز قيد التشغيل. فعندما يركز طفلكِ على التلفاز بدلًا من الطعام، لا يستطيع إدراك شعوره بالشبع بصورة كاملة. ونتيجة لذلك، قد يتوقف عن الأكل قبل أن يشبع، أو على العكس، قد يستمر في تناوله حتى بعد الشبع. ويتطلب توجيه انتباه طفلكِ إلى الطعام الذي يتناوله وإدراكه لحظة الشبع مهارةً تُكتسب مع الوقت. وتُعد هذه المهارة مفتاحًا مهمًا جدًا لترسيخ عادات غذائية صحية طويلة الأمد لدى طفلكِ.') WHERE id = '415ce321-e862-4b3b-9a4e-2e689e0f9a0f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا لم تكوني قد اشتريتِ جهازًا بعد، فيمكنكِ البدء بالبحث عن جهاز مراقبة الطفل كإجراء احترازي للسلامة. ولا يلزم الانتظار حتى يحين وقت انتقال طفلكِ إلى غرفة منفصلة لشرائه. فهذه الأجهزة مفيدة جدًا لمراقبة طفلكِ عندما يتعذر عليكِ البقاء بجانبه طوال الوقت، وللتدخل فورًا عند الحاجة. ويمكنكِ اختيار طراز ينقل الصوت فقط، أو تفضيل جهاز مراقبة مزود بكاميرا. وأهم ما ينبغي الانتباه إليه عند شراء جهاز مراقبة الطفل هو أن يكون نطاق تغطيته مناسبًا للمسافة بين الغرف. وإذا كنتِ ستشترين الجهاز لاستخدامه عند انتقال طفلكِ إلى غرفة منفصلة، فيمكنكِ النظر في الطرز المزودة بخاصية الرؤية الليلية. كذلك ينبغي أن يكون جهاز المراقبة الذي تختارينه سهل الحمل، وأن يكون ميكروفونه عالي الحساسية.') WHERE id = '66e0fb2c-314f-41f3-bf17-cb60663f6d11';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ربما يكون طفلكِ قد بدأ المشي بالفعل. وحتى إن لم يكن قد مشى بعد، فقد تكون خطواته الأولى مسألة وقت فحسب! لكن قد تستغرق عملية المشي لدى بعض الأطفال وقتًا أطول قليلًا، وهذا التأخر لا يعني بالضرورة وجود مشكلة. فمثلًا، إذا كان طفلكِ يحبو بسرعة كبيرة، فقد يكون ذلك أحد أهم العوامل التي تؤخر مشيه. إذ إن قدرته على الوصول إلى المكان الذي يريده عن طريق الحبو تقلل من حماسه للمشي، لأنه يستطيع التنقل بسهولة إلى أي مكان حبوًا. كما أن زيادة الوزن من الأسباب التي قد تؤخر بدء الأطفال بالمشي. ولا تؤدي هذه الحالة إلى بطء المشي فحسب، بل قد تجعل تطور حركات مثل التقلب والحبو أبطأ من المعتاد أيضًا. لذلك، إذا كان وزن طفلكِ زائدًا قليلًا، فقد يحتاج إلى مزيد من الوقت ليبدأ المشي.') WHERE id = '704954bf-6728-49ee-8d83-22a42aaa6a0b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تؤدي مدة النوم وجودته دورًا بالغ الأهمية في نمو طفلكِ واكتسابه مهارات جديدة. ويُعد نظام النوم المنتظم الذي تساعدين طفلكِ على اكتسابه في هذه المرحلة أحد العوامل الأساسية التي تحدد جودة نومه طوال حياته. خلال مرحلة حديثي الولادة، كان طفلكِ يقضي معظم يومه تقريبًا نائمًا. ومع مرور الأشهر، يقل عدد مرات نومه ومدتها، كما تقل مرات استيقاظه ليلًا. ابتداءً من الشهر الحادي عشر، يبلغ متوسط نوم الطفل ليلًا نحو ١٠-١١ ساعة، بينما ينام نهارًا نحو ٢-٣ ساعات. إذا كنتِ تعتقدين أن طفلكِ ينام أقل من هذه المدة، فقد يرجع ذلك إلى سببين. الأول أنه لا يعرف كيف ينام بمفرده من دون مساعدة. والثاني أنه قد لا يتمكن من النوم بسبب فرط التعب، لأنكِ لا تلاحظين علامات شعوره بالنعاس في الوقت المناسب. لذلك ننصحكِ بمراقبة طفلكِ بصورة أفضل، وإذا كنتِ لا تزالين تساعدينه على النوم بوسائل مثل الهز أو الرضاعة، فنوصيكِ بالتخلي عن هذه العادات غير المناسبة.') WHERE id = '7be3db50-1dd0-41ad-aa34-ad5ba68d390b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'امتلاك طفلكِ عظامًا سليمة هو الأساس لحياة صحية. ويؤدي تكوين هيكل عظمي سليم، إلى جانب عادات التغذية الصحيحة ونمط الحياة الصحي، دورًا حاسمًا في تمتع طفلكِ مستقبلًا بجودة حياة أفضل. والكالسيوم ضروري للغاية كي يتمكن طفلكِ من تحريك عضلاته بسهولة، وكذلك لدعم الدورة الدموية في جسمه. ومن هذا المنطلق، يُعد الكالسيوم بالطبع أهم المعادن التي تحدد صحة عضلات طفلكِ وعظامه. ويُخزَّن معظم الكالسيوم الكافي في العظام خلال أول ٢٠ عامًا من الحياة، إلا أن هذه العملية تكون سريعة جدًا في مرحلة الرضاعة ثم تتباطأ تدريجيًا. لذلك من المهم للغاية أن يحصل جسم طفلكِ على كمية كافية من الكالسيوم من خلال غذائه. وإضافة إلى حليب الأم أو الحليب الصناعي، من الضروري لتحقيق مدخول مناسب من الكالسيوم أن تحرصي على إدراج الكفير والزبادي والزبدة، مع تحقيق توازن مناسب بين الخضراوات والفواكه في نظام طفلكِ الغذائي.') WHERE id = 'b5d04c21-7460-44fc-9948-e2c4d43a3411';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد لا يستخدم طفلكِ في هذه المرحلة كلمات ذات معنى واضح تمامًا بعد. ومع ذلك، أصبح قادرًا على إيصال ما يريده إليكِ عندما يحاول إخباركِ بشيء. ومع تسارع نموه الذهني بصورة ملحوظة، يستطيع طفلكِ أن يُشعركِ بسعادته، وأن يعبّر بطريقة بسيطة عن رفضه لشيء ما. وقد يكون ذلك أحيانًا بالصراخ، وأحيانًا أخرى بالكلام بصوت خافت. يحاول طفلكِ في هذه الفترة تنمية حصيلته اللغوية وفهم ما تقولينه بصورة أوضح. ولدعم هذا التطور، يمكنكِ بدلًا من إعطائه ما يريده فورًا أن تطرحي عليه أسئلة مثل: "هل تريد ماءك؟"، "هل تريدين مني أن أناولك لعبتك؟". وبهذه الطريقة، يمكنكِ مساعدة طفلكِ على التمييز بصورة أفضل بين أسماء الأشياء التي تُستخدم كثيرًا في الحياة اليومية. كما أن طلبكِ من طفلكِ إحضار شيء إليكِ سيكون مفيدًا لمساعدته على فهم معاني الكلمات بصورة أفضل.') WHERE id = '170d06eb-e49e-4fd4-a248-7ff0e64baa15';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'رغم أنكِ قد تجدين صعوبة في تصديق ذلك، فقد أتم طفلكِ عامًا كاملًا في العالم الخارجي. وعلى الرغم من أنكِ تعرفين أنه ما زال بحاجة إلى الحماية، فقد حان الوقت للتخلي عن الإفراط في حمايته. فقد تجعله الحماية المفرطة ينتظر المساعدة باكيًا عند مواجهة المشكلات مستقبلًا بدلًا من محاولة إيجاد حل لها. وقد يظل طفلكِ ينظر في عينيكِ وينتظر مساعدتكِ كلما واجه صعوبة. لكن ينبغي ألا تتدخلي قبل أن تمنحيه فرصة للتعامل مع التحديات بنفسه. فمثلًا، قد تكون بداية جيدة ألا ترفعي طفلكِ في كل مرة يسقط فيها، بل تشجعيه على النهوض بنفسه. ذلك لأن العادات المكتسبة في هذا العمر تبدأ بتشكيل شخصيته التي سترافقه طوال حياته.') WHERE id = 'f135783e-e842-4807-b9fe-4cad5e477cf1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك العديد من المهارات الحركية الدقيقة والكبيرة التي اكتسبها طفلكِ حتى هذا الشهر، وأخرى سيكتسبها خلاله. وبأبسط تعبير، يعني التطور الحركي اكتساب الطفل القدرة على الحركة. ولتحقيق ذلك، يجب أن يستخدم دماغه لتنظيم حركات عضلاته بصورة متناسقة. تتحقق المهارات الحركية الكبرى من خلال عمل مجموعات العضلات الكبيرة، ويجب بالطبع التحكم فيها بواسطة الدماغ لا عن طريق ردود الفعل المنعكسة. أما المهارات الحركية الدقيقة فهي قدرة طفلكِ على تحريك مجموعات العضلات الصغيرة، وتشمل بصورة أساسية حركات اليدين والأصابع. فمثلًا، قد يبدأ طفلكِ اعتبارًا من هذا الشهر بالإشارة إليكِ بإصبعه السبابة إلى شيء يريده. كما قد يتمكن من الوقوف مستعينًا بالأشياء التي يستطيع الإمساك بها بسهولة. وبفضل قدرته على استخدام أصابعه كلًا على حدة، قد يبدأ الآن باستخدام الملعقة. وعلى الرغم من أن استخدامه للملعقة لن يكون منظمًا جدًا في هذه المرحلة، فإنه يكون قد تعلّم الغرض منها. لذلك ينبغي أن تتيحي لطفلكِ فرصة تنمية مهاراته الحركية، وأن تدركي خلال مرحلة تعلمه أنه فرد مستقل، وتتركي له المهام التي يمكنه القيام بها بنفسه.') WHERE id = '0fd161d0-cd50-4708-86e8-1b252aeca43a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مثل جميع الأطفال، لن يحب طفلكِ أن يُمنع أو تُفرض عليه القيود. وقد يؤدي تقييده خلال هذه المرحلة التي يكتشف فيها العالم من خلال اللعب إلى بعض المشكلات. ففي مرحلة الاستكشاف، قد يبعثر طفلكِ الأشياء من حوله باستمرار ويحوّل ذلك إلى لعبة. لكن منعه من فعل ذلك بهدف الحفاظ على ترتيب المنزل قد يدفعه أحيانًا إلى إظهار سلوك عدواني. وقد أظهرت بعض الدراسات أن السلوكيات العدوانية أكثر شيوعًا لدى أطفال الآباء الذين يتّبعون أساليب غير سليمة، مثل فرض القيود والانتقاد والمنع. لذلك، ينبغي ألا تتدخلي إلا عند الضرورة وباستخدام الأساليب الصحيحة. وعندما يُظهر طفلكِ سلوكًا غير مرغوب فيه، يمكنكِ التحدث إليه ومحاولة التواصل معه. ورغم أنه لا يستطيع الرد عليكِ بعد، فإنه سيفهم ما تريدين قوله.') WHERE id = 'e6a475d2-fe45-454c-a75a-76f9744ef10b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ قادرًا الآن على إدراك الفروق بين ألعابه بوضوح، ولذلك بات يلعب بها بوعي أكبر. فعلى سبيل المثال، بدلًا من وضع كرته في فمه أو إمساكها وتأملها لدقائق، يمكنه الآن رميها وفقًا للغرض منها، ثم الذهاب إلى المكان الذي رماها فيه والتقاطها. وهو يعرف أن الحبو على يديه وركبتيه سيساعده على الوصول إلى كرته. وخلال هذه المرحلة، التي تطورت فيها كثيرًا قدرته على الإمساك بأطراف أصابعه، أصبح يستخدم أصابعه بشكل هادف. وتدل هذه المهارات الجديدة كلها على أن طفلكِ يمر بمرحلة تعلّم نشطة وأنه قادر على التحكم في قدراته الذهنية بفاعلية. وقد يتباطأ هذا التطور بسبب وسائل مثل التلفاز والجهاز اللوحي والهاتف، التي تشتت انتباهه عن الاكتشافات الجديدة. لذلك، ننصحكِ بإبعاد طفلكِ لفترة أطول قليلًا عن هذه الوسائل التي قد تؤدي إلى اكتساب عادات سلبية.') WHERE id = '099e9644-c317-463e-9565-cf38395da13a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل نموه الذهني، بدأ طفلكِ الآن يفهم العلاقة بين السبب والنتيجة بصورة أفضل. وبات قادرًا على استخدام قدرته على تغيير أماكن الأشياء من حوله كما يشاء! ويشمل ذلك إفراغ سلة الملابس المتسخة أيضًا... 😊 وكما هي الحال لدى جميع الأطفال، فإن إحدى أنشطة طفلكِ المفضلة هي إفراغ كل ما يحتوي على أشياء! وقد تكون هذه الأدراج أو الخزائن أو سلال الملابس المتسخة أو حقيبة مستحضرات التجميل الخاصة بكِ أو الأغراض الموجودة في السيارة أو سلة الألعاب. فقد تعلّم الآن أنه يستطيع إحداث تغيير عندما يفعل ذلك، والنتيجة التي يراها تسعده وتزيد حماسه. ورغم أن هذا الأمر قد يكون مرهقًا جدًا لكثير من الأمهات، فعلينا إخباركِ بأنه سيستمر فترة أطول قليلًا. ومع ذلك، ننصحكِ بعدم منع طفلكِ خلال هذه المرحلة، لأن منعه قد يبطئ عملية تجربته للأشياء الجديدة وتعلّمه منها.') WHERE id = 'de5be5b0-43b6-421c-9cf6-60c30a757402';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال هذه المرحلة التي يُظهر فيها طفلكِ تطورًا جسديًا، مثل الوقوف ومحاولة المشي، توجد بعض النقاط التي ينبغي لكِ معرفتها لمساعدته على تطوير قدراته اللغوية أيضًا. ورغم أن معظم الأصوات التي يصدرها قد تبدو بلا معنى، فإن طفلكِ يضع في هذه المرحلة أساس مهاراته اللغوية من خلال الاستماع إلى كلامكِ. لذلك، من المهم جدًا أن تنطقي الكلمات بصورة صحيحة كلما كان طفلكِ بجانبكِ. وأثناء حديثكِ، ستساعده رؤية حركات فمكِ ولسانكِ عند إصدار الأصوات على تعلّم كيفية إصدار أصوات ذات معنى. فعلى سبيل المثال، عندما تحضّرين الطعام لطفلكِ، فإن شرح الخطوات له مع عرض ما تفعلينه يوفّر بيئة تعليمية مناسبة وفعالة للغاية. كما أن طرح الأسئلة عليه باستمرار في هذه المرحلة سيجذب انتباهه أكثر. ورغم أنه لا يستطيع الرد عليكِ بعد، فإن طفلكِ، الذي تطورت قدرته على الاستيعاب كثيرًا، سيفهم جيدًا ما تريدين قوله.') WHERE id = 'b81a1e32-8dc9-494a-bc85-0cdde994004d';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'هناك بعض الحيل البسيطة التي يمكنكِ تطبيقها لزيادة حماس طفلكِ للمشي. والأهم هو أن تراقبي جيدًا ما إذا كان مستعدًا للمشي من الناحية النمائية. فإذا كنتِ تعتقدين أن طفلكِ مستعد للمشي، يمكنكِ وضع ألعابه المفضلة على مسافة قصيرة منه ضمن مجال رؤيته، بدلًا من وضعها بجانبه مباشرة. فوضع كل ما يريده أمامه باستمرار وهو جالس قد يقلل دافعيته، ولن يشعر بالحاجة إلى المشي. ويمكنكِ خلال اليوم التأكد من ثبات الأثاث والأشياء التي يستند إليها، واستخدام أشياء مثيرة لاهتمامه لتشجيعه على التمسك بها والوقوف. كما أن عدم إبقائه جالسًا لفترات طويلة أثناء ساعات يقظته، والتدرّب على المشي داخل المنزل وخارجه، سيزيدان حماسه. ويمكنكِ أيضًا السماح له بالمشي حافي القدمين داخل المنزل لتسهيل مشيه وتقوية عضلات قدميه وساقيه.') WHERE id = '7a1e8c2b-10cc-434b-be5a-358025ea3b29';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تتساءلين عن الأنشطة التي يمكنكِ ممارستها مع طفلكِ خلال هذا الشهر. وهناك الكثير من الأنشطة التي ستستمتعان بها معًا، وتدعم في الوقت نفسه نموه الذهني والجسدي. فعلى سبيل المثال، يمكنكِ أن تُري طفلكِ غرضًا ثم تخفيه في مكان يستطيع رؤيته، وبعد ذلك تطلبين منه أن يحضره. وبهذه الطريقة، يمكن لطفلكِ تطوير التناسق بين اليد والعين والاستمتاع كثيرًا في الوقت نفسه. وعندما يحضر الغرض إليكِ، فإن شكره سيسهم أيضًا في إرساء أساس العادات الجيدة التي ينبغي أن يكتسبها مستقبلًا. ويمكنكِ كذلك تحويل أنشطتكما اليومية المعتادة إلى ألعاب. فعلى سبيل المثال، أثناء الاستعداد للخروج، يمكنكِ الوقوف أمام المرآة بحيث يرى طفلكِ انعكاسكِ، ثم التلويح له بيدكِ وتشجيعه على الرد بالمثل. وقبل تحضير وجبته التالية، يمكنكِ إخراج الأطعمة وتعريفه بها بعبارات مثل: «هذا كبير»، و«هذا صغير»، و«هذا أصفر»، و«هذا برتقالي». استمتعا بوقتكما! 😊') WHERE id = '6301b867-ee49-4968-aaba-34f711fa6ee8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لقد تطورت المهارات الحركية الدقيقة لدى طفلكِ بدرجة كبيرة، وأصبح قادرًا بفضل ذلك على استخدام أصابعه بفعالية. ويمكنه، خصوصًا باستخدام السبابة والإبهام، ترتيب ألعابه في صفوف ومحاولة تكديسها فوق بعضها، كما يستمتع بإدخال بعضها في بعض. بل قد ينزع جواربه فور إلباسه إياها مهما حاولتِ إبقاءها في قدميه. وإذا لم تمنعيه من ذلك بصرامة، فلن يتحول هذا السلوك إلى عناد، وقد ترينه يحاول إعادة ارتداء الجورب الذي نزعه. ولدعم هذا التطور لدى طفلكِ، عليكِ مساعدته وإرشاده إلى كيفية التحكم في حركاته بنفسه. فعلى سبيل المثال، بما أن طفلكِ بدأ يستخدم يديه وقدميه وأصابعه بشكل هادف ومباشر، يُفضّل تجنب إبقائه مرتديًا الجوارب طوال الوقت داخل المنزل. إن تمكُّن طفلكِ من الإحساس بيديه وقدميه بالكامل سيسهم بدرجة كبيرة في نمو عضلاته وتطور مهاراته.') WHERE id = '5a5a24f6-dfde-4cd0-9700-1725829fdabb';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يدرك طفلكِ أنه محور الاهتمام في المنزل، وهذا يجعله سعيدًا جدًا. وقد يقوم بحركات غريبة لجذب انتباهكِ عندما لا تهتمين به. وكغيره من الأطفال، يرغب طفلكِ في الحصول على الاهتمام من والديه ومن المحيطين به، إذ قد يعدّ الاهتمام به وتلبية حاجته إليه دليلًا ملموسًا على الحب والتقدير. وهذا أمر طبيعي لطفلكِ الذي لم يكتسب بعد فهمًا كاملًا للمفاهيم المجردة والمحسوسة. كما أن تلبية حاجة طفلكِ إلى الاهتمام بالقدر الكافي ستساعده على الشعور بالأمان وبأنه شخص ذو قيمة، وهذا من أهم العوامل التي تسهم في تمتعه بصحة نفسية أفضل عندما يصبح بالغًا في المستقبل.') WHERE id = 'a5cfafcf-5098-4fd7-b06b-9e5991ba4455';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تشير دراسات عديدة إلى أن استخدام اللهاية، ولا سيما خلال السنة الأولى من العمر، يقلل خطر متلازمة موت الرضع المفاجئ. ولكن إذا كنتِ من الأمهات اللواتي يستخدمن اللهاية لأطفالهن، فعليكِ اختيارها بعناية ومعرفة مدة الاستخدام المناسبة. وأهم ما ينبغي مراعاته هو عمر طفلكِ ومرحلة نموه، لأن اللهايات غير المناسبة لعمره ونموه قد تؤثر بسهولة في بنية الفم والأسنان. كما يجب أن تتأكدي جيدًا من أن اللهاية التي تستخدمينها ليست مصنوعة من بلاستيك يحتوي على مادة BPA. وخلال مرحلة التسنين، يمكنكِ استخدام لهايات مطاطية بدلًا من البلاستيكية لتلبية حاجة طفلكِ إلى العض وتهدئته. أما خلال النهار، فيمكنكِ اختيار اللهايات البلاستيكية المزودة بفتحات، إذ تساعده على التنفس براحة أكبر.') WHERE id = '29360a2f-1179-4451-8558-fbdf819c9334';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'مع تقدم طفلكِ في مراحل نموه، قد يتغير نمط نومه هذا الشهر بطريقة لا ترهقكِ كثيرًا. وعادةً ما يتمثل هذا التغيير في قِصر فترات النوم النهاري وزيادة مدة النوم ليلًا. وقد ينخفض عدد قيلولاته من 2-3 مرات إلى مرة واحدة، وإذا كانت مدة القيلولة 60 دقيقة فقد تقصر إلى 15-20 دقيقة. وخلال هذه المرحلة الانتقالية، قد يشعر طفلكِ بالانزعاج نهارًا لبعض الوقت ويدخل في نوبات من البكاء. ولمساعدته على التكيف مع النمط الجديد، يمكنكِ تنظيم التوازن الزمني بين نومه ليلًا ونهارًا. فعلى سبيل المثال، إذا كان طفلكِ يستيقظ الساعة 6 صباحًا وينام الساعة 8 مساءً، فإن أخذه قيلولة قرابة الساعة 1 ظهرًا سيساعد على تكوين نمط نوم متوازن. وإذا كان يجد في البداية صعوبة في النوم ليلًا بسبب الإرهاق، فقد يساعده الحمام الدافئ على النوم المتواصل طوال الليل.') WHERE id = '29be8b55-c3ca-46ad-9c7e-b1ccdcfeab74';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'أصبح طفلكِ الآن قادرًا على تناول الطعام بنفسه. ولعل أكثر ما يثير القلق في هذه المرحلة هو خطر الاختناق. غير أن أبحاثًا أُجريت في السنوات الأخيرة توصلت إلى أن أسلوب التغذية الذاتية للرضع أكثر أمانًا من أسلوب التغذية التقليدي. لذلك، عندما يُطبَّق هذا الأسلوب بطريقة صحيحة، يكون تناول طفلكِ الطعام بنفسه آمنًا ومنخفض المخاطر إلى حد كبير. والسبب الأهم في ذلك هو أن التحكم في العملية لا يكون بيدكِ بالكامل، بل بيد طفلكِ، فهو الأقدر على تنظيم مراحل وضع الطعام في فمه ومضغه ودفعه نحو الحلق بحركات اللسان ثم بلعه. ومن أسباب انخفاض خطر الاختناق في هذا العمر أيضًا أن حلق الطفل يكون أقرب إلى مقدمة الفم، بينما يكون لسانه في موضع متوسط. ولذلك يستطيع طفلكِ بسهولة إخراج قطعة طعام أكبر من أن يبتلعها بفضل منعكس التهوع.') WHERE id = '8de7c43c-84d8-440a-a1bf-7f758e886f0f';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ابتداءً من هذا الشهر، قد تلاحظين أن كثيرًا من الأطفال المحيطين بكِ ممن هم في عمر طفلكِ، ومن بينهم طفلكِ، قد بدأوا المشي. وإذا لم يبدأ طفلكِ المشي بعد، فتذكري أنه لا يزال أمامه نحو 6 أشهر للتدرب عليه. ومن المتوقع أن يتأخر المشي لدى الأطفال الذين تأخروا في الجلوس والتقلب والحبو، بوصفه مرحلة من مراحل نموهم. ولكن حتى في حال عدم وجود تأخر في هذه المراحل النمائية، ينبغي بعد إجراء الفحوصات اللازمة الانتظار بهدوء حتى الشهر 18 دون قلق. ويمكن معرفة استعداد طفلكِ للمشي عندما يتمكن من الوقوف مستندًا إلى شيء ما والحفاظ على توازنه، ولو لمدة قصيرة. وقد يؤدي إفراط الوالدين في حمايته إلى تأخير هذه العملية بضعة أشهر. لذلك، إذا كنتِ تحملين طفلكِ بين ذراعيكِ معظم الوقت خوفًا من أن يتأذى أو يسقط، فقد يزداد احتمال تأخره في المشي.') WHERE id = '52890d53-8d1e-42df-9458-72c4f9145d95';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'حان وقت إطعام طفلكِ. الطعام جاهز، والمائدة جاهزة، وطفلكِ مستعد. لكن ما هذا؟ بدلًا من تناول الطعام الذي أعددتِه بشق الأنفس، يلقيه طفلكِ على الأرض! إذا بدا لكِ هذا الموقف مألوفًا، فعليكِ أولًا أن تعلمي أنكِ لستِ وحدكِ. من أهم أسباب إلقاء طفلكِ الطعام على الأرض أنه اكتشف قدرته على نقل الأشياء وتغيير أماكنها. في هذه المرحلة، يفعل طفلكِ ذلك بدافع الفضول ورغبته في معرفة ما سيحدث عندما يلقي الطعام على الأرض. ولكيلا يحوّل هذا السلوك إلى عادة أو لعبة، تجنّبي ردود الفعل مثل الضحك أو الصراخ. عندما يفعل طفلكِ ذلك، انحني إلى مستواه وتواصلي معه بصريًا، ثم أخبريه أن ما فعله غير صحيح. وإذا استمر في إلقاء الطعام، فيمكنكِ إنزاله عن كرسي الطعام بهدوء وإخباره بأن وقت الطعام قد انتهى.') WHERE id = '10cae169-a8b4-4be4-bdf5-84293f56e461';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لمساعدة عضلات ساقي طفلكِ على أن تصبح أقوى، واصلي قدر الإمكان تركه يتجوّل داخل المنزل مرتديًا الجوارب. وحتى يبدأ طفلكِ بالمشي جيدًا لبعض الوقت من دون أن يسقط، احرصي على أن تكون الأحذية التي يرتديها خارج المنزل لينة ومرنة. وعلى عكس الاعتقاد الشائع، قد تتسبب الأحذية ذات النعال الصلبة في التواء قدم طفلكِ. ومهما كنتِ حريصة، فسوف يسقط كثيرًا خلال مرحلة التعلّم والتجربة. إذا لم تبالغي في رد فعلكِ عند سقوطه، فلن يستجيب طفلكِ بالبكاء أو يطلب مساعدتكِ ما لم يشعر بالألم. وإذا تألم طفلكِ بعد سقوطه وبدأ بالبكاء، فبدلًا من حمله فورًا، يمكنكِ الجلوس بجانبه على ركبتيكِ واحتضانه. وهذا مهم جدًا حتى لا يتوقف طفلكِ عن محاولة المشي أو يفقد حماسه.') WHERE id = '4b5a6bf3-177f-49f1-b076-3c5623ae0a32';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُتمّ طفلكِ الآن عامه الأول، وقد أصبحتِ أكثر خبرة في الأمومة، أجمل شعور في العالم. والآن حان وقت الاحتفال! 😊 إن حفلة عيد الميلاد الأول مخصّصة للوالدين أكثر مما هي للطفل. ومع أن طفلكِ قد لا يفهم الآن ما يحدث، فلا شك لدينا في أن هذا اليوم الكبير سيصبح ذكرى جميلة تستعيدونها في المستقبل. 😊 الجميع يحب الأماكن المفتوحة. لذلك، إذا كان ذلك ممكنًا، يمكنكِ إقامة حفلة عيد ميلاده الأولى في الحديقة أو في الهواء الطلق، مع مراعاة الفصل والظروف الجوية. ستكون رؤية وجوه جديدة، واجتماع الناس معًا، والاستمتاع بوفرة أشعة الشمس أمورًا ممتعة جدًا لطفلكِ. إذا كنتِ ستقيمين حفلة عيد الميلاد اليوم، فننصحكِ بتحديد مواعيدها وفقًا لنظام نوم طفلكِ. فعلى سبيل المثال، إذا تزامن موعد انتهاء الحفلة مع وقت نومه، فلن يشعر طفلكِ بالانزعاج، كما سينام بسهولة أكبر بعد أن يكون قد فرّغ طاقته. وحتى إن لم تقيمي حفلة، فلا تنسي التقاط الكثير من الصور والاحتفاظ بها جيدًا، حتى تتمكني من عرض ذكريات هذا اليوم الكبير عليه لاحقًا. استمتعي بوقتكِ! 😊') WHERE id = '7c4e1e7b-a0c0-4944-ab8c-78e8b2b58f41';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد تثير نوبات البكاء التي تصيب طفلكِ من وقت إلى آخر قلقكِ الشديد. وهذه النوبات، التي تشيع خصوصًا بين عمر 0-2 سنة، قد تنتج عن احتياجات جسدية، أو طفرات النمو، أو رغبة الطفل في جذب الانتباه، أو انزعاج فسيولوجي. إذا كان طفلكِ منزعجًا باستمرار وتنتابه نوبات بكاء متكررة، فسيكون من المفيد جدًا لكِ طلب الدعم من مختص. ومن الأسباب الأخرى لبكاء طفلكِ، خصوصًا خلال هذه الفترة، حاجته المستمرة إلى اهتمامكِ وحبكِ. فمع نشوء الخوف من فقدانكِ لديه، يرغب طفلكِ في رؤيتكِ بجانبه طوال اليوم. وقد تستمر هذه المرحلة على النحو نفسه لمدة عام آخر. ومهما كان سبب بكاء طفلكِ، فإن الاهتمام الذي تمنحينه له في تلك اللحظة مهم جدًا. وقد يتمثل هذا الاهتمام في مداعبة خده أثناء الرضاعة، والاستمتاع باللعب معه، وإخباره كثيرًا بأنكِ تحبينه. وبهذه الطريقة، يمكن أن ينمو لدى طفلكِ شعور راسخ بالأمان، ويقل إلى أدنى حد احتمال تعرضه لأي اضطراب عاطفي أو مزاجي في المستقبل.') WHERE id = '5059c6f2-d65d-48d0-b7c2-e56ec92f965b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا كان طفلكِ يمص إصبعه، وخاصة أثناء النوم، فقد تراودكِ أسئلة عن سبب ذلك. يرى المختصون أن مصّ الإصبع أمر طبيعي لأن الأطفال يكونون في مرحلة عمرية تُسمى المرحلة الفموية. وفي هذه المرحلة، يتعرّف طفلكِ إلى العالم الخارجي عن طريق فمه، ويشعر بالإشباع النفسي بهذه الطريقة. وقد تظهر عادة مصّ الإصبع لدى جميع الأطفال تقريبًا عند اقترابهم من عمر سنة واحدة. ويبلغ هذا السلوك ذروته خلال نحو 6 أشهر. وقد تؤدي محاولة منع طفلكِ من مصّ إصبعه قبل عمر 3-4 سنوات إلى مواجهته بعض المشكلات النفسية. فعلى سبيل المثال، إذا مُنع هذا السلوك قبل اكتمال هذه المرحلة، فقد يعود طفلكِ إلى مصّ إصبعه عند مواجهة المشكلات بعد بلوغه سن المدرسة. لذلك، تذكّري أن هذه وسيلة للشعور بالراحة وجزء طبيعي من نمو طفلكِ، ولا تمنعيه من مصّ إصبعه.') WHERE id = '31ea1093-e45e-4706-9187-09cec848711c';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يكون جدول تطعيمات طفلكِ مزدحمًا قليلًا هذا الشهر. ولكن نظرًا إلى أن تطعيمات مهمة جدًا ضد أمراض معدية ستُعطى في الشهر 12، ننصحكِ بالالتزام بالجدول المحدد. وتشمل هذه التطعيمات: الحصبة، والحصبة الألمانية، والنكاف، بالإضافة إلى لقاح المكورات الرئوية. قد تكون الأمراض التي تسببها المكورات الرئوية خطيرة وشديدة. إذ يمكن أن تؤدي هذه البكتيريا إلى مشكلات تتراوح من أمراض خفيفة إلى تسمم الدم والتهاب السحايا. ويساعد لقاح المكورات الرئوية المقترن الذي سيُعطى لطفلكِ على الوقاية من المخاطر الشديدة مثل التهاب السحايا وتسمم الدم. ومن المعروف أيضًا أنه يقي من بعض حالات التهاب الأذن الوسطى. لذلك، يُنصح بشدة بإعطاء لقاح المكورات الرئوية للرضّع والأطفال في سن اللعب. وستقلل التطعيمات التي سيتلقاها طفلكِ هذا الشهر من خطر إصابته بهذه الأمراض طوال حياته إلى أدنى حد.') WHERE id = 'a0fe42da-edbb-44ae-9aba-92568413962b';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تحدث الإصابة بالنكاف (التهاب الغدة النكفية الوبائي) بسبب الفيروسات. وينتقل بسهولة عبر قطرات اللعاب الصغيرة التي تنتشر أثناء التحدث أو العطس أو التقبيل أو السعال. وهو عدوى فيروسية تصيب الغدد اللعابية والغدد النكفية الممتدة على طول الفك. أما الحصبة، فوفقًا لبيانات منظمة الصحة العالمية، هي مرض شديد العدوى وخطير يتسبب سنويًا في وفاة ملايين الأشخاص غير المطعّمين. ويسبب هذا المرض طفحًا جلديًا، ويشكّل خطرًا على الرضع غير المطعّمين. والحصبة الألمانية أيضًا مرض فيروسي مُعدٍ يصاحبه طفح جلدي مرقّط وبارز. ويمكن لهذه الأمراض أن تنتقل بسهولة من شخص إلى آخر. لكن نظرًا إلى الفعالية الوقائية العالية جدًا للقاحات في الوقت الحاضر، نوصيكِ بالالتزام بجدول التطعيمات.') WHERE id = 'ec8978cf-052f-4504-a3c1-e0f1b9dc401e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'على الرغم من أن طفلكِ قد بلغ 12 شهرًا، فإن القيلولة النهارية لا تزال مهمة، لأن نشاطه خلال اليوم ازداد مقارنة بالسابق. وفي هذه المرحلة، تكفي طفلكِ في المتوسط قيلولة واحدة خلال النهار مدتها 1-2 ساعة. ومن المهم الحفاظ على التوازن، لأن قلة النوم النهاري أو زيادته قد تؤثران في انتظام النوم ليلًا وجودته. إذا كنتِ قد وضعتِ روتينًا لطفلكِ، فسيصبح نومه ليلًا أكثر انتظامًا مقارنة بالأشهر السابقة. وبما أن طفلكِ لم يعد بحاجة إلى الرضاعة أو تناول الطعام ليلًا، فقد يستمر نومه المتواصل حتى 12 ساعة. يحتاج طفلكِ إلى النوم المتواصل طوال الليل من أجل نموه الجسدي ونشاطه الذهني. لذلك، لا داعي لإيقاظه من النوم لإطعامه. ولكن إذا كان طفلكِ لا يزال يستيقظ ليلًا بسبب الجوع، فقد تحتاجين إلى مساعدته تدريجيًا على التوقف عن هذه العادة، مع مراعاة نصائح طبيبه.') WHERE id = '21b97e51-16ae-47ca-a3b8-788c861f7d61';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمثّل هذا الشهر بداية مرحلة يصبح فيها النمو الجسدي لطفلكِ أبطأ مقارنة بالسنة الأولى من عمره. لذلك، يمكن اعتبار اكتساب طفلكِ وزنًا قليلًا، أو حتى عدم اكتسابه أي وزن في بعض الأشهر، أمرًا طبيعيًا في معظم الحالات. في الشهر 12، قد يتراوح وزن طفلكِ ضمن نطاق واسع يتراوح بين 7100-12500 غرام. ووفقًا للبيانات المتوفرة في بلدنا، يبلغ متوسط وزن الطفل في عمر 12 شهرًا نحو 9600 غرام. أما طول طفلكِ ابتداءً من هذا الشهر، فقد يتراوح بين 64-81 سم، بمتوسط يبلغ نحو 75 سم. تذكّري أن جميع هذه الأرقام قد تختلف بحسب الجنس والوزن عند الولادة والعوامل الوراثية وخصائص النمو. كما أن هذه الأرقام لا تُعد معايير قياسية للأطفال المولودين قبل أوانهم. وإذا كنتِ تعتقدين أن قياسات طفلكِ لا تقع ضمن هذه النطاقات، فيمكنكِ الحصول على أدق المعلومات من خلال استشارة طبيبكِ.') WHERE id = '4117c981-d400-493d-b227-ec432d7ba8ac';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إن إتمام طفلكِ عامه الأول في العالم الخارجي مرحلة مهمة تُرسى فيها أسس تكوين فرديته. وتعني الفردية إدراك طفلكِ للخصائص التي تميّزه عن الآخرين، وتُعد هذه المرحلة جزءًا من اكتسابه هويته الخاصة. وعلى الرغم من أنه لا يزال شديد التعلّق بكِ والاعتماد عليكِ، فإن بدء إدراكه أنه شخص مختلف عنكِ وعن الآخرين يُعد من أسس تطور شخصيته. وفي هذا السياق، عندما يبلغ طفلكِ 12 شهرًا، يبدأ بفهم نفسه بصورة أفضل وإدراك ما يحيط به بفاعلية أكبر. وفي هذه المرحلة التي يبدأ فيها بالشعور بالاستقلالية، من المهم جدًا لنموه أن تتقبّلي كونه فردًا مستقلًا. كما أصبح طفلكِ أكثر نشاطًا من الناحية الاجتماعية، ولذلك ستزداد حاجته إلى الطاقة بالمقدار نفسه. لهذا السبب، عليكِ أن تراعي جيدًا القيم الغذائية للأطعمة التي تقدمينها لطفلكِ ومدى ملاءمتها للموسم.') WHERE id = '8be39fcb-46bd-46a8-bfbf-0293af3adc49';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يُعد لقاح جدري الماء أحد أهم اللقاحات المدرجة في جدول تطعيمات طفلكِ. وجدري الماء مرض شديد العدوى يحدث عادةً في مرحلة الطفولة المبكرة، ويصاحبه ارتفاع في درجة الحرارة في معظم الحالات، ويتميّز بطفح جلدي مثير للحكة وبثور مملوءة بالسوائل. ويُعد هذا المرض، الذي يسببه فيروس الحماق النطاقي (VZV)، من أكثر أنواع العدوى سهولةً في الانتشار، والإنسان هو مصدره الوحيد. ويمكن أن ينتقل المرض بسهولة من شخص مصاب بالفيروس عبر الرذاذ التنفسي، أو نتيجة ملامسة السائل الموجود داخل البثور المائية على الجلد. تبدأ قابلية نقل العدوى قبل ظهور الطفح الجلدي بـ1-2 يوم، وتستمر حتى تتكوّن قشور على جميع مواضع الطفح. ويصل احتمال انتقال العدوى، ولا سيما عند المخالطة داخل المنزل، إلى 80-90%. ينتشر جدري الماء على نطاق واسع في بلدنا أيضًا، ويكثر ظهوره في فصلي الشتاء والربيع. وعلى الرغم من أنه يُشاهد عادةً لدى الأطفال الذين تتراوح أعمارهم بين 1-9 سنوات، فقد يصيب المراهقين والبالغين أيضًا. ويُعد التطعيم الوسيلة الأكثر فاعلية للوقاية من جدري الماء. لذلك، من المهم جدًا أن تلتزمي بجدول تطعيمات طفلكِ.') WHERE id = '6005eb52-15af-43d7-bcb9-cf624b6fbca5';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'قد يبدأ طفلكِ الآن باكتساب عادات غذائية معينة من خلال الأطعمة التي تقدمينها له. وبعد إتمام أول 12 شهرًا من عمره خصوصًا، يصل طفلكِ إلى مرحلة يستطيع فيها تناول العديد من الأطعمة، بما في ذلك الأطعمة المسببة للحساسية. وهذا يعني أنه أصبح مستعدًا لتناول الطعام المنزلي ومعظم ما تتناولينه. لكن قد تظهر لديه خلال هذه المرحلة حالة تُسمى "رفض الطعام" تجاه بعض الأطعمة. كما قد يرغب طفلكِ، الذي دخل مرحلة تكوين فرديته، في أن يقرر بنفسه متى يأكل وكم يأكل. تذكّري أن عادات الأكل الصحية التي يكتسبها طفلكِ في سن مبكرة ستتحول إلى نمط سلوكي يرافقه طوال حياته. لذلك، يُنصح بعدم تقديم الأطعمة المعبأة المعروفة بضررها، والمنخفضة القيمة الغذائية، والتي تُعد مصدرًا للسعرات الحرارية الفارغة، لطفلكِ لفترة أخرى.') WHERE id = '28f50db1-faf4-4213-a827-8ee377ef26fc';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'تمثّل هذه الأشهر بداية المرحلة الأكثر نشاطًا من الناحية الاجتماعية لدى طفلكِ. فرغبة طفلكِ في التواصل مع محيطه تعني أنه سيحاول تقليد كل ما يراه ويسمعه. فعلى سبيل المثال، إذا سبق له أن لاحظ ذلك في محيطه، فقد يشعر الآن بالحزن أو حتى يبكي عندما يبتعد عنه الأشخاص الذين يحبهم. وفي إطار هذا التطور الاجتماعي، قد يبدأ طفلكِ أيضًا باستخدام لغة خاصة ابتكرها في ذهنه. وخلال هذه المرحلة، قد ينطق كلمات أساسية مثل لعبة وماء وطعام بطرق مختلفة جدًا. وإضافةً إلى ذلك، من المهم جدًا أن تراقبي تطوره الاجتماعي بعناية للكشف المبكر عن أي فقدان محتمل للسمع. إذا كان طفلكِ قد بلغ 12 شهرًا وكنتِ تعتقدين أنه لا يستجيب للأصوات والمحفزات الخارجية، فقد تحتاجين إلى التواصل مع طبيبكِ.') WHERE id = '1b7f06dd-c2fb-4278-a493-16339dceb2f1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'ظهرت في السنوات الأخيرة فئة تزعم أن اللقاحات عمومًا، ولا سيما لقاح الحصبة والنكاف والحصبة الألمانية (QPM)، تسبب التوحد. وخلافًا للاعتقاد الشائع، لا يُعد التوحد مرضًا واحدًا، بل هو اضطراب مرتبط بنمو الدماغ تظهر علاماته في مرحلة الطفولة المبكرة ويُعرف باسم اضطراب طيف التوحد (ASP). ويُلاحظ لدى الأطفال المشخّصين باضطراب طيف التوحد قصور في التواصل والتفاعل الاجتماعي، وسلوكيات متكررة، واهتمامات محدودة. وعلى الرغم من أن سبب اضطراب طيف التوحد لم يُفهم بالكامل بعد، فإن عوامل وراثية متعددة والتفاعل بين الجينات والبيئة يؤديان دورًا أكبر في حدوثه. وتؤكد منظمة الصحة العالمية وغيرها من المؤسسات الموثوقة أن مكونات اللقاحات ليست سامة للرضع أو الأطفال أو البالغين. وعلى عكس ادعاءات من يربطون اللقاحات بالتوحد، أُجريت دراسات كثيرة حول هذا الموضوع في أنحاء العالم، ولم تثبت أي منها أن اللقاحات تسبب التوحد مباشرةً. لذلك نود أن نذكّركِ مجددًا بأهمية إعطاء اللقاحات، فهي الوسيلة الوحيدة للوقاية من أمراض شديدة العدوى قد تهدد الحياة، وبضرورة الالتزام بجدول التطعيمات المخصص لطفلكِ.') WHERE id = '1d726360-db3e-4087-aa23-4eebeaf883e8';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'إذا بدأ طفلكِ بإظهار استقلاليته ومحاولة إنجاز بعض الأمور بمفرده، فعليكِ ألا تمنعيه. فقد يؤدي منعه إلى زعزعة ثقته بنفسه وإضعاف حماسه لتعلم أشياء جديدة. وننصحكِ بمراقبته من بعيد وعدم التدخل عند الحاجة، ما دام الموقف لا ينطوي على احتمال إيذائه لنفسه. لكن عدم تحقيق التوازن الصحيح في هذه المرحلة قد يؤدي إلى اكتساب طفلكِ بعض السلوكيات العنيدة مستقبلًا. لذا، فإن عدم تدخلكِ لا يعني ترك طفلكِ وشأنه من دون متابعة أو إشراف. وقد يتصرف طفلكِ أيضًا خلال هذه الأشهر بإلحاح واستعجال للحصول على ما يريده. وفي هذه الحالة، حاولي تعليمه الانتظار. زيدي تدريجيًا المدة التي يصبر فيها طفلكِ للحصول على ما يتوقعه، ثم قولي له في الوقت المناسب: "شكرًا لك لأنك انتظرت"، فهذا سيسهّل عليكِ هذه العملية كثيرًا.') WHERE id = '721c9809-540c-47c4-8190-d643e809029e';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بدأ طفلكِ الآن بالجلوس معكم إلى مائدة الأسرة، وأصبح بإمكانه تناول كل طعام تتناولينه. ومع ذلك، هناك شيء لا يفقد قيمته أبدًا بالنسبة إلى طفلكِ: حليب الأم! خلال مرحلة الانتقال إلى الأطعمة التكميلية على وجه الخصوص، قد لا تولي بعض الأمهات إنتاج الحليب القدر نفسه من الاهتمام السابق، بسبب إدخال مصدر آخر للسعرات الحرارية إلى النظام الغذائي. وسواء كانت كمية حليبكِ قليلة أم وفيرة، تظل مكوناته بالغة الأهمية لنمو طفلكِ الجسدي والعقلي السليم. لذلك ينبغي أن تواصلي لبعض الوقت اتباع نظام غذائي متوازن، والحصول على قسط جيد من الراحة والنوم الكافي، والابتعاد عن التوتر. وحتى إن لم تزد كمية حليبكِ، فإن مكوناته تتغير وفقًا لاحتياجات نمو طفلكِ؛ لذا لا يزال جسمكِ بحاجة إلى نحو 500 سعرة حرارية إضافية لإنتاج الحليب. ولتلبية حاجة جسمكِ إلى هذه الطاقة الإضافية، يمكنكِ إضافة 2-3 أنواع من الفاكهة ومنتجات الألبان إلى نظامكِ الغذائي.') WHERE id = 'd6098b08-62c8-4bb2-b4c1-b75ce5f1f080';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'بفضل تطور المهارات الحركية الدقيقة لدى طفلكِ، يمكنه الآن البدء باستخدام الكوب. وإذا كان طفلكِ قد استخدم زجاجة الرضاعة حتى هذه المرحلة، فيوصي الخبراء بالبدء بفطامه عنها بعد بلوغه عمر سنة واحدة. فقد يؤدي استخدامها لفترة طويلة إلى زيادة تعلقه بها. وحتى لا تتحول عملية الفطام هذه إلى تجربة صادمة لطفلكِ، من الأفضل تنفيذها تدريجيًا وعلى مدى فترة من الزمن. وعلى الرغم من اختلاف الأساليب، يمكن أن تمتد المهلة المستهدفة للفطام عن زجاجة الرضاعة حتى عمر سنتين. لكن ينبغي أن يكون طفلكِ قد توقف عن استخدامها تمامًا عند بلوغه عمر سنتين. ويمكنكِ جعل هذه العملية، التي قد تكون مملة لطفلكِ، أكثر متعة. فعلى سبيل المثال، ستشجعه الأكواب التي تحمل صورة شخصية يعرفها ويحبها.') WHERE id = 'f6a48924-56e6-420c-9c9e-4191836f170a';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'منذ لحظة ولادته، يراقبكِ طفلكِ ويتابع ما تفعلينه ويبدأ بحفظ كل ذلك في ذاكرته. ومن هنا تبدأ رحلته في اكتشاف ذاته. لذلك ينبغي أن تنتبهي إلى سلوكياتكِ في هذه المرحلة أكثر من أي وقت مضى. ففي البداية، يختار طفلكِ أقرب أفراد الأسرة ليكونوا قدوة له. ومع مرور الوقت، قد يبدأ تلقائيًا باتخاذ أشخاص آخرين من محيطه قدوةً أيضًا. وقد يختلف هذا الاختيار تبعًا لتغيّر اهتمامات طفلكِ وتطورها. وبصفتكِ أحد الوالدين، ينبغي لكِ ولشريككِ إظهار سلوكيات يُحتذى بها، وتعزيز تواصل طفلكِ مع الأشخاص الذين يمكنه اتخاذهم قدوةً في محيطكما. ولأن الأسرة هي العامل الأساسي في تكوين حصيلة طفلكِ المعرفية، فإن تصحيح سلوكياتكما السلبية أولًا سيكون بداية جيدة.') WHERE id = '0d87ed0c-727b-4e64-9ccc-fb3e890b1bf1';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لكل الأنشطة التي ستقومين بها مع طفلكِ أو من أجله أهداف محددة ونقاط مشتركة. فهي تهدف إلى مساعدته ليصبح أكثر اجتماعية وثقة بنفسه وتصالحًا مع ذاته ومحيطه، سواء الآن أو عندما يكبر. ومن هذا المنطلق، فإن تكوين مجموعات لعب تضم أطفالًا من عمر طفلكِ له آثار إيجابية عديدة. فمن خلال التفاعل داخل المجموعة، يمر طفلكِ في مرحلة اللعب بعملية تعلّم طبيعية وممتعة. كما تعزز مجموعة اللعب التي تجمعه بأقرانه قدرته على المشاركة والتواصل مع الأطفال الآخرين. وإضافة إلى ذلك، فإن وجود طفلكِ مع أطفال من فئته العمرية يرسّخ لديه أسس الوعي الاجتماعي. لذلك، يمكنكِ الحرص على الالتقاء بانتظام بأقاربكِ وأصدقائكِ الذين لديهم أطفال في عمر طفلكِ.') WHERE id = '289e1ce5-6829-49f4-8414-fd82ef2d5291';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نحصل على جميع الفيتامينات تقريبًا من خلال الغذاء، وهي تؤدي وظائف عديدة في الجسم، بدءًا من تكوين الدم وتعزيز المناعة والحماية من العدوى، وصولًا إلى دعم النمو والتطور. لكن فيتامين D يتمتع بأهمية خاصة بين جميع الفيتامينات. وهو نوع من الفيتامينات يُعرف باسم الكالسيفيرول، ويذوب في الدهون ويُخزَّن في الكبد والأنسجة الدهنية. ويوجد فيتامين D في شكلين هما D2 وD3. يدخل هذا الفيتامين إلى الجسم عن طريق أشعة الشمس والغذاء، ثم يمر بسلسلة من العمليات في الكلى والكبد حتى يتمكن الجسم من الاستفادة منه. وفي هذه المرحلة، يُعد فيتامين D بالغ الأهمية لنمو عظام طفلكِ وأسنانه والحفاظ على صحتها. فلا تستطيع عظام طفلكِ امتصاص الكالسيوم والفوسفور اللذين تحتاج إليهما عند غياب فيتامين D. لذلك يحتاج طفلكِ إلى التعرض لأشعة الشمس مدة 20 دقيقة تقريبًا يوميًا. كما سيكون من المفيد أن تضيفي إلى نظامه الغذائي كميات كافية من الأطعمة الغنية بفيتامين D، مثل الحليب واللبن الرائب والكفير والجبن والزبادي والزبدة والتونة والسلمون وصفار البيض.') WHERE id = '567791cf-026f-48e1-a1ae-11fb0c471664';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يتكوّن دماغ الإنسان من منطقتين منفصلتين هما نصف الكرة المخية الأيمن ونصف الكرة المخية الأيسر. ويتحكم النصف الأيسر من الدماغ في اليد اليمنى، بينما يتحكم النصف الأيمن في اليد اليسرى. وفي هذه المرحلة، يُرجح أن يكون طفلكِ قادرًا على استخدام كلتا يديه بالقدر نفسه. ومن الأمور التي تثير فضول العائلات معرفة متى يتضح إن كان الطفل سيستخدم يده اليسرى أم اليمنى. وعلى الرغم من عدم وجود إجابة دقيقة عن هذا السؤال، فقد لا يتحدد أي اليدين سيستخدمها طفلكِ بمهارة أكبر إلا بعد بلوغه سن 3-4 سنوات. ومع ذلك، قد يبدأ طفلكِ منذ الآن بإظهار بعض العلامات. فمثلًا، قد يكون دورانه عكس اتجاه عقارب الساعة عندما تطلبين منه الالتفاف، أو محاولته الإمساك بشيء تمدينه إليه بيده اليسرى، من العلامات المبكرة لاستخدام اليد اليسرى. ويُعد استخدام اليد اليسرى عادةً حالة طبيعية ذات أساس وراثي، ولا يسبب أي مشكلة إلا في حالات نادرة. وإذا كنتِ أنتِ وشريككِ تستخدمان اليد اليسرى، فإن احتمال أن يستخدم طفلكِ اليد اليسرى يبلغ نحو 50%. أما إذا كان أحدكما فقط يستخدم اليد اليسرى، فقد تنخفض هذه النسبة إلى 25%. وإذا كنتِ تعتقدين أن طفلكِ يستخدم يده اليسرى، فلا ينبغي أن تجبريه على استخدام يده اليمنى، لأن ذلك قد يؤدي إلى مشكلات عديدة، وفي مقدمتها صعوبات التعلّم.') WHERE id = '75f0b847-2817-4187-947e-77f90574e166';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'لا يحتاج طفلكِ إلى الماء منذ ولادته وحتى بدء مرحلة الأغذية التكميلية. فإذا كنتِ ترضعينه طبيعيًا، فإن احتواء حليبكِ على ما يصل إلى 90% من الماء يلبي احتياجاته وأكثر. وعند عدم توفر حليب الأم، لا يحتاج طفلكِ إلى ماء إضافي ما دامت تركيبة حليب الرضع الاصطناعي تُحضَّر بالنسب الصحيحة، إلا إذا أوصى الطبيب بخلاف ذلك. ولكن ابتداءً من الشهر 6، حين تبدأ مرحلة الأغذية التكميلية، يحتاج جسم طفلكِ إلى الماء للمساعدة على هضم الأطعمة التي تقدمينها له. وتزداد حاجته إلى الماء بحسب نوع الطعام الذي يتناوله وكميته. كما يمكن أن يؤثر وزنه وطوله وكمية حليب الأم أو الحليب الاصطناعي الذي يحصل عليه في هذه النسبة. ويمكن أن يساعدكِ لون بول طفلكِ ورائحته في تقدير كمية الماء التي يحتاج إليها. فالبول عديم الرائحة وذو اللون الأصفر الفاتح يدل على حصوله على كمية كافية من الماء. ويمكنكِ تقديم الماء لطفلكِ بعد الوجبات بالقدر الذي يرغب فيه. وإذا كان طفلكِ يعاني من الإمساك خصوصًا، فتذكري أنكِ قد تحتاجين إلى زيادة كمية الماء التي يتناولها.') WHERE id = '226f1510-b007-4bb8-8b57-95b8e4235edf';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'نما طفلكِ وتطور بسرعة كبيرة خلال فترة قصيرة. وبالطبع، لذلك نتيجة واضحة: لم يعد سريره الصغير يتسع له! 😊 قد تعتقدين في هذه المرحلة أن طفلكِ يحتاج إلى سرير أكبر، لكننا ننصحكِ بعدم التسرع في اتخاذ هذا القرار. فما دام طفلكِ لم يبدأ بالتسلق، سيظل السرير الصغير أكثر أمانًا له، لأنه كثيرًا ما يتقلب أثناء النوم، ما قد يؤدي إلى سقوطه وتعرضه لإصابات في الرأس بسبب الارتفاع. لذلك قد يكون تكبير سرير طفلكِ الصغير أو توسيعه خيارًا أكثر ملاءمة لراحته وسلامته. وعندما يبدأ طفلكِ بالتسلق، قد تفيدكِ الحواجز الجانبية التي تعزز حماية السرير. كما يمكنكِ وضع وسائد على الأرض حول السرير الصغير بوصفها إجراءً إضافيًا للسلامة.') WHERE id = 'b97f83a4-16ac-40bf-8c1e-c667c7b0e4af';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'يمثل اللعب فرصة رائعة لطفلكِ لاكتشاف اهتماماته الخاصة، وتطوير مهارات جديدة، وتطبيق كل ما يتعلمه. لذلك تحتل ألعاب طفلكِ مكانة بالغة الأهمية في نموه وتطوره. وخلال عمر 1 سنة، يحب الأطفال كثيرًا الألعاب التي يمكنهم فصل أجزائها وجمعها وتركيبها وفكها ووضعها في أماكنها. لذلك، عند شراء ألعاب جديدة لطفلكِ، يمكنكِ اختيار ألعاب يمكن استخدامها بطرائق مختلفة عديدة. وفي هذه المرحلة العمرية، يمكنكِ العثور على منتجات تُباع باسم «رفيق المشي» لتشجيع طفلكِ على المشي، وبخيارات تناسب مختلف الميزانيات. كما قد تفيدكِ الألعاب التي تنمّي خياله وتشجعه على النشاط. ولدعم نمو طفلكِ الاجتماعي، يمكنكِ أيضًا البحث عن ألعاب تتيح له اللعب مع أطفال آخرين من عمره ومع البالغين.') WHERE id = 'c3cee02b-ffb7-41f8-a78b-1e3c3739d873';
UPDATE public.baby_daily_info SET info_ar = COALESCE(info_ar, 'خلال الفحص الطبي هذا الشهر، سيطلب طبيب الأطفال الذي يتابع حالة طفلكِ إجراء بعض تحاليل الدم له. تُعد هذه التحاليل بالغة الأهمية لفحص العديد من المؤشرات بالتفصيل، وفي مقدمتها مستوى الحديد. وبما أن طفلكِ يمر بمرحلة نمو وتطور سريعين، فإن احتياج جسمه إلى الحديد يكون أكبر مقارنةً بالمراحل الأخرى من حياته. وابتداءً من هذا الشهر، إذا كانت الأطعمة التي يتناولها طفلكِ لا تحتوي على كمية كافية من الحديد، فقد تظهر بعض المشكلات المرتبطة بنقصه. ويُعد فقر الدم الناجم عن نقص الحديد تحديدًا من أكثر المشكلات شيوعًا خلال هذه الفترة. وقد يؤدي نقص الحديد إلى إبطاء التطور الذهني لطفلكِ، كما قد يؤثر في وظائف عضلاته. ولأن هذه الحالة قد تسبب بعض التأخر في النمو الذهني والجسدي، فمن المهم الانتباه إليها.') WHERE id = 'd8d155e1-a69b-4e80-a661-38a50b003754';